#define CUDA_QK_K 256
#define DS4_CUDA_UNUSED __attribute__((unused))

enum {
    /* attention_decode_mixed_kernel stores raw-window scores plus visible
     * compressed scores in shared memory.  The host routes larger unmasked
     * decode calls to the online attention kernel so this fixed buffer never
     * becomes an out-of-bounds write at long context. */
    DS4_CUDA_ATTENTION_SCORE_CAP = 8192u,
    DS4_CUDA_ATTENTION_RAW_SCORE_CAP = 256u,
    DS4_CUDA_TOPK_MERGE_GROUP = 8u
};

struct ds4_gpu_tensor {
    void *ptr;
    uint64_t bytes;
    int owner;
    int memc;   /* census consumer class captured at alloc/reserve time
                   (ds4_mem_consumer_class); calloc zero = ENGINE_OTHER.
                   Frees and demand-page ensures charge this class so the
                   engine-side scope only has to bracket creation. */
};

typedef struct ds4_gpu_top2_result {
    uint32_t id0;
    uint32_t id1;
    float    value0;
    float    value1;
} ds4_gpu_top2_result;

typedef struct ds4_gpu_candidate_cert_result {
    uint32_t candidate_id;
    uint32_t certified;
    uint32_t bound_id;
    float    candidate_logit;
    float    max_bound;
} ds4_gpu_candidate_cert_result;

typedef struct {
    uint8_t scales[CUDA_QK_K / 16];
    uint8_t qs[CUDA_QK_K / 4];
    uint16_t d;
    uint16_t dmin;
} cuda_block_q2_K;

typedef struct {
    uint16_t d;
    uint16_t dmin;
    uint8_t scales[12];
    uint8_t qs[CUDA_QK_K / 2];
} cuda_block_q4_K;

typedef struct {
    float d;
    int8_t qs[CUDA_QK_K];
    int16_t bsums[CUDA_QK_K / 16];
} cuda_block_q8_K;

typedef struct {
    uint16_t d;
    uint16_t qs[CUDA_QK_K / 8];
} cuda_block_iq2_xxs;

