/* Captured decode graphs (g_layer_graphs / g_dense_graphs / g_moe_graphs)
 * bake raw device pointers into their kernel-node arg lists, including the
 * sticky high-water scratch buffers below.  Freeing such a buffer for
 * growth leaves every cached exec holding a dangling pointer; the next
 * replay reads freed memory (CUDA illegal memory access).  Defined after
 * the three cache tables; forward-declared here for the allocators. */
static void ds4_cuda_invalidate_captured_graphs(const char *why);

static void *cuda_tmp_alloc(uint64_t bytes, const char *what) {
    if (bytes == 0) return NULL;
    /* Task #22 diag (DS4_CUDA_TMP_PREALLOC_MB): floor the shared scratch so it
     * never resizes mid-run.  Discriminates the free-while-in-use resize hazard
     * below without changing launch timing. */
    static uint64_t floor_bytes = 0;
    static int floor_read = 0;
    if (!floor_read) {
        floor_read = 1;
        const char *e = getenv("DS4_CUDA_TMP_PREALLOC_MB");
        if (e && e[0]) {
            char *end = NULL;
            unsigned long long mb = strtoull(e, &end, 10);
            if (end != e && mb > 0) floor_bytes = (uint64_t)mb * 1048576ull;
        }
    }
    if (bytes < floor_bytes) bytes = floor_bytes;
    if (g_cuda_tmp_bytes >= bytes) return g_cuda_tmp;
    /* forum-#65: growth under capture is unservable -- the invalidator
     * below would refuse (execs can't be destroyed mid-capture) yet the
     * cudaFree/cudaMalloc pair would still run and poison the capture
     * with sticky errors.  Refuse cleanly instead; callers already treat
     * NULL as a failed (and reported) op.  Post the warmed-flag fix this
     * is defense-in-depth: the re-run warm pass sizes us eagerly first. */
    if (ds4_capture_active()) {
        fprintf(stderr, "ds4: cuda_tmp growth refused under capture (%s, %.2f MiB)\n",
                what ? what : "scratch", (double)bytes / 1048576.0);
        return NULL;
    }
    if (g_cuda_tmp) {
        /* Free-while-in-flight hardening (2026-07-13 warm-admit crash
         * audit; exonerated for that crash, kept as hardening): the
         * graph invalidation below only protects captured REPLAYS.
         * Eager work launched before this growth call -- the previous
         * decode step's post-readback tail, earlier ops of the same
         * admission chunk, moe-stream kernels -- may still hold the
         * retiring pointer when cudaFree runs.  Drain the device first,
         * same discipline as tt_scratch_ensure.  Growth is unreachable
         * under capture (ds4_cuda_capture_warm_tmp_scratch pre-sizing);
         * the guard makes an invariant break degrade to the
         * invalidator's existing refusal path instead of a
         * capture-poisoning device sync.  Cost is confined to rare
         * sticky high-water growth events. */
        if (!ds4_capture_active()) (void)cudaDeviceSynchronize();
        /* Growth frees a pointer that cached captured graphs may have
         * baked at capture time (decode-body consumers: indexer topk
         * tree scratch, topk sort, q8 prequant).  An EAGER prefill of a
         * new-max prompt length lands here mid-session; without the
         * invalidation the next decode replays against freed memory.
         * Repro: serial server, full re-prefill longer than every prior
         * prefill, first decode after it dies (2026-06-11 serial-conc
         * crash).  Resizes are rare (sticky high-water), so the
         * recapture cost decays to zero. */
        ds4_cuda_invalidate_captured_graphs(what ? what : "cuda_tmp resize");
        (void)cudaFree(g_cuda_tmp);
        cuda_mem_note_free(DS4_MEMC_SCRATCH_STICKY, DS4_MEMD_UNIFIED_DEVICE,
                           g_cuda_tmp_bytes, g_cuda_tmp_bytes);
        g_cuda_tmp = NULL;
        g_cuda_tmp_bytes = 0;
    }
    void *ptr = NULL;
    cudaError_t err = cudaMalloc(&ptr, (size_t)bytes);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA temp alloc failed for %s (%.2f MiB): %s\n",
                what ? what : "scratch", (double)bytes / 1048576.0, cudaGetErrorString(err));
        (void)cudaGetLastError();
        return NULL;
    }
    /* Deterministic-init the freshly (re)allocated scratch.  Some batched
     * kernels read padding/tail elements of this shared scratch that they did
     * not write (e.g. cublas workspace tails, topk-sort padding beyond n_comp).
     * cudaMalloc returns recycled memory whose contents depend on the prior
     * allocation history, so when an UNRELATED allocation (e.g. the MTP
     * drafter's decode_scalars cudaMalloc) shifts where this buffer lands on a
     * mid-run resize, those unwritten tail reads change -> a near-threshold
     * argmax flip downstream.  Zeroing on (re)alloc makes the read-before-write
     * deterministic.  Cheap: resizes are rare (sticky high-water buffer). */
    if (ptr) (void)cudaMemset(ptr, 0, (size_t)bytes);
    cuda_mem_note_alloc(DS4_MEMC_SCRATCH_STICKY, DS4_MEMD_UNIFIED_DEVICE,
                        bytes, bytes);
    g_cuda_tmp = ptr;
    g_cuda_tmp_bytes = bytes;
    return g_cuda_tmp;
}

static void *tt_scratch_ensure(uint64_t bytes, const char *what) {
    static int oom_printed = 0;
    if (bytes == 0) return NULL;
    if (g_tt_scratch_bytes >= bytes) return g_tt_scratch;
    (void)cudaDeviceSynchronize();
    if (g_tt_scratch) {
        (void)cudaFree(g_tt_scratch);
        cuda_mem_note_free(DS4_MEMC_SCRATCH_STICKY, DS4_MEMD_UNIFIED_DEVICE,
                           g_tt_scratch_bytes, g_tt_scratch_bytes);
        g_tt_scratch = NULL;
        g_tt_scratch_bytes = 0;
    }
    void *ptr = NULL;
    cudaError_t err = cudaMalloc(&ptr, (size_t)bytes);
    if (err != cudaSuccess) {
        if (!oom_printed) {
            oom_printed = 1;
            fprintf(stderr, "ds4: CUDA token-tile scratch alloc failed for %s (%.2f MiB): %s; falling back\n",
                    what ? what : "scratch", (double)bytes / 1048576.0, cudaGetErrorString(err));
        }
        (void)cudaGetLastError();
        return NULL;
    }
    if (ptr) (void)cudaMemset(ptr, 0, (size_t)bytes);
    cuda_mem_note_alloc(DS4_MEMC_SCRATCH_STICKY, DS4_MEMD_UNIFIED_DEVICE,
                        bytes, bytes);
    g_tt_scratch = ptr;
    g_tt_scratch_bytes = bytes;
    return g_tt_scratch;
}

static inline uint64_t tt_align256_u64(uint64_t x) {
    return (x + 255ull) & ~255ull;
}

