}

static const char *cuda_model_ptr(const void *model_map, uint64_t offset) {
    if (model_map == g_model_host_base && g_model_device_base) return g_model_device_base + offset;
    return (const char *)model_map + offset;
}

static int cuda_model_current_direct_available(const void *model_map) {
    return model_map && model_map == g_model_host_base &&
           (g_model_device_owned || g_model_registered);
}

static uint64_t cuda_parse_mib_env(const char *name, int *present) {
    const char *env = getenv(name);
    if (present) *present = 0;
    if (!env || !env[0]) return 0;
    char *end = NULL;
    unsigned long long v = strtoull(env, &end, 10);
    if (end == env || *end != '\0') return 0;
    if (present) *present = 1;
    if (v > UINT64_MAX / 1048576ull) return UINT64_MAX;
    return (uint64_t)v * 1048576ull;
}

/* --------------------------------------------------------------------
 * memgov D3-3b: the weight-resolve env vocabulary, read ONCE.
 *
 * Every knob the model-weight resolve graph consults -- tier selection,
 * budgets, staging geometry, verbosity -- snapshots on first use and is
 * never re-read: one vocabulary per boot, and the per-dispatch paths
 * (cuda_derived_weight_ptr runs per matmul launch) stop paying an
 * environ walk per call.  Parses are the legacy fragments moved, not
 * rewritten.  Boot-once paths outside the resolve graph (prefetch,
 * whole-model copy, artifact build) keep their own reads: env cannot
 * change between those reads and this snapshot within one exec. */
typedef struct {
    /* tier selection */
    int weight_cache;           /* DS4_CUDA_WEIGHT_CACHE set */
    int weight_preload;         /* DS4_CUDA_WEIGHT_PRELOAD set */
    int direct_model;           /* DS4_CUDA_DIRECT_MODEL set (fallback tier's test) */
    int direct_model_nonempty;  /* ...set AND non-empty (range tier's stricter historical test) */
    int no_fd_cache;            /* DS4_CUDA_NO_FD_CACHE set */
    int verbose;                /* DS4_CUDA_WEIGHT_CACHE_VERBOSE set */
    int keep_model_pages;       /* DS4_CUDA_KEEP_MODEL_PAGES set */
    int vmm_arena_off;          /* DS4_CUDA_VMM_ARENA == "0" exactly */
    int ipc_manifest;           /* DS4_CUDA_WEIGHT_IPC_MANIFEST set */
    /* budgets + staging geometry (need-fit logic stays at the callers) */
    uint64_t cache_limit_bytes; /* WEIGHT_CACHE_LIMIT_GB: 24 GiB default; present-unparseable = 0 (disables) */
    uint64_t copy_chunk_bytes;  /* MODEL_COPY_CHUNK_MB: 64 MiB default, 16..4096 MiB clamp */
    uint64_t arena_chunk_mb;    /* WEIGHT_ARENA_CHUNK_MB: 1792 default, 256..8192 clamp */
    uint64_t vmm_chunk_mb;      /* VMM_ARENA_CHUNK_MB: 0 = match request, else 64..4096 clamp */
    /* derived-weight + q8 cache family */
    int no_derived;             /* DS4_CUDA_NO_DERIVED_WEIGHTS set */
    int derived_verbose;        /* DS4_CUDA_DERIVED_WEIGHT_VERBOSE set */
    int no_q8_f16_cache;
    int q8_f16_all;
    int no_attn_out_f16_cache;  /* DS4_CUDA_NO_ATTENTION_OUTPUT_F16_CACHE */
    int no_attn_q_b_f16_cache;
    int attn_out_preload;       /* DS4_CUDA_ATTENTION_OUTPUT_PRELOAD */
    int no_q8_dp4a;
    int no_q8_f32_cache;
    int q8_f32_all;
    int attn_q_b_f32_cache;
    int q8_f32_large;
    uint64_t q8_f16_limit_bytes;   /* Q8_F16_CACHE_MB: UINT64_MAX when unset/unparseable */
    int q8_f16_reserve_present;    /* Q8_F16_CACHE_RESERVE_MB (total-dependent default stays at the caller) */
    uint64_t q8_f16_reserve_bytes;
} cuda_weight_env_t;

static cuda_weight_env_t cuda_weight_env_read(void) {
    cuda_weight_env_t e = {};
    e.weight_cache = getenv("DS4_CUDA_WEIGHT_CACHE") != NULL;
    e.weight_preload = getenv("DS4_CUDA_WEIGHT_PRELOAD") != NULL;
    const char *direct = getenv("DS4_CUDA_DIRECT_MODEL");
    e.direct_model = direct != NULL;
    e.direct_model_nonempty = direct != NULL && direct[0] != '\0';
    e.no_fd_cache = getenv("DS4_CUDA_NO_FD_CACHE") != NULL;
    e.verbose = getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE") != NULL;
    e.keep_model_pages = getenv("DS4_CUDA_KEEP_MODEL_PAGES") != NULL;
    const char *vmm = getenv("DS4_CUDA_VMM_ARENA");
    e.vmm_arena_off = vmm && vmm[0] == '0' && vmm[1] == '\0';
    e.ipc_manifest = getenv("DS4_CUDA_WEIGHT_IPC_MANIFEST") != NULL;
    {
        /* Default cap protects against OOM on UMA systems where a full
         * ~80 GiB model would otherwise duplicate the mmap'd host pages
         * into HBM-backed cudaMalloc allocations and exhaust the 121 GiB
         * UMA pool.  24 GiB comfortably covers attn projections +
         * embedding + output head + shared FFN; routed MoE experts
         * (~65 GiB, only top-K active per token) fall back to the
         * UVA-mapped pointer for cold lookups.  Tune up via
         * DS4_CUDA_WEIGHT_CACHE_LIMIT_GB on hosts with more budget. */
        uint64_t gb = 0;
        const char *env = getenv("DS4_CUDA_WEIGHT_CACHE_LIMIT_GB");
        if (env && env[0]) {
            char *end = NULL;
            unsigned long long v = strtoull(env, &end, 10);
            if (end != env) gb = (uint64_t)v;
            e.cache_limit_bytes = gb * 1073741824ull;
        } else {
            e.cache_limit_bytes = 24ull * 1073741824ull;
        }
    }
    {
        uint64_t mb = 64;
        const char *env = getenv("DS4_CUDA_MODEL_COPY_CHUNK_MB");
        if (env && env[0]) {
            char *end = NULL;
            unsigned long long v = strtoull(env, &end, 10);
            if (end != env && v > 0) mb = (uint64_t)v;
        }
        if (mb < 16) mb = 16;
        if (mb > 4096) mb = 4096;
        e.copy_chunk_bytes = mb * 1048576ull;
    }
    {
        uint64_t mb = 1792;
        const char *env = getenv("DS4_CUDA_WEIGHT_ARENA_CHUNK_MB");
        if (env && env[0]) {
            char *end = NULL;
            unsigned long long v = strtoull(env, &end, 10);
            if (end != env && v > 0) mb = (uint64_t)v;
        }
        if (mb < 256) mb = 256;
        if (mb > 8192) mb = 8192;
        e.arena_chunk_mb = mb;
    }
    {
        uint64_t mb = 0;
        const char *env = getenv("DS4_CUDA_VMM_ARENA_CHUNK_MB");
        if (env && env[0]) {
            char *end = NULL;
            unsigned long long v = strtoull(env, &end, 10);
            if (end != env && v > 0) mb = (uint64_t)v;
        }
        if (mb != 0) {
            if (mb < 64) mb = 64;
            if (mb > 4096) mb = 4096;
        }
        e.vmm_chunk_mb = mb;
    }
    e.no_derived = getenv("DS4_CUDA_NO_DERIVED_WEIGHTS") != NULL;
    e.derived_verbose = getenv("DS4_CUDA_DERIVED_WEIGHT_VERBOSE") != NULL;
    e.no_q8_f16_cache = getenv("DS4_CUDA_NO_Q8_F16_CACHE") != NULL;
    e.q8_f16_all = getenv("DS4_CUDA_Q8_F16_ALL") != NULL;
    e.no_attn_out_f16_cache = getenv("DS4_CUDA_NO_ATTENTION_OUTPUT_F16_CACHE") != NULL;
    e.no_attn_q_b_f16_cache = getenv("DS4_CUDA_NO_ATTN_Q_B_F16_CACHE") != NULL;
    e.attn_out_preload = getenv("DS4_CUDA_ATTENTION_OUTPUT_PRELOAD") != NULL;
    e.no_q8_dp4a = getenv("DS4_CUDA_NO_Q8_DP4A") != NULL;
    e.no_q8_f32_cache = getenv("DS4_CUDA_NO_Q8_F32_CACHE") != NULL;
    e.q8_f32_all = getenv("DS4_CUDA_Q8_F32_ALL") != NULL;
    e.attn_q_b_f32_cache = getenv("DS4_CUDA_ATTN_Q_B_F32_CACHE") != NULL;
    e.q8_f32_large = getenv("DS4_CUDA_Q8_F32_LARGE") != NULL;
    {
        int present = 0;
        const uint64_t limit = cuda_parse_mib_env("DS4_CUDA_Q8_F16_CACHE_MB", &present);
        e.q8_f16_limit_bytes = present ? limit : UINT64_MAX;
        e.q8_f16_reserve_bytes = cuda_parse_mib_env("DS4_CUDA_Q8_F16_CACHE_RESERVE_MB",
                                                    &e.q8_f16_reserve_present);
    }
    return e;
}

static const cuda_weight_env_t &cuda_weight_env(void) {
    /* C++ magic static: thread-safe once-init -- the strict form of the
     * g_vmm_supported lazy-cache idiom (resolve tiers run from server
     * threads; the guard's acquire/release does the fencing). */
    static const cuda_weight_env_t e = cuda_weight_env_read();
    return e;
}

static int cuda_model_has_full_range(const void *model_map, uint64_t model_size) {
    if (!model_map || model_size == 0) return 0;
    for (const cuda_model_range &r : g_model_ranges) {
        if (r.host_base == model_map && r.offset == 0 && r.bytes >= model_size) return 1;
    }
    return 0;
}

static void cuda_model_preserve_current_direct_mapping(void) {
    if (!g_model_host_base || g_model_registered_size == 0) return;
    if (!g_model_device_owned && !g_model_registered) return;

    if (!cuda_model_has_full_range(g_model_host_base, g_model_registered_size)) {
        if (g_model_device_owned && g_model_device_base) {
            if (cuda_model_range_publish({
                    g_model_host_base,
                    0,
                    g_model_registered_size,
                    (char *)g_model_device_base,
                    NULL,
                    NULL,
                    0,
                    0,
                    0,
                    0,
                    0,
                    0,
                    0,
                    0
                })) {
                g_model_range_bytes += g_model_registered_size;
            }
        } else if (g_model_registered && g_model_device_base) {
            (void)cuda_model_range_publish({
                g_model_host_base,
                0,
                g_model_registered_size,
                (char *)g_model_device_base,
                (void *)g_model_host_base,
                (char *)g_model_device_base,
                g_model_registered_size,
                1,
                0,
                0,
                0,
                0,
                0,
                0
            });
        }
    }

    g_model_device_owned = 0;
    g_model_registered = 0;
}

/* Allocate a device-resident copy of [offset, offset+bytes) from model_map and
 * push it into g_model_ranges so future cuda_model_range_ptr lookups hit it.
 * Returns the device pointer on success, NULL on cudaMalloc/cudaMemcpy failure.
 * Caller is responsible for any policy gating (budget cap, env opt-out, etc.) */
static const char *cuda_model_range_populate_device_copy(const void *model_map,
                                                          uint64_t offset,
                                                          uint64_t bytes,
                                                          const char *what) {
    /* memgov D2 hardening: the cold device-copy tier is a real promotion
     * (unregistered device bytes), so it takes the same governed decision
     * as the unit tiers.  Legacy verdict is ADMIT verbatim -- this tier
     * historically had no gating ("caller is responsible for any policy
     * gating"), so observe mode stays bit-identical.  A refusal degrades
     * to the coherent mapped pointer where that is kernel-safe (integrated
     * map), else NULL -- the caller's historical failure path. */
    ds4_gov_claim mcl = {0};
    mcl.requester = DS4_GOVC_ENGINE_BOOT;
    mcl.memc = DS4_MEMC_WEIGHT_SPAN;
    mcl.domain = DS4_MEMD_UNIFIED_DEVICE;
    mcl.proposed_outstanding = g_model_range_bytes + bytes;
    mcl.operation_transient = g_model_plan_frozen ? bytes : 0;
    if (ds4_gov_governed_check("cold_materialize", &mcl, DS4_GOV_ADMIT)
            != DS4_GOV_ADMIT) {
        return cuda_model_direct_fallback_ptr(model_map, offset);
    }
    void *dev = NULL;
    cudaError_t err = cudaMalloc(&dev, (size_t)bytes);
    if (err != cudaSuccess) {
        (void)cudaGetLastError();
        fprintf(stderr, "ds4: CUDA model range alloc failed for %s (%.2f MiB): %s\n",
                what ? what : "weights", (double)bytes / 1048576.0, cudaGetErrorString(err));
        /* Physical failure degrades exactly like a governed refusal
         * (0998f5a's contract): mapped-serve where coherent, else the
         * historical NULL. */
        return cuda_model_direct_fallback_ptr(model_map, offset);
    }

    const char *src = (const char *)model_map + offset;
    const uint64_t chunk = 64ull * 1024ull * 1024ull;
    for (uint64_t done = 0; done < bytes; done += chunk) {
        uint64_t n = bytes - done < chunk ? bytes - done : chunk;
        err = cudaMemcpy((char *)dev + done, src + done, (size_t)n, cudaMemcpyHostToDevice);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model range copy failed for %s at %.2f/%.2f MiB: %s (serving mapped)\n",
                    what ? what : "weights",
                    (double)done / 1048576.0,
                    (double)bytes / 1048576.0,
                    cudaGetErrorString(err));
            (void)cudaFree(dev);
            (void)cudaGetLastError();
            /* Probe-proven shape (rent-gate M leg, 08-14): the per-range
             * register tier page-rounds its registrations, so a tiny
             * neighbor tensor can land with its source STRADDLING a
             * registration boundary -- its own registration fails with
             * HostMemoryAlreadyRegistered (silent by design) and the
             * cudaMemcpy here rejects the boundary-crossing source with
             * invalid argument (kv_rms_weight, deterministic).  The raw
             * coherent map serves any host range regardless of
             * registration geometry; degrade, never dead-resolve. */
            return cuda_model_direct_fallback_ptr(model_map, offset);
        }
    }
    g_in_governed_materialize = 1;   /* claim taken above: funneled publication */
    const int pub = cuda_model_range_publish({model_map, offset, bytes, (char *)dev, NULL, NULL, 0, 0, 0, 0, 0, 0, 0, 0});
    g_in_governed_materialize = 0;
    if (!pub) {
        (void)cudaFree(dev);
        return NULL;
    }
    g_model_range_bytes += bytes;
    cuda_mem_note_alloc_src(DS4_MEMC_WEIGHT_SPAN, DS4_MEMD_UNIFIED_DEVICE,
                            bytes, bytes, model_map);
    cuda_substrate_cover(model_map, bytes);   /* tripwire: promotion materialized */
    if (cuda_weight_env().verbose) {
        fprintf(stderr, "ds4: CUDA cached %s %.2f MiB (total %.2f GiB)\n",
                what ? what : "weights",
                (double)bytes / 1048576.0,
                (double)g_model_range_bytes / 1073741824.0);
    }
    return (const char *)dev;
}

/* Pure registry resolve (no side effects): the exact-hit candidate, then
 * the ordered scans.  Two passes: device-resident copies must win over the
 * whole-model registered mapping even though the registered range was
 * pushed first (a single ordered scan returned the mapped pointer for
 * every offset interior to a cached span, silently starving the HBM cache
 * -- only exact span-start offsets ever hit it via the index).  NULL means
 * "no registry answer"; the caller continues to the cold fallbacks.
 * Shared by the live lookup and the D1a-1 parity probe, which differ only
 * in WHICH index supplied the exact candidate. */
static const char *cuda_model_range_resolve(const void *model_map,
                                            uint64_t offset, uint64_t bytes,
                                            const cuda_model_range *exact_r) {
    const uint64_t end = offset + bytes;
    if (exact_r && exact_r->host_base == model_map && end >= offset &&
        bytes <= exact_r->bytes) {
        return exact_r->device_ptr;
    }
    for (const cuda_model_range &r : g_model_ranges) {
        if (r.host_base == model_map && !r.host_registered &&
            offset >= r.offset && end >= offset && end <= r.offset + r.bytes) {
            return r.device_ptr + (offset - r.offset);
        }
    }
    for (const cuda_model_range &r : g_model_ranges) {
        if (r.host_base == model_map && offset >= r.offset && end >= offset && end <= r.offset + r.bytes) {
            return r.device_ptr + (offset - r.offset);
        }
        if (r.host_base == model_map && r.host_registered && r.registered_base && r.registered_device_base) {
            const uintptr_t h0 = (uintptr_t)((const char *)model_map + offset);
            const uintptr_t h1 = h0 + bytes;
            const uintptr_t r0 = (uintptr_t)r.registered_base;
            const uintptr_t r1 = r0 + r.registered_bytes;
            if (h1 >= h0 && h0 >= r0 && h1 <= r1) return r.registered_device_base + (h0 - r0);
        }
    }
    return NULL;
}

static const char *cuda_model_range_ptr(const void *model_map, uint64_t offset, uint64_t bytes, const char *what) {
    if (bytes == 0) return cuda_model_ptr(model_map, offset);

    /* Device-resident HBM cache hits win over UVA-mapped registered pointers:
     * direct HBM reads are ~10% faster than mapped reads through host page
     * tables (measured on plain decode at GB10).  Cache lookup runs first; the
     * registered-mapped shortcut below is the cold fallback when an allocation
     * hasn't been pre-populated. */
    const cuda_model_range *exact_r = NULL;
    auto exact = g_model_range_by_offset.find(cuda_range_key{model_map, offset});
    if (exact != g_model_range_by_offset.end())
        exact_r = &g_model_ranges[exact->second];
    const char *resolved = cuda_model_range_resolve(model_map, offset, bytes, exact_r);
    if (resolved) return resolved;

    const cuda_weight_env_t &we = cuda_weight_env();
    if (cuda_model_current_direct_available(model_map)) return cuda_model_ptr(model_map, offset);
    if (model_map == g_model_host_base && g_model_hmm_direct &&
        !we.weight_cache && !we.weight_preload) {
        return cuda_model_ptr(model_map, offset);
    }
    /* memgov D3-2: a TERMINAL host-mapped source on the coherent
     * integrated map serves the raw ATS pointer HERE -- no promotion
     * walk, no per-range registration, no API calls (capture-safe by
     * construction).  The rent-gate M-leg forensics (08-14) showed why
     * the register tier cannot be the mapped mechanism on this shape:
     * page-rounded per-range registrations build a patchwork over the
     * mmap, every later cold copy whose source intersects it fails
     * 'invalid argument', and an unpublished fallback makes capture-time
     * resolves re-walk the tiers into cudaMalloc-under-capture (poisoned
     * decode graphs).  Registry hits above still win (imports, artifacts'
     * derived ranges); discrete maps fall through to the register tier. */
    {
        const int msrc = cuda_mem_src_index(model_map);
        if (msrc >= 0 && msrc < DS4_MSRC_MAX &&
            g_model_srcs.v[msrc].residency == DS4_RESIDENCY_HOST_MAPPED &&
            model_map == g_model_coherent_direct_map)
            return cuda_model_ptr(model_map, offset);
    }
    if (we.direct_model_nonempty) return cuda_model_ptr(model_map, offset);

    if (!we.no_fd_cache) {
        const char *fd_ptr = cuda_model_range_ptr_from_fd(model_map, offset, bytes, what);
        if (fd_ptr) return fd_ptr;
    }

    cudaError_t err = cudaSuccess;
    if (g_model_range_mapping_supported) {
        const long page_sz_l = sysconf(_SC_PAGESIZE);
        const uint64_t page_sz = page_sz_l > 0 ? (uint64_t)page_sz_l : 4096u;
        const uintptr_t host_addr = (uintptr_t)((const char *)model_map + offset);
        const uintptr_t reg_addr = host_addr & ~(uintptr_t)(page_sz - 1u);
        const uint64_t reg_delta = (uint64_t)(host_addr - reg_addr);
        const uint64_t reg_bytes = (reg_delta + bytes + page_sz - 1u) & ~(page_sz - 1u);
        void *reg_dev = NULL;
        err = cudaHostRegister((void *)reg_addr,
                               (size_t)reg_bytes,
                               cudaHostRegisterMapped);
        if (err == cudaSuccess) {
            cuda_pinned_file_note_register((void *)reg_addr, reg_bytes);
            err = cudaHostGetDevicePointer(&reg_dev, (void *)reg_addr, 0);
            if (err == cudaSuccess && reg_dev) {
                char *dev_ptr = (char *)reg_dev + reg_delta;
                if (!cuda_model_range_publish({model_map, offset, bytes, dev_ptr, (void *)reg_addr, (char *)reg_dev, reg_bytes, 1, 0})) {
                    (void)cudaHostUnregister((void *)reg_addr);
                    cuda_pinned_file_note_unregister((void *)reg_addr);
                    (void)cudaGetLastError();
                    return cuda_model_range_populate_device_copy(model_map, offset, bytes, what);
                }
                if (we.verbose) {
                    fprintf(stderr, "ds4: CUDA mapped %s %.2f MiB\n",
                            what ? what : "weights",
                            (double)bytes / 1048576.0);
                }
                return dev_ptr;
            }
            fprintf(stderr, "ds4: CUDA model range map pointer failed for %s: %s\n",
                    what ? what : "weights", cudaGetErrorString(err));
            (void)cudaHostUnregister((void *)reg_addr);
            cuda_pinned_file_note_unregister((void *)reg_addr);
            (void)cudaGetLastError();
        } else {
            if (err == cudaErrorNotSupported || err == cudaErrorInvalidValue) g_model_range_mapping_supported = 0;
            (void)cudaGetLastError();
        }
    }

    return cuda_model_range_populate_device_copy(model_map, offset, bytes, what);
}

static char *cuda_derived_weight_ptr(
        const void *model_map,
        uint64_t source_offset,
        uint64_t source_bytes,
        uint32_t kind,
        uint64_t in_dim,
        uint64_t out_dim,
        uint32_t group_count,
        uint64_t bytes,
        const char *label) {
    const cuda_weight_env_t &we = cuda_weight_env();
    if (we.no_derived) return NULL;
    for (const cuda_derived_range &r : g_derived_ranges) {
        if (r.host_base == model_map &&
            r.source_offset == source_offset &&
            r.source_bytes == source_bytes &&
            r.kind == kind &&
            r.in_dim == in_dim &&
            r.out_dim == out_dim &&
            r.group_count == group_count &&
            bytes <= r.bytes) {
            if (we.derived_verbose) {
                fprintf(stderr, "ds4: CUDA derived weight hit %s %.2f MiB\n",
                        label ? label : "derived",
                        (double)r.bytes / 1048576.0);
            }
            return r.device_ptr;
        }
    }
    return NULL;
}

static void cuda_q8_f16_cache_release_all(void) {
    /* D1a-1: one bulk class note (unchanged shape) + per-source rows
     * summed from the live ranges -- each range's alloc attributed by
     * host_base, so the rows mirror the cell exactly.  Runs mid-serving
     * too (cuBLAS-failure disable path), not just at teardown. */
    uint64_t by_src[DS4_MSRC_MAX + 1] = {0};
    for (const cuda_q8_f16_range &r : g_q8_f16_ranges)
        by_src[cuda_mem_src_index(r.host_base)] +=
            r.in_dim * r.out_dim * sizeof(__half);
    ds4_gov_epoch_write_begin(&g_mem_census_epoch, &g_mem_census_faults);
    ds4_mem_cell_note_free(
        &g_mem_census[DS4_MEMC_WEIGHT_DERIVED][DS4_MEMD_UNIFIED_DEVICE],
        g_q8_f16_bytes, g_q8_f16_bytes, &g_mem_census_faults);
    for (int s = 0; s <= DS4_MSRC_MAX; s++) {
        if (by_src[s] == 0) continue;
        ds4_mem_cell_note_free(
            &g_mem_src_census[s][DS4_MEMC_WEIGHT_DERIVED][DS4_MEMD_UNIFIED_DEVICE],
            by_src[s], by_src[s], &g_mem_census_faults);
    }
    ds4_gov_epoch_write_end(&g_mem_census_epoch, &g_mem_census_faults);
    for (const cuda_q8_f16_range &r : g_q8_f16_ranges) {
        (void)cudaFree(r.device_ptr);
    }
    g_q8_f16_ranges.clear();
    g_q8_f16_by_offset.clear();
    g_q8_f16_bytes = 0;
}

static uint64_t cuda_q8_f16_cache_limit_bytes(void) {
    return cuda_weight_env().q8_f16_limit_bytes;
}

static uint64_t cuda_q8_f16_cache_reserve_bytes(uint64_t total_bytes) {
    const cuda_weight_env_t &we = cuda_weight_env();
    if (we.q8_f16_reserve_present) return we.q8_f16_reserve_bytes;

    if (total_bytes >= 112ull * 1024ull * 1024ull * 1024ull) {
        return 512ull * 1048576ull;
    }

    /* The expanded Q8->F16 cache is only an acceleration path.  Keep enough
     * device memory free for cuBLAS workspaces, transient graph buffers, and
     * driver bookkeeping instead of letting optional cached weights consume the
     * last few GiB on 96 GiB cards. */
    const uint64_t min_reserve = 4096ull * 1048576ull;
    const uint64_t pct_reserve = total_bytes / 20u; /* 5% */
    return pct_reserve > min_reserve ? pct_reserve : min_reserve;
}

static void cuda_q8_f16_cache_budget_notice(
        const char *reason,
        uint64_t request_bytes,
        uint64_t free_bytes,
        uint64_t total_bytes,
        uint64_t reserve_bytes,
        uint64_t limit_bytes) {
    if (g_q8_f16_budget_notice_printed && !cuda_weight_env().verbose) return;
    g_q8_f16_budget_notice_printed = 1;
    if (limit_bytes != UINT64_MAX && free_bytes == 0 && total_bytes == 0 && reserve_bytes == 0) {
        fprintf(stderr,
                "ds4: CUDA q8 fp16 cache %s; using q8 kernels "
                "(request=%.2f MiB cached=%.2f GiB limit=%.2f GiB)\n",
                reason,
                (double)request_bytes / 1048576.0,
                (double)g_q8_f16_bytes / 1073741824.0,
                (double)limit_bytes / 1073741824.0);
    } else if (limit_bytes == UINT64_MAX) {
        fprintf(stderr,
                "ds4: CUDA q8 fp16 cache %s; using q8 kernels "
                "(request=%.2f MiB cached=%.2f GiB free=%.2f GiB reserve=%.2f GiB total=%.2f GiB)\n",
                reason,
                (double)request_bytes / 1048576.0,
                (double)g_q8_f16_bytes / 1073741824.0,
                (double)free_bytes / 1073741824.0,
                (double)reserve_bytes / 1073741824.0,
                (double)total_bytes / 1073741824.0);
    } else {
        fprintf(stderr,
                "ds4: CUDA q8 fp16 cache %s; using q8 kernels "
                "(request=%.2f MiB cached=%.2f GiB limit=%.2f GiB free=%.2f GiB reserve=%.2f GiB total=%.2f GiB)\n",
                reason,
                (double)request_bytes / 1048576.0,
                (double)g_q8_f16_bytes / 1073741824.0,
                (double)limit_bytes / 1073741824.0,
                (double)free_bytes / 1073741824.0,
                (double)reserve_bytes / 1073741824.0,
                (double)total_bytes / 1073741824.0);
    }
}

static int cuda_q8_f16_cache_has_budget(uint64_t request_bytes, const char *label) {
    (void)label;
    const uint64_t limit = cuda_q8_f16_cache_limit_bytes();
    if (limit == 0) return 0;
    if (g_q8_f16_bytes > limit || request_bytes > limit - g_q8_f16_bytes) {
        cuda_q8_f16_cache_budget_notice("limit reached", request_bytes, 0, 0, 0, limit);
        return 0;
    }

    /* MT-6 (audit V10, gap-3/C11): the budget reads the ONE typed
     * observation every other verdict reads, not a second raw
     * cudaMemGetInfo answer -- on GB10 the raw read under-counted free
     * by the reclaimable page cache, refusing cache builds the box could
     * fund.  Same conservative reserve below, honest free above it. */
    ds4_mem_observation obs;
    if (ds4_gpu_mem_observe(&obs) != 0 || obs.status != DS4_MEMOBS_OK) {
        fprintf(stderr, "ds4: CUDA q8 fp16 cache memory query failed; using q8 kernels\n");
        return 0;
    }

    const uint64_t free_bytes = obs.free_bytes;
    const uint64_t total_bytes = obs.total_bytes;
    const uint64_t reserve_bytes = cuda_q8_f16_cache_reserve_bytes(total_bytes);
    if (request_bytes > free_bytes ||
        free_bytes - request_bytes < reserve_bytes) {
        cuda_q8_f16_cache_budget_notice("budget exhausted", request_bytes,
                                        free_bytes, total_bytes,
                                        reserve_bytes, limit);
        return 0;
    }
    return 1;
}

static void cuda_q8_f16_cache_disable_after_failure(const char *what, uint64_t request_bytes) {
    if (!g_q8_f16_disabled_after_oom) {
        fprintf(stderr,
                "ds4: CUDA q8 fp16 cache disabled after %s "
                "(request=%.2f MiB cached=%.2f GiB); using q8 kernels\n",
                what ? what : "allocation failure",
                (double)request_bytes / 1048576.0,
                (double)g_q8_f16_bytes / 1073741824.0);
    }
    g_q8_f16_disabled_after_oom = 1;
    if (!g_q8_f16_ranges.empty()) {
        (void)cudaDeviceSynchronize();
        cuda_q8_f16_cache_release_all();
    }
    (void)cudaGetLastError();
}

static int cuda_q8_f16_cache_allowed(const char *label, uint64_t in_dim, uint64_t out_dim) {
    const cuda_weight_env_t &we = cuda_weight_env();
    if (g_quality_mode) return 0;
    if (g_q8_f16_disabled_after_oom) return 0;
    if (we.no_q8_f16_cache) return 0;
    if (cuda_q8_f16_cache_limit_bytes() == 0) return 0;
    if (we.q8_f16_all) return 1;
    if (!label) return 0;
    if (strstr(label, "attn_output_a") != NULL ||
        strstr(label, "attn_output_b") != NULL ||
        strstr(label, "attention_output_a") != NULL ||
        strstr(label, "attention_output_b") != NULL) {
        return !we.no_attn_out_f16_cache;
    }
    if (strstr(label, "attn_q_b") != NULL) {
        return !we.no_attn_q_b_f16_cache;
    }
    if (strstr(label, "ffn_gate_shexp") != NULL ||
        strstr(label, "ffn_up_shexp") != NULL ||
        strstr(label, "ffn_down_shexp") != NULL) {
        return 1;
    }
    return (in_dim == 4096u && out_dim == 2048u) ||
           (in_dim == 2048u && out_dim == 4096u) ||
           (in_dim == 4096u && out_dim == 1024u) ||
           (in_dim == 4096u && out_dim == 512u) ||
           (!we.no_attn_q_b_f16_cache &&
            in_dim == 1024u && out_dim == 32768u);
}

static int cuda_q8_label_is_attention_output(const char *label) {
    return label &&
           (strstr(label, "attn_output_a") != NULL ||
            strstr(label, "attn_output_b") != NULL ||
            strstr(label, "attention_output_a") != NULL ||
            strstr(label, "attention_output_b") != NULL);
}

static int cuda_q8_label_is_attention_output_b(const char *label) {
    return label &&
           (strstr(label, "attn_output_b") != NULL ||
            strstr(label, "attention_output_b") != NULL);
}

static int cuda_q8_use_dp4a(void) {
    return !cuda_weight_env().no_q8_dp4a;
}

static int cuda_q8_f16_preload_allowed(const char *label, uint64_t in_dim, uint64_t out_dim) {
    const cuda_weight_env_t &we = cuda_weight_env();
    if (cuda_q8_label_is_attention_output(label) &&
        !we.attn_out_preload && !we.q8_f16_all) {
        return 0;
    }
    return cuda_q8_f16_cache_allowed(label, in_dim, out_dim);
}

static int cuda_q8_f32_cache_allowed(const char *label, uint64_t in_dim, uint64_t out_dim) {
    const cuda_weight_env_t &we = cuda_weight_env();
    if (we.no_q8_f32_cache) return 0;
    if (we.q8_f32_all) return 1;
    if (label && strstr(label, "attn_q_b") != NULL) {
        return we.attn_q_b_f32_cache;
    }
    return we.q8_f32_large &&
           in_dim == 1024u && out_dim == 32768u;
}

static const __half *cuda_q8_f16_ptr(
        const void *model_map,
        uint64_t offset,
        uint64_t weight_bytes,
        uint64_t in_dim,
        uint64_t out_dim,
        const char *label) {
    auto exact = g_q8_f16_by_offset.find(cuda_range_key{model_map, offset});
    if (exact != g_q8_f16_by_offset.end()) {
        const cuda_q8_f16_range &r = g_q8_f16_ranges[exact->second];
        if (r.host_base == model_map && r.weight_bytes == weight_bytes &&
            r.in_dim == in_dim && r.out_dim == out_dim) {
            return r.device_ptr;
        }
    }
    if (!cuda_q8_f16_cache_allowed(label, in_dim, out_dim)) return NULL;
    if (in_dim != 0 && out_dim > UINT64_MAX / in_dim / sizeof(__half)) return NULL;
    const uint64_t out_bytes = in_dim * out_dim * sizeof(__half);
    char *derived = cuda_derived_weight_ptr(model_map,
                                            offset,
                                            weight_bytes,
                                            CUDA_DERIVED_Q8_0_F16_COLMAJOR,
                                            in_dim,
                                            out_dim,
                                            0,
                                            out_bytes,
                                            label ? label : "q8_0_f16");
    if (derived) return (const __half *)derived;

    const char *q8 = cuda_model_range_ptr(model_map, offset, weight_bytes, "q8_0");
    if (!q8) return NULL;

    if (!cuda_q8_f16_cache_has_budget(out_bytes, label)) return NULL;

    __half *dev = NULL;
    cudaError_t err = cudaMalloc(&dev, (size_t)out_bytes);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA q8 fp16 cache alloc failed (%.2f MiB): %s\n",
                (double)out_bytes / 1048576.0, cudaGetErrorString(err));
        cuda_q8_f16_cache_disable_after_failure("allocation failure", out_bytes);
        return NULL;
    }
    const uint64_t blocks = (in_dim + 31) / 32;
    const uint64_t n = in_dim * out_dim;
    dequant_q8_0_to_f16_kernel<<<(n + 255) / 256, 256, 0, ds4_current_stream()>>>(dev,
                                                          (const unsigned char *)q8,
                                                          in_dim,
                                                          out_dim,
                                                          blocks);
    if (!cuda_ok(cudaGetLastError(), "q8 fp16 dequant launch")) {
        (void)cudaFree(dev);
        cuda_q8_f16_cache_disable_after_failure("dequant launch failure", out_bytes);
        return NULL;
    }
    if (!cuda_q8_f16_publish({model_map, offset, weight_bytes, in_dim, out_dim, dev})) {
        (void)cudaFree(dev);
        return NULL;
    }
    g_q8_f16_bytes += out_bytes;
    cuda_mem_note_alloc_src(DS4_MEMC_WEIGHT_DERIVED, DS4_MEMD_UNIFIED_DEVICE,
                            out_bytes, out_bytes, model_map);
    if (cuda_weight_env().verbose) {
        fprintf(stderr, "ds4: CUDA cached q8 fp16 %.2f MiB (total %.2f GiB)\n",
                (double)out_bytes / 1048576.0,
                (double)g_q8_f16_bytes / 1073741824.0);
    }
    return dev;
}

static float *cuda_q8_f32_ptr(
        const void *model_map,
        uint64_t offset,
        uint64_t weight_bytes,
        uint64_t in_dim,
        uint64_t out_dim,
        const char *label) {
    auto exact = g_q8_f32_by_offset.find(cuda_range_key{model_map, offset});
    if (exact != g_q8_f32_by_offset.end()) {
        const cuda_q8_f32_range &r = g_q8_f32_ranges[exact->second];
        if (r.host_base == model_map && r.weight_bytes == weight_bytes &&
            r.in_dim == in_dim && r.out_dim == out_dim) {
            return r.device_ptr;
        }
    }
    if (!cuda_q8_f32_cache_allowed(label, in_dim, out_dim)) return NULL;
    if (in_dim != 0 && out_dim > UINT64_MAX / in_dim / sizeof(float)) return NULL;
    const uint64_t out_bytes = in_dim * out_dim * sizeof(float);
    char *derived = cuda_derived_weight_ptr(model_map,
                                            offset,
                                            weight_bytes,
                                            CUDA_DERIVED_Q8_0_F32_COLMAJOR,
                                            in_dim,
                                            out_dim,
                                            0,
                                            out_bytes,
                                            label ? label : "q8_0_f32");
    if (derived) return (float *)derived;

    const char *q8 = cuda_model_range_ptr(model_map, offset, weight_bytes, label ? label : "q8_0");
    if (!q8) return NULL;

    float *dev = NULL;
    cudaError_t err = cudaMalloc(&dev, (size_t)out_bytes);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA q8 fp32 cache alloc failed (%.2f MiB): %s\n",
                (double)out_bytes / 1048576.0, cudaGetErrorString(err));
        (void)cudaGetLastError();
        return NULL;
    }
    const uint64_t blocks = (in_dim + 31) / 32;
    const uint64_t n = in_dim * out_dim;
    dequant_q8_0_to_f32_kernel<<<(n + 255) / 256, 256, 0, ds4_current_stream()>>>(dev,
                                                          (const unsigned char *)q8,
                                                          in_dim,
                                                          out_dim,
                                                          blocks);
    if (!cuda_ok(cudaGetLastError(), "q8 fp32 dequant launch")) {
        (void)cudaFree(dev);
        return NULL;
    }
    if (!cuda_q8_f32_publish({model_map, offset, weight_bytes, in_dim, out_dim, dev})) {
        (void)cudaFree(dev);
        return NULL;
    }
    g_q8_f32_bytes += out_bytes;
    cuda_mem_note_alloc_src(DS4_MEMC_WEIGHT_DERIVED, DS4_MEMD_UNIFIED_DEVICE,
                            out_bytes, out_bytes, model_map);
    if (cuda_weight_env().verbose) {
        fprintf(stderr, "ds4: CUDA cached q8 fp32 %.2f MiB (total %.2f GiB)\n",
                (double)out_bytes / 1048576.0,
                (double)g_q8_f32_bytes / 1073741824.0);
    }
    return dev;
}

static int cuda_ok(cudaError_t err, const char *what) {
    if (err == cudaSuccess) return 1;
    fprintf(stderr, "ds4: CUDA %s failed: %s\n", what, cudaGetErrorString(err));
    return 0;
}

/* --------------------------------------------------------------------
 * Device-side decode scalars: allocation + per-token update.
 *
 * See the struct definition near the file top for the design rationale.
 * These three functions form the C-callable surface: ds4.c calls
 *   ds4_gpu_decode_scalars_init()                    once per session,
 *   ds4_gpu_decode_scalars_set(pos, raw_cap, ...)    once per token,
 *   ds4_gpu_decode_scalars_cleanup()                 at GPU teardown.
 * Plus an opaque-pointer accessor for shims that need to forward the
 * device-side struct address to position-dependent kernels.
 *
 * Both allocations are session-lifetime.  Init is idempotent.  Init
 * failure leaves the globals NULL and returns 0; the caller is expected
 * to treat layer-graphs-disabled as the fallback path.  Cleanup is also
 * idempotent and safe to call multiple times. */
extern "C" int ds4_gpu_decode_scalars_init(void) {
    if (g_decode_host != NULL && g_decode_dev != NULL) {
        return 1;  /* already initialized */
    }
    if (g_decode_host == NULL) {
        if (!cuda_ok(cudaHostAlloc((void **)&g_decode_host,
                                   sizeof(*g_decode_host),
                                   cudaHostAllocDefault),
                     "decode scalars host alloc")) {
            g_decode_host = NULL;
            return 0;
        }
    }
    if (g_decode_dev == NULL) {
        if (!cuda_ok(cudaMalloc((void **)&g_decode_dev,
                                sizeof(*g_decode_dev)),
                     "decode scalars dev alloc")) {
            cudaFreeHost(g_decode_host);
            g_decode_host = NULL;
            g_decode_dev = NULL;
            return 0;
        }
    }
    memset(g_decode_host, 0, sizeof(*g_decode_host));
    /* Prime the device copy so any first-token kernel that reads s->*
     * before the first captured memcpy fires sees deterministic zeros
     * rather than uninitialized memory.  Outside any graph capture. */
    if (!cuda_ok(cudaMemcpy(g_decode_dev, g_decode_host,
                            sizeof(*g_decode_host),
                            cudaMemcpyHostToDevice),
                 "decode scalars prime")) {
        cudaFree(g_decode_dev);
        cudaFreeHost(g_decode_host);
        g_decode_dev = NULL;
        g_decode_host = NULL;
        return 0;
    }
    cuda_mem_note_alloc(DS4_MEMC_SCALARS_MIRROR, DS4_MEMD_UNIFIED_DEVICE,
                        sizeof(*g_decode_host), sizeof(*g_decode_host));
    cuda_mem_note_alloc(DS4_MEMC_SCALARS_MIRROR, DS4_MEMD_PINNED_HOST,
                        sizeof(*g_decode_host), sizeof(*g_decode_host));
    return 1;
}

extern "C" void ds4_gpu_decode_scalars_cleanup(void) {
    if (g_decode_dev != NULL) {
        cudaFree(g_decode_dev);
        cuda_mem_note_free(DS4_MEMC_SCALARS_MIRROR, DS4_MEMD_UNIFIED_DEVICE,
                           sizeof(*g_decode_host), sizeof(*g_decode_host));
        g_decode_dev = NULL;
    }
    if (g_decode_host != NULL) {
        cudaFreeHost(g_decode_host);
        cuda_mem_note_free(DS4_MEMC_SCALARS_MIRROR, DS4_MEMD_PINNED_HOST,
                           sizeof(*g_decode_host), sizeof(*g_decode_host));
        g_decode_host = NULL;
    }
}

/* Returns the stable device-side struct pointer that callers forward to
 * position-dependent kernel shims.  May return NULL if init failed or
 * was never called; callers should treat that as "skip layer graphs". */
extern "C" const void *ds4_gpu_decode_scalars_device_ptr(void) {
    return (const void *)g_decode_dev;
}

/* Write the host struct in-place for the next replay.  Caller passes:
 *   pos0       -- base sequence position (0 for first decode token, etc.)
 *   raw_cap    -- raw KV ring capacity (model constant)
 *   raw_window -- raw-attention window length (model constant)
 *   ratio      -- compressor ratio (4 for V4 Flash)
 *   n_comp     -- compressed tokens visible this step (caller-computed
 *                 because indexed-attention shortens the count)
 *   flags      -- bit 0: emit FP8 KV this step
 *                 bit 1: indexed-attention path
 *                 bit 2: ratio4 (reserved; informational)
 *   token      -- decode token id this step (read by the hash-mode
 *                 router-select kernels from the device mirror)
 *
 * Outside graph capture this just touches a pinned page; cost is one
 * 32-byte store + a uint32 divmod.  Inside replay it is invisible (the
 * captured memcpy fires from the per-graph schedule).
 *
 * No-ops harmlessly if init has not run; that is the "graphs disabled"
 * path. */
extern "C" void ds4_gpu_decode_scalars_set(
        uint32_t pos0,
        uint32_t raw_cap,
        uint32_t raw_window,
        uint32_t ratio,
        uint32_t n_comp,
        uint32_t flags,
        uint32_t token) {
    if (g_decode_host == NULL) return;
    const uint32_t cap = raw_cap ? raw_cap : 1u;
    const uint32_t r   = ratio   ? ratio   : 1u;
    const uint32_t pos1   = pos0 + 1u;
    const uint32_t n_raw  = (pos1 < raw_window) ? pos1 : raw_window;
    /* raw_start = (pos1 - n_raw) % raw_cap; n_raw <= pos1 so no underflow. */
    const uint32_t raw_start = (pos1 - n_raw) % cap;
    g_decode_host->pos0       = pos0;
    g_decode_host->raw_row    = pos0 % cap;
    g_decode_host->raw_start  = raw_start;
    g_decode_host->n_raw      = n_raw;
    g_decode_host->n_comp     = n_comp;
    g_decode_host->emit_phase = pos0 % r;
    /* comp_row / index_row are NOT touched here -- they're set per-emit by
     * ds4_gpu_decode_scalars_set_emit_rows() and remain valid across the
     * non-emit per-layer steps too (kernels just won't read them). */
    g_decode_host->flags      = flags;
    g_decode_host->token      = token;
}

/* C1 (cont capture): explicit-window variant.  The batched multiseq step
 * computes its raw read-window on the host (metal_graph_raw_window_for_batch
 * semantics, including the raw_cap clamp) and publishes those EXACT values,
 * so substrate-mode kernels reproduce the eager inline args bit-for-bit.
 * comp_row/index_row stay untouched (per-layer substrate carries rows). */
extern "C" void ds4_gpu_decode_scalars_set_ext(
        uint32_t pos0,
        uint32_t raw_row,
        uint32_t raw_start,
        uint32_t n_raw,
        uint32_t n_comp,
        uint32_t emit_phase,
        uint32_t flags,
        uint32_t token) {
    if (g_decode_host == NULL) return;
    g_decode_host->pos0       = pos0;
    g_decode_host->raw_row    = raw_row;
    g_decode_host->raw_start  = raw_start;
    g_decode_host->n_raw      = n_raw;
    g_decode_host->n_comp     = n_comp;
    g_decode_host->emit_phase = emit_phase;
    g_decode_host->flags      = flags;
    g_decode_host->token      = token;
}

/* UNSAFE pending removal in Step 4c.  See plan doc local/docs/
 * ds4_full_layer_graph_capture_plan.html sec 4.2 (P1a).
 *
 * Per-emit setter for the row scalars.  Today called from ds4.c at each
 * per-layer emit step (compressor + indexer); each call mutates a SINGLE
 * pinned host buffer (g_decode_host) shared across all 43 layers.  R6
 * mechanism: the queued async H2D reads its host source at execution
 * time, so the CPU's next-layer set_emit_rows() overwrites the source
 * before the previous layer's memcpy executes.  Bit-identical parity
 * holds today by accident only -- all 43 compressed layers see identical
 * g->layer_n_comp[il] at any ratio-4 emit pos, so the racy overwrite
 * happens to write the same value.  Step 4c migrates the R1 row-view
 * kernels (fp8_kv_quantize_row_kernel, indexer_hadamard_fp4_row_kernel)
 * to read row scalars from the per-layer ds4_layer_scalars substrate
 * and removes these setters.  Do not call from new code. */
extern "C" void ds4_gpu_decode_scalars_set_emit_rows(uint32_t comp_row,
                                                       uint32_t index_row) {
    if (g_decode_host == NULL) return;
    g_decode_host->comp_row  = comp_row;
    g_decode_host->index_row = index_row;
}

/* UNSAFE pending removal in Step 4c.  See plan doc sec 4.2 (P1a) + R6.
 *
 * Per-layer setter for the visible-compressed-token count.  This was the
 * function that originally exhibited R6: writing g_decode_host->n_comp per
 * layer races the GPU's queued async memcpy from the same pinned buffer.
 * Step 4 Commit B fixup-2 (c587d96) stopped calling it; the attention
 * kernel overrides only token-stable scalars (n_raw, raw_start) from the
 * shared struct and keeps n_comp inline.  Retained as a no-op-when-unused
 * declaration only so existing in-tree callers don't accidentally re-
 * introduce the race during the Step 4b/4c transition.  Step 4c migrates
 * n_comp into the per-layer ds4_layer_scalars substrate and removes this
 * setter.  Do not call from new code. */
extern "C" void ds4_gpu_decode_scalars_set_n_comp(uint32_t n_comp) {
    if (g_decode_host == NULL) return;
    g_decode_host->n_comp = n_comp;
}

/* Push the current pinned-host struct contents to the device-side mirror.
 * Called from ds4.c once per decode token, after ds4_gpu_decode_scalars_set
 * and before the per-layer body starts issuing kernels that read
 * g_decode_dev->*.  Issued on ds4_current_stream() so it can either:
 *   - run on the default stream outside capture (pilot path), where it is
 *     ordered before subsequent kernels via the implicit-stream rule, or
 *   - become a captured node inside an outer per-token graph (future
 *     Step 5/6), where the captured-memcpy address-bound semantic lets the
 *     same node propagate each replay's host update to the device.
 *
 * No-op if init never ran; that is the "graphs disabled" path. */
extern "C" int ds4_gpu_decode_scalars_flush(void) {
    if (g_decode_host == NULL || g_decode_dev == NULL) return 1;
    return cuda_ok(cudaMemcpyAsync(g_decode_dev, g_decode_host,
                                   sizeof(*g_decode_host),
                                   cudaMemcpyHostToDevice,
                                   ds4_current_stream()),
                   "decode scalars flush");
}

/* =====================================================================
 * Layer-scalars substrate (Step 4b: R6 fix).
 *
 * See struct ds4_layer_scalars definition near the file top + plan doc
 * sec 15 for the full design rationale.  These functions form the C-
 * callable surface that ds4.c will wire up in Step 4c:
 *
 *   ds4_gpu_decode_layer_scalars_init()         once per GPU session
 *   ds4_gpu_decode_layer_scalars_host()         once per decode token (top)
 *   ds4_gpu_decode_layer_scalars_flush()        once per decode token (after host fill)
 *   ds4_gpu_decode_layer_scalars_device_ptr()   pass to per-layer kernel shims
 *   ds4_gpu_decode_layer_scalars_cleanup()      at GPU teardown
 *
 * No callers in this commit -- Step 4b is the scaffold-only landing.  The
 * shim-side parameter and kernel-side reads come in Step 4c sub-commits
 * R1', C1, C2, I1, I2, A1 (see plan doc sec 16 + 17).
 *
 * Init is idempotent.  Init failure leaves all three globals NULL and
 * returns 0; the caller treats that as "layer-graphs-disabled" and stays
 * on the inline-arg path.  Cleanup is also idempotent. */
extern "C" int ds4_gpu_decode_layer_scalars_init(void) {
    if (g_layer_host[0] != NULL && g_layer_host[1] != NULL && g_layer_dev != NULL) {
        return 1;  /* already initialized */
    }
    const size_t bytes = (size_t)DS4_LAYER_SCALARS_COUNT * sizeof(struct ds4_layer_scalars);
    for (int b = 0; b < 2; ++b) {
        if (g_layer_host[b] == NULL) {
            if (!cuda_ok(cudaHostAlloc((void **)&g_layer_host[b], bytes,
                                       cudaHostAllocDefault),
                         "layer scalars host alloc")) {
                /* Roll back any partial allocations so a retry can re-init
                 * cleanly. */
                for (int c = 0; c < b; ++c) {
                    if (g_layer_host[c]) {
                        cudaFreeHost(g_layer_host[c]);
                        g_layer_host[c] = NULL;
                    }
                }
                return 0;
            }
        }
    }
    if (g_layer_dev == NULL) {
        if (!cuda_ok(cudaMalloc((void **)&g_layer_dev, bytes),
                     "layer scalars dev alloc")) {
            for (int b = 0; b < 2; ++b) {
                if (g_layer_host[b]) {
                    cudaFreeHost(g_layer_host[b]);
                    g_layer_host[b] = NULL;
                }
            }
            g_layer_dev = NULL;
            return 0;
        }
    }
    /* Zero both host buffers so a first-token read of an unwritten slot is
     * deterministic (n_comp=0, comp_row=0, index_row=0, flags=0).  Then
     * prime the device array via a synchronous copy so kernels that read
     * &g_layer_dev[il] before the first per-token flush see the same
     * zeros rather than uninitialized memory.  Outside any graph capture. */
    memset(g_layer_host[0], 0, bytes);
    memset(g_layer_host[1], 0, bytes);
    if (!cuda_ok(cudaMemcpy(g_layer_dev, g_layer_host[0], bytes,
                            cudaMemcpyHostToDevice),
                 "layer scalars prime")) {
        cudaFree(g_layer_dev);
        for (int b = 0; b < 2; ++b) {
            cudaFreeHost(g_layer_host[b]);
            g_layer_host[b] = NULL;
        }
        g_layer_dev = NULL;
        return 0;
    }
    g_layer_dev_idx = 0;
    cuda_mem_note_alloc(DS4_MEMC_SCALARS_MIRROR, DS4_MEMD_UNIFIED_DEVICE,
                        bytes, bytes);
    cuda_mem_note_alloc(DS4_MEMC_SCALARS_MIRROR, DS4_MEMD_PINNED_HOST,
                        2u * bytes, 2u * bytes);
    return 1;
}

extern "C" void ds4_gpu_decode_layer_scalars_cleanup(void) {
    const size_t bytes = (size_t)DS4_LAYER_SCALARS_COUNT *
                         sizeof(struct ds4_layer_scalars);
    if (g_layer_dev != NULL) {
        cudaFree(g_layer_dev);
        cuda_mem_note_free(DS4_MEMC_SCALARS_MIRROR, DS4_MEMD_UNIFIED_DEVICE,
                           bytes, bytes);
        g_layer_dev = NULL;
    }
    for (int b = 0; b < 2; ++b) {
        if (g_layer_host[b] != NULL) {
            cudaFreeHost(g_layer_host[b]);
            cuda_mem_note_free(DS4_MEMC_SCALARS_MIRROR, DS4_MEMD_PINNED_HOST,
                               bytes, bytes);
            g_layer_host[b] = NULL;
        }
    }
    g_layer_dev_idx = 0;
}

/* Returns the stable device-array base pointer.  Callers in Step 4c will
 * compute per-layer pointers as `(const struct ds4_layer_scalars *)
 * device_ptr + il` and forward to per-layer kernel shims.  May return NULL
 * if init failed or was never called; callers should treat that as
 * "layer-graphs-disabled" and fall back to inline-arg paths. */
extern "C" const void *ds4_gpu_decode_layer_scalars_device_ptr(void) {
    return (const void *)g_layer_dev;
}

/* Returns the currently-active host buffer.  Caller writes all
 * DS4_LAYER_SCALARS_COUNT entries before calling _flush().  The pointer
 * rotates between two stable addresses each token; callers must NOT
 * cache it across token boundaries.  Returns NULL if init failed. */
extern "C" void *ds4_gpu_decode_layer_scalars_host(void) {
    return (void *)g_layer_host[g_layer_dev_idx];
}

/* Per-layer setter for the active host buffer.  Writes all four fields
 * of g_layer_host[idx][il] in one call.  The struct definition stays
 * private to ds4_cuda.cu (the public header exposes only this setter);
 * callers in ds4.c populate the 43 entries via a tight loop over `il`.
 *
 * No-op if init never ran.  Called once per layer per token; callers
 * MUST call _flush() once after all entries are written so the H2D
 * memcpy fires before the per-layer kernels read from the device side.
 *
 * Argument order (PC3-revised): the two counts first (attention then
 * indexer -- attention is the most common reader), then the two emit-
 * row fields paired the same way.  The old `flags` arg is removed --
 * its bit 0 (emit_this_step) and bit 1 (indexed_active) had no in-tree
 * consumers; recompute on-demand from n_comp / n_index_comp if needed. */
extern "C" void ds4_gpu_decode_layer_scalars_set(
        uint32_t il,
        uint32_t n_comp,
        uint32_t n_index_comp,
        uint32_t comp_row,
        uint32_t index_row) {
    if (g_layer_host[g_layer_dev_idx] == NULL ||
        il >= DS4_LAYER_SCALARS_COUNT) return;
    struct ds4_layer_scalars *e = &g_layer_host[g_layer_dev_idx][il];
    e->n_comp       = n_comp;
    e->n_index_comp = n_index_comp;
    e->comp_row     = comp_row;
    e->index_row    = index_row;
}

/* Push the active host buffer to the device array and rotate the index.
 * Issues one cudaMemcpyAsync of DS4_LAYER_SCALARS_COUNT * 16 bytes on
 * ds4_current_stream() -- today eager on stream 0, under Step 6's wider
 * per-token capture may become a captured node.
 *
 * The index rotation happens AFTER queueing the memcpy: the memcpy node
 * has the current g_layer_host[idx] address burned into its source-pointer
 * arg at queue time, and the GPU dereferences that address at execution
 * time.  Rotating idx now only affects the NEXT token's CPU write target;
 * the GPU still reads from the buffer it was just queued against.  See
 * plan doc sec 15.3 for the full ordering proof.
 *
 * Returns 1 on success / no-op (init not run), 0 on infrastructure
 * failure. */
extern "C" int ds4_gpu_decode_layer_scalars_flush(void) {
    if (g_layer_host[g_layer_dev_idx] == NULL || g_layer_dev == NULL) return 1;
    const size_t bytes = (size_t)DS4_LAYER_SCALARS_COUNT * sizeof(struct ds4_layer_scalars);
    int ok = cuda_ok(cudaMemcpyAsync(g_layer_dev, g_layer_host[g_layer_dev_idx],
                                     bytes,
                                     cudaMemcpyHostToDevice,
                                     ds4_current_stream()),
                     "layer scalars flush");
    if (ok) g_layer_dev_idx ^= 1;
    return ok;
}

/* C2 Inc2: per-row emit-row table (see the struct block above).  Same
 * init/set/flush discipline as the per-layer scalars; ~2.7 KB per flush. */
extern "C" int ds4_gpu_decode_row_scalars_init(void) {
    if (g_row_host[0] != NULL && g_row_host[1] != NULL && g_row_dev != NULL) {
        return 1;
    }
    const size_t bytes = (size_t)DS4_ROW_SCALARS_MAX_ROWS *
                         DS4_LAYER_SCALARS_COUNT * sizeof(struct ds4_row_scalars);
    for (int b = 0; b < 2; ++b) {
        if (g_row_host[b] == NULL) {
            if (!cuda_ok(cudaHostAlloc((void **)&g_row_host[b], bytes,
                                       cudaHostAllocDefault),
                         "row scalars host alloc")) {
                for (int c = 0; c < b; ++c) {
                    if (g_row_host[c]) { cudaFreeHost(g_row_host[c]); g_row_host[c] = NULL; }
                }
                return 0;
            }
        }
    }
    if (g_row_dev == NULL) {
        if (!cuda_ok(cudaMalloc((void **)&g_row_dev, bytes),
                     "row scalars dev alloc")) {
            for (int b = 0; b < 2; ++b) {
                if (g_row_host[b]) { cudaFreeHost(g_row_host[b]); g_row_host[b] = NULL; }
            }
            g_row_dev = NULL;
            return 0;
        }
    }
    memset(g_row_host[0], 0, bytes);
    memset(g_row_host[1], 0, bytes);
    if (!cuda_ok(cudaMemcpy(g_row_dev, g_row_host[0], bytes,
                            cudaMemcpyHostToDevice),
                 "row scalars prime")) {
        cudaFree(g_row_dev);
        for (int b = 0; b < 2; ++b) {
            cudaFreeHost(g_row_host[b]);
            g_row_host[b] = NULL;
        }
        g_row_dev = NULL;
        return 0;
    }
    g_row_dev_idx = 0;
    cuda_mem_note_alloc(DS4_MEMC_SCALARS_MIRROR, DS4_MEMD_UNIFIED_DEVICE,
                        bytes, bytes);
    cuda_mem_note_alloc(DS4_MEMC_SCALARS_MIRROR, DS4_MEMD_PINNED_HOST,
                        2u * bytes, 2u * bytes);
    return 1;
}

extern "C" void ds4_gpu_decode_row_scalars_set(
        uint32_t row,
        uint32_t il,
        uint32_t comp_row,
        uint32_t index_row) {
    if (g_row_host[g_row_dev_idx] == NULL ||
        row >= DS4_ROW_SCALARS_MAX_ROWS ||
        il >= DS4_LAYER_SCALARS_COUNT) return;
    struct ds4_row_scalars *e =
        &g_row_host[g_row_dev_idx][row * DS4_LAYER_SCALARS_COUNT + il];
    e->comp_row  = comp_row;
    e->index_row = index_row;
}

extern "C" int ds4_gpu_decode_row_scalars_flush(void) {
    if (g_row_host[g_row_dev_idx] == NULL || g_row_dev == NULL) return 1;
    const size_t bytes = (size_t)DS4_ROW_SCALARS_MAX_ROWS *
                         DS4_LAYER_SCALARS_COUNT * sizeof(struct ds4_row_scalars);
    int ok = cuda_ok(cudaMemcpyAsync(g_row_dev, g_row_host[g_row_dev_idx],
                                     bytes,
                                     cudaMemcpyHostToDevice,
                                     ds4_current_stream()),
                     "row scalars flush");
    if (ok) g_row_dev_idx ^= 1;
    return ok;
}

static double cuda_wall_sec(void) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    return (double)ts.tv_sec + (double)ts.tv_nsec * 1.0e-9;
}

static int cuda_model_load_progress_enabled(void) {
    return !cuda_weight_env().verbose;
}

static void cuda_model_load_progress_reset(void) {
    g_model_load_progress_next = 0;
    g_model_load_progress_last = 0.0;
    g_model_load_progress_started = 0;
    g_model_load_progress_tty = 0;
}

static void cuda_model_load_progress_note(uint64_t cached_bytes) {
    if (!cuda_model_load_progress_enabled()) return;

    const double now = cuda_wall_sec();
    if (!g_model_load_progress_started) {
        g_model_load_progress_started = 1;
        g_model_load_progress_tty = isatty(STDERR_FILENO) != 0;
        g_model_load_progress_next = (g_model_load_progress_tty ? 2ull : 16ull) *
                                     1024ull * 1024ull * 1024ull;
        g_model_load_progress_last = now;
        if (g_model_load_progress_tty) {
            fprintf(stderr, "ds4: CUDA loading model tensors into device cache: 0.00 GiB");
        } else {
            fprintf(stderr, "ds4: CUDA loading model tensors into device cache\n");
        }
    }

    if (cached_bytes < g_model_load_progress_next &&
        now - g_model_load_progress_last < (g_model_load_progress_tty ? 2.0 : 10.0)) {
        return;
    }

    if (g_model_load_progress_tty) {
        fprintf(stderr, "\rds4: CUDA loading model tensors into device cache: %.2f GiB",
                (double)cached_bytes / 1073741824.0);
    } else {
        fprintf(stderr, "ds4: CUDA loading model tensors %.2f GiB cached\n",
                (double)cached_bytes / 1073741824.0);
    }
    fflush(stderr);
    g_model_load_progress_last = now;
    const uint64_t step = (g_model_load_progress_tty ? 2ull : 16ull) *
                          1024ull * 1024ull * 1024ull;
    while (g_model_load_progress_next <= cached_bytes) {
        g_model_load_progress_next += step;
    }
}

static int cuda_model_prefetch_range(const void *model_map, uint64_t model_size, uint64_t map_offset, uint64_t map_size) {
    if (!model_map || map_size == 0 || map_offset > model_size || map_size > model_size - map_offset) return 0;
    if (getenv("DS4_CUDA_NO_MODEL_PREFETCH") != NULL ||
        getenv("DS4_CUDA_COPY_MODEL") != NULL ||
        getenv("DS4_CUDA_WEIGHT_CACHE") != NULL ||
        getenv("DS4_CUDA_WEIGHT_PRELOAD") != NULL) {
        return 0;
    }

    int device = 0;
    if (cudaGetDevice(&device) != cudaSuccess) {
        (void)cudaGetLastError();
        return 0;
    }

    int pageable = 0;
    cudaError_t err = cudaDeviceGetAttribute(&pageable, cudaDevAttrPageableMemoryAccess, device);
    if (err != cudaSuccess || !pageable) {
        (void)cudaGetLastError();
        return 0;
    }
    cudaMemLocation loc;
    memset(&loc, 0, sizeof(loc));
    loc.type = cudaMemLocationTypeDevice;
    loc.id = device;

    const long page_sz_l = sysconf(_SC_PAGESIZE);
    const uint64_t page_sz = page_sz_l > 0 ? (uint64_t)page_sz_l : 4096u;
    const uintptr_t host_addr = (uintptr_t)((const char *)model_map + map_offset);
    const uintptr_t pre_addr = host_addr & ~(uintptr_t)(page_sz - 1u);
    const uint64_t pre_delta = (uint64_t)(host_addr - pre_addr);
    const uint64_t pre_bytes = (pre_delta + map_size + page_sz - 1u) & ~(page_sz - 1u);
    void *pre_ptr = (void *)pre_addr;

    const double t0 = cuda_wall_sec();
    err = cudaMemAdvise(pre_ptr, (size_t)pre_bytes, cudaMemAdviseSetReadMostly, loc);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA model read-mostly advise skipped: %s\n", cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }
    err = cudaMemAdvise(pre_ptr, (size_t)pre_bytes, cudaMemAdviseSetPreferredLocation, loc);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA model preferred-location advise skipped: %s\n", cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }

    if (!g_model_prefetch_stream) {
        err = cudaStreamCreateWithFlags(&g_model_prefetch_stream, cudaStreamNonBlocking);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model prefetch stream creation skipped: %s\n", cudaGetErrorString(err));
            (void)cudaGetLastError();
            return 0;
        }
    }

    err = cudaMemPrefetchAsync(pre_ptr, (size_t)pre_bytes, loc, 0, g_model_prefetch_stream);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA model prefetch skipped: %s\n", cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }
    if (getenv("DS4_CUDA_MODEL_PREFETCH_SYNC") != NULL) {
        err = cudaStreamSynchronize(g_model_prefetch_stream);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model prefetch sync failed: %s\n", cudaGetErrorString(err));
            (void)cudaGetLastError();
            return 0;
        }
    }
    const double t1 = cuda_wall_sec();
    fprintf(stderr,
            "ds4: CUDA ATS/HMM prefetch queued %.2f GiB of model tensors in %.3fs\n",
            (double)map_size / 1073741824.0,
            t1 - t0);
    g_model_hmm_direct = 1;
    return 1;
}

static uint64_t cuda_model_copy_chunk_bytes(void) {
    return cuda_weight_env().copy_chunk_bytes;
}

static void cuda_model_discard_source_pages(const void *model_map, uint64_t model_size, uint64_t offset, uint64_t bytes) {
#if defined(POSIX_MADV_DONTNEED)
    if (cuda_weight_env().keep_model_pages || !model_map || bytes == 0 || offset > model_size) return;
    if (bytes > model_size - offset) bytes = model_size - offset;
    const long page_sz_l = sysconf(_SC_PAGESIZE);
    const uint64_t page_sz = page_sz_l > 0 ? (uint64_t)page_sz_l : 4096u;
    const uintptr_t h0 = (uintptr_t)((const char *)model_map + offset);
    const uintptr_t h1 = h0 + bytes;
    const uintptr_t p0 = h0 & ~(uintptr_t)(page_sz - 1u);
    const uintptr_t p1 = (h1 + page_sz - 1u) & ~(uintptr_t)(page_sz - 1u);
    if (p1 > p0) (void)posix_madvise((void *)p0, (size_t)(p1 - p0), POSIX_MADV_DONTNEED);
#else
    (void)model_map;
    (void)model_size;
    (void)offset;
    (void)bytes;
#endif
}

static void cuda_model_drop_file_pages(uint64_t offset, uint64_t bytes) {
#if defined(POSIX_FADV_DONTNEED)
    if (g_model_fd < 0 || cuda_weight_env().keep_model_pages || bytes == 0) return;
    (void)posix_fadvise(g_model_fd, (off_t)offset, (off_t)bytes, POSIX_FADV_DONTNEED);
#else
    (void)offset;
    (void)bytes;
#endif
}

static uint64_t cuda_round_down(uint64_t v, uint64_t align) {
    if (align <= 1) return v;
    return (v / align) * align;
}

static uint64_t cuda_round_up(uint64_t v, uint64_t align) {
    if (align <= 1) return v;
    const uint64_t rem = v % align;
    return rem == 0 ? v : v + (align - rem);
}

static void *cuda_align_ptr(void *ptr, uint64_t align) {
    if (align <= 1) return ptr;
    uintptr_t p = (uintptr_t)ptr;
    uintptr_t a = (uintptr_t)align;
    return (void *)(((p + a - 1u) / a) * a);
}

/* memgov D1b-2 fix: release the pinned staging slots.  The eager pass
 * calls this when its pass ends so no pinned residue survives to the
 * bank fit (the pre-D1b walk had none); the lazy tier re-allocates on
 * its first miss through the normal grow path below. */
static void cuda_model_stage_pool_release(void) {
    for (size_t i = 0; i < 4; i++) {
        if (g_model_stage_event[i]) {
            (void)cudaEventDestroy(g_model_stage_event[i]);
            g_model_stage_event[i] = NULL;
        }
        if (g_model_stage_raw[i]) {
            (void)cudaFreeHost(g_model_stage_raw[i]);
            cuda_mem_note_free(DS4_MEMC_STAGE_PIN, DS4_MEMD_PINNED_HOST,
                               g_mem_stage_slot_bytes[i],
                               g_mem_stage_slot_bytes[i]);
            g_mem_stage_slot_bytes[i] = 0;
            g_model_stage_raw[i] = NULL;
            g_model_stage[i] = NULL;
        }
    }
    g_model_stage_bytes = 0;
}

static int cuda_model_stage_pool_alloc(uint64_t bytes) {
    if (g_model_stage_bytes >= bytes) return 1;
    cuda_model_stage_pool_release();
    if (!g_model_upload_stream) {
        cudaError_t err = cudaStreamCreateWithFlags(&g_model_upload_stream, cudaStreamNonBlocking);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model upload stream creation failed: %s\n", cudaGetErrorString(err));
            (void)cudaGetLastError();
            return 0;
        }
    }
    for (size_t i = 0; i < 4; i++) {
        cudaError_t err = cudaMallocHost(&g_model_stage_raw[i], (size_t)bytes);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA pinned model staging allocation failed: %s\n", cudaGetErrorString(err));
            (void)cudaGetLastError();
            return 0;
        }
        cuda_mem_note_alloc(DS4_MEMC_STAGE_PIN, DS4_MEMD_PINNED_HOST,
                            bytes, bytes);
        g_mem_stage_slot_bytes[i] = bytes;
        g_model_stage[i] = cuda_align_ptr(g_model_stage_raw[i], g_model_direct_align);
        err = cudaEventCreateWithFlags(&g_model_stage_event[i], cudaEventDisableTiming);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model staging event creation failed: %s\n", cudaGetErrorString(err));
            (void)cudaGetLastError();
            return 0;
        }
    }
    g_model_stage_bytes = bytes;
    return 1;
}

static int cuda_pread_full(int fd, void *buf, uint64_t bytes, uint64_t offset) {
    uint64_t done = 0;
    while (done < bytes) {
        const size_t n_req = (bytes - done > (uint64_t)SSIZE_MAX) ? (size_t)SSIZE_MAX : (size_t)(bytes - done);
        ssize_t n = pread(fd, (char *)buf + done, n_req, (off_t)(offset + done));
        if (n < 0) {
            if (errno == EINTR) continue;
            return 0;
        }
        if (n == 0) return 0;
        done += (uint64_t)n;
    }
    return 1;
}

static int cuda_model_stage_read(void *stage, uint64_t stage_bytes,
                                 uint64_t offset, uint64_t bytes,
                                 const char **payload) {
    *payload = (const char *)stage;
#if defined(__linux__) && defined(O_DIRECT)
    if (g_model_direct_fd >= 0 && g_model_direct_align > 1 && g_model_file_size != 0) {
        const uint64_t aligned_off = cuda_round_down(offset, g_model_direct_align);
        const uint64_t delta = offset - aligned_off;
        uint64_t read_size = cuda_round_up(delta + bytes, g_model_direct_align);
        if (aligned_off <= g_model_file_size &&
            read_size <= stage_bytes &&
            read_size <= g_model_file_size - aligned_off) {
            const int saved_errno = errno;
            errno = 0;
            if (cuda_pread_full(g_model_direct_fd, stage, read_size, aligned_off)) {
                *payload = (const char *)stage + delta;
                errno = saved_errno;
                return 1;
            }
            const int direct_errno = errno;
            if (direct_errno == EINVAL || direct_errno == EFAULT || direct_errno == ENOTSUP || direct_errno == EOPNOTSUPP) {
                if (cuda_weight_env().verbose) {
                    fprintf(stderr, "ds4: CUDA direct model read disabled: %s\n", strerror(direct_errno));
                }
                (void)close(g_model_direct_fd);
                g_model_direct_fd = -1;
                g_model_direct_align = 1;
            }
            errno = direct_errno;
        }
    }
#else
    (void)stage_bytes;
#endif
    return cuda_pread_full(g_model_fd, stage, bytes, offset);
}

static uint64_t cuda_model_cache_limit_bytes(void) {
    return cuda_weight_env().cache_limit_bytes;
}

/* True iff model_map's expert raws were REPLACED by complete in-process
 * aligned artifacts (ds4_gpu_build_derived_artifacts).  Gates the self-load
 * fast-tier memory shape: skip the whole-model host registration and uncap
 * the device-copy budget for this map's remaining raw spans, so residency
 * lands exactly where a weight-server import puts it (device artifacts +
 * device copies of the non-expert raws; expert raws stay cold on disk). */
static int cuda_model_map_replaces_complete(const void *model_map) {
    if (!g_derived_replaces_complete || !model_map) return 0;
    for (const cuda_derived_range &r : g_derived_ranges) {
        if (r.host_base == model_map &&
            (r.kind == CUDA_DERIVED_IQ2_XXS_ALIGNED_MOE ||
             r.kind == CUDA_DERIVED_Q2_K_ALIGNED_MOE)) {
            return 1;
        }
    }
    return 0;
}

/* memgov D1a-3: the unit compiler's policy-provenance input. */
extern "C" int ds4_gpu_model_map_replaces_complete(const void *model_map) {
    return cuda_model_map_replaces_complete(model_map);
}

static uint64_t cuda_model_arena_chunk_bytes(uint64_t need) {
    uint64_t bytes = cuda_weight_env().arena_chunk_mb * 1048576ull;
    if (bytes < need) {
        const uint64_t align = 256ull * 1048576ull;
        bytes = (need + align - 1u) & ~(align - 1u);
    }
    return bytes;
}

// Returns 1 iff this process should serve its own VMM-backed weight arena.
// Cached after first call. Hard-gated when the worker is already importing
// ranges from ds4_weight_server (DS4_CUDA_WEIGHT_IPC_MANIFEST) -- the sidecar
// is then authoritative and a second VMM allocation would double-book the
// model. Soft-gated by DS4_CUDA_VMM_ARENA=0 as an escape hatch (profiler /
// driver quirks). On hardware that lacks VMM, the probe records 0 and the
// caller transparently falls back to the cudaMalloc arena below.
static int cuda_vmm_arena_supported(void) {
    if (g_vmm_supported != -1) return g_vmm_supported;
    const cuda_weight_env_t &we = cuda_weight_env();
    if (we.vmm_arena_off) { g_vmm_supported = 0; return 0; }
    if (we.ipc_manifest) { g_vmm_supported = 0; return 0; }
    if (!driver_ok(cuInit(0), "init for VMM probe")) { g_vmm_supported = 0; return 0; }
    int dev = 0;
    if (cudaGetDevice(&dev) != cudaSuccess) { (void)cudaGetLastError(); g_vmm_supported = 0; return 0; }
    CUdevice cu_dev;
    if (cuDeviceGet(&cu_dev, dev) != CUDA_SUCCESS) { g_vmm_supported = 0; return 0; }
    int vmm = 0;
    if (cuDeviceGetAttribute(&vmm, CU_DEVICE_ATTRIBUTE_VIRTUAL_MEMORY_MANAGEMENT_SUPPORTED, cu_dev) != CUDA_SUCCESS || !vmm) {
        g_vmm_supported = 0;
        return 0;
    }
    CUmemAllocationProp prop;
    memset(&prop, 0, sizeof(prop));
    prop.type = CU_MEM_ALLOCATION_TYPE_PINNED;
    prop.location.type = CU_MEM_LOCATION_TYPE_DEVICE;
    prop.location.id = dev;
    prop.requestedHandleTypes = CU_MEM_HANDLE_TYPE_NONE;
    size_t gran = 0;
    if (cuMemGetAllocationGranularity(&gran, &prop, CU_MEM_ALLOC_GRANULARITY_RECOMMENDED) != CUDA_SUCCESS || gran == 0) {
        g_vmm_supported = 0;
        return 0;
    }
    g_vmm_granularity = (uint64_t)gran;
    g_vmm_supported = 1;
    int integrated = 0;
    (void)cudaDeviceGetAttribute(&integrated, cudaDevAttrIntegrated, dev);
    if (we.verbose) {
        fprintf(stderr,
                "ds4: CUDA VMM arena enabled (integrated=%d granularity=%llu)\n",
                integrated, (unsigned long long)g_vmm_granularity);
    }
    return 1;
}

// Per-call VMM chunk size. By default we match the request size exactly,
// granularity-rounded -- this mirrors ds4_weight_server, which gives one
// VMM allocation per coalesced plan range (138 ranges, ~80.77 GiB
// allocated for a 80.76 GiB model -- 0.01% overhead). A 1024 MiB minimum
// would have left ~500 MiB unused per range and ballooned VRAM use by
// ~70% for the V4 Flash IQ2 model.
//
// DS4_CUDA_VMM_ARENA_CHUNK_MB is a *minimum* if set explicitly: lets
// users coalesce small allocations into fewer VMM mappings if the
// driver's per-process mapping limit becomes a concern.
static uint64_t cuda_vmm_arena_chunk_bytes(uint64_t need) {
    uint64_t bytes = cuda_weight_env().vmm_chunk_mb * 1048576ull;
    if (bytes < need) bytes = need;
    if (g_vmm_granularity > 1) {
        const uint64_t g = g_vmm_granularity;
        bytes = ((bytes + g - 1u) / g) * g;
    }
    return bytes;
}

// Bump-allocate `bytes` from a VMM-backed weight arena. Falls back to NULL
// on any driver error so callers can transparently retry via the existing
// cudaMalloc arena. Read-only PROT for the mapped range; weight upload
// happens through a separate PROT_READWRITE alias the caller obtains by
// running the same pinned-staged copy path the cudaMalloc arena uses.
static char *cuda_vmm_arena_alloc(const void *model_map, uint64_t bytes,
                                  const char *what) {
    if (bytes == 0) return NULL;
    if (!cuda_vmm_arena_supported()) return NULL;
    const uint64_t align = 256u;
    const uint64_t aligned = (bytes + align - 1u) & ~(align - 1u);

    // Re-use space in an existing arena chunk if it fits.
    for (cuda_vmm_arena &a : g_vmm_arenas) {
        const uint64_t used_aligned = (a.used + align - 1u) & ~(align - 1u);
        if (used_aligned <= a.alloc_bytes && aligned <= a.alloc_bytes - used_aligned) {
            char *ptr = (char *)(uintptr_t)(a.va + used_aligned);
            a.used = used_aligned + aligned;
            cuda_mem_note_alloc_srcidx(DS4_MEMC_WEIGHT_ARENA,
                                       DS4_MEMD_UNIFIED_DEVICE,
                                       aligned, 0, a.src);
            return ptr;
        }
    }

    const uint64_t chunk_bytes = cuda_vmm_arena_chunk_bytes(aligned);
    int dev = 0;
    if (cudaGetDevice(&dev) != cudaSuccess) { (void)cudaGetLastError(); return NULL; }

    CUmemAllocationProp prop;
    memset(&prop, 0, sizeof(prop));
    prop.type = CU_MEM_ALLOCATION_TYPE_PINNED;
    prop.location.type = CU_MEM_LOCATION_TYPE_DEVICE;
    prop.location.id = dev;
    prop.requestedHandleTypes = CU_MEM_HANDLE_TYPE_NONE;

    CUmemGenericAllocationHandle handle;
    memset(&handle, 0, sizeof(handle));
    if (!driver_ok(cuMemCreate(&handle, (size_t)chunk_bytes, &prop, 0),
                   "VMM arena create")) {
        // Stop trying VMM for the rest of the run so we don't spam logs.
        g_vmm_supported = 0;
        return NULL;
    }
    CUdeviceptr va = 0;
    if (!driver_ok(cuMemAddressReserve(&va, (size_t)chunk_bytes,
                                       (size_t)g_vmm_granularity, 0, 0),
                   "VMM arena reserve")) {
        (void)cuMemRelease(handle);
        g_vmm_supported = 0;
        return NULL;
    }
    if (!driver_ok(cuMemMap(va, (size_t)chunk_bytes, 0, handle, 0),
                   "VMM arena map")) {
        (void)cuMemAddressFree(va, (size_t)chunk_bytes);
        (void)cuMemRelease(handle);
        g_vmm_supported = 0;
        return NULL;
    }
    CUmemAccessDesc access;
    memset(&access, 0, sizeof(access));
    access.location.type = CU_MEM_LOCATION_TYPE_DEVICE;
    access.location.id = dev;
    // Read-write: the weight upload path writes through this same VA before
    // any kernel reads, and the existing matmul callers treat weights as
    // read-only by convention. Matches ds4_weight_server's owner-side path.
    access.flags = CU_MEM_ACCESS_FLAGS_PROT_READWRITE;
    if (!driver_ok(cuMemSetAccess(va, (size_t)chunk_bytes, &access, 1),
                   "VMM arena set access")) {
        (void)cuMemUnmap(va, (size_t)chunk_bytes);
        (void)cuMemAddressFree(va, (size_t)chunk_bytes);
        (void)cuMemRelease(handle);
        g_vmm_supported = 0;
        return NULL;
    }

    cuda_vmm_arena a;
    a.handle = handle;
    a.va = va;
    a.alloc_bytes = chunk_bytes;
    a.used = aligned;
    a.src = cuda_mem_src_index(model_map);
    g_vmm_arenas.push_back(a);
    cuda_mem_note_alloc_srcidx(DS4_MEMC_WEIGHT_ARENA, DS4_MEMD_UNIFIED_DEVICE,
                               aligned, chunk_bytes, a.src);

    if (cuda_weight_env().verbose) {
        uint64_t total = 0;
        for (const cuda_vmm_arena &it : g_vmm_arenas) total += it.alloc_bytes;
        fprintf(stderr,
                "ds4: CUDA VMM arena allocated %.2f MiB for %s (chunks=%zu total=%.2f GiB)\n",
                (double)chunk_bytes / 1048576.0,
                what ? what : "weights",
                g_vmm_arenas.size(),
                (double)total / 1073741824.0);
    }
    return (char *)(uintptr_t)va;
}

static void cuda_vmm_arenas_release_all(void) {
    for (cuda_vmm_arena &a : g_vmm_arenas) {
        if (a.va && a.alloc_bytes) {
            (void)cuMemUnmap(a.va, (size_t)a.alloc_bytes);
            (void)cuMemAddressFree(a.va, (size_t)a.alloc_bytes);
        }
        if (a.handle) (void)cuMemRelease(a.handle);
        cuda_mem_note_free_srcidx(DS4_MEMC_WEIGHT_ARENA, DS4_MEMD_UNIFIED_DEVICE,
                                  a.used, a.alloc_bytes, a.src);
    }
    g_vmm_arenas.clear();
}

// R5 Inc1b: demand-mapped reserved tensors.  ds4_gpu_tensor_reserve() takes
// the full VIRTUAL range up front (so views, kernel pointer arithmetic, and
// uniform per-bank strides are byte-identical to an eager cudaMalloc slab)
// but maps NO physical pages; ds4_gpu_tensor_ensure() maps granularity-sized
// pages on demand as the caller is about to write.  Distinct from the weight
// arena above: that one is a bump allocator that maps everything at creation
// and is policy-gated off when weights are imported (DS4_CUDA_WEIGHT_IPC_
// MANIFEST) -- exactly how production clients run -- so demand reservation
// keeps its own capability probe with no weight-policy entanglement.
// Registry-keyed by VA range: ensure()/resident() accept ANY tensor (slab
// base, view at a bank offset, eager allocation) and resolve through the
// containing reservation; eager tensors fall through as mapped no-ops.
// Single-threaded by contract, like every other graph-state mutation: the
// engine's forward/admit loop is the only caller.
struct cuda_vmm_demand {
    CUdeviceptr va;
    uint64_t    span;        // page-rounded reserved bytes
    uint64_t    page;        // mapping granularity at reserve time
    uint64_t    mapped;      // resident bytes (page multiples)
    std::vector<CUmemGenericAllocationHandle> pages;  // 0 = unmapped
};
static std::vector<cuda_vmm_demand *> g_vmm_demand;
static int g_vmm_demand_caps = -1;       // -1 unprobed, 0 no, 1 yes
static uint64_t g_vmm_demand_page = 0;   // minimum mapping granularity

extern "C" uint64_t ds4_gpu_vmm_demand_page(void) {
    if (g_vmm_demand_caps != -1) return g_vmm_demand_caps ? g_vmm_demand_page : 0;
    g_vmm_demand_caps = 0;
    if (!driver_ok(cuInit(0), "init for VMM demand probe")) return 0;
    int dev = 0;
    if (cudaGetDevice(&dev) != cudaSuccess) { (void)cudaGetLastError(); return 0; }
    CUdevice cu_dev;
    if (cuDeviceGet(&cu_dev, dev) != CUDA_SUCCESS) return 0;
    int vmm = 0;
    if (cuDeviceGetAttribute(&vmm, CU_DEVICE_ATTRIBUTE_VIRTUAL_MEMORY_MANAGEMENT_SUPPORTED, cu_dev) != CUDA_SUCCESS || !vmm)
        return 0;
    CUmemAllocationProp prop;
    memset(&prop, 0, sizeof(prop));
    prop.type = CU_MEM_ALLOCATION_TYPE_PINNED;
    prop.location.type = CU_MEM_LOCATION_TYPE_DEVICE;
    prop.location.id = dev;
    prop.requestedHandleTypes = CU_MEM_HANDLE_TYPE_NONE;
    size_t gran = 0;
    // MINIMUM, not RECOMMENDED: the resident floor of a sparse cache scales
    // with the page size, so smaller is strictly better here.
    if (cuMemGetAllocationGranularity(&gran, &prop, CU_MEM_ALLOC_GRANULARITY_MINIMUM) != CUDA_SUCCESS || gran == 0)
        return 0;
    g_vmm_demand_page = (uint64_t)gran;
    g_vmm_demand_caps = 1;
    return g_vmm_demand_page;
}

// The reservation containing [p+offset, p+offset+bytes), or NULL (eager).
static cuda_vmm_demand *cuda_vmm_demand_find(const void *p, uint64_t offset, uint64_t bytes) {
    const uint64_t a = (uint64_t)(uintptr_t)p + offset;
    for (cuda_vmm_demand *d : g_vmm_demand)
        if (a >= (uint64_t)d->va && a + bytes <= (uint64_t)d->va + d->span)
            return d;
    return NULL;
}

static char *cuda_model_arena_alloc(const void *model_map, uint64_t bytes,
                                    const char *what) {
    if (bytes == 0) return NULL;
    if (g_model_cache_full) return NULL;
    const uint64_t align = 256u;
    const uint64_t aligned = (bytes + align - 1u) & ~(align - 1u);

    for (cuda_model_arena &a : g_model_arenas) {
        const uint64_t used = (a.used + align - 1u) & ~(align - 1u);
        if (used <= a.bytes && aligned <= a.bytes - used) {
            char *ptr = a.device_ptr + used;
            a.used = used + aligned;
            cuda_mem_note_alloc_srcidx(DS4_MEMC_WEIGHT_ARENA,
                                       DS4_MEMD_UNIFIED_DEVICE,
                                       aligned, 0, a.src);
            return ptr;
        }
    }

    const uint64_t limit = cuda_model_cache_limit_bytes();
    if (g_model_range_bytes > limit || aligned > limit - g_model_range_bytes) return NULL;

    const uint64_t chunk = cuda_model_arena_chunk_bytes(aligned);
    void *dev = NULL;
    cudaError_t err = cudaMalloc(&dev, (size_t)chunk);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA model arena alloc failed for %s (%.2f MiB chunk): %s\n",
                what ? what : "weights",
                (double)chunk / 1048576.0,
                cudaGetErrorString(err));
        (void)cudaGetLastError();
        g_model_cache_full = 1;
        return NULL;
    }
    g_model_arenas.push_back({(char *)dev, chunk, aligned,
                              cuda_mem_src_index(model_map)});
    /* Census: chunk commit + this call's bump.  Bump asks accumulate on
     * `requested`; the chunk's rounding tail is the cell's slack. */
    cuda_mem_note_alloc_srcidx(DS4_MEMC_WEIGHT_ARENA, DS4_MEMD_UNIFIED_DEVICE,
                               aligned, chunk, g_model_arenas.back().src);
    if (cuda_weight_env().verbose) {
        uint64_t arena_bytes = 0;
        for (const cuda_model_arena &a : g_model_arenas) arena_bytes += a.bytes;
        fprintf(stderr, "ds4: CUDA model arena allocated %.2f MiB (arenas %.2f GiB)\n",
                (double)chunk / 1048576.0,
                (double)arena_bytes / 1073741824.0);
    }
    return (char *)dev;
}

/* A raw host pointer is safe for kernels only after CUDA owns, registered, or
 * HMM-prefetched the mapping.  Otherwise let the caller try per-range mapping
 * or a device copy instead of surfacing an async illegal access later. */
static const char *cuda_model_direct_fallback_ptr(const void *model_map, uint64_t offset) {
    if (cuda_model_current_direct_available(model_map) ||
        (model_map == g_model_host_base && g_model_hmm_direct) ||
        (model_map && model_map == g_model_coherent_direct_map) ||
        cuda_weight_env().direct_model) {
        return cuda_model_ptr(model_map, offset);
    }
    return NULL;
}

/* --------------------------------------------------------------------
 * memgov D1b-1: ONE staged upload pipeline (plan §5.4).
 *
 * Both promotion modes copy source bytes into a device carve through
 * the same 4-slot pinned staging pipeline; the source fill is the only
 * per-map difference: fd reads for the map that owns g_model_fd, a
 * host-pointer memcpy from the mapped file for every other map — which
 * the fd tier could never serve.
 *
 * `direct_discard` selects the SOURCE MODE — the two behaviors are
 * policy-coupled by design:
 *   0 (eager default): memcpy FROM THE MAP, no discard — the pre-D1b
 *     walk's exact mechanism, so the boot faults MAPPED file pages and
 *     the MemAvailable trajectory the bank fit samples mid-boot is
 *     control-identical by construction.  The D1b-2 close probes
 *     measured both alternatives deflating the fit input: O_DIRECT
 *     leaves no page-cache credit at all (~0.8 GiB, ~2 banks), and
 *     buffered preads fill UNMAPPED cache that MemAvailable credits
 *     less than mapped file pages (~0.4 GiB residual).
 *   1 (lazy always; eager under DS4_CUDA_EAGER_SOURCE_DISCARD): fd reads
 *     (O_DIRECT when available) + per-chunk source-page discard — the
 *     lazy tier's historical behavior, and the F4 measured mode for
 *     eager.
 * Registered support-map pages are pinned and are never madvised. */
static int cuda_stage_copy_to_dev(const void *model_map, uint64_t offset,
                                  uint64_t bytes, char *dev,
                                  int direct_discard, const char *what) {
    const int fd_source = g_model_fd >= 0 && g_model_fd_host_base &&
                          model_map == g_model_fd_host_base;
    cudaError_t err = cudaSuccess;
    const uint64_t chunk = cuda_model_copy_chunk_bytes();
    const uint64_t stage_bytes = chunk + (g_model_direct_align > 1 ? g_model_direct_align : 1);
    if (!cuda_model_stage_pool_alloc(stage_bytes)) return 0;

    uint64_t copied = 0;
    uint64_t chunk_idx = 0;
    while (copied < bytes) {
        const uint64_t n = (bytes - copied < chunk) ? (bytes - copied) : chunk;
        const uint64_t bi = chunk_idx % 4u;
        if (chunk_idx >= 4u) {
            err = cudaEventSynchronize(g_model_stage_event[bi]);
            if (err != cudaSuccess) {
                fprintf(stderr, "ds4: CUDA model staging wait failed for %s: %s\n",
                        what ? what : "weights", cudaGetErrorString(err));
                (void)cudaGetLastError();
                return 0;
            }
        }
        const char *payload = NULL;
        if (fd_source && direct_discard) {
            if (!cuda_model_stage_read(g_model_stage[bi], g_model_stage_bytes,
                                       offset + copied, n, &payload)) {
                fprintf(stderr, "ds4: CUDA model range read failed for %s at %.2f MiB: %s\n",
                        what ? what : "weights",
                        (double)copied / 1048576.0,
                        strerror(errno));
                return 0;
            }
        } else {
            /* Map source: faults MAPPED file pages, the pre-D1b walk's
             * exact cache shape (the fit-time credit, see above). */
            memcpy(g_model_stage[bi],
                   (const char *)model_map + offset + copied, (size_t)n);
            payload = (const char *)g_model_stage[bi];
        }
        err = cudaMemcpyAsync(dev + copied, payload, (size_t)n,
                              cudaMemcpyHostToDevice, g_model_upload_stream);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model range copy failed for %s at %.2f MiB: %s\n",
                    what ? what : "weights",
                    (double)copied / 1048576.0,
                    cudaGetErrorString(err));
            (void)cudaGetLastError();
            return 0;
        }
        err = cudaEventRecord(g_model_stage_event[bi], g_model_upload_stream);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model staging record failed for %s: %s\n",
                    what ? what : "weights", cudaGetErrorString(err));
            (void)cudaGetLastError();
            return 0;
        }
        if (direct_discard && fd_source) {
            cuda_model_drop_file_pages(offset + copied, n);
            cuda_model_discard_source_pages(model_map, g_model_registered_size, offset + copied, n);
        }
        copied += n;
        cuda_model_load_progress_note(g_model_range_bytes + copied);
        chunk_idx++;
    }
    err = cudaStreamSynchronize(g_model_upload_stream);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA model range upload sync failed for %s: %s\n",
                what ? what : "weights", cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }
    return 1;
}

/* --------------------------------------------------------------------
 * memgov D1b-1: the canonical materializer (plan §5.4).
 *
 * Typed per-unit outcomes; ONE publication per unit (every device-copy
 * range stamps unit_lo == unit_hi by construction).  Plan decisions —
 * policy, coverage, budget funding — belong to the caller; the copy
 * transaction below is purely physical.  The outcome vocabulary is the
 * PUBLIC ds4_residency_unit_state (ds4_mem_census.h, memgov D5-2; the
 * former engine-private CUDA_MAT_* enum retired into it verbatim:
 * LAZY_DEFERRED = source residency lazy, the eager pass defers to first
 * touch by SCHEDULE vs the budget's unfunded REFUSAL of the same
 * deferral (D3-2); EXPERT_COLD_BY_POLICY = fd-tier touch on a unit the
 * catalog stamps cold by POLICY, never device-promoted (D3-4)).
 *
 * memgov D5-2: outcome counters keyed by the SOURCE's resolved residency
 * policy (+ the unattributed row), read by the porcelains through
 * ds4_gpu_residency_units_read.  FAILED outcomes additionally attribute
 * {model_role, stage} for ds4_residency_failures_total.  Plain monotonic
 * counters (metrics-registry discipline), no epoch bracket. */
static uint64_t g_materialize_outcomes[DS4_RESUNIT_POLICY_ROWS][DS4_RESUNIT__COUNT];
static uint64_t g_residency_failures[DS4_MSRC_ROLE__COUNT][DS4_RESSTAGE__COUNT];

/* One tick funnel: src < 0 (or a bad policy byte) lands in the
 * unattributed row, never dropped -- totals preserved by construction. */
static void cuda_resunit_note_n(int src, int oc, uint64_t n) {
    int pol = DS4_RESIDENCY__COUNT;
    if (src >= 0 && src < DS4_MSRC_MAX) {
        const int r = g_model_srcs.v[src].residency;
        if (r >= 0 && r < DS4_RESIDENCY__COUNT) pol = r;
    }
    if (oc >= 0 && oc < DS4_RESUNIT__COUNT)
        g_materialize_outcomes[pol][oc] += n;
}

static void cuda_resunit_fail_note_n(int src, int stage, uint64_t n) {
    int role = DS4_MSRC_ROLE_PRIMARY;
    if (src >= 0 && src < DS4_MSRC_MAX) {
        const int r = g_model_srcs.v[src].role;
        if (r >= 0 && r < DS4_MSRC_ROLE__COUNT) role = r;
    }
    if (stage >= 0 && stage < DS4_RESSTAGE__COUNT)
        g_residency_failures[role][stage] += n;
}

/* memgov D5-2: porcelain readers.  Nonzero = out of the fixed domain
 * (the absence answer on backends that keep no plan is the Metal/CPU
 * stub's, mirroring the census read contract). */
extern "C" int ds4_gpu_residency_units_read(int policy, int state,
                                            uint64_t *out) {
    if (!out || policy < 0 || policy >= DS4_RESUNIT_POLICY_ROWS ||
        state < 0 || state >= DS4_RESUNIT__COUNT) return 1;
    *out = g_materialize_outcomes[policy][state];
    return 0;
}

extern "C" int ds4_gpu_residency_failures_read(int role, int stage,
                                               uint64_t *out) {
    if (!out || role < 0 || role >= DS4_MSRC_ROLE__COUNT ||
        stage < 0 || stage >= DS4_RESSTAGE__COUNT) return 1;
    *out = g_residency_failures[role][stage];
    return 0;
}

/* Copy ONE funded unit into an arena carve and publish it.  Failure
 * leaves any carve behind (bump arenas cannot un-carve) — the census
 * already holds it as arena slack: the transactional-residue rule, same
 * as the fd tier's precedent.  VMM arena preferred when supported: same
 * backing storage the ds4_weight_server uses, 2 MiB device pages,
 * 1.7-2.0x prefill on PRO 6000; hard-gated off under an IPC manifest,
 * transparent cudaMalloc-arena retry on driver errors. */
static int cuda_unit_materialize_copy(const void *model_map,
                                      const ds4_phys_unit *u,
                                      int direct_discard, const char *what) {
    char *dev = cuda_vmm_arena_alloc(model_map, u->src_bytes, what);
    if (!dev) dev = cuda_model_arena_alloc(model_map, u->src_bytes, what);
    if (!dev) return DS4_RESUNIT_FAILED;
    if (!cuda_stage_copy_to_dev(model_map, u->src_off, u->src_bytes, dev,
                                direct_discard, what))
        return DS4_RESUNIT_FAILED;
    /* memgov D2-2: a claimed promotion path; the funnel's post-freeze
     * tripwire keys on the marker (no early return between set and
     * clear: publish is the next call). */
    g_in_governed_materialize = 1;
    const int pub = cuda_model_range_publish({model_map, u->src_off,
                                              u->src_bytes, dev,
                                              NULL, NULL, 0, 0, 1, 0, 0,
                                              0, 0, 0});
    g_in_governed_materialize = 0;
    if (!pub) return DS4_RESUNIT_FAILED;
    g_model_range_bytes += u->src_bytes;
    cuda_substrate_cover(model_map, u->src_bytes);   /* tripwire: unit materialized */
    cuda_model_load_progress_note(g_model_range_bytes);
    if (cuda_weight_env().verbose) {
        fprintf(stderr, "ds4: CUDA materialized %s %.2f MiB (total %.2f GiB)\n",
                what ? what : "unit",
                (double)u->src_bytes / 1048576.0,
                (double)g_model_range_bytes / 1073741824.0);
    }
    return DS4_RESUNIT_POPULATED;
}

/* memgov D1b-2: the LAZY pass materializes CONTAINING UNITS through the
 * same core as the eager pass — arbitrary-extent promotions cease to
 * exist.  Eligibility is the historical fd tier's, unchanged: fd-owner
 * base map only (any other map would read bytes from the wrong file —
 * the caller falls through to the registered-mapping/populate tiers,
 * whose host pointers are correct for every mmap), per-unit budget fit,
 * source-page discard always on (the historical lazy behavior; the
 * D1b-1 gate applies to the EAGER pass only).  Requests never straddle
 * units on live paths (a unit boundary never splits a tensor, and
 * consumers request within tensors); a theoretical multi-unit span
 * materializes its units and then falls through to the mapped tiers if
 * the re-resolve still misses (no contiguity across carves) — the same
 * degradation the funnel-refusal path already takes.  No bound table =
 * no lazy promotion (plan-first: a range that exists is a range the
 * plan knows). */
static const char *cuda_model_range_ptr_from_fd(
        const void *model_map,
        uint64_t offset,
        uint64_t bytes,
        const char *what) {
    if (g_model_fd < 0 || bytes == 0) return NULL;
    if (g_model_fd_host_base && model_map != g_model_fd_host_base) return NULL;
    const int src = cuda_mem_src_index(model_map);
    const ds4_phys_unit *units =
        (src >= 0 && src < DS4_MSRC_MAX) ? g_model_units_v[src] : NULL;
    const uint32_t nu =
        (src >= 0 && src < DS4_MSRC_MAX) ? g_model_units_n[src] : 0;
    if (!units || nu == 0) return NULL;
    int lo = -1, hi = -1;
    ds4_units_span_of(units, nu, offset, bytes, &lo, &hi);
    if (lo < 0) return NULL;
    const uint64_t limit = cuda_model_map_replaces_complete(model_map)
        ? UINT64_MAX
        : cuda_model_cache_limit_bytes();
    for (int ui = lo; ui <= hi; ui++) {
        const ds4_phys_unit *u = &units[ui];
        /* memgov D3-2: HOST_MAPPED is a TERMINAL policy -- mapped units
         * are lazy-INELIGIBLE (the D3-0 finding: this loop was policy-
         * blind, so a single-lever NO_HBM boot device-promoted the very
         * bytes the stamp said stay mapped).  NULL, not the direct
         * fallback: the per-range register tier is the mapped serving
         * mechanism, same as the legacy pair produced.  EXPERT_COLD
         * eligibility is deliberately untouched (bug-for-bug; its own
         * adjudication rides D3-4). */
        if (u->policy == DS4_UPOL_HOST_MAPPED) {
            cuda_resunit_note_n(src, DS4_RESUNIT_HOST_MAPPED_BY_POLICY, 1);
            return NULL;
        }
        /* memgov D3-4 adjudication: EXPERT_COLD stays cold by POLICY,
         * not by budget accident.  Historically this loop device-
         * promoted raw experts on first touch until the 24 GiB budget
         * exhausted, THEN degraded -- an unplanned multi-GiB device
         * charge that only ever ran on already-degraded boots (the
         * shape needs NO_DERIVED_WEIGHTS + a failed/absent whole-map
         * registration; every healthy shape serves experts through
         * artifacts or a blanket tier first).  The exit below is the
         * budget-exhausted exit verbatim, taken deterministically. */
        if (u->policy == DS4_UPOL_EXPERT_COLD) {
            cuda_resunit_note_n(src, DS4_RESUNIT_EXPERT_COLD_BY_POLICY, 1);
            return cuda_model_direct_fallback_ptr(model_map, offset);
        }
        int covered = 0;
        for (const cuda_model_range &r : g_model_ranges) {
            if (r.host_base != model_map || r.host_registered) continue;
            if (r.offset <= u->src_off &&
                r.offset + r.bytes >= u->src_off + u->src_bytes) {
                covered = 1;
                break;
            }
        }
        if (covered) continue;
        /* memgov D2-2: the lazy miss is the same governed decision as
         * the eager unit.  Post-freeze the ENGINE_BOOT lease holds the
         * boot absolute (resident >= any range-scoped proposal, so the
         * shrink rule spends nothing) and the honest physical ask rides
         * operation_transient instead -- one claim shape, two lifecycle
         * phases.  Any non-ADMIT takes the legacy exhausted path
         * (direct mapped fallback; correctness never depends on the
         * promotion). */
        const int legacy = (g_model_range_bytes >= limit ||
                            u->src_bytes > limit - g_model_range_bytes)
                               ? DS4_GOV_REFUSE_CLASS : DS4_GOV_ADMIT;
        ds4_gov_claim mcl = {0};
        mcl.requester = DS4_GOVC_ENGINE_BOOT;
        mcl.memc = DS4_MEMC_WEIGHT_ARENA;
        mcl.domain = DS4_MEMD_UNIFIED_DEVICE;
        mcl.proposed_outstanding = g_model_range_bytes + u->src_bytes;
        mcl.class_limit = limit == UINT64_MAX ? 0 : (limit ? limit : 1);
        mcl.operation_transient = g_model_plan_frozen ? u->src_bytes : 0;
        if (ds4_gov_governed_check("lazy_materialize", &mcl, legacy)
                != DS4_GOV_ADMIT) {
            if (cuda_weight_env().verbose) {
                fprintf(stderr, "ds4: CUDA direct %s %.2f MiB (cache budget %.2f GiB exhausted)\n",
                        what ? what : "weights",
                        (double)bytes / 1048576.0,
                        (double)limit / 1073741824.0);
            }
            return cuda_model_direct_fallback_ptr(model_map, offset);
        }
        const int oc = cuda_unit_materialize_copy(model_map, u,
                                                  /*direct_discard=*/1, what);
        cuda_resunit_note_n(src, oc, 1);
        if (oc == DS4_RESUNIT_FAILED)
            cuda_resunit_fail_note_n(src, DS4_RESSTAGE_LAZY, 1);
        if (oc != DS4_RESUNIT_POPULATED) return NULL;
    }
    /* Every needed unit is device-resident: the resolve that missed now
     * hits (single-unit requests — the live shape).  A multi-unit span
     * with no single covering range returns NULL and the mapped tiers
     * serve. */
    const cuda_model_range *exact_r = NULL;
    auto exact = g_model_range_by_offset.find(cuda_range_key{model_map, offset});
    if (exact != g_model_range_by_offset.end())
        exact_r = &g_model_ranges[exact->second];
    return cuda_model_range_resolve(model_map, offset, bytes, exact_r);
}

static int cuda_model_copy_chunked(const void *model_map, uint64_t model_size, uint64_t map_offset, uint64_t map_size) {
    if (!model_map || model_size == 0 || map_offset > model_size || map_size > model_size - map_offset) return 0;
    if (getenv("DS4_CUDA_NO_MODEL_COPY") != NULL ||
        getenv("DS4_CUDA_DIRECT_MODEL") != NULL ||
        getenv("DS4_CUDA_WEIGHT_CACHE") != NULL ||
        getenv("DS4_CUDA_WEIGHT_PRELOAD") != NULL) {
        return 0;
    }
    if (g_model_device_owned || g_model_registered) return 1;

    void *dev = NULL;
    const double t0 = cuda_wall_sec();
    cudaError_t err = cudaMalloc(&dev, (size_t)model_size);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA model allocation skipped: %s\n", cudaGetErrorString(err));
        (void)cudaGetLastError();
        return 0;
    }

    fprintf(stderr, "ds4: CUDA chunk-copying %.2f GiB model image\n",
            (double)model_size / 1073741824.0);

    const uint64_t chunk = cuda_model_copy_chunk_bytes();
    void *stage = NULL;
    err = cudaMallocHost(&stage, (size_t)chunk);
    if (err != cudaSuccess) {
        fprintf(stderr, "ds4: CUDA pinned model staging allocation failed: %s\n", cudaGetErrorString(err));
        (void)cudaFree(dev);
        (void)cudaGetLastError();
        return 0;
    }

    if (map_offset > 0) {
        uint64_t copied_header = 0;
        while (copied_header < map_offset) {
            const uint64_t n = (map_offset - copied_header < chunk) ? (map_offset - copied_header) : chunk;
            memcpy(stage, (const char *)model_map + copied_header, (size_t)n);
            err = cudaMemcpy((char *)dev + copied_header, stage, (size_t)n, cudaMemcpyHostToDevice);
            if (err != cudaSuccess) {
                fprintf(stderr, "ds4: CUDA model header copy failed: %s\n", cudaGetErrorString(err));
                (void)cudaFreeHost(stage);
                (void)cudaFree(dev);
                (void)cudaGetLastError();
                return 0;
            }
            copied_header += n;
        }
    }

    uint64_t copied = 0;
    double last_report = t0;
    while (copied < map_size) {
        const uint64_t n = (map_size - copied < chunk) ? (map_size - copied) : chunk;
        const uint64_t off = map_offset + copied;
        memcpy(stage, (const char *)model_map + off, (size_t)n);
        err = cudaMemcpy((char *)dev + off, stage, (size_t)n, cudaMemcpyHostToDevice);
        if (err != cudaSuccess) {
            fprintf(stderr, "ds4: CUDA model chunk copy failed at %.2f GiB: %s\n",
                    (double)copied / 1073741824.0, cudaGetErrorString(err));
            (void)cudaFreeHost(stage);
            (void)cudaFree(dev);
            (void)cudaGetLastError();
            return 0;
        }
        cuda_model_discard_source_pages(model_map, model_size, off, n);
        copied += n;
        const double now = cuda_wall_sec();
        if (getenv("DS4_CUDA_MODEL_COPY_VERBOSE") != NULL && now - last_report >= 2.0) {
            fprintf(stderr, "ds4: CUDA model chunk copy %.2f/%.2f GiB\n",
                    (double)copied / 1073741824.0,
                    (double)map_size / 1073741824.0);
            last_report = now;
        }
    }

    (void)cudaFreeHost(stage);
    g_model_device_base = (const char *)dev;
    g_model_device_owned = 1;
    g_model_hmm_direct = 0;
    cuda_mem_note_alloc_src(DS4_MEMC_WEIGHT_WHOLE, DS4_MEMD_UNIFIED_DEVICE,
                            model_size, model_size, model_map);
    g_mem_device_owned_bytes = model_size;
    const double t1 = cuda_wall_sec();
    fprintf(stderr,
            "ds4: CUDA model chunk copy complete in %.3fs (%.2f GiB tensors)\n",
            t1 - t0,
            (double)map_size / 1073741824.0);
    return 1;
}

static void cuda_model_range_release_all(void) {
    for (const cuda_derived_range &r : g_derived_ranges) {
        if (r.imported_vmm) {
            if (r.vmm_va && r.vmm_alloc_bytes) {
                (void)cuMemUnmap(r.vmm_va, (size_t)r.vmm_alloc_bytes);
                (void)cuMemAddressFree(r.vmm_va, (size_t)r.vmm_alloc_bytes);
            }
            if (r.vmm_handle) {
                (void)cuMemRelease(r.vmm_handle);
            }
            cuda_mem_note_free_src(DS4_MEMC_WEIGHT_IMPORT, DS4_MEMD_UNIFIED_DEVICE,
                                   r.bytes, r.vmm_alloc_bytes, r.host_base);
        } else if (r.imported_ipc && r.device_ptr) {
            (void)cudaIpcCloseMemHandle(r.device_ptr);
            cuda_mem_note_free_src(DS4_MEMC_WEIGHT_IMPORT, DS4_MEMD_UNIFIED_DEVICE,
                                   r.bytes, r.bytes, r.host_base);
        } else if (r.device_ptr) {
            /* In-process self-load artifact (plain cudaMalloc). */
            (void)cudaFree(r.device_ptr);
            cuda_mem_note_free_src(DS4_MEMC_WEIGHT_ARTIFACT, DS4_MEMD_UNIFIED_DEVICE,
                                   r.bytes, r.bytes, r.host_base);
        }
    }
    g_derived_ranges.clear();
    g_derived_range_bytes = 0;
    g_derived_artifact_source = CUDA_DERIVED_ARTIFACTS_NONE;
    g_derived_artifact_count = 0;
    g_derived_artifact_bytes = 0;
    g_derived_artifact_build_secs = 0.0;
    g_derived_replaces_complete = 0;
    for (const cuda_model_range &r : g_model_ranges) {
        if (r.host_registered && r.registered_base) {
            (void)cudaHostUnregister(r.registered_base);
            cuda_pinned_file_note_unregister(r.registered_base);
        } else if (r.imported_vmm) {
            if (r.vmm_va && r.vmm_alloc_bytes) {
                (void)cuMemUnmap(r.vmm_va, (size_t)r.vmm_alloc_bytes);
                (void)cuMemAddressFree(r.vmm_va, (size_t)r.vmm_alloc_bytes);
            }
            if (r.vmm_handle) {
                (void)cuMemRelease(r.vmm_handle);
            }
            cuda_mem_note_free_src(DS4_MEMC_WEIGHT_IMPORT, DS4_MEMD_UNIFIED_DEVICE,
                                   r.bytes, r.vmm_alloc_bytes, r.host_base);
        } else if (r.imported_ipc && r.device_ptr) {
            (void)cudaIpcCloseMemHandle(r.device_ptr);
            cuda_mem_note_free_src(DS4_MEMC_WEIGHT_IMPORT, DS4_MEMD_UNIFIED_DEVICE,
                                   r.bytes, r.bytes, r.host_base);
        } else if (r.device_ptr && !r.arena_allocated) {
            (void)cudaFree(r.device_ptr);
            cuda_mem_note_free_src(DS4_MEMC_WEIGHT_SPAN, DS4_MEMD_UNIFIED_DEVICE,
                                   r.bytes, r.bytes, r.host_base);
        }
    }
    for (const cuda_model_arena &a : g_model_arenas) {
        if (a.device_ptr) {
            (void)cudaFree(a.device_ptr);
            cuda_mem_note_free_srcidx(DS4_MEMC_WEIGHT_ARENA,
                                      DS4_MEMD_UNIFIED_DEVICE,
                                      a.used, a.bytes, a.src);
        }
    }
    g_model_arenas.clear();
    // VMM-backed arenas own the device VA + handle for many ranges in
    // g_model_ranges; the per-range pointers above are aliases into these
    // arenas and must not be cudaFree'd individually. Release order:
    // unmap, address-free, release handle -- matches ds4_weight_server.
    cuda_vmm_arenas_release_all();
    g_model_ranges.clear();
    g_model_range_by_offset.clear();
    g_model_range_bytes = 0;
    g_substrate_promotable_total = 0;     /* tripwire: census dies with the ranges */
    g_substrate_promotable_covered = 0;
    cuda_model_load_progress_reset();
}

/* deepmem lite-3: bytes of base-map promotable weight spans still certain
 * to be device-promoted (declared by the startup walk, covered as they
 * materialize or become provably unnecessary).  ~0 on eager boots -- the
 * standing assertion that eager completed; ~8 GiB under the
 * DS4_CUDA_NO_HBM_CACHE lever.  Saturating; stale reads err HIGH
 * (conservative). */
extern "C" uint64_t ds4_gpu_substrate_outstanding(void) {
    const uint64_t t = g_substrate_promotable_total;
    const uint64_t c = g_substrate_promotable_covered;
    return t > c ? t - c : 0;
}

static int cublas_ok(cublasStatus_t st, const char *what) {
    if (st == CUBLAS_STATUS_SUCCESS) return 1;
    fprintf(stderr, "ds4: cuBLAS %s failed: status %d\n", what, (int)st);
    return 0;
}

/* Opp C Phase 1A.3 forward decls.  The defining sites live further down
 * in this file (the __constant__ table near the FP8 quantizer, the env
 * helpers in the layer-graph section); forward-declaring the helpers
 * here lets ds4_gpu_init populate the table and ds4_gpu_cleanup print
 * the tripwire without needing a giant reorder.  The __constant__ symbol
 * itself is reached only via its host-side init helper -- nvcc does not
 * accept an `extern __constant__` declaration alongside a later
 * definition, so we don't forward-declare the symbol. */
static int ds4_cuda_fp8_kv_decode_table_init(void);
extern "C" int ds4_cuda_fp8_kv_enabled(void);
extern "C" int ds4_cuda_fp8_kv_debug_enabled(void);
extern "C" int ds4_cuda_fp4_index_enabled(void);  /* P2 Inc3 */
extern "C" unsigned long long ds4_cuda_fp8_kv_read_path_blocks(void);
extern "C" unsigned long long ds4_cuda_fp8_kv_indexed_read_path_blocks(void);
extern "C" unsigned long long ds4_cuda_fp4_index_read_path_blocks(void);  /* P2 Inc3 */

/* Field report (NVIDIA forum 378855 post 48): a GB10 binary made with a
 * generic `make cuda CUDA_ARCH=...` boots and serves, but at a fraction of
 * the cuda-spark speed (370 vs ~1000 tok/s prefill, 15 vs 30+ decode) --
 * weights stream over the UVA map instead of the Spark HBM cache, and the
 * sm_121-native kernels (Blackwell MMA, mxf4 indexer) are compiled out or
 * JIT'd from generic PTX.  The build configuration is invisible at runtime,
 * so the mis-built server looks healthy while serving at a third of the
 * speed.  Returns 1 iff the active CUDA device is GB10-class (sm_121) while
 * this ds4_cuda.o was compiled without the sm_121 arch configuration
 * (CUDA_ARCH=sm_121 supplies DS4_CUDA_HAVE_MXF4); the server turns that
 * into a boot advisory. */
/* 0 = no mismatch (sm_121-arch build, or not a GB10).
 * 1 = fully generic build on a GB10: no sm_121a-native kernels, no MXF4
 *     indexer (e.g. `make cuda CUDA_ARCH=sm_120`, `make cuda-generic`,
 *     or a portable Docker build).
 * The old code 2 (sm_121-arch build missing only the Spark HBM weight
 * cache, forum 378855 post 65) is EXTINCT as of deepmem lite-2: the
 * startup span walk is compiled unconditionally and gated at runtime
 * (integrated device + DS4_CUDA_NO_HBM_CACHE), so `make cuda
 * CUDA_ARCH=sm_121` and `make cuda-spark` produce the same behavior. */
extern "C" int ds4_cuda_spark_build_mismatch(void) {
    int have_mxf4 = 0;
#if defined(DS4_CUDA_HAVE_MXF4)
    have_mxf4 = 1;
#endif
    if (have_mxf4) return 0;
    int dev = 0;
    cudaDeviceProp prop;
    if (cudaGetDevice(&dev) != cudaSuccess ||
        cudaGetDeviceProperties(&prop, dev) != cudaSuccess) {
        (void)cudaGetLastError();
        return 0;
    }
    if (!(prop.major == 12 && prop.minor == 1)) return 0;
    return 1;
}

extern "C" int ds4_gpu_init(void) {
    int dev = 0;
    if (!cuda_ok(cudaSetDevice(dev), "set device")) return 0;
    cudaDeviceProp prop;
    if (cudaGetDeviceProperties(&prop, dev) == cudaSuccess) {
        fprintf(stderr, "ds4: CUDA backend initialized on %s (sm_%d%d)\n",
                prop.name, prop.major, prop.minor);
    }
    if (!g_cublas_ready) {
        if (!cublas_ok(cublasCreate(&g_cublas), "create handle")) return 0;
        const cublasMath_t math_mode =
            (g_quality_mode || getenv("DS4_CUDA_NO_TF32") != NULL)
                ? CUBLAS_DEFAULT_MATH
                : CUBLAS_TF32_TENSOR_OP_MATH;
        (void)cublasSetMathMode(g_cublas, math_mode);
        /* S1.1a: dedicated split-K workspace (see g_cublas_ws decl).  On alloc
         * failure we leave it NULL and cuBLAS falls back to its own (non-
         * deterministic) workspace -- correctness of the GEMM is unaffected.
         *
         * v0.5 inc-12: the workspace SIZE stays 32 MiB -- cuBLAS keys alg
         * selection on the available workspace, and the 12k twin gate showed
         * ANY size change (1 MiB, 4 MiB tried) shifts alg picks -> ulp-level
         * output changes -> spec-trajectory drift.  DS4_CUDA_WS_MB stays as a
         * diagnostic override only.  The memset diet happens per-CALL instead:
         * see cuda_cublas_ws_prep. */
        size_t cublas_ws_mb = 32;
        {
            const char *env = getenv("DS4_CUDA_WS_MB");
            if (env && env[0]) {
                const long v = atol(env);
                if (v >= 0 && v <= 1024) cublas_ws_mb = (size_t)v;
            }
        }
        const size_t cublas_ws_bytes = cublas_ws_mb * 1024u * 1024u;
        if (cudaMalloc(&g_cublas_ws, cublas_ws_bytes) == cudaSuccess) {
            g_cublas_ws_bytes = cublas_ws_bytes;
            (void)cublasSetWorkspace(g_cublas, g_cublas_ws, g_cublas_ws_bytes);
            cuda_mem_note_alloc(DS4_MEMC_KERNEL_PARTIALS,
                                DS4_MEMD_UNIFIED_DEVICE,
                                cublas_ws_bytes, cublas_ws_bytes);
        } else {
            (void)cudaGetLastError();
            g_cublas_ws = NULL;
            g_cublas_ws_bytes = 0;
        }
        g_cublas_ready = 1;
    }
    /* Dedicated split-K F16 partials scratch. Allocated here (eager init,
     * before any graph capture) so the captured-decode graph can reference a
     * stable device pointer without an illegal mid-capture cudaMalloc. By
     * construction out_dim*ksplit stays near the ~2K block target, so 1M floats
     * is far more than the partials ever need; a failure just disables split-K
     * (the matmul falls back to the single-block-per-row kernel). */
    if (g_f16_splitk_partials == NULL) {
        const uint64_t bytes = (uint64_t)1024u * 1024u * sizeof(float); /* 4 MiB */
        void *p = NULL;
        if (cudaMalloc(&p, (size_t)bytes) == cudaSuccess) {
            g_f16_splitk_partials = (float *)p;
            g_f16_splitk_partials_bytes = bytes;
            cuda_mem_note_alloc(DS4_MEMC_KERNEL_PARTIALS,
                                DS4_MEMD_UNIFIED_DEVICE, bytes, bytes);
        } else {
            (void)cudaGetLastError();
        }
    }
    /* M2-Inc1 fused HC-stage scratch (256 floats covers dots 24*2 + sumsq 32
     * + out-sumsq 48).  A failure just disables the fused path (the entry
     * falls back to the unfused chain). */
    if (g_hc_stage_scratch == NULL) {
        void *p = NULL;
        if (cudaMalloc(&p, 256u * sizeof(float)) == cudaSuccess) {
            g_hc_stage_scratch = (float *)p;
            cuda_mem_note_alloc(DS4_MEMC_KERNEL_PARTIALS,
                                DS4_MEMD_UNIFIED_DEVICE,
                                256u * sizeof(float), 256u * sizeof(float));
        } else {
            (void)cudaGetLastError();
        }
    }
    /* M2-Inc3 fused router split-K partials (256 rows x 8 ksegs), sized x8
     * tok rows for the C3-Inc1 batched variant (64 KiB).  A failure just
     * disables the fused router (the entry falls back to the 3-kernel
     * chain). */
    if (g_router_fused_partials == NULL) {
        void *p = NULL;
        if (cudaMalloc(&p, 8u * 2048u * sizeof(float)) == cudaSuccess) {
            g_router_fused_partials = (float *)p;
            cuda_mem_note_alloc(DS4_MEMC_KERNEL_PARTIALS,
                                DS4_MEMD_UNIFIED_DEVICE,
                                8u * 2048u * sizeof(float),
                                8u * 2048u * sizeof(float));
        } else {
            (void)cudaGetLastError();
        }
    }
    /* M2-Inc5 fused compressor pair+store partials (2 matmuls x 2048 =
     * width*ksplit), sized x8 tok rows for the C3-Inc2 batched variant
     * (128 KiB).  A failure just disables the fused compressor pair
     * (unfused chain). */
    if (g_comp_pair_partials == NULL) {
        void *p = NULL;
        if (cudaMalloc(&p, 8u * 2u * 2048u * sizeof(float)) == cudaSuccess) {
            g_comp_pair_partials = (float *)p;
            cuda_mem_note_alloc(DS4_MEMC_KERNEL_PARTIALS,
                                DS4_MEMD_UNIFIED_DEVICE,
                                8u * 2u * 2048u * sizeof(float),
                                8u * 2u * 2048u * sizeof(float));
        } else {
            (void)cudaGetLastError();
        }
    }
    /* M2-Inc1b/2a q8 fold sidecars: DEDICATED double-buffered rings.
     * cuda_tmp_alloc is a single shared sticky scratch (every caller gets
     * the same pointer), so sidecars must NOT come from it: two sidecar
     * allocations in one entry would alias and the emissions overwrite
     * each other (the 2026-07-04 Inc2a gibberish regression).  A 2-deep
     * ring per format is sufficient: each sidecar is consumed before the
     * same-purpose buffer two emitting calls later is rewritten.  Sized
     * for rows up to 8192 elems.  Failure just disables the folds. */
    for (int i = 0; i < 2; i++) {
        const uint64_t q80_bytes = 8192u + 16u + (8192u / 32u) * sizeof(float);
        const uint64_t q81_bytes = (8192u / 32u) * 36u;
        if (g_q8_fold_q80_buf[i] == NULL) {
            void *p = NULL;
            if (cudaMalloc(&p, (size_t)q80_bytes) == cudaSuccess) {
                g_q8_fold_q80_buf[i] = (int8_t *)p;
                cuda_mem_note_alloc(DS4_MEMC_KERNEL_PARTIALS,
                                    DS4_MEMD_UNIFIED_DEVICE,
                                    q80_bytes, q80_bytes);
            } else (void)cudaGetLastError();
        }
        if (g_q8_fold_q81_buf[i] == NULL) {
            void *p = NULL;
            if (cudaMalloc(&p, (size_t)q81_bytes) == cudaSuccess) {
                g_q8_fold_q81_buf[i] = p;
                cuda_mem_note_alloc(DS4_MEMC_KERNEL_PARTIALS,
                                    DS4_MEMD_UNIFIED_DEVICE,
                                    q81_bytes, q81_bytes);
            } else (void)cudaGetLastError();
        }
    }
    /* SM count for the flash-decode attention split gate. */
    (void)cudaDeviceGetAttribute(&g_cuda_sm_count, cudaDevAttrMultiProcessorCount, dev);
    /* Flash-decode attention partials scratch (eager init -> capture-stable
     * pointer).  v0.4 HG sizing: n_tokens*n_head*n_split*(head_dim+2) floats
     * at the dispatch caps (8 tokens * 64 heads * 16 splits * 514 = 4.21M
     * floats, ~16.1 MiB).  Also serves the older per-head split path (64*8*
     * 514 fits trivially).  A failure just disables both split paths (the
     * single-block decode kernel remains the fallback). */
    if (g_attn_split_partials == NULL) {
        const uint64_t bytes = (uint64_t)8u * 64u * 16u * 514u * sizeof(float);
        void *p = NULL;
        if (cudaMalloc(&p, (size_t)bytes) == cudaSuccess) {
            g_attn_split_partials = (float *)p;
            g_attn_split_partials_bytes = bytes;
            cuda_mem_note_alloc(DS4_MEMC_KERNEL_PARTIALS,
                                DS4_MEMD_UNIFIED_DEVICE, bytes, bytes);
        } else {
            (void)cudaGetLastError();
        }
    }
    /* Opp C Phase 1A.3 / v0.3: populate the E4M3FN magnitude lookup table
     * on the device UNCONDITIONALLY (512 B once at init).  It was gated on
     * ds4_cuda_fp8_kv_enabled(), which left fp8_kv_dequant readers with an
     * all-zeros table in F32-primary boots -- an F32-primary server
     * restoring a v3 packed-row disk-KV payload dequant-expanded every
     * non-RoPE lane to 0.0 (caught by kv_crossmode_gate leg L2_f32; the
     * fp4 path never had the trap because e2m1 decode is a pure function).
     * Any entry point that can read packed codes must work regardless of
     * which storage config is serving. */
    if (!ds4_cuda_fp8_kv_decode_table_init()) return 0;
    return 1;
}

extern "C" void ds4_gpu_cleanup(void) {
    (void)cudaDeviceSynchronize();
    /* Opp C Phase 1A tripwire: when DS4_CUDA_FP8_KV_DEBUG is set, surface
     * how many decode blocks actually executed the FP8 read branch in
     * each kernel.  A nonzero count is the evidence that a matching
     * token-MD5 between FP8-on and baseline reflects bit-identical
     * reconstruction rather than a NULL'd wiring that silently fell back
     * to FP32.  The counters themselves stay armed unconditionally --
     * this gate only controls the stderr print so a review-clean build
     * stays quiet. */
    if (ds4_cuda_fp8_kv_enabled() && ds4_cuda_fp8_kv_debug_enabled()) {
        const unsigned long long dense   = ds4_cuda_fp8_kv_read_path_blocks();
        const unsigned long long indexed = ds4_cuda_fp8_kv_indexed_read_path_blocks();
        fprintf(stderr, "ds4: DS4_CUDA_FP8_KV path stats -- dense decode blocks: %llu, indexed decode blocks: %llu\n",
                dense, indexed);
    }
    /* P2 Inc3: FP4 indexer read tripwire (reuses the same debug gate).  Nonzero
     * proves indexer_score_one_direct consumed the packed mirror, so a matching
     * token-MD5 vs fp4-off reflects bit-identical reconstruction. */
    if (ds4_cuda_fp4_index_enabled() && ds4_cuda_fp8_kv_debug_enabled()) {
        fprintf(stderr, "ds4: DS4_CUDA_FP4_INDEX path stats -- indexer fp4 scorer launches: %llu\n",
                ds4_cuda_fp4_index_read_path_blocks());
    }
    if (g_cublas_ready) {
        (void)cublasDestroy(g_cublas);
        g_cublas_ready = 0;
        g_cublas = NULL;
    }
    if (g_cublas_ws) {
        (void)cudaFree(g_cublas_ws);
        cuda_mem_note_free(DS4_MEMC_KERNEL_PARTIALS, DS4_MEMD_UNIFIED_DEVICE,
                           g_cublas_ws_bytes, g_cublas_ws_bytes);
        g_cublas_ws = NULL;
        g_cublas_ws_bytes = 0;
    }
    cuda_model_range_release_all();
    cuda_q8_f16_cache_release_all();
    g_q8_f16_disabled_after_oom = 0;
    g_q8_f16_budget_notice_printed = 0;
    {
        /* D1a-1: bulk class note + per-source rows (see the f16 twin). */
        uint64_t by_src[DS4_MSRC_MAX + 1] = {0};
        for (const cuda_q8_f32_range &r : g_q8_f32_ranges)
            by_src[cuda_mem_src_index(r.host_base)] +=
                r.in_dim * r.out_dim * sizeof(float);
        ds4_gov_epoch_write_begin(&g_mem_census_epoch, &g_mem_census_faults);
        ds4_mem_cell_note_free(
            &g_mem_census[DS4_MEMC_WEIGHT_DERIVED][DS4_MEMD_UNIFIED_DEVICE],
            g_q8_f32_bytes, g_q8_f32_bytes, &g_mem_census_faults);
        for (int s = 0; s <= DS4_MSRC_MAX; s++) {
            if (by_src[s] == 0) continue;
            ds4_mem_cell_note_free(
                &g_mem_src_census[s][DS4_MEMC_WEIGHT_DERIVED][DS4_MEMD_UNIFIED_DEVICE],
                by_src[s], by_src[s], &g_mem_census_faults);
        }
        ds4_gov_epoch_write_end(&g_mem_census_epoch, &g_mem_census_faults);
    }
    for (const cuda_q8_f32_range &r : g_q8_f32_ranges) {
        (void)cudaFree(r.device_ptr);
    }
    g_q8_f32_ranges.clear();
    g_q8_f32_by_offset.clear();
    g_q8_f32_bytes = 0;
    if (g_cuda_tmp) {
        (void)cudaFree(g_cuda_tmp);
        cuda_mem_note_free(DS4_MEMC_SCRATCH_STICKY, DS4_MEMD_UNIFIED_DEVICE,
                           g_cuda_tmp_bytes, g_cuda_tmp_bytes);
        g_cuda_tmp = NULL;
        g_cuda_tmp_bytes = 0;
    }
    if (g_tt_scratch) {
        (void)cudaFree(g_tt_scratch);
        cuda_mem_note_free(DS4_MEMC_SCRATCH_STICKY, DS4_MEMD_UNIFIED_DEVICE,
                           g_tt_scratch_bytes, g_tt_scratch_bytes);
        g_tt_scratch = NULL;
        g_tt_scratch_bytes = 0;
    }
    if (g_f16_splitk_partials) {
        (void)cudaFree(g_f16_splitk_partials);
        cuda_mem_note_free(DS4_MEMC_KERNEL_PARTIALS, DS4_MEMD_UNIFIED_DEVICE,
                           g_f16_splitk_partials_bytes,
                           g_f16_splitk_partials_bytes);
        g_f16_splitk_partials = NULL;
        g_f16_splitk_partials_bytes = 0;
    }
    if (g_hc_stage_scratch) {
        (void)cudaFree(g_hc_stage_scratch);
        cuda_mem_note_free(DS4_MEMC_KERNEL_PARTIALS, DS4_MEMD_UNIFIED_DEVICE,
                           256u * sizeof(float), 256u * sizeof(float));
        g_hc_stage_scratch = NULL;
    }
    {
        const uint64_t q80_bytes = 8192u + 16u + (8192u / 32u) * sizeof(float);
        const uint64_t q81_bytes = (8192u / 32u) * 36u;
        for (int i = 0; i < 2; i++) {
            if (g_q8_fold_q80_buf[i]) {
                (void)cudaFree(g_q8_fold_q80_buf[i]);
                cuda_mem_note_free(DS4_MEMC_KERNEL_PARTIALS,
                                   DS4_MEMD_UNIFIED_DEVICE,
                                   q80_bytes, q80_bytes);
                g_q8_fold_q80_buf[i] = NULL;
            }
            if (g_q8_fold_q81_buf[i]) {
                (void)cudaFree(g_q8_fold_q81_buf[i]);
                cuda_mem_note_free(DS4_MEMC_KERNEL_PARTIALS,
                                   DS4_MEMD_UNIFIED_DEVICE,
                                   q81_bytes, q81_bytes);
                g_q8_fold_q81_buf[i] = NULL;
            }
        }
    }
    cuda_q8_fold_reset();
    if (g_router_fused_partials) {
        (void)cudaFree(g_router_fused_partials);
        cuda_mem_note_free(DS4_MEMC_KERNEL_PARTIALS, DS4_MEMD_UNIFIED_DEVICE,
                           8u * 2048u * sizeof(float),
                           8u * 2048u * sizeof(float));
        g_router_fused_partials = NULL;
    }
    if (g_comp_pair_partials) {
        (void)cudaFree(g_comp_pair_partials);
        cuda_mem_note_free(DS4_MEMC_KERNEL_PARTIALS, DS4_MEMD_UNIFIED_DEVICE,
                           8u * 2u * 2048u * sizeof(float),
                           8u * 2u * 2048u * sizeof(float));
        g_comp_pair_partials = NULL;
    }
    for (size_t i = 0; i < 4; i++) {
        if (g_model_stage_event[i]) {
            (void)cudaEventDestroy(g_model_stage_event[i]);
            g_model_stage_event[i] = NULL;
        }
        if (g_model_stage_raw[i]) {
            (void)cudaFreeHost(g_model_stage_raw[i]);
            cuda_mem_note_free(DS4_MEMC_STAGE_PIN, DS4_MEMD_PINNED_HOST,
                               g_mem_stage_slot_bytes[i],
                               g_mem_stage_slot_bytes[i]);
            g_mem_stage_slot_bytes[i] = 0;
            g_model_stage_raw[i] = NULL;
            g_model_stage[i] = NULL;
        }
    }
    g_model_stage_bytes = 0;
    if (g_model_upload_stream) {
        (void)cudaStreamDestroy(g_model_upload_stream);
        g_model_upload_stream = NULL;
    }
    if (g_model_device_owned && g_model_device_base) {
        (void)cudaFree((void *)g_model_device_base);
        /* D1a-1: device_owned surviving to teardown implies no later
         * set_model_map displaced it, so g_model_host_base is still the
         * owning map. */
        cuda_mem_note_free_src(DS4_MEMC_WEIGHT_WHOLE, DS4_MEMD_UNIFIED_DEVICE,
                               g_mem_device_owned_bytes,
                               g_mem_device_owned_bytes, g_model_host_base);
        g_mem_device_owned_bytes = 0;
    }
    if (g_model_registered && g_model_host_base) {
        (void)cudaHostUnregister((void *)g_model_host_base);
        cuda_pinned_file_note_unregister(g_model_host_base);
    }
    g_model_host_base = NULL;
    g_model_device_base = NULL;
    g_model_registered_size = 0;
    g_model_registered = 0;
    g_model_device_owned = 0;
    g_model_range_mapping_supported = 1;
    g_model_hmm_direct = 0;
    g_model_coherent_direct_map = NULL;
    g_model_fd = -1;
    if (g_model_direct_fd >= 0) {
        (void)close(g_model_direct_fd);
        g_model_direct_fd = -1;
    }
    g_model_direct_align = 1;
    g_model_file_size = 0;
    g_model_cache_full = 0;
    if (g_model_prefetch_stream) {
        (void)cudaStreamDestroy(g_model_prefetch_stream);
        g_model_prefetch_stream = NULL;
    }
}

__global__ static void fill_f32_kernel(float *x, uint64_t n, float v);

extern "C" ds4_gpu_tensor *ds4_gpu_tensor_alloc(uint64_t bytes) {
    if (bytes == 0) bytes = 1;
    ds4_gpu_tensor *t = (ds4_gpu_tensor *)calloc(1, sizeof(*t));
    if (!t) return NULL;
    if (!cuda_ok(cudaMalloc(&t->ptr, (size_t)bytes), "tensor alloc")) {
        free(t);
        return NULL;
    }
    t->bytes = bytes;
    t->owner = 1;
    t->memc = cuda_mem_scope_class();
    cuda_mem_note_alloc(t->memc, DS4_MEMD_UNIFIED_DEVICE, bytes, bytes);
    return t;
}

extern "C" ds4_gpu_tensor *ds4_gpu_tensor_alloc_managed(uint64_t bytes) {
    if (bytes == 0) bytes = 1;
    ds4_gpu_tensor *t = (ds4_gpu_tensor *)calloc(1, sizeof(*t));
    if (!t) return NULL;
    if (!cuda_ok(cudaMallocManaged(&t->ptr, (size_t)bytes), "managed tensor alloc")) {
        free(t);
        return NULL;
    }
    t->bytes = bytes;
    t->owner = 1;
    t->memc = cuda_mem_scope_class();
    cuda_mem_note_alloc(t->memc, DS4_MEMD_UNIFIED_DEVICE, bytes, bytes);
    return t;
}

static uint64_t cuda_managed_kv_reserve_bytes(uint64_t total_bytes) {
    const uint64_t min_reserve = 8ull * 1073741824ull;
    const uint64_t max_reserve = 40ull * 1073741824ull;
    uint64_t reserve = total_bytes / 4u;
    if (reserve < min_reserve) reserve = min_reserve;
    if (reserve > max_reserve) reserve = max_reserve;
    return reserve;
}

extern "C" int ds4_gpu_should_use_managed_kv_cache(uint64_t kv_cache_bytes, uint64_t context_bytes) {
    if (kv_cache_bytes == 0) return 0;

    /* Very large KV caches are where device-only cudaMalloc() can make a
     * unified-memory machine unresponsive.  Managed memory restores the old
     * demand-paged behavior for this one long-lived allocation class only. */
    const uint64_t huge_kv = 8ull * 1073741824ull;
    if (kv_cache_bytes >= huge_kv) return 1;

    const uint64_t large_context = 8ull * 1073741824ull;
    if (context_bytes < large_context) return 0;

    /* MT-6 (audit V10 twin, gap-3/C12): route the mid-band decision through
     * the ONE typed observation (max of cuda free and MemAvailable on
     * integrated parts) instead of a second raw cudaMemGetInfo answer that
     * under-counts reclaimable page cache and steered borderline contexts
     * to managed-VA for no reason.  The >=8 GiB unconditional tier above
     * is untouched. */
    ds4_mem_observation obs;
    if (ds4_gpu_mem_observe(&obs) != 0 || obs.status != DS4_MEMOBS_OK)
        return 0;

    const uint64_t free_bytes = obs.free_bytes;
    const uint64_t total_bytes = obs.total_bytes;
    const uint64_t reserve_bytes = cuda_managed_kv_reserve_bytes(total_bytes);
    if (context_bytes > free_bytes) return 1;
    return free_bytes - context_bytes < reserve_bytes;
}

/* memgov D0a-2: THE typed memory-observation provider.  Body is the old
 * ds4_gpu_mem_info verbatim plus status/source stamping; ds4_gpu_mem_info
 * below is now a shim over this (ds4_mem_obs_to_legacy), so every legacy
 * caller sees bit-identical values and return codes. */
extern "C" int ds4_gpu_mem_observe(ds4_mem_observation *out) {
    ds4_mem_observation o;
    memset(&o, 0, sizeof(o));
    o.status = DS4_MEMOBS_QUERY_ERROR;
    o.source = DS4_MEMOBS_SRC_NONE;
    size_t free_b = 0;
    size_t total_b = 0;
    cudaError_t err = cudaMemGetInfo(&free_b, &total_b);
    if (err != cudaSuccess) {
        (void)cudaGetLastError();
        if (out) *out = o;
        return 1;
    }
    o.status = DS4_MEMOBS_OK;
    o.source = DS4_MEMOBS_SRC_CUDA_FREE;
    uint64_t free_out = (uint64_t)free_b;
    o.cuda_free_bytes = (uint64_t)free_b;   /* MG-2: raw pair, disclosed */
#ifdef __linux__
    /* Integrated/unified (GB10): cudaMemGetInfo's free tracks MemFree and
     * ignores reclaimable page cache -- on this box often tens of GB of cold
     * gguf file pages that cudaMalloc can claim just fine.  MemAvailable is
     * the kernel's own "allocatable before OOM" answer, which is the budget
     * question; take whichever is larger. */
    int dev = 0;
    int integrated = 0;
    if (cudaGetDevice(&dev) == cudaSuccess &&
        cudaDeviceGetAttribute(&integrated, cudaDevAttrIntegrated, dev) == cudaSuccess &&
        integrated) {
        FILE *f = fopen("/proc/meminfo", "r");
        if (f) {
            char line[160];
            while (fgets(line, sizeof line, f)) {
                unsigned long long kb = 0;
                if (sscanf(line, "MemAvailable: %llu kB", &kb) == 1) {
                    /* MemAvailable is the kernel's own "allocatable before OOM"
                     * estimate and, on GB10's HMM path, is accurate as-is:
                     * cudaHostRegisterMapped does NOT mlock the model mapping
                     * (measured Unevictable/Mlocked stay ~26 MiB while
                     * g_pinned_file_bytes is ~6.5 GiB), so those file pages
                     * remain genuinely reclaimable and MemAvailable already
                     * counts them.
                     *
                     * A former `avail -= g_pinned_file_bytes` correction here
                     * assumed discrete-GPU-style pinning (pages counted
                     * reclaimable but actually unreclaimable).  That assumption
                     * is false on this box: it double-penalized by the entire
                     * registered model, drove free_out below the session-graph
                     * need, and 503'd every serial request even though the
                     * alloc fits -- the weights are served from the anon
                     * DS4_MODEL_ANON_HUGE artifacts, so reclaiming the fallback
                     * mapping's page cache does not thrash decode.  Trust
                     * MemAvailable; the caller's own headroom is the margin. */
                    uint64_t avail = kb * 1024ull;
                    o.meminfo_avail_bytes = avail;   /* MG-2: raw pair */
                    if (avail > free_out) {
                        free_out = avail;
                        o.source = DS4_MEMOBS_SRC_MEMINFO_AVAILABLE;
                    }
                    break;
                }
            }
            fclose(f);
        }
    }
    (void)cudaGetLastError();
#endif
    o.free_bytes = free_out;
    o.total_bytes = (uint64_t)total_b;
    if (out) *out = o;
    return 0;
}

extern "C" int ds4_gpu_mem_info(uint64_t *free_bytes, uint64_t *total_bytes) {
    ds4_mem_observation o;
    (void)ds4_gpu_mem_observe(&o);
    return ds4_mem_obs_to_legacy(&o, free_bytes, total_bytes);
}

extern "C" void ds4_gpu_boot_trim(void) {
    /* Releases only UNUSED graph-pool reserve (bytes backing no live graph
     * exec); everything the boot prewarm deliberately warmed -- module SASS,
     * cuBLAS state, sticky scratch -- stays resident. */
    int dev = 0;
    if (cudaGetDevice(&dev) != cudaSuccess) dev = 0;
    (void)cudaDeviceGraphMemTrim(dev);
    (void)cudaGetLastError();
}

/* memgaps MG-1: the boot trim, callable at refusal time, reporting what
 * the typed observation got back.  Session churn (right-size regrows,
 * serial free/create, per-call static graphs) re-accumulates freed-graph
 * pool reserve after the one boot trim; on unified boxes that reserve
 * depresses the ONE estimate every admission verdict consumes.  The
 * delta rides ds4_gpu_mem_observe -- the same answer the verdicts read
 * -- so it measures the return where it matters.  Kernel-side noise can
 * ride the delta; callers treat it as disclosure, not ledger. */
/* MT-6 (audit V9): idle exec-pool sweep, defined with the pools below. */
static uint64_t ds4_cuda_graph_exec_idle_trim(void);

extern "C" uint64_t ds4_gpu_own_trim(void) {
    ds4_mem_observation a, b;
    const int a_ok = ds4_gpu_mem_observe(&a) == 0 && a.status == DS4_MEMOBS_OK;
    /* MT-6 (audit V9): shed idle captured-graph execs first -- the sweep's
     * driver-side frees are what cudaDeviceGraphMemTrim below then returns,
     * and the whole action rides the same observe bracket so the disclosed
     * delta stays one number. */
    (void)ds4_cuda_graph_exec_idle_trim();
    ds4_gpu_boot_trim();
    if (!a_ok) return 0;
    if (ds4_gpu_mem_observe(&b) != 0 || b.status != DS4_MEMOBS_OK) return 0;
    return b.free_bytes > a.free_bytes ? b.free_bytes - a.free_bytes : 0;
}

extern "C" ds4_gpu_tensor *ds4_gpu_tensor_view(const ds4_gpu_tensor *base, uint64_t offset, uint64_t bytes) {
    if (!base || offset > base->bytes || bytes > base->bytes - offset) return NULL;
    ds4_gpu_tensor *t = (ds4_gpu_tensor *)calloc(1, sizeof(*t));
    if (!t) return NULL;
    t->ptr = (char *)base->ptr + offset;
    t->bytes = bytes;
    t->owner = 0;
    /* memgov D0a-3: a view is a WINDOW into the base's allocation -- pages
     * ensured (or trimmed) through it charge the base's census class, not
     * the ambient scope at view creation.  Without this, the emit-site
     * ensure_rows hooks (which run through per-bank slab views installed
     * at admission) charged ENGINE_OTHER ~2 pages/layer per new tenant --
     * measured 84 MiB on the first admission. */
    t->memc = base->memc;
    return t;
}

extern "C" ds4_gpu_tensor *ds4_gpu_tensor_reserve(uint64_t bytes) {
    if (bytes == 0) bytes = 1;
    const uint64_t page = ds4_gpu_vmm_demand_page();
    if (page == 0) return NULL;                /* no VMM: caller allocates eagerly */
    const uint64_t span = (bytes + page - 1u) / page * page;
    CUdeviceptr va = 0;
    if (!driver_ok(cuMemAddressReserve(&va, (size_t)span, (size_t)page, 0, 0),
                   "VMM demand reserve"))
        return NULL;
    ds4_gpu_tensor *t = (ds4_gpu_tensor *)calloc(1, sizeof(*t));
    cuda_vmm_demand *d = new (std::nothrow) cuda_vmm_demand();
    if (!t || !d) {
        (void)cuMemAddressFree(va, (size_t)span);
        free(t);
        delete d;
        return NULL;
    }
    d->va = va;
    d->span = span;
    d->page = page;
    d->mapped = 0;
    d->pages.assign((size_t)(span / page), 0);
    g_vmm_demand.push_back(d);
    t->ptr = (void *)(uintptr_t)va;
    t->bytes = bytes;
    t->owner = 2;                              /* reserved: freed via the registry */
    /* Census: a reservation is VIRTUAL -- no cell charge here.  Physical
     * commitment lands page-by-page in ds4_gpu_tensor_ensure below. */
    t->memc = cuda_mem_scope_class();
    return t;
}

extern "C" int ds4_gpu_tensor_ensure(const ds4_gpu_tensor *tensor, uint64_t offset, uint64_t bytes) {
    if (!tensor) return 0;
    if (bytes == 0) return 1;
    if (offset > tensor->bytes || bytes > tensor->bytes - offset) return 0;
    cuda_vmm_demand *d = cuda_vmm_demand_find(tensor->ptr, offset, bytes);
    if (!d) return 1;                          /* eager allocation: always resident */
    const uint64_t rel = ((uint64_t)(uintptr_t)tensor->ptr + offset) - (uint64_t)d->va;
    const uint64_t p0 = rel / d->page;
    const uint64_t p1 = (rel + bytes - 1u) / d->page;
    int dev = 0;
    if (cudaGetDevice(&dev) != cudaSuccess) { (void)cudaGetLastError(); return 0; }
    for (uint64_t p = p0; p <= p1; p++) {
        if (d->pages[(size_t)p]) continue;
        CUmemAllocationProp prop;
        memset(&prop, 0, sizeof(prop));
        prop.type = CU_MEM_ALLOCATION_TYPE_PINNED;
        prop.location.type = CU_MEM_LOCATION_TYPE_DEVICE;
        prop.location.id = dev;
        prop.requestedHandleTypes = CU_MEM_HANDLE_TYPE_NONE;
        CUmemGenericAllocationHandle h;
        memset(&h, 0, sizeof(h));
        if (!driver_ok(cuMemCreate(&h, (size_t)d->page, &prop, 0), "VMM demand page create"))
            return 0;
        const CUdeviceptr pa = d->va + (CUdeviceptr)(p * d->page);
        if (!driver_ok(cuMemMap(pa, (size_t)d->page, 0, h, 0), "VMM demand page map")) {
            (void)cuMemRelease(h);
            return 0;
        }
        CUmemAccessDesc access;
        memset(&access, 0, sizeof(access));
        access.location.type = CU_MEM_LOCATION_TYPE_DEVICE;
        access.location.id = dev;
        access.flags = CU_MEM_ACCESS_FLAGS_PROT_READWRITE;
        if (!driver_ok(cuMemSetAccess(pa, (size_t)d->page, &access, 1), "VMM demand page access")) {
            (void)cuMemUnmap(pa, (size_t)d->page);
            (void)cuMemRelease(h);
            return 0;
        }
        d->pages[(size_t)p] = h;
        d->mapped += d->page;
        cuda_mem_note_alloc(tensor->memc, DS4_MEMD_UNIFIED_DEVICE,
                            d->page, d->page);
    }
    return 1;
}

extern "C" uint64_t ds4_gpu_tensor_resident(const ds4_gpu_tensor *tensor, uint64_t offset, uint64_t bytes) {
    if (!tensor || bytes == 0) return 0;
    if (offset > tensor->bytes) return 0;
    if (bytes > tensor->bytes - offset) bytes = tensor->bytes - offset;
    const cuda_vmm_demand *d = cuda_vmm_demand_find(tensor->ptr, offset, bytes);
    if (!d) return bytes;                      /* eager allocation: fully resident */
    const uint64_t rel = ((uint64_t)(uintptr_t)tensor->ptr + offset) - (uint64_t)d->va;
    const uint64_t p0 = rel / d->page;
    const uint64_t p1 = (rel + bytes - 1u) / d->page;
    uint64_t res = 0;
    for (uint64_t p = p0; p <= p1; p++)
        if (d->pages[(size_t)p]) res += d->page;
    return res;
}

/* memgov D0a-4: trim failure-injection (TEST ONLY).  Forces the two driver
 * failures the loop below must survive.  An injected unmap failure takes
 * the exact keep-everything path a real one takes (skip the page BEFORE
 * touching the driver).  An injected release failure skips the REAL
 * cuMemRelease, deliberately orphaning the handle: the leak is physical,
 * so the cell's slack claim stays reconcilable against the allocator and
 * cudaMemGetInfo -- an injection that released anyway would make the
 * ledger lie about reality.  Armed as a bounded burst (first N candidate
 * driver calls fail, then the hook disarms) via DS4_CUDA_TRIM_INJECT=
 * unmap:N|release:N, or programmatically by units through
 * ds4_gpu_trim_inject_set, which always wins over the env.  Single-writer
 * like the census registry: trim runs on the engine thread only. */
static int      g_trim_inject_env_seen = 0;
static int      g_trim_inject_site = DS4_TRIM_INJECT_OFF;
static uint32_t g_trim_inject_left = 0;
static uint32_t g_trim_inject_fired = 0;

static void cuda_trim_inject_env_once(void) {
    if (g_trim_inject_env_seen) return;
    g_trim_inject_env_seen = 1;
    const char *e = getenv("DS4_CUDA_TRIM_INJECT");
    if (!e || !*e) return;
    if (!ds4_trim_inject_parse(e, &g_trim_inject_site, &g_trim_inject_left)) {
        fprintf(stderr, "ds4: trim inject: bad spec '%s' (want unmap:N|release:N) -- off\n", e);
        return;
    }
    fprintf(stderr, "ds4: trim inject: armed %s x%u (TEST ONLY)\n",
            g_trim_inject_site == DS4_TRIM_INJECT_UNMAP ? "unmap" : "release",
            g_trim_inject_left);
}

static int cuda_trim_inject_fire(int site) {
    if (g_trim_inject_site != site || g_trim_inject_left == 0) return 0;
    g_trim_inject_left--;
    g_trim_inject_fired++;
    fprintf(stderr, "ds4: trim inject: forced %s failure (%u left)\n",
            site == DS4_TRIM_INJECT_UNMAP ? "cuMemUnmap" : "cuMemRelease",
            g_trim_inject_left);
    return 1;
}

extern "C" int ds4_gpu_trim_inject_set(int site, uint32_t count) {
    cuda_trim_inject_env_once();   /* a later env parse must not clobber this */
    const int valid = (site == DS4_TRIM_INJECT_UNMAP ||
                       site == DS4_TRIM_INJECT_RELEASE);
    g_trim_inject_site = valid ? site : DS4_TRIM_INJECT_OFF;
    g_trim_inject_left = valid ? count : 0;
    return 1;                      /* CUDA backend: injection supported */
}

extern "C" uint32_t ds4_gpu_trim_inject_fired(void) {
    return g_trim_inject_fired;
}

extern "C" uint64_t ds4_gpu_tensor_trim_estimate(const ds4_gpu_tensor *tensor, uint64_t offset, uint64_t bytes) {
    /* The trim loop's page walk with the driver calls removed: mapped bytes
     * of the pages entirely inside [offset, offset+bytes).  Shares trim's
     * p0/p1x arithmetic below so quote and release cannot drift. */
    if (!tensor || bytes == 0) return 0;
    if (offset > tensor->bytes) return 0;
    if (bytes > tensor->bytes - offset) bytes = tensor->bytes - offset;
    const cuda_vmm_demand *d = cuda_vmm_demand_find(tensor->ptr, offset, bytes);
    if (!d) return 0;                          /* eager allocation: nothing to trim */
    const uint64_t rel = ((uint64_t)(uintptr_t)tensor->ptr + offset) - (uint64_t)d->va;
    const uint64_t p0  = (rel + d->page - 1u) / d->page;
    const uint64_t p1x = (rel + bytes) / d->page;
    uint64_t est = 0;
    for (uint64_t p = p0; p < p1x; p++)
        if (d->pages[(size_t)p]) est += d->page;
    return est;
}

extern "C" uint64_t ds4_gpu_tensor_trim(const ds4_gpu_tensor *tensor, uint64_t offset, uint64_t bytes) {
    /* Unmap the demand-mapped pages lying ENTIRELY inside [offset, offset+bytes)
     * of a ds4_gpu_tensor_reserve() tensor.  Interior pages only: the caller's
     * spans (per-bank cache strides) are not page-aligned, so an edge page can
     * back two neighboring spans and must survive a one-sided trim.  The VA
     * reservation is untouched -- captured graph nodes keep valid pointers, and
     * ds4_gpu_tensor_ensure() re-maps on the next tenant's first emit.  The
     * caller owns the ordering guarantees: no in-flight GPU work may reference
     * the range (sync off-capture first) and nothing may read it again before
     * an ensure.  Returns bytes released; 0 for eager (non-reserved) tensors. */
    if (!tensor || bytes == 0) return 0;
    if (offset > tensor->bytes) return 0;
    if (bytes > tensor->bytes - offset) bytes = tensor->bytes - offset;
    cuda_vmm_demand *d = cuda_vmm_demand_find(tensor->ptr, offset, bytes);
    if (!d) return 0;                          /* eager allocation: nothing to trim */
    cuda_trim_inject_env_once();
    const uint64_t rel = ((uint64_t)(uintptr_t)tensor->ptr + offset) - (uint64_t)d->va;
    const uint64_t p0  = (rel + d->page - 1u) / d->page;   /* first page fully inside */
    const uint64_t p1x = (rel + bytes) / d->page;          /* exclusive end page */
    uint64_t released = 0;
    for (uint64_t p = p0; p < p1x; p++) {
        if (!d->pages[(size_t)p]) continue;
        /* deepmem D-1b: a failed driver call must not orphan the page.
         * Unmap failure keeps the handle AND the accounting (the page is
         * still mapped, still owned, still resident).  Release failure
         * after a successful unmap is a physical leak: accounting follows
         * the mapping (the VA no longer reads it), but the bytes were NOT
         * returned to the system, so they are not counted as released. */
        if (cuda_trim_inject_fire(DS4_TRIM_INJECT_UNMAP))
            continue;
        if (!driver_ok(cuMemUnmap(d->va + (CUdeviceptr)(p * d->page),
                                  (size_t)d->page),
                       "VMM trim page unmap"))
            continue;
        const int rel_ok = cuda_trim_inject_fire(DS4_TRIM_INJECT_RELEASE) ? 0 :
                           driver_ok(cuMemRelease(d->pages[(size_t)p]),
                                     "VMM trim page release");
        d->pages[(size_t)p] = 0;
        d->mapped -= d->page;
        if (rel_ok) released += d->page;
        /* Census mirrors the D-1b semantics exactly: the ask (mapping) is
         * gone either way, but a release failure did NOT return the bytes
         * -- freed_committed stays behind and the residue shows up as
         * cell slack, never as an undercharge. */
        cuda_mem_note_free(tensor->memc, DS4_MEMD_UNIFIED_DEVICE,
                           d->page, rel_ok ? d->page : 0);
    }
    return released;
}

extern "C" void ds4_gpu_tensor_free(ds4_gpu_tensor *tensor) {
    if (!tensor) return;
    if (tensor->owner == 2) {
        for (size_t i = 0; i < g_vmm_demand.size(); i++) {
            cuda_vmm_demand *d = g_vmm_demand[i];
            if ((void *)(uintptr_t)d->va != tensor->ptr) continue;
            for (size_t p = 0; p < d->pages.size(); p++) {
                if (!d->pages[p]) continue;
                (void)cuMemUnmap(d->va + (CUdeviceptr)(p * d->page), (size_t)d->page);
                (void)cuMemRelease(d->pages[p]);
            }
            cuda_mem_note_free(tensor->memc, DS4_MEMD_UNIFIED_DEVICE,
                               d->mapped, d->mapped);
            (void)cuMemAddressFree(d->va, (size_t)d->span);
            g_vmm_demand.erase(g_vmm_demand.begin() + (ptrdiff_t)i);
            delete d;
            break;
        }
        free(tensor);
        return;
    }
    if (tensor->owner && tensor->ptr) {
        (void)cudaFree(tensor->ptr);
        cuda_mem_note_free(tensor->memc, DS4_MEMD_UNIFIED_DEVICE,
                           tensor->bytes, tensor->bytes);
    }
    free(tensor);
}

extern "C" uint64_t ds4_gpu_tensor_bytes(const ds4_gpu_tensor *tensor) {
    return tensor ? tensor->bytes : 0;
}

extern "C" const void *ds4_gpu_tensor_ptr(const ds4_gpu_tensor *tensor) {
    /* Step 6: pointer-identity accessor for layer-graph cache-key
     * construction.  Returns the cudaMalloc base; never dereferenced from
     * C-side (just memcmp'd into the key). */
    return tensor ? tensor->ptr : NULL;
}

extern "C" void *ds4_gpu_tensor_contents(ds4_gpu_tensor *tensor) {
    if (!tensor) return NULL;
    (void)cudaDeviceSynchronize();
    return tensor->ptr;
}

extern "C" int ds4_gpu_tensor_fill_f32(ds4_gpu_tensor *tensor, float value, uint64_t count) {
    if (!tensor || count > tensor->bytes / sizeof(float)) return 0;
    if (count == 0) return 1;
    fill_f32_kernel<<<(count + 255u) / 256u, 256, 0, ds4_current_stream()>>>((float *)tensor->ptr, count, value);
    return cuda_ok(cudaGetLastError(), "tensor fill f32 launch");
}

extern "C" int ds4_gpu_tensor_write(ds4_gpu_tensor *tensor, uint64_t offset, const void *data, uint64_t bytes) {
    if (!tensor || !data || offset > tensor->bytes || bytes > tensor->bytes - offset) return 0;
    return cuda_ok(cudaMemcpy((char *)tensor->ptr + offset, data, (size_t)bytes, cudaMemcpyHostToDevice), "tensor write");
}

extern "C" int ds4_gpu_tensor_read(const ds4_gpu_tensor *tensor, uint64_t offset, void *data, uint64_t bytes) {
    if (!tensor || !data || offset > tensor->bytes || bytes > tensor->bytes - offset) return 0;
    return cuda_ok(cudaMemcpy(data, (const char *)tensor->ptr + offset, (size_t)bytes, cudaMemcpyDeviceToHost), "tensor read");
}

extern "C" int ds4_gpu_tensor_copy(ds4_gpu_tensor *dst, uint64_t dst_offset,
                                     const ds4_gpu_tensor *src, uint64_t src_offset,
                                     uint64_t bytes) {
    if (!dst || !src || dst_offset > dst->bytes || src_offset > src->bytes ||
        bytes > dst->bytes - dst_offset || bytes > src->bytes - src_offset) {
        return 0;
    }
    if (bytes == 0) return 1;
    /* C1 (cont capture): a synchronous cudaMemcpy is illegal inside stream
     * capture (it would invalidate the capture).  Under an active capture
     * (thread-local stream override set) record the copy as an async D2D
     * node on the capture stream instead -- device-side consumers are
     * stream-ordered either way, and no in-tree caller reads the
     * destination from the host without an intervening end_commands sync.
     * Outside capture the historical blocking copy is preserved. */
    if (ds4_capture_active()) {
        return cuda_ok(cudaMemcpyAsync((char *)dst->ptr + dst_offset,
                                       (const char *)src->ptr + src_offset,
                                       (size_t)bytes,
                                       cudaMemcpyDeviceToDevice,
                                       ds4_current_stream()),
                       "tensor copy (captured)");
    }
    return cuda_ok(cudaMemcpy((char *)dst->ptr + dst_offset,
                              (const char *)src->ptr + src_offset,
                              (size_t)bytes,
                              cudaMemcpyDeviceToDevice),
                   "tensor copy");
}

/* CUDA submits stream-ordered: there is no command scope to open, so the
 * begin/end pair are compatibility stubs (begin always "succeeds"; end is a
 * heavyweight device sync + diag readback).  Callers doing OPTIONAL
 * bracketing (open-iff-closed, e.g. the cont-MTP rollback restore) gate on
 * commands_scoped() == 0 and skip the pair entirely -- see ds4_gpu.h. */
extern "C" int ds4_gpu_commands_scoped(void) { return 0; }
extern "C" int ds4_gpu_begin_commands(void) { return 1; }
extern "C" int ds4_gpu_flush_commands(void) { return cuda_ok(cudaDeviceSynchronize(), "flush"); }
/* #9 diagnosis (2026-08-04): captured-topk live-bound violation counter.
 * Written by indexer_topk_stream512_kernel's guard when the live scan
 * bound read from the per-layer substrate is zero or exceeds the baked
 * row stride (either would have been the illegal-access / %0 fault this
 * instruments).  Polled after every command batch below. */
__device__ unsigned int g_topk_bound_viol_count  = 0u;
__device__ unsigned int g_topk_bound_viol_n      = 0u;
__device__ unsigned int g_topk_bound_viol_stride = 0u;
#ifdef DS4_S512_APPEND_GUARD
/* #9 mechanism probe (2026-08-04, harness-only define): stream512 append
 * overflow telemetry -- see the guard at the buf append site. */
__device__ unsigned int g_s512_append_ovf_count = 0u;
__device__ unsigned int g_s512_append_ovf_max   = 0u;
#endif
#ifdef DS4_S512_TRACE
/* #9 post-mortem breadcrumbs (2026-08-04, harness-only define): per-WARP
 * phase markers written through host-mapped memory so they survive a
 * device fault.  Slot layout: [(block*16 + warp)*2] = (iter << 8) | phase,
 * [(block*16 + warp)*2 + 1] = s_cnt observed by the warp leader at the
 * marker.  Any intra-block phase/iteration skew at death = the barrier
 * phase-slip class; the max-phase warp localizes the faulting region. */
__device__ volatile unsigned int *g_s512_trace = NULL;
#endif

extern "C" int ds4_gpu_end_commands(void) {
    int ok = cuda_ok(cudaDeviceSynchronize(), "end commands");
    static unsigned int seen = 0u;
    unsigned int cnt = 0u;
    cudaError_t perr = cudaMemcpyFromSymbol(&cnt, g_topk_bound_viol_count, sizeof cnt);
    if (perr == cudaSuccess && cnt != seen) {
        unsigned int vn = 0u, vs = 0u;
        (void)cudaMemcpyFromSymbol(&vn, g_topk_bound_viol_n, sizeof vn);
        (void)cudaMemcpyFromSymbol(&vs, g_topk_bound_viol_stride, sizeof vs);
        fprintf(stderr, "ds4: TOPK-BOUND-VIOL count=%u live_n=%u baked_stride=%u\n",
                cnt, vn, vs);
        seen = cnt;
    } else if (perr != cudaSuccess && !ok) {
        /* Poisoned context: the counter is unreadable, so a crash-step
         * violation cannot be ruled in or out from the log -- say so
         * instead of silently printing nothing (run-2 ambiguity, 08-04). */
        fprintf(stderr, "ds4: TOPK-BOUND-VIOL poll unreadable (context poisoned)\n");
        (void)cudaGetLastError();
    }
    return ok;
}
extern "C" int ds4_gpu_synchronize(void) { return cuda_ok(cudaDeviceSynchronize(), "synchronize"); }
/* Task #22 diag: legacy-stream-only sync.  Unlike ds4_gpu_synchronize it does
 * NOT drain non-blocking streams, so it discriminates "all actors are
 * blocking-stream-ordered" from "a non-blocking-stream actor races the layer". */
extern "C" int ds4_gpu_stream_synchronize(void) {
    return cuda_ok(cudaStreamSynchronize(ds4_current_stream()), "stream synchronize");
}

extern "C" int ds4_gpu_set_model_map(const void *model_map, uint64_t model_size) {
    if (!model_map || model_size == 0) return 0;
    if (g_model_host_base == model_map && g_model_registered_size == model_size) return 1;
    cuda_model_preserve_current_direct_mapping();
    g_model_host_base = model_map;
    g_model_device_base = (const char *)model_map;
    g_model_registered_size = model_size;
    g_model_range_mapping_supported = 1;
    g_model_hmm_direct = 0;
    /* Re-mapping the coherent map re-derives its fact below; other maps'
     * calls must not erase it (the base map keeps serving through it). */
    if (model_map == g_model_coherent_direct_map)
        g_model_coherent_direct_map = NULL;
    g_model_cache_full = 0;
    // Bind g_model_fd to this model on first registration. set_model_fd is
    // called once for the main model before the first set_model_map call;
    // subsequent set_model_map calls (e.g. for an auxiliary model like an MTP
    // draft GGUF) must not take over the fd association, even though they
    // overwrite g_model_host_base.
    if (g_model_fd >= 0 && !g_model_fd_host_base) {
        g_model_fd_host_base = model_map;
    }

    const char *copy_env = getenv("DS4_CUDA_COPY_MODEL");
    if (copy_env && copy_env[0]) {
        void *dev = NULL;
        const double t0 = clock() / (double)CLOCKS_PER_SEC;
        cudaError_t err = cudaMalloc(&dev, (size_t)model_size);
        if (err == cudaSuccess) {
            fprintf(stderr, "ds4: CUDA copying %.2f GiB model to device memory\n",
                    (double)model_size / 1073741824.0);
            err = cudaMemcpy(dev, model_map, (size_t)model_size, cudaMemcpyHostToDevice);
            if (err == cudaSuccess) {
                g_model_device_base = (const char *)dev;
                g_model_device_owned = 1;
                cuda_mem_note_alloc_src(DS4_MEMC_WEIGHT_WHOLE,
                                        DS4_MEMD_UNIFIED_DEVICE,
                                        model_size, model_size, model_map);
                g_mem_device_owned_bytes = model_size;
                const double t1 = clock() / (double)CLOCKS_PER_SEC;
                fprintf(stderr, "ds4: CUDA model copy complete in %.3fs\n", t1 - t0);
                return 1;
            }
            fprintf(stderr, "ds4: CUDA model copy failed: %s\n", cudaGetErrorString(err));
            (void)cudaFree(dev);
            (void)cudaGetLastError();
        } else {
            fprintf(stderr, "ds4: CUDA model allocation skipped: %s\n", cudaGetErrorString(err));
            (void)cudaGetLastError();
        }
    }

    /* Importing weights from a VMM weight server on an integrated / unified-memory
     * GPU (e.g. DGX Spark GB10): do NOT pin the full host mmap. The server already
     * holds the model in device VMM; cudaHostRegister-ing the same ~80 GiB here
     * double-residencies it against that VMM (2x the model on one shared LPDDR5X
     * pool -> can't fit twice -> disk thrash). Leave the raw mmap as the base
     * pointer: the IPC import overlays device pointers for the weight ranges, and
     * any stray non-imported (metadata) deref reaches the pageable mmap via
     * ATS/HMM. Discrete GPUs keep the registration path (separate host/VRAM pools).
     *
     * FOLLOW-UP (B): making our VMM arena the *default* single-process residency
     * path on integrated (no server) is a separate, larger change -- it needs a
     * coalesced up-front loader to match the server's ~20 s load + ~19.64 t/s.
     * See local/docs/ds4_gb10_vmm_default_followup_2026-05-30.md. */
    if (getenv("DS4_CUDA_WEIGHT_IPC_MANIFEST") != NULL ||
        cuda_model_map_replaces_complete(model_map)) {
        const int self_load_artifacts = cuda_model_map_replaces_complete(model_map);
        int integrated = 0;
        int reg_dev = 0;
        if (cudaGetDevice(&reg_dev) == cudaSuccess) {
            (void)cudaDeviceGetAttribute(&integrated, cudaDevAttrIntegrated, reg_dev);
        }
        if (integrated) {
            g_model_device_base = (const char *)model_map;
            if (self_load_artifacts) {
                /* In-process aligned artifacts replaced the expert raws:
                 * pinning the full mmap here would double-residency the
                 * ~73 GiB of expert weights against their device artifacts.
                 * Unlike the manifest case, hmm_direct stays OFF: nothing
                 * imported the non-expert raws, so cuda_model_range_ptr must
                 * fall through to the fd cache / startup walk (both uncapped
                 * for this map), which load them into device memory on
                 * demand — the same residency a weight-server import gives
                 * them.  Expert raws stay cold on disk; the raw mmap pointer
                 * (g_model_device_base) still serves the aligned-consumer
                 * fallback reads through HMM at mmap rates.
                 * memgov D2 hardening: that coherence fact is recorded so a
                 * GOVERNED refusal of the promotion tiers (operator floor
                 * under enforce) degrades to mapped-serve instead of
                 * failing the resolve — routing still prefers promotion. */
                g_model_coherent_direct_map = model_map;
                fprintf(stderr,
                        "ds4: CUDA integrated + in-process artifacts: skipping full host "
                        "registration (%.2f GiB mmap left unpinned; expert weights served "
                        "from device artifacts)\n",
                        (double)model_size / 1073741824.0);
            } else {
                g_model_hmm_direct = 1;
                fprintf(stderr,
                        "ds4: CUDA integrated + VMM import: skipping full host registration "
                        "(%.2f GiB mmap left unpinned; weights served from device VMM)\n",
                        (double)model_size / 1073741824.0);
            }
            return 1;
        }
    }

    /* GB10 / driver 580.142 reports cudaDevAttrHostRegisterReadOnlySupported = 0,
     * so requesting cudaHostRegisterReadOnly here fails with cudaErrorNotSupported
     * and the entire model-resident fast path falls back to per-deref H2D streaming.
     * Plain `Mapped` works on Spark. */
    cudaError_t err = cudaHostRegister((void *)model_map, (size_t)model_size,
                                       cudaHostRegisterMapped);
    if (err == cudaSuccess) {
        cuda_pinned_file_note_register(model_map, model_size);
        void *dev = NULL;
        err = cudaHostGetDevicePointer(&dev, (void *)model_map, 0);
        if (err == cudaSuccess && dev) {
            g_model_device_base = (const char *)dev;
            g_model_registered = 1;
            fprintf(stderr, "ds4: CUDA registered %.2f GiB model mapping for device access\n",
                    (double)model_size / 1073741824.0);
        } else {
            fprintf(stderr, "ds4: CUDA host registration pointer lookup failed: %s\n", cudaGetErrorString(err));
            (void)cudaGetLastError();
        }
    } else {
        fprintf(stderr, "ds4: CUDA host registration skipped: %s\n", cudaGetErrorString(err));
        (void)cudaGetLastError();
    }
    return 1;
}

extern "C" void ds4_gpu_unregister_model_map(const void *base) {
    /* Retire the host registration for ONE mapping whose owner is about to
     * free it.  A cudaHostRegister pin outliving its allocation poisons
     * unrelated cudaMemcpy calls whose host buffers land on the recycled
     * pages ("invalid argument" with perfectly valid parameters).  Serving
     * never hits this -- its maps live for the process; map-swapping callers
     * (the kernel unit tests) must call this before free().  Touches only
     * host-registration state: device artifacts and imported ranges of other
     * maps are left alone. */
    if (!base) return;
    if (g_model_coherent_direct_map == base) g_model_coherent_direct_map = NULL;
    if (g_model_registered && g_model_host_base == base) {
        (void)cudaHostUnregister((void *)base);
        cuda_pinned_file_note_unregister(base);
        g_model_registered = 0;
        g_model_host_base = NULL;
        g_model_device_base = NULL;
        g_model_registered_size = 0;
        return;
    }
    for (cuda_model_range &r : g_model_ranges) {
        if (r.host_registered && r.registered_base == (void *)base) {
            (void)cudaHostUnregister(r.registered_base);
            cuda_pinned_file_note_unregister(r.registered_base);
            /* Every range lookup keys on host_base equality; nulling it makes
             * the entry inert without disturbing sibling range indices. */
            r.host_registered = 0;
            r.registered_base = NULL;
            r.registered_device_base = NULL;
            r.registered_bytes = 0;
            r.host_base = NULL;
            r.device_ptr = NULL;
        }
    }
}

extern "C" int ds4_gpu_set_model_map_range(const void *model_map, uint64_t model_size, uint64_t map_offset, uint64_t map_size, uint64_t max_tensor_bytes) {
    (void)max_tensor_bytes;
    if (!ds4_gpu_set_model_map(model_map, model_size)) return 0;
    if (getenv("DS4_CUDA_COPY_MODEL_CHUNKED") != NULL &&
        !cuda_model_copy_chunked(model_map, model_size, map_offset, map_size)) {
        (void)cuda_model_prefetch_range(model_map, model_size, map_offset, map_size);
    }
    return 1;
}

extern "C" int ds4_gpu_set_model_map_spans(
        const void *model_map,
        uint64_t model_size,
        const uint64_t *offsets,
        const uint64_t *sizes,
        uint32_t count,
        uint64_t max_tensor_bytes) {
    (void)max_tensor_bytes;
    if (!model_map || model_size == 0 || !offsets || !sizes || count == 0) return 0;
    for (uint32_t i = 0; i < count; i++) {
        if (offsets[i] > model_size ||
            sizes[i] == 0 ||
            sizes[i] > model_size - offsets[i]) {
            return 0;
        }
    }
    if (!ds4_gpu_set_model_map(model_map, model_size)) return 0;

    if (getenv("DS4_CUDA_COPY_MODEL_CHUNKED") != NULL) {
        if (count > 1) {
            for (uint32_t i = 0; i < count; i++) {
                (void)cuda_model_prefetch_range(model_map, model_size, offsets[i], sizes[i]);
            }
            return 1;
        }
        for (uint32_t i = 0; i < count; i++) {
            if (!cuda_model_copy_chunked(model_map, model_size, offsets[i], sizes[i])) {
                (void)cuda_model_prefetch_range(model_map, model_size, offsets[i], sizes[i]);
            }
        }
    }
    return 1;
}

extern "C" int ds4_gpu_set_model_fd(int fd) {
    g_model_fd = fd;
    g_model_fd_host_base = g_model_host_base;
    g_model_file_size = 0;
    if (g_model_direct_fd >= 0) {
        (void)close(g_model_direct_fd);
        g_model_direct_fd = -1;
    }
    g_model_direct_align = 1;
    if (fd >= 0) {
        struct stat st;
        if (fstat(fd, &st) == 0 && st.st_size > 0) {
            g_model_file_size = (uint64_t)st.st_size;
            if (st.st_blksize > 1) g_model_direct_align = (uint64_t)st.st_blksize;
        }
#if defined(__linux__) && defined(O_DIRECT)
        if (getenv("DS4_CUDA_NO_DIRECT_IO") == NULL) {
            char proc_path[64];
            snprintf(proc_path, sizeof(proc_path), "/proc/self/fd/%d", fd);
            int direct_fd = open(proc_path, O_RDONLY | O_DIRECT);
            if (direct_fd >= 0) {
                g_model_direct_fd = direct_fd;
                if (g_model_direct_align < 512) g_model_direct_align = 512;
                if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
                    fprintf(stderr, "ds4: CUDA model direct I/O enabled (align=%llu)\n",
                            (unsigned long long)g_model_direct_align);
                }
            } else if (getenv("DS4_CUDA_WEIGHT_CACHE_VERBOSE")) {
                fprintf(stderr, "ds4: CUDA model direct I/O unavailable: %s\n", strerror(errno));
            }
        }
#endif
    }
    return 1;
}

static int cuda_hex_value(int c) {
    if (c >= '0' && c <= '9') return c - '0';
    if (c >= 'a' && c <= 'f') return c - 'a' + 10;
    if (c >= 'A' && c <= 'F') return c - 'A' + 10;
    return -1;
}

static int cuda_hex_decode(const char *hex, void *out, size_t out_bytes) {
    if (!hex || !out) return 0;
    const size_t nhex = strlen(hex);
    if (nhex != out_bytes * 2u) return 0;
    unsigned char *dst = (unsigned char *)out;
    for (size_t i = 0; i < out_bytes; i++) {
        const int hi = cuda_hex_value(hex[2u * i]);
        const int lo = cuda_hex_value(hex[2u * i + 1u]);
        if (hi < 0 || lo < 0) return 0;
        dst[i] = (unsigned char)((hi << 4) | lo);
    }
    return 1;
}

static int driver_ok(CUresult result, const char *what) {
    if (result == CUDA_SUCCESS) return 1;
    const char *name = NULL;
    const char *text = NULL;
    (void)cuGetErrorName(result, &name);
    (void)cuGetErrorString(result, &text);
    fprintf(stderr, "ds4: CUDA driver %s failed: %s%s%s\n",
            what,
            name ? name : "unknown",
            text ? ": " : "",
            text ? text : "");
    return 0;
}

static int recv_vmm_fd(const char *socket_path, unsigned long long alloc_id, unsigned long long *alloc_bytes_out) {
    if (!socket_path || !socket_path[0]) return -1;
    int fd = socket(AF_UNIX, SOCK_STREAM, 0);
    if (fd < 0) {
        fprintf(stderr, "ds4: CUDA VMM broker socket failed: %s\n", strerror(errno));
        return -1;
    }
    sockaddr_un addr;
    memset(&addr, 0, sizeof(addr));
    addr.sun_family = AF_UNIX;
    if (strlen(socket_path) >= sizeof(addr.sun_path)) {
        fprintf(stderr, "ds4: CUDA VMM broker socket path too long: %s\n", socket_path);
        close(fd);
        return -1;
    }
    strncpy(addr.sun_path, socket_path, sizeof(addr.sun_path) - 1u);
    if (connect(fd, (sockaddr *)&addr, sizeof(addr)) != 0) {
        fprintf(stderr, "ds4: CUDA VMM broker connect failed %s: %s\n", socket_path, strerror(errno));
        close(fd);
        return -1;
    }
    char req[64];
    snprintf(req, sizeof(req), "GET %llu\n", alloc_id);
    if (write(fd, req, strlen(req)) != (ssize_t)strlen(req)) {
        fprintf(stderr, "ds4: CUDA VMM broker request failed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    char buf[128];
    char control[CMSG_SPACE(sizeof(int))];
    memset(buf, 0, sizeof(buf));
    memset(control, 0, sizeof(control));
    struct iovec iov;
    iov.iov_base = buf;
    iov.iov_len = sizeof(buf) - 1u;
    struct msghdr msg;
    memset(&msg, 0, sizeof(msg));
    msg.msg_iov = &iov;
    msg.msg_iovlen = 1;
    msg.msg_control = control;
    msg.msg_controllen = sizeof(control);
    ssize_t n = recvmsg(fd, &msg, 0);
    close(fd);
    if (n <= 0) {
        fprintf(stderr, "ds4: CUDA VMM broker response failed\n");
        return -1;
    }
    buf[n] = '\0';
    unsigned long long got_id = 0;
    unsigned long long got_bytes = 0;
    if (sscanf(buf, "OK %llu %llu", &got_id, &got_bytes) != 2 || got_id != alloc_id) {
        fprintf(stderr, "ds4: CUDA VMM broker rejected alloc %llu: %s\n", alloc_id, buf);
        return -1;
    }
    int recv_fd = -1;
    for (struct cmsghdr *cmsg = CMSG_FIRSTHDR(&msg); cmsg; cmsg = CMSG_NXTHDR(&msg, cmsg)) {
        if (cmsg->cmsg_level == SOL_SOCKET && cmsg->cmsg_type == SCM_RIGHTS &&
            cmsg->cmsg_len >= CMSG_LEN(sizeof(int))) {
            memcpy(&recv_fd, CMSG_DATA(cmsg), sizeof(int));
            break;
        }
    }
    if (recv_fd < 0) {
        fprintf(stderr, "ds4: CUDA VMM broker did not send an FD for alloc %llu\n", alloc_id);
        return -1;
    }
    if (alloc_bytes_out) *alloc_bytes_out = got_bytes;
    return recv_fd;
}

static int import_vmm_allocation(
        const void *model_map,
        uint64_t model_size,
        const char *model_id,
        const char *broker_path,
        unsigned long long alloc_id,
        unsigned long long file_size,
        unsigned long long off,
        unsigned long long bytes,
        unsigned long long alloc_bytes,
        uint64_t *imported_bytes,
        uint64_t *imported_ranges) {
    if ((uint64_t)file_size != model_size ||
        (uint64_t)off > model_size ||
        (uint64_t)bytes > model_size - (uint64_t)off ||
        bytes == 0 ||
        alloc_bytes < bytes) {
        fprintf(stderr,
                "ds4: CUDA shared VMM allocation rejected for %s "
                "(manifest size=%llu local size=%llu off=%llu bytes=%llu alloc=%llu)\n",
                model_id,
                file_size,
                (unsigned long long)model_size,
                off,
                bytes,
                alloc_bytes);
        return 0;
    }

    unsigned long long broker_alloc_bytes = 0;
    int fd = recv_vmm_fd(broker_path, alloc_id, &broker_alloc_bytes);
    if (fd < 0) return 0;
    if (broker_alloc_bytes != alloc_bytes) {
        fprintf(stderr,
                "ds4: CUDA VMM broker alloc size mismatch for %s alloc=%llu broker=%llu manifest=%llu\n",
                model_id,
                alloc_id,
                broker_alloc_bytes,
                alloc_bytes);
        close(fd);
        return 0;
    }

    CUmemGenericAllocationHandle handle;
    memset(&handle, 0, sizeof(handle));
    if (!driver_ok(cuMemImportFromShareableHandle(&handle,
                                                  (void *)(uintptr_t)fd,
                                                  CU_MEM_HANDLE_TYPE_POSIX_FILE_DESCRIPTOR),
                   "VMM import POSIX FD")) {
        close(fd);
        return 0;
    }
    close(fd);

    CUdeviceptr va = 0;
    if (!driver_ok(cuMemAddressReserve(&va, (size_t)alloc_bytes, 0, 0, 0), "VMM import address reserve")) {
        (void)cuMemRelease(handle);
        return 0;
    }
    if (!driver_ok(cuMemMap(va, (size_t)alloc_bytes, 0, handle, 0), "VMM import map")) {
        (void)cuMemAddressFree(va, (size_t)alloc_bytes);
        (void)cuMemRelease(handle);
        return 0;
    }
    CUmemAccessDesc access;
    memset(&access, 0, sizeof(access));
    access.location.type = CU_MEM_LOCATION_TYPE_DEVICE;
    int dev_id = 0;
    (void)cudaGetDevice(&dev_id);
    access.location.id = dev_id;
    access.flags = CU_MEM_ACCESS_FLAGS_PROT_READ;
    if (!driver_ok(cuMemSetAccess(va, (size_t)alloc_bytes, &access, 1), "VMM import set access")) {
        (void)cuMemUnmap(va, (size_t)alloc_bytes);
        (void)cuMemAddressFree(va, (size_t)alloc_bytes);
        (void)cuMemRelease(handle);
        return 0;
    }

    if (!cuda_model_range_publish({
            model_map,
            (uint64_t)off,
            (uint64_t)bytes,
            (char *)va,
            NULL,
            NULL,
            0,
            0,
            0,
            0,
            1,
            handle,
            va,
            (uint64_t)alloc_bytes,
        })) {
        (void)cuMemUnmap(va, (size_t)alloc_bytes);
        (void)cuMemAddressFree(va, (size_t)alloc_bytes);
        (void)cuMemRelease(handle);
        return 0;
    }
    g_model_range_bytes += (uint64_t)bytes;
    cuda_mem_note_alloc_src(DS4_MEMC_WEIGHT_IMPORT, DS4_MEMD_UNIFIED_DEVICE,
                            (uint64_t)bytes, (uint64_t)alloc_bytes, model_map);
    *imported_bytes += (uint64_t)bytes;
    *imported_ranges += 1;
    return 1;
}

static int import_vmm_derived_allocation(
        const void *model_map,
        uint64_t model_size,
        const char *model_id,
        const char *broker_path,
        unsigned long long alloc_id,
        unsigned long long file_size,
        unsigned long long source_off,
        unsigned long long source_bytes,
        unsigned int kind,
        unsigned long long in_dim,
        unsigned long long out_dim,
        unsigned int group_count,
        unsigned long long bytes,
        unsigned long long alloc_bytes,
        uint64_t *imported_bytes,
        uint64_t *imported_ranges) {
    if ((uint64_t)file_size != model_size ||
        (uint64_t)source_off > model_size ||
        (uint64_t)source_bytes > model_size - (uint64_t)source_off ||
        source_bytes == 0 ||
        bytes == 0 ||
        alloc_bytes < bytes) {
        fprintf(stderr,
                "ds4: CUDA derived VMM allocation rejected for %s "
                "(manifest size=%llu local size=%llu source=%llu bytes=%llu derived=%llu alloc=%llu)\n",
                model_id,
                file_size,
                (unsigned long long)model_size,
                source_off,
                source_bytes,
                bytes,
                alloc_bytes);
        return 0;
    }

    unsigned long long broker_alloc_bytes = 0;
    int fd = recv_vmm_fd(broker_path, alloc_id, &broker_alloc_bytes);
    if (fd < 0) return 0;
    if (broker_alloc_bytes != alloc_bytes) {
        fprintf(stderr,
                "ds4: CUDA VMM broker derived alloc size mismatch for %s alloc=%llu broker=%llu manifest=%llu\n",
                model_id,
                alloc_id,
                broker_alloc_bytes,
                alloc_bytes);
        close(fd);
        return 0;
    }

    CUmemGenericAllocationHandle handle;
    memset(&handle, 0, sizeof(handle));
    if (!driver_ok(cuMemImportFromShareableHandle(&handle,
                                                  (void *)(uintptr_t)fd,
                                                  CU_MEM_HANDLE_TYPE_POSIX_FILE_DESCRIPTOR),
                   "VMM import derived POSIX FD")) {
        close(fd);
        return 0;
    }
    close(fd);

    CUdeviceptr va = 0;
    if (!driver_ok(cuMemAddressReserve(&va, (size_t)alloc_bytes, 0, 0, 0),
                   "VMM import derived address reserve")) {
        (void)cuMemRelease(handle);
        return 0;
    }
    if (!driver_ok(cuMemMap(va, (size_t)alloc_bytes, 0, handle, 0), "VMM import derived map")) {
        (void)cuMemAddressFree(va, (size_t)alloc_bytes);
        (void)cuMemRelease(handle);
        return 0;
    }
    CUmemAccessDesc access;
    memset(&access, 0, sizeof(access));
    access.location.type = CU_MEM_LOCATION_TYPE_DEVICE;
    int dev_id = 0;
    (void)cudaGetDevice(&dev_id);
    access.location.id = dev_id;
    access.flags = CU_MEM_ACCESS_FLAGS_PROT_READ;
    if (!driver_ok(cuMemSetAccess(va, (size_t)alloc_bytes, &access, 1),
                   "VMM import derived set access")) {
        (void)cuMemUnmap(va, (size_t)alloc_bytes);
        (void)cuMemAddressFree(va, (size_t)alloc_bytes);
        (void)cuMemRelease(handle);
        return 0;
    }

    if (!cuda_derived_range_publish({
            model_map,
            (uint64_t)source_off,
            (uint64_t)source_bytes,
            (uint32_t)kind,
            (uint64_t)in_dim,
            (uint64_t)out_dim,
            (uint32_t)group_count,
            (uint64_t)bytes,
            (char *)va,
            0,
            1,
            handle,
            va,
            (uint64_t)alloc_bytes,
        })) {
        (void)cuMemUnmap(va, (size_t)alloc_bytes);
        (void)cuMemAddressFree(va, (size_t)alloc_bytes);
        (void)cuMemRelease(handle);
        return 0;
    }
    g_derived_range_bytes += (uint64_t)bytes;
    cuda_mem_note_alloc_src(DS4_MEMC_WEIGHT_IMPORT, DS4_MEMD_UNIFIED_DEVICE,
                            (uint64_t)bytes, (uint64_t)alloc_bytes, model_map);
    *imported_bytes += (uint64_t)bytes;
    *imported_ranges += 1;
    return 1;
}

/* Rider #48: verify the manifest's content fingerprint for model_id
 * against this process's own mapping of the model file, BEFORE any range
 * is published (a mismatch after partial publication would need rollback).
 * The manifest is a few KiB, so a dedicated pre-scan pass is cheap and
 * keeps the check independent of record order in the file.
 * Returns 2 = verified, 1 = proceed unverified (no record / unknown algo /
 * check disabled), 0 = refuse (fingerprint or size mismatch: the weight
 * server is serving different bytes than this engine's file). */
static int manifest_content_identity_check(const char *manifest_path,
                                           const void *model_map,
                                           uint64_t model_size,
                                           const char *model_id) {
    const char *knob = getenv("DS4_WEIGHT_FP_CHECK");
    if (knob && knob[0] == '0' && knob[1] == '\0') {
        fprintf(stderr,
                "ds4: CUDA weight manifest content check DISABLED for %s "
                "(DS4_WEIGHT_FP_CHECK=0); identity by model id + size only\n",
                model_id);
        return 1;
    }
    FILE *fp = fopen(manifest_path, "r");
    if (!fp) return 1; /* the caller re-opens and reports open failures */
    char line[4096];
    int found = 0;
    unsigned long long rec_size = 0;
    char rec_algo[64] = {0};
    char rec_hex[64] = {0};
    while (fgets(line, sizeof(line), fp)) {
        char *p = line;
        while (*p == ' ' || *p == '\t') p++;
        if (*p == '#' || *p == '\n' || *p == '\0') continue;
        char rec[32] = {0};
        char id[64] = {0};
        if (sscanf(p, "%31s %63s %llu %63s %63s",
                   rec, id, &rec_size, rec_algo, rec_hex) != 5) continue;
        if (strcmp(rec, "content") != 0 || strcmp(id, model_id) != 0) continue;
        found = 1;
        break;
    }
    fclose(fp);
    if (!found) {
        fprintf(stderr,
                "ds4: CUDA weight manifest carries no content fingerprint for "
                "%s (older ds4_weight_server); identity by model id + size "
                "only\n",
                model_id);
        return 1;
    }
    if (strcmp(rec_algo, DS4_WFP_ALGO) != 0) {
        fprintf(stderr,
                "ds4: CUDA weight manifest content fingerprint for %s uses "
                "unknown algo %s (this engine speaks %s); identity by model "
                "id + size only\n",
                model_id, rec_algo, DS4_WFP_ALGO);
        return 1;
    }
    uint64_t local_fp = ds4_weight_content_fingerprint(model_map, model_size);
    uint64_t manifest_fp = (uint64_t)strtoull(rec_hex, NULL, 16);
    if ((uint64_t)rec_size != model_size || manifest_fp != local_fp) {
        fprintf(stderr,
                "ds4: CUDA weight manifest CONTENT IDENTITY MISMATCH for %s: "
                "manifest %s size=%llu, local %016llx size=%llu. The weight "
                "server is serving different bytes than this engine's model "
                "file; restart ds4_weight_server on the current gguf.\n",
                model_id,
                rec_hex,
                rec_size,
                (unsigned long long)local_fp,
                (unsigned long long)model_size);
        return 0;
    }
    return 2;
}

extern "C" int ds4_gpu_import_model_ipc_manifest(
        const void *model_map,
        uint64_t model_size,
        const char *manifest_path,
        const char *model_id) {
    if (!model_map || model_size == 0 || !manifest_path || !manifest_path[0] ||
        !model_id || !model_id[0]) {
        return 0;
    }
    int content_state = manifest_content_identity_check(manifest_path,
                                                        model_map,
                                                        model_size,
                                                        model_id);
    if (content_state == 0) return 0;
    FILE *fp = fopen(manifest_path, "r");
    if (!fp) {
        fprintf(stderr, "ds4: CUDA shared weight manifest open failed: %s: %s\n",
                manifest_path, strerror(errno));
        return 0;
    }

    char line[4096];
    char broker_path[512] = {0};
    uint64_t imported_bytes = 0;
    uint64_t imported_ranges = 0;
    uint64_t imported_derived_bytes = 0;
    uint64_t imported_derived_ranges = 0;
    int saw_header = 0;
    int vmm_manifest = 0;
    int ok = 1;
    while (fgets(line, sizeof(line), fp)) {
        char *p = line;
        while (*p == ' ' || *p == '\t') p++;
        if (*p == '#' || *p == '\n' || *p == '\0') continue;
        if (!strncmp(p, "DS4_WEIGHT_SERVER_IPC_V1", 24) ||
            !strncmp(p, "DS4_WEIGHT_SERVER_IPC_DERIVED_V1", 32) ||
            !strncmp(p, "DS4_WEIGHTD_IPC_V1", 18)) {
            saw_header = 1;
            vmm_manifest = 0;
            continue;
        }
        if (!strncmp(p, "DS4_WEIGHT_SERVER_VMM_V1", 24) ||
            !strncmp(p, "DS4_WEIGHT_SERVER_VMM_DERIVED_V1", 32)) {
            saw_header = 1;
            vmm_manifest = 1;
            continue;
        }

        char rec[32] = {0};
        char id[64] = {0};
        char hex[256] = {0};
        unsigned long long file_size = 0;
        unsigned long long off = 0;
        unsigned long long bytes = 0;
        if (vmm_manifest) {
            char broker_candidate[512] = {0};
            if (sscanf(p, "%31s %511s", rec, broker_candidate) == 2) {
                if (strcmp(rec, "broker") == 0) {
                    strncpy(broker_path, broker_candidate, sizeof(broker_path) - 1u);
                    broker_path[sizeof(broker_path) - 1u] = '\0';
                    continue;
                }
            }
            if (sscanf(p, "%31s", rec) == 1 && strcmp(rec, "derived-alloc") == 0) {
                unsigned long long alloc_id = 0;
                unsigned int kind = 0;
                unsigned int group_count = 0;
                unsigned long long source_off = 0;
                unsigned long long source_bytes = 0;
                unsigned long long in_dim = 0;
                unsigned long long out_dim = 0;
                unsigned long long derived_bytes = 0;
                unsigned long long derived_alloc_bytes = 0;
                char source_name[256] = {0};
                if (sscanf(p, "%31s %llu %63s %llu %llu %llu %u %llu %llu %u %llu %llu %255s",
                           rec,
                           &alloc_id,
                           id,
                           &file_size,
                           &source_off,
                           &source_bytes,
                           &kind,
                           &in_dim,
                           &out_dim,
                           &group_count,
                           &derived_bytes,
                           &derived_alloc_bytes,
                           source_name) != 13) {
                    continue;
                }
                if (strcmp(id, model_id) != 0) continue;
                if (!broker_path[0]) {
                    fprintf(stderr, "ds4: CUDA shared VMM manifest missing broker before derived allocation\n");
                    ok = 0;
                    break;
                }
                if (!driver_ok(cuInit(0), "init")) {
                    ok = 0;
                    break;
                }
                if (!import_vmm_derived_allocation(model_map,
                                                   model_size,
                                                   model_id,
                                                   broker_path,
                                                   alloc_id,
                                                   file_size,
                                                   source_off,
                                                   source_bytes,
                                                   kind,
                                                   in_dim,
                                                   out_dim,
                                                   group_count,
                                                   derived_bytes,
                                                   derived_alloc_bytes,
                                                   &imported_derived_bytes,
                                                   &imported_derived_ranges)) {
                    ok = 0;
                    break;
                }
                continue;
            }
            unsigned long long alloc_id = 0;
            unsigned long long alloc_bytes = 0;
            if (sscanf(p, "%31s %llu %63s %llu %llu %llu %llu",
                       rec, &alloc_id, id, &file_size, &off, &bytes, &alloc_bytes) != 7) {
                continue;
            }
            if (strcmp(rec, "alloc") != 0 || strcmp(id, model_id) != 0) continue;
            if (!broker_path[0]) {
                fprintf(stderr, "ds4: CUDA shared VMM manifest missing broker before alloc record\n");
                ok = 0;
                break;
            }
            if (!driver_ok(cuInit(0), "init")) {
                ok = 0;
                break;
            }
            if (!import_vmm_allocation(model_map,
                                       model_size,
                                       model_id,
                                       broker_path,
                                       alloc_id,
                                       file_size,
                                       off,
                                       bytes,
                                       alloc_bytes,
                                       &imported_bytes,
                                       &imported_ranges)) {
                ok = 0;
                break;
            }
            continue;
        }
        if (!strncmp(p, "derived-range", 13)) {
            unsigned int kind = 0;
            unsigned int group_count = 0;
            unsigned long long source_off = 0;
            unsigned long long source_bytes = 0;
            unsigned long long in_dim = 0;
            unsigned long long out_dim = 0;
            unsigned long long derived_bytes = 0;
            char source_name[256] = {0};
            if (sscanf(p, "%31s %63s %llu %llu %llu %u %llu %llu %u %llu %255s %255s",
                       rec,
                       id,
                       &file_size,
                       &source_off,
                       &source_bytes,
                       &kind,
                       &in_dim,
                       &out_dim,
                       &group_count,
                       &derived_bytes,
                       hex,
                       source_name) != 12) {
                continue;
            }
            if (strcmp(id, model_id) != 0) continue;
            if ((uint64_t)file_size != model_size ||
                (uint64_t)source_off > model_size ||
                (uint64_t)source_bytes > model_size - (uint64_t)source_off ||
                source_bytes == 0 ||
                derived_bytes == 0) {
                fprintf(stderr,
                        "ds4: CUDA shared derived weight manifest range rejected for %s "
                        "(manifest size=%llu local size=%llu source=%llu source_bytes=%llu derived=%llu)\n",
                        model_id,
                        file_size,
                        (unsigned long long)model_size,
                        source_off,
                        source_bytes,
                        derived_bytes);
                ok = 0;
                break;
            }
            cudaIpcMemHandle_t handle;
            memset(&handle, 0, sizeof(handle));
            if (!cuda_hex_decode(hex, &handle, sizeof(handle))) {
                fprintf(stderr, "ds4: CUDA shared derived weight manifest has invalid IPC handle for %s\n", model_id);
                ok = 0;
                break;
            }
            void *dev = NULL;
            cudaError_t err = cudaIpcOpenMemHandle(&dev, handle, cudaIpcMemLazyEnablePeerAccess);
            if (err != cudaSuccess) {
                fprintf(stderr,
                        "ds4: CUDA shared derived weight IPC import failed for %s source=%llu bytes=%.2f MiB: %s\n",
                        model_id,
                        source_off,
                        (double)derived_bytes / 1048576.0,
                        cudaGetErrorString(err));
                (void)cudaGetLastError();
                ok = 0;
                break;
            }
            if (!cuda_derived_range_publish({
                    model_map,
                    (uint64_t)source_off,
                    (uint64_t)source_bytes,
                    (uint32_t)kind,
                    (uint64_t)in_dim,
                    (uint64_t)out_dim,
                    (uint32_t)group_count,
                    (uint64_t)derived_bytes,
                    (char *)dev,
                    1,
                    0,
                    0,
                    0,
                    0,
                })) {
                (void)cudaIpcCloseMemHandle(dev);
                (void)cudaGetLastError();
                ok = 0;
                break;
            }
            g_derived_range_bytes += (uint64_t)derived_bytes;
            cuda_mem_note_alloc_src(DS4_MEMC_WEIGHT_IMPORT, DS4_MEMD_UNIFIED_DEVICE,
                                    (uint64_t)derived_bytes,
                                    (uint64_t)derived_bytes, model_map);
            imported_derived_bytes += (uint64_t)derived_bytes;
            imported_derived_ranges++;
            continue;
        }
        if (sscanf(p, "%31s %63s %llu %llu %llu %255s",
                   rec, id, &file_size, &off, &bytes, hex) != 6) {
            continue;
        }
        if (strcmp(rec, "range") != 0 || strcmp(id, model_id) != 0) continue;
        if ((uint64_t)file_size != model_size ||
            (uint64_t)off > model_size ||
            (uint64_t)bytes > model_size - (uint64_t)off ||
            bytes == 0) {
            fprintf(stderr,
                    "ds4: CUDA shared weight manifest range rejected for %s "
                    "(manifest size=%llu local size=%llu off=%llu bytes=%llu)\n",
                    model_id,
                    file_size,
                    (unsigned long long)model_size,
                    off,
                    bytes);
            ok = 0;
            break;
        }

        cudaIpcMemHandle_t handle;
        memset(&handle, 0, sizeof(handle));
        if (!cuda_hex_decode(hex, &handle, sizeof(handle))) {
            fprintf(stderr, "ds4: CUDA shared weight manifest has invalid IPC handle for %s\n", model_id);
            ok = 0;
            break;
        }
        void *dev = NULL;
        cudaError_t err = cudaIpcOpenMemHandle(&dev, handle, cudaIpcMemLazyEnablePeerAccess);
        if (err != cudaSuccess) {
            fprintf(stderr,
                    "ds4: CUDA shared weight IPC import failed for %s off=%llu bytes=%.2f MiB: %s\n",
                    model_id,
                    off,
                    (double)bytes / 1048576.0,
                    cudaGetErrorString(err));
            (void)cudaGetLastError();
            ok = 0;
            break;
        }
        if (!cuda_model_range_publish({
                model_map,
                (uint64_t)off,
                (uint64_t)bytes,
                (char *)dev,
                NULL,
                NULL,
                0,
                0,
                0,
                1,
                0,
                0,
                0,
                0,
            })) {
            (void)cudaIpcCloseMemHandle(dev);
            (void)cudaGetLastError();
            ok = 0;
            break;
        }
        g_model_range_bytes += (uint64_t)bytes;
        cuda_mem_note_alloc_src(DS4_MEMC_WEIGHT_IMPORT, DS4_MEMD_UNIFIED_DEVICE,
                                (uint64_t)bytes, (uint64_t)bytes, model_map);
        imported_bytes += (uint64_t)bytes;
        imported_ranges++;
    }
    fclose(fp);
    if (!saw_header) {
        fprintf(stderr, "ds4: CUDA shared weight manifest missing DS4_WEIGHT_SERVER_IPC_V1 header: %s\n",
                manifest_path);
        return 0;
    }
    if (!ok) return 0;
    if (imported_ranges == 0) {
        fprintf(stderr, "ds4: CUDA shared weight manifest had no ranges for model id %s\n", model_id);
        return 0;
    }
    fprintf(stderr,
            "ds4: CUDA imported shared %s weight cache for %s: %.2f GiB across %llu ranges%s",
            vmm_manifest ? "VMM" : "IPC",
            model_id,
            (double)imported_bytes / 1073741824.0,
            (unsigned long long)imported_ranges,
            content_state == 2 ? " (content identity verified)" : "");
    if (imported_derived_ranges != 0) {
        fprintf(stderr,
                " plus %.2f MiB across %llu derived artifacts",
                (double)imported_derived_bytes / 1048576.0,
                (unsigned long long)imported_derived_ranges);
        g_derived_artifact_source = CUDA_DERIVED_ARTIFACTS_IMPORTED;
        g_derived_artifact_count += imported_derived_ranges;
        g_derived_artifact_bytes += imported_derived_bytes;
    } else if (strcmp(model_id, "base") == 0 &&
               g_derived_artifact_source == CUDA_DERIVED_ARTIFACTS_NONE) {
        g_derived_artifact_none_reason =
            "manifest has no derived artifacts; start ds4_weight_server with the "
            "--repack-*-aligned defaults";
    }
    fprintf(stderr, "\n");
    return 1;
}

/* ---- self-load aligned artifacts (v0.2.2) ---------------------------------
 * A boot with no DS4_CUDA_WEIGHT_IPC_MANIFEST used to run every dispatch on
 * the raw-layout tier: the aligned-SoA fast paths were gated on
 * weight-server-built derived artifacts, so installer self-load boots
 * measured decode 13.9 vs ~17.8 tok/s (prefill ~488 vs ~800) with no log
 * tell.  Build the SAME artifacts in-process at load — the builders, S5
 * parallel driver, and byte layouts are shared with the weight server via
 * cuda/mmq/ds4_repack.cu (FNV bit-identity gated) — and register them in
 * g_derived_ranges so every cuda_derived_weight_ptr dispatch site is
 * untouched.  Precedence: manifest import > in-process build > raw.
 * DS4_CUDA_NO_DERIVED_WEIGHTS (existing kill switch) disables the build too;
 * DS4_CUDA_BUILD_ARTIFACTS=0 opts out of just the boot-time build. */
static uint32_t cuda_moe_iq2_aligned_enabled(void);
static uint32_t cuda_moe_q2k_aligned_enabled(void);
static uint32_t cuda_q8_aligned_enabled(void);

extern "C" int ds4_gpu_build_derived_artifacts(
        const void *model_map,
        uint64_t model_size,
        const char *model_path) {
    if (!model_map || model_size == 0 || !model_path || !model_path[0]) return 0;
    if (getenv("DS4_CUDA_WEIGHT_IPC_MANIFEST") != NULL) return 0;
    if (getenv("DS4_CUDA_NO_DERIVED_WEIGHTS") != NULL) {
        g_derived_artifact_none_reason = "DS4_CUDA_NO_DERIVED_WEIGHTS is set";
        return 0;
    }
    const char *knob = getenv("DS4_CUDA_BUILD_ARTIFACTS");
    if (knob && knob[0] == '0' && knob[1] == '\0') {
        g_derived_artifact_none_reason = "DS4_CUDA_BUILD_ARTIFACTS=0";
        return 0;
    }
    int integrated = 0;
    int dev = 0;
    if (cudaGetDevice(&dev) != cudaSuccess ||
        cudaDeviceGetAttribute(&integrated, cudaDevAttrIntegrated, dev) != cudaSuccess ||
        !integrated) {
        /* Discrete VRAM cannot hold the ~79 GiB artifact set next to the
         * streamed model; the weight-server repack route stays the fast
         * tier there. */
        g_derived_artifact_none_reason =
            "discrete GPU (use ds4_weight_server --repack-*-aligned for the aligned tier)";
        return 0;
    }

    ds4_repack_file m;
    if (!ds4_repack_map_file("ds4", model_path, m)) {
        g_derived_artifact_none_reason = "model reopen failed";
        return 0;
    }
    if (m.size != model_size) {
        ds4_repack_unmap_file(m);
        g_derived_artifact_none_reason = "model size mismatch on reopen";
        return 0;
    }
    std::vector<ds4_repack_tensor> records;
    const bool catalog_ok = ds4_repack_collect_catalog("ds4", m, nullptr, &records);
    ds4_repack_unmap_file(m);
    if (!catalog_ok) {
        g_derived_artifact_none_reason = "GGUF catalog parse failed";
        return 0;
    }

    /* The iq2/q2k artifacts REPLACE their raw residency (the whole-model
     * registration skip + walk uncap key on a COMPLETE replace set), so a
     * kill switch on either MoE dispatch disables both MoE builds: a partial
     * set would strand the other kind's ~30-45 GiB raws on the slow tier
     * while its artifacts still hold device memory.  Q8 stays independent —
     * it is additive. */
    const bool build_moe = cuda_moe_iq2_aligned_enabled() != 0 &&
                           cuda_moe_q2k_aligned_enabled() != 0;
    const bool build_q8 = cuda_q8_aligned_enabled() != 0;
    /* inc-12f: prebuild the q8->f16 colmajor out_a cache the packed prefill
     * path otherwise first-touch-builds on the first admit per boot (41 x
     * ~31 ms alloc+dequant stalls, ~1.3 s of cold TTFT).  Rides the existing
     * derived-artifact contract (cuda_q8_f16_ptr consults the registry before
     * lazily building), so dispatch sites are untouched and the bytes are
     * identical by the shared kernel math.  Mirrors the runtime admission
     * gate so the artifact never outlives its consumer.  Building here, ahead
     * of the KV bank fit, also charges the ~2.9 GiB to MemAvailable BEFORE
     * banks are sized -- the lazy build ate post-fit headroom instead. */
    const char *f16_knob = getenv("DS4_CUDA_PREBUILD_F16");
    /* flat-pool p1: the fused own out_a kernel replaces the packed-f16
     * consumer whenever aligned Q8_0 artifacts are on, so prebuilding the
     * ~2.9 GiB f16 cache would strand memory nothing reads (the fit would
     * charge it against KV banks).  The kill-switch leg
     * (DS4_CUDA_NO_OUTA_OWN) restores the prebuild with its consumer; a
     * runtime geometry decline still lazily builds per layer, as before
     * inc-12f. */
    const bool outa_own_serves = getenv("DS4_CUDA_NO_OUTA_OWN") == NULL && build_q8;
    const bool build_f16 = !(f16_knob && f16_knob[0] == '0' && f16_knob[1] == '\0') &&
                           !outa_own_serves &&
                           cuda_q8_f16_cache_allowed("attn_output_a", 0, 0) != 0;
    if (!build_moe && !build_q8 && !build_f16) {
        g_derived_artifact_none_reason = "aligned dispatches disabled by env";
        return 0;
    }

    const double t0 = cuda_wall_sec();
    ds4_repack_build_args a;
    a.log_prefix = "ds4";
    a.model_id = "base";
    a.path = model_path;
    a.records = &records;
    a.device = dev;
    a.copy_chunk_bytes = 256ull * 1048576ull; /* weight-server --copy-chunk-mb default */
    std::vector<ds4_repack_artifact> arts;
    uint64_t built_bytes = 0;
    uint64_t part = 0;
    bool ok = true;
    /* Same build order as the weight server: q2k, iq2, q8. */
    if (ok && build_moe) {
        ok = ds4_repack_build_q2k_aligned(a, arts, &part);
        built_bytes += part;
    }
    if (ok && build_moe) {
        ok = ds4_repack_build_iq2_aligned(a, arts, &part);
        built_bytes += part;
    }
    if (ok && build_q8) {
        ok = ds4_repack_build_q8_aligned(a, arts, &part);
        built_bytes += part;
    }
    if (ok && build_f16) {
        /* Optional acceleration tier: a failed prebuild keeps the lazy
         * first-touch path and must not demote the aligned artifacts. */
        if (ds4_repack_build_q8_f16(a, arts, &part)) {
            built_bytes += part;
        } else {
            fprintf(stderr, "ds4: q8 f16 prebuild failed; keeping the lazy cache path\n");
        }
    }
    if (!ok) {
        for (ds4_repack_artifact &art : arts) {
            if (art.dev) (void)cudaFree(art.dev);
        }
        g_derived_artifact_none_reason = "in-process build failed; raw fallback";
        return 0;
    }
    if (arts.empty()) {
        g_derived_artifact_none_reason = "no candidate tensors in this GGUF";
        return 0;
    }

    uint64_t published = 0;
    for (ds4_repack_artifact &art : arts) {
        if (!cuda_derived_range_publish({
                model_map,
                art.t->off,
                art.t->bytes,
                art.kind,
                art.in_dim,
                art.out_dim,
                art.group_count,
                art.bytes,
                (char *)art.dev,
                0,
                0,
                0,
                0,
                0,
            })) {
            /* D1a-4 refusal: free the orphan build and mark the artifact
             * absent (nulled dev) so the completeness scan below cannot
             * count a REPLACE candidate the registry never accepted. */
            (void)cudaFree(art.dev);
            built_bytes -= art.bytes;
            art.dev = NULL;
            continue;
        }
        g_derived_range_bytes += art.bytes;
        cuda_mem_note_alloc_src(DS4_MEMC_WEIGHT_ARTIFACT, DS4_MEMD_UNIFIED_DEVICE,
                                art.bytes, art.bytes, model_map);
        published++;
    }

    /* Replace-set completeness: the registration skip must only fire when
     * every iq2/q2k candidate raw is actually replaced. */
    int replaces_complete = build_moe ? 1 : 0;
    if (build_moe) {
        for (const ds4_repack_tensor &t : records) {
            if (!ds4_repack_iq2_candidate(t) && !ds4_repack_q2k_candidate(t)) continue;
            bool have = false;
            for (const ds4_repack_artifact &art : arts) {
                if (art.t == &t && art.dev) { have = true; break; }
            }
            if (!have) { replaces_complete = 0; break; }
        }
    }
    g_derived_replaces_complete = replaces_complete;

    g_derived_artifact_source = CUDA_DERIVED_ARTIFACTS_BUILT;
    g_derived_artifact_count = published;
    g_derived_artifact_bytes = built_bytes;
    g_derived_artifact_build_secs = cuda_wall_sec() - t0;
    return (int)published;
}

extern "C" void ds4_gpu_derived_artifact_stats(
        int *source,
        uint64_t *count,
        uint64_t *bytes,
        double *build_secs) {
    if (source) *source = g_derived_artifact_source;
    if (count) *count = g_derived_artifact_count;
    if (bytes) *bytes = g_derived_artifact_bytes;
    if (build_secs) *build_secs = g_derived_artifact_build_secs;
}

/* One canonical boot line for the aligned-artifact perf tier — the absence
 * of the fast path must never again be silent. */
extern "C" void ds4_gpu_report_derived_artifacts(void) {
    switch (g_derived_artifact_source) {
    case CUDA_DERIVED_ARTIFACTS_BUILT:
        fprintf(stderr,
                "ds4: aligned artifacts built in-process (%llu artifacts, %.2f GiB, %.1fs)\n",
                (unsigned long long)g_derived_artifact_count,
                (double)g_derived_artifact_bytes / 1073741824.0,
                g_derived_artifact_build_secs);
        break;
    case CUDA_DERIVED_ARTIFACTS_IMPORTED:
        fprintf(stderr,
                "ds4: aligned artifacts imported from weight server (%llu artifacts, %.2f GiB)\n",
                (unsigned long long)g_derived_artifact_count,
                (double)g_derived_artifact_bytes / 1073741824.0);
        break;
    default:
        fprintf(stderr,
                "ds4: aligned artifacts: none — raw-layout dispatch tier (%s)\n",
                g_derived_artifact_none_reason
                    ? g_derived_artifact_none_reason
                    : "no aligned artifacts were imported or built");
        break;
    }
}

/* memgov D1a-1: per-source boot residency lines + ledger reconciliation.
 * Every WEIGHT_* note dual-writes cell + source row under one epoch
 * bracket, so in a fault-free ledger the rows of each weight class sum
 * to its census cell EXACTLY; a divergence here is an attribution bug
 * and counts a census fault (every standing gate asserts faults == 0).
 * Weight classes are the contiguous enum run ARENA..HOST_PIN. */
extern "C" void ds4_gpu_report_model_sources(void) {
    /* D1a-4 backfill: boot publications precede the unit-table binds (the
     * pre-cache walk and manifest imports run inside model open; the
     * tables compile after), so ranges published early carry the -1/-1
     * no-plan marker.  Stamp them now from the bound tables -- the stamp
     * is a pure function of (map, interval), so late stamping is exact.
     * Publications after the binds stamp at publish time, keeping the
     * "every live range is plan-known" invariant continuous post-boot. */
    for (cuda_model_range &r : g_model_ranges) {
        if (r.host_base && r.unit_lo < 0)
            cuda_range_stamp(r.host_base, r.offset, r.bytes,
                             &r.src, &r.unit_lo, &r.unit_hi);
    }
    for (cuda_derived_range &r : g_derived_ranges) {
        if (r.host_base && r.unit_lo < 0)
            cuda_range_stamp(r.host_base, r.source_offset, r.source_bytes,
                             &r.src, &r.unit_lo, &r.unit_hi);
    }
    for (cuda_q8_f16_range &r : g_q8_f16_ranges) {
        if (r.host_base && r.unit_lo < 0)
            cuda_range_stamp(r.host_base, r.offset, r.weight_bytes,
                             &r.src, &r.unit_lo, &r.unit_hi);
    }
    for (cuda_q8_f32_range &r : g_q8_f32_ranges) {
        if (r.host_base && r.unit_lo < 0)
            cuda_range_stamp(r.host_base, r.offset, r.weight_bytes,
                             &r.src, &r.unit_lo, &r.unit_hi);
    }
    for (int i = 0; i < g_model_srcs.count; i++) {
        const ds4_model_source *s = &g_model_srcs.v[i];
        uint64_t dev_live = 0;
        for (int cls = DS4_MEMC_WEIGHT_ARENA; cls <= DS4_MEMC_WEIGHT_HOST_PIN; cls++)
            dev_live += ds4_mem_cell_live(
                &g_mem_src_census[i][cls][DS4_MEMD_UNIFIED_DEVICE]);
        const uint64_t pin_live = ds4_mem_cell_live(
            &g_mem_src_census[i][DS4_MEMC_WEIGHT_HOST_PIN][DS4_MEMD_PINNED_HOST]);
        fprintf(stderr,
                "ds4: model source %s [%s]: map %.2f GiB, device %.2f GiB, "
                "host-pinned %.2f GiB (%s)\n",
                s->name,
                ds4_model_source_role_name(s->role),
                (double)s->map_len / 1073741824.0,
                (double)dev_live / 1073741824.0,
                (double)pin_live / 1073741824.0,
                s->path[0] ? s->path : "-");
    }
    {
        uint64_t un_dev = 0, un_pin = 0;
        for (int cls = DS4_MEMC_WEIGHT_ARENA; cls <= DS4_MEMC_WEIGHT_HOST_PIN; cls++) {
            un_dev += ds4_mem_cell_live(
                &g_mem_src_census[DS4_MSRC_MAX][cls][DS4_MEMD_UNIFIED_DEVICE]);
            un_pin += ds4_mem_cell_live(
                &g_mem_src_census[DS4_MSRC_MAX][cls][DS4_MEMD_PINNED_HOST]);
        }
        if (un_dev || un_pin) {
            fprintf(stderr,
                    "ds4: model source UNATTRIBUTED: device %.2f GiB, "
                    "host-pinned %.2f GiB (weight traffic outside every bound map)\n",
                    (double)un_dev / 1073741824.0,
                    (double)un_pin / 1073741824.0);
        }
    }
    int mismatches = 0;
    for (int cls = DS4_MEMC_WEIGHT_ARENA; cls <= DS4_MEMC_WEIGHT_HOST_PIN; cls++) {
        for (int dom = 0; dom < DS4_MEMD__COUNT; dom++) {
            ds4_mem_cell sum = {0, 0, 0, 0, 0, 0};
            for (int s = 0; s <= DS4_MSRC_MAX; s++) {
                const ds4_mem_cell *c = &g_mem_src_census[s][cls][dom];
                sum.requested += c->requested;
                sum.committed += c->committed;
                sum.freed_requested += c->freed_requested;
                sum.freed_committed += c->freed_committed;
            }
            const ds4_mem_cell *cell = &g_mem_census[cls][dom];
            if (sum.requested != cell->requested ||
                sum.committed != cell->committed ||
                sum.freed_requested != cell->freed_requested ||
                sum.freed_committed != cell->freed_committed) {
                mismatches++;
                g_mem_census_faults++;
                fprintf(stderr,
                        "ds4: MEM-CENSUS FAULT: source ledger mismatch "
                        "class=%d dom=%d cell live=%llu rows live=%llu\n",
                        cls, dom,
                        (unsigned long long)ds4_mem_cell_live(cell),
                        (unsigned long long)(sum.committed - sum.freed_committed));
            }
        }
    }
    if (mismatches == 0 && g_model_srcs.count > 0) {
        fprintf(stderr,
                "ds4: model-source ledger reconciled: %d weight classes x %d "
                "domains == census cells (%d sources)\n",
                DS4_MEMC_WEIGHT_HOST_PIN - DS4_MEMC_WEIGHT_ARENA + 1,
                (int)DS4_MEMD__COUNT,
                g_model_srcs.count);
    }
    /* D1a-4: one range-plan line per source -- live publications vs how
     * many the plan knows (unit-stamped).  planned == total is the gate
     * assertion; refused publications already faulted one by one. */
    for (int i = 0; i < g_model_srcs.count; i++) {
        uint32_t nm = 0, nm_planned = 0, nd = 0, nd_planned = 0;
        uint32_t nq = 0, nq_planned = 0, nm_multi = 0;
        for (const cuda_model_range &r : g_model_ranges) {
            if (!r.host_base || r.src != i) continue;
            nm++;
            if (r.unit_lo >= 0) nm_planned++;
            /* memgov D1b-3: with both promotion passes materializing
             * plan units, every DEVICE-COPY range is exactly one unit.
             * Imports legitimately span unit runs (one coalesced
             * interval satisfies many units) and the registered
             * whole-map view spans everything -- both excluded.  The
             * gates assert multi == 0: an extent-shaped copy
             * reappearing anywhere is a materializer regression. */
            if (!r.host_registered && !r.imported_ipc && !r.imported_vmm &&
                r.unit_lo >= 0 && r.unit_lo != r.unit_hi)
                nm_multi++;
        }
        for (const cuda_derived_range &r : g_derived_ranges) {
            if (!r.host_base || r.src != i) continue;
            nd++;
            if (r.unit_lo >= 0) nd_planned++;
        }
        for (const cuda_q8_f16_range &r : g_q8_f16_ranges) {
            if (!r.host_base || r.src != i) continue;
            nq++;
            if (r.unit_lo >= 0) nq_planned++;
        }
        for (const cuda_q8_f32_range &r : g_q8_f32_ranges) {
            if (!r.host_base || r.src != i) continue;
            nq++;
            if (r.unit_lo >= 0) nq_planned++;
        }
        fprintf(stderr,
                "ds4: range plan %s: model %u/%u planned, derived %u/%u, "
                "q8 %u/%u, multi %u, refused %llu\n",
                g_model_srcs.v[i].name,
                nm_planned, nm, nd_planned, nd, nq_planned, nq, nm_multi,
                (unsigned long long)g_range_publish_refused);
    }
}

/* memgov D1b-1: the EAGER pass — materialize a map's funded residency
 * plan (its bound canonical-unit table) before serve.  Replaces the
 * walk's private span compiler + ds4_gpu_cache_model_range: the table
 * IS the enumeration, slice-aware active sets included, so a slice boot
 * promotes exactly its plan (closes the D1a-4 5/10 slice-blindness
 * measurement).  Defaults ON for INTEGRATED devices only — on GB10-class
 * unified memory the deferred promotions this pre-pays are exactly the
 * bytes the bank planner otherwise cannot see (hbm_cache_ab_2026-08-05:
 * 29-vs-13-bank overcommit); discrete devices keep the historical shape
 * (no eager pass; the lazy fd tier still promotes on demand).
 *
 * Per-unit outcomes, decided in plan order:
 *   HOST_MAPPED_BY_POLICY  non-promote policy (NO_HBM boots) — declared
 *                          to the substrate tripwire, never copied
 *   ALREADY_READY          an exact-offset device range covers the unit
 *                          (a prior materialization)
 *   SATISFIED_IMPORT       ONE other device-resident interval fully
 *                          covers it — the ds4_unit_import_satisfied
 *                          rule evaluated over the live registry
 *                          (host-registered ranges never count); this
 *                          replaces the S6 coverage belt for the eager
 *                          pass at unit granularity
 *   POPULATED              arena carve + staged copy + funnel publish
 *   FAILED                 allocation/copy/publication failure — the
 *                          caller aborts engine open (old walk contract)
 * Budget-unfunded promote units take NO outcome: they are not in the
 * funded plan (the porcelain reports them) and stay lazy-eligible,
 * mirroring the old walk's per-chunk skip.  Expert-cold and
 * artifact-replaced units are the cold tier by design and are not the
 * eager pass's units at all.
 *
 * The substrate tripwire declares the ACTIVE promotable bytes up front —
 * on slice boots this is the slice's bytes, correcting the old walk's
 * slice-blind declaration (a slice boot's "substrate outstanding" now
 * reflects its own plan). */
extern "C" int ds4_gpu_materialize_model_plan(const void *model_map,
                                              uint64_t model_size,
                                              uint64_t *populated_bytes) {
    if (populated_bytes) *populated_bytes = 0;
    if (!model_map || model_size == 0) return 1;
    {
        int dev = 0, integrated = 0;
        if (cudaGetDevice(&dev) == cudaSuccess)
            (void)cudaDeviceGetAttribute(&integrated, cudaDevAttrIntegrated, dev);
        if (!integrated) return 1;
    }
    const int src = cuda_mem_src_index(model_map);
    const ds4_phys_unit *units =
        (src >= 0 && src < DS4_MSRC_MAX) ? g_model_units_v[src] : NULL;
    const uint32_t nu =
        (src >= 0 && src < DS4_MSRC_MAX) ? g_model_units_n[src] : 0;
    const char *nm = src >= 0 ? g_model_srcs.v[src].name : "?";
    if (!units || nu == 0) {
        /* Plan-first contract: no bound table, no eager promotion (a
         * corrupt table must not become the plan — the compile/bind
         * path already counted its fault loudly).  Lazy tiers serve. */
        fprintf(stderr,
                "ds4: materialize %s: no bound unit table; eager pass skipped\n",
                nm);
        return 1;
    }
    /* Tripwire declaration (v0.5.6.3 substrate view): every byte that
     * WILL eventually device-promote, before any budget skip.  memgov
     * D3-2: DEVICE_PROMOTE units count whether the schedule is eager or
     * lazy (the lazy tier covers on materialization); HOST_MAPPED units
     * are TERMINAL host residents under the typed policy -- they never
     * promote, so declaring them would charge the fit ~8 GiB for bytes
     * mapped serving never takes back (the old pair-lever shape carried
     * exactly that phantom outstanding). */
    if (g_model_fd_host_base && model_map == g_model_fd_host_base) {
        for (uint32_t i = 0; i < nu; i++) {
            if (units[i].policy == DS4_UPOL_DEVICE_PROMOTE)
                g_substrate_promotable_total += units[i].src_bytes;
        }
    }
    if (g_model_device_owned) {
        for (uint32_t i = 0; i < nu; i++) {
            if (units[i].policy == DS4_UPOL_DEVICE_PROMOTE)
                cuda_substrate_cover(model_map, units[i].src_bytes);
        }
        fprintf(stderr,
                "ds4: materialize %s: device-owned map; plan covered, no copies\n",
                nm);
        return 1;
    }
    /* memgov D3-2: the eager-vs-lazy SCHEDULE is the source's, read from
     * the handle resolved at bind -- never the environment. */
    const int lazy_schedule =
        src >= 0 && src < DS4_MSRC_MAX &&
        g_model_srcs.v[src].residency == DS4_RESIDENCY_LAZY_COPY_DEVICE;
    const uint64_t limit = cuda_model_map_replaces_complete(model_map)
        ? UINT64_MAX
        : cuda_model_cache_limit_bytes();
    /* Coupled source mode (see cuda_stage_copy_to_dev): default buffered
     * + no discard = the pre-D1b boot's page-cache shape; the env flips
     * eager to O_DIRECT + discard (the F4 measured mode). */
    const int direct_discard =
        getenv("DS4_CUDA_EAGER_SOURCE_DISCARD") != NULL;
    uint64_t counts[DS4_RESUNIT__COUNT] = {0};
    uint32_t promote = 0, funded = 0, unfunded = 0;
    uint64_t pop_bytes = 0;
    int failed = 0;
    for (uint32_t i = 0; i < nu && !failed; i++) {
        const ds4_phys_unit *u = &units[i];
        if (u->policy == DS4_UPOL_HOST_MAPPED) {
            counts[DS4_RESUNIT_HOST_MAPPED_BY_POLICY]++;
            continue;
        }
        if (u->policy != DS4_UPOL_DEVICE_PROMOTE) continue;
        if (lazy_schedule) {
            counts[DS4_RESUNIT_LAZY_DEFERRED]++;
            continue;
        }
        promote++;
        if (u->src_off > model_size || u->src_bytes > model_size - u->src_off) {
            /* The verify pass cannot see the map size; a unit outside the
             * map would send the host-memcpy source out of bounds.  Loud
             * failure, same contract as the old walk's span check. */
            fprintf(stderr,
                    "ds4: materialize %s: unit %u outside map (off=%llu bytes=%llu size=%llu)\n",
                    nm, i, (unsigned long long)u->src_off,
                    (unsigned long long)u->src_bytes,
                    (unsigned long long)model_size);
            counts[DS4_RESUNIT_FAILED]++;
            failed = 1;
            continue;
        }
        int covered = 0, exact_hit = 0;
        for (const cuda_model_range &r : g_model_ranges) {
            if (r.host_base != model_map || r.host_registered) continue;
            if (r.offset <= u->src_off &&
                r.offset + r.bytes >= u->src_off + u->src_bytes) {
                covered = 1;
                exact_hit = (r.offset == u->src_off);
                break;
            }
        }
        if (covered) {
            counts[exact_hit ? DS4_RESUNIT_ALREADY_READY
                             : DS4_RESUNIT_SATISFIED_IMPORT]++;
            cuda_substrate_cover(model_map, u->src_bytes);
            continue;
        }
        /* memgov D2-2: every promotion is a GOVERNED decision.  The
         * claim's class verdict carries the legacy budget predicate
         * verbatim (proposed = range + unit vs the same limit, so
         * observe mode is bit-identical); the live verdict adds the
         * honest marginal charge -- during the eager pass the
         * incremental ENGINE_BOOT publications below keep resident ==
         * range, so unfunded == this unit's bytes (never the whole
         * accumulated range).  A REFUSE (any kind, incl. fail-closed
         * FAULT) lands exactly on the legacy unfunded path: the unit
         * stays lazy-eligible, nothing is lost. */
        const int legacy = (g_model_range_bytes >= limit ||
                            u->src_bytes > limit - g_model_range_bytes)
                               ? DS4_GOV_REFUSE_CLASS : DS4_GOV_ADMIT;
        ds4_gov_claim mcl = {0};
        mcl.requester = DS4_GOVC_ENGINE_BOOT;
        mcl.memc = DS4_MEMC_WEIGHT_ARENA;
        mcl.domain = DS4_MEMD_UNIFIED_DEVICE;
        mcl.proposed_outstanding = g_model_range_bytes + u->src_bytes;
        /* class_limit 0 = UNCAPPED to the evaluator: complete-map
         * replacement (UINT64_MAX) maps there; a zero limit must refuse
         * any ask, so it pins to 1. */
        mcl.class_limit = limit == UINT64_MAX ? 0 : (limit ? limit : 1);
        if (ds4_gov_governed_check("boot_materialize", &mcl, legacy)
                != DS4_GOV_ADMIT) {
            unfunded++;
            cuda_substrate_cover(model_map, u->src_bytes);   /* budget-capped: will not promote eagerly */
            continue;
        }
        funded++;
        char label[64];
        snprintf(label, sizeof(label), "%s unit:%u", nm, i);
        const int oc = cuda_unit_materialize_copy(model_map, u,
                                                  direct_discard, label);
        counts[oc]++;
        if (oc == DS4_RESUNIT_POPULATED) {
            pop_bytes += u->src_bytes;
            /* Incremental boot lease: resident tracks the range registry
             * so each later unit's quote charges only ITS bytes.  The
             * server's boot-settle publication replaces this with the
             * full census absolute (leases replace, never accumulate). */
            ds4_gov_publish_use(DS4_GOVC_ENGINE_BOOT,
                                g_model_range_bytes, g_model_range_bytes);
        } else if (oc == DS4_RESUNIT_FAILED) {
            failed = 1;
        }
    }
    /* No pinned residue past the pass: the bank fit samples MemAvailable
     * after engine open, and the pre-D1b walk left no staging behind.
     * The lazy tier re-allocates on its first miss. */
    cuda_model_stage_pool_release();
    for (int i = 0; i < DS4_RESUNIT__COUNT; i++)
        cuda_resunit_note_n(src, i, counts[i]);
    cuda_resunit_fail_note_n(src, DS4_RESSTAGE_BOOT, counts[DS4_RESUNIT_FAILED]);
    if (populated_bytes) *populated_bytes = pop_bytes;
    fprintf(stderr,
            "ds4: materialize %s: funded %u/%u promote units (%u unfunded), "
            "populated %llu (%.2f GiB), ready %llu, import %llu, "
            "mapped-policy %llu, lazy-policy %llu, failed %llu\n",
            nm, funded, promote, unfunded,
            (unsigned long long)counts[DS4_RESUNIT_POPULATED],
            (double)pop_bytes / 1073741824.0,
            (unsigned long long)counts[DS4_RESUNIT_ALREADY_READY],
            (unsigned long long)counts[DS4_RESUNIT_SATISFIED_IMPORT],
            (unsigned long long)counts[DS4_RESUNIT_HOST_MAPPED_BY_POLICY],
            (unsigned long long)counts[DS4_RESUNIT_LAZY_DEFERRED],
            (unsigned long long)counts[DS4_RESUNIT_FAILED]);
    return failed ? 0 : 1;
}

extern "C" int ds4_gpu_cache_q8_f16_range(const void *model_map, uint64_t model_size, uint64_t offset, uint64_t bytes, uint64_t in_dim, uint64_t out_dim, const char *label) {
    if (!model_map || bytes == 0) return 1;
    if (offset > model_size || bytes > model_size - offset) return 0;
    static int optional_q8_preload_disabled = 0;
    if (optional_q8_preload_disabled) return 1;
    const char *cache_label = label ? label : "q8_0";
    if (getenv("DS4_CUDA_Q8_F32_PRELOAD") != NULL &&
        cuda_q8_f32_cache_allowed(cache_label, in_dim, out_dim)) {
        if (cuda_q8_f32_ptr(model_map, offset, bytes, in_dim, out_dim, cache_label)) return 1;
        optional_q8_preload_disabled = 1;
        return 1;
    }
    if (!cuda_q8_f16_preload_allowed(cache_label, in_dim, out_dim)) return 1;
    if (cuda_q8_f16_ptr(model_map, offset, bytes, in_dim, out_dim, cache_label)) return 1;
    optional_q8_preload_disabled = 1;
    return 1;
}

extern "C" void ds4_gpu_print_memory_report(const char *label) {
    size_t free_b = 0, total_b = 0;
    (void)cudaMemGetInfo(&free_b, &total_b);
    /* memgaps gap-4: raw cuda free tracks MemFree on unified boxes and
     * under-reports by the reclaimable cache; print the budget answer
     * beside it so the report cannot mislead an operator. */
    ds4_mem_observation o;
    (void)ds4_gpu_mem_observe(&o);
    if (o.status == DS4_MEMOBS_OK && o.meminfo_avail_bytes != 0)
        fprintf(stderr,
                "ds4: CUDA memory report %s: free %.2f MiB (meminfo-available %.2f MiB) total %.2f MiB\n",
                label ? label : "", (double)free_b / 1048576.0,
                (double)o.meminfo_avail_bytes / 1048576.0,
                (double)total_b / 1048576.0);
    else
        fprintf(stderr, "ds4: CUDA memory report %s: free %.2f MiB total %.2f MiB\n",
                label ? label : "", (double)free_b / 1048576.0, (double)total_b / 1048576.0);
}

extern "C" void ds4_gpu_set_quality(bool quality) {
    g_quality_mode = quality ? 1 : 0;
    if (g_cublas_ready) {
        const cublasMath_t math_mode =
            (g_quality_mode || getenv("DS4_CUDA_NO_TF32") != NULL)
                ? CUBLAS_DEFAULT_MATH
                : CUBLAS_TF32_TENSOR_OP_MATH;
        (void)cublasSetMathMode(g_cublas, math_mode);
    }
}

__global__ static void embed_token_hc_kernel(float *out, const unsigned short *w, uint32_t token, uint32_t n_embd, uint32_t n_hc) {
    uint32_t i = blockIdx.x * blockDim.x + threadIdx.x;
    uint32_t n = n_embd * n_hc;
    if (i >= n) return;
    uint32_t e = i % n_embd;
    out[i] = __half2float(reinterpret_cast<const __half *>(w)[(uint64_t)token * n_embd + e]);
}

__global__ static void embed_tokens_hc_kernel(
        float *out,
        const int32_t *tokens,
        const __half *w,
        uint32_t n_vocab,
        uint32_t n_tokens,
        uint32_t n_embd,
        uint32_t n_hc) {
    uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)n_tokens * n_hc * n_embd;
    if (gid >= n) return;
    uint32_t d = gid % n_embd;
    uint64_t tmp = gid / n_embd;
    uint32_t t = tmp / n_hc;
    int32_t tok_i = tokens[t];
    uint32_t tok = tok_i < 0 ? 0u : (uint32_t)tok_i;
    if (tok >= n_vocab) tok = 0;
    out[gid] = __half2float(w[(uint64_t)tok * n_embd + d]);
}

__global__ static void matmul_f16_kernel(
        float *out,
        const __half *w,
        const float *x,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t n_tok) {
    uint64_t row = (uint64_t)blockIdx.x;
    uint64_t tok = (uint64_t)blockIdx.y;
    if (row >= out_dim || tok >= n_tok) return;

    float sum = 0.0f;
    const __half *wr = w + row * in_dim;
    const float *xr = x + tok * in_dim;
    for (uint64_t i = threadIdx.x; i < in_dim; i += blockDim.x) {
        sum += __half2float(wr[i]) * xr[i];
    }

    __shared__ float partial[256];
    partial[threadIdx.x] = sum;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    if (threadIdx.x == 0) out[tok * out_dim + row] = partial[0];
}

__global__ static void matmul_f16_serial_kernel(
        float *out,
        const __half *w,
        const float *x,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t n_tok) {
    uint64_t row = (uint64_t)blockIdx.x;
    uint64_t tok = (uint64_t)blockIdx.y;
    if (row >= out_dim || tok >= n_tok || threadIdx.x != 0) return;

    float sum = 0.0f;
    const __half *wr = w + row * in_dim;
    const float *xr = x + tok * in_dim;
    for (uint64_t i = 0; i < in_dim; i++) {
        sum += __half2float(wr[i]) * xr[i];
    }
    out[tok * out_dim + row] = sum;
}

__global__ static void matmul_f16_ordered_chunks_kernel(
        float *out,
        const __half *w,
        const float *x,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t n_tok) {
    uint64_t row = (uint64_t)blockIdx.x;
    uint64_t tok = (uint64_t)blockIdx.y;
    if (row >= out_dim || tok >= n_tok) return;

    __shared__ float partial[32];
    const uint32_t tid = threadIdx.x;
    float sum = 0.0f;
    const uint64_t chunk = (in_dim + 31u) / 32u;
    const uint64_t k0 = (uint64_t)tid * chunk;
    uint64_t k1 = k0 + chunk;
    if (k1 > in_dim) k1 = in_dim;
    const __half *wr = w + row * in_dim;
    const float *xr = x + tok * in_dim;
    for (uint64_t i = k0; i < k1; i++) {
        sum += __half2float(wr[i]) * xr[i];
    }
    partial[tid] = sum;
    __syncthreads();
    if (tid == 0) {
        float total = 0.0f;
        for (uint32_t i = 0; i < 32u; i++) total += partial[i];
        out[tok * out_dim + row] = total;
    }
}

__global__ static void matmul_f16_pair_ordered_chunks_kernel(
        float *out0,
        float *out1,
        const __half *w0,
        const __half *w1,
        const float *x,
        uint64_t in_dim,
        uint64_t out0_dim,
        uint64_t out1_dim) {
    uint64_t row = (uint64_t)blockIdx.x;
    if (row >= out0_dim && row >= out1_dim) return;

    __shared__ float partial0[32];
    __shared__ float partial1[32];
    const uint32_t tid = threadIdx.x;
    float sum0 = 0.0f;
    float sum1 = 0.0f;
    const uint64_t chunk = (in_dim + 31u) / 32u;
    const uint64_t k0 = (uint64_t)tid * chunk;
    uint64_t k1 = k0 + chunk;
    if (k1 > in_dim) k1 = in_dim;
    const __half *wr0 = row < out0_dim ? w0 + row * in_dim : w0;
    const __half *wr1 = row < out1_dim ? w1 + row * in_dim : w1;
    for (uint64_t i = k0; i < k1; i++) {
        const float xv = x[i];
        if (row < out0_dim) sum0 += __half2float(wr0[i]) * xv;
        if (row < out1_dim) sum1 += __half2float(wr1[i]) * xv;
    }
    partial0[tid] = sum0;
    partial1[tid] = sum1;
    __syncthreads();
    if (tid == 0) {
        float total0 = 0.0f;
        float total1 = 0.0f;
        for (uint32_t i = 0; i < 32u; i++) {
            total0 += partial0[i];
            total1 += partial1[i];
        }
        if (row < out0_dim) out0[row] = total0;
        if (row < out1_dim) out1[row] = total1;
    }
}

__global__ static void matmul_f32_kernel(
        float *out,
        const float *w,
        const float *x,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t n_tok) {
    uint64_t row = (uint64_t)blockIdx.x;
    uint64_t tok = (uint64_t)blockIdx.y;
    if (row >= out_dim || tok >= n_tok) return;

    float sum = 0.0f;
    const float *wr = w + row * in_dim;
    const float *xr = x + tok * in_dim;
    for (uint64_t i = threadIdx.x; i < in_dim; i += blockDim.x) {
        sum += wr[i] * xr[i];
    }

    __shared__ float partial[256];
    partial[threadIdx.x] = sum;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    if (threadIdx.x == 0) out[tok * out_dim + row] = partial[0];
}

__global__ static void repeat_hc_kernel(float *out, const float *row, uint32_t n_embd, uint32_t n_hc) {
    uint64_t i = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)n_embd * n_hc;
    if (i >= n) return;
    out[i] = row[i % n_embd];
}

/* Batched repeat_hc: rows[n_rows x n_embd] -> out[n_rows x n_hc x n_embd].
 * Row r's embd vector is broadcast into n_hc consecutive copies. */
__global__ static void repeat_hc_rows_kernel(float *out, const float *rows,
                                             uint32_t n_embd, uint32_t n_hc, uint32_t n_rows) {
    uint64_t i = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t per_row = (uint64_t)n_embd * n_hc;
    uint64_t total = per_row * n_rows;
    if (i >= total) return;
    uint64_t row = i / per_row;
    uint64_t d   = (i % per_row) % n_embd;
    out[i] = rows[row * n_embd + d];
}

__global__ static void f32_to_f16_kernel(__half *out, const float *x, uint64_t n) {
    uint64_t i = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    if (i < n) out[i] = __float2half(x[i]);
}

__device__ static float warp_sum_f32(float v) {
    for (int offset = 16; offset > 0; offset >>= 1) {
        v += __shfl_down_sync(0xffffffffu, v, offset);
    }
    return v;
}

/* Deterministic block reduction for a 256-thread (8-warp) block. Fixed
 * shuffle-tree order within each warp, then a fixed 8-element shuffle-tree
 * across warps -- scheduling-independent, so it is bit-identical run-to-run
 * and between eager and captured replay. Result is valid in thread 0. */
__device__ static float block_reduce_sum_256(float v) {
    v = warp_sum_f32(v);                       /* lane 0 of each warp holds its warp sum */
    __shared__ float s[8];
    const uint32_t lane = threadIdx.x & 31u;
    const uint32_t warp = threadIdx.x >> 5u;
    if (lane == 0u) s[warp] = v;
    __syncthreads();
    float r = 0.0f;
    if (warp == 0u) {
        r = (lane < 8u) ? s[lane] : 0.0f;
        r += __shfl_down_sync(0xffffffffu, r, 4);
        r += __shfl_down_sync(0xffffffffu, r, 2);
        r += __shfl_down_sync(0xffffffffu, r, 1);
    }
    return r;                                   /* valid in thread 0 (warp 0, lane 0) */
}

/* Split-K F16 matmul, pass 1 (decode, n_tok==1). Each (row, kseg) block
 * reduces its contiguous in_dim segment [kseg*seg, (kseg+1)*seg) with
 * coalesced stride-blockDim loads, then writes a per-segment partial. Splitting
 * the row's dot product across kseg blocks raises the launched-block count so
 * the GPU's SMs actually fill (the single-block-per-row fast kernel left
 * waves_per_multiprocessor << 1 on the small-out_dim projections). */
__global__ static void matmul_f16_splitk_kernel(
        float *partial,
        const __half *w,
        const float *x,
        uint64_t in_dim,
        uint64_t out_dim,
        uint32_t ksplit,
        int vec_ok) {
    const uint64_t row = (uint64_t)blockIdx.x;
    const uint32_t kseg = blockIdx.y;
    if (row >= out_dim) return;
    /* Round the segment length up to a multiple of 8 so every segment start k0
     * is 8-half aligned -> the uint4 (8-half) vector loads below stay 16B
     * aligned. Segments still tile [0,in_dim); a fully-trailing segment
     * (k0 >= in_dim) just contributes 0. */
    uint64_t seg = (in_dim + (uint64_t)ksplit - 1u) / (uint64_t)ksplit;
    seg = (seg + 7u) & ~(uint64_t)7u;
    const uint64_t k0 = (uint64_t)kseg * seg;
    if (k0 >= in_dim) {
        if (threadIdx.x == 0u) partial[row * (uint64_t)ksplit + (uint64_t)kseg] = 0.0f;
        return;
    }
    uint64_t k1 = k0 + seg;
    if (k1 > in_dim) k1 = in_dim;
    const __half *wr = w + row * in_dim;
    const uint32_t tid = threadIdx.x;
    const uint32_t nt = blockDim.x;
    float sum = 0.0f;
    if (vec_ok) {
        /* Vectorized: each thread consumes 8 contiguous halves per step via a
         * 16B uint4 load (coalesced: consecutive threads -> consecutive 16B),
         * paired with two float4 activation loads. ~8x fewer memory
         * instructions than the scalar path -> better latency tolerance on a
         * reduction that ncu shows is latency-, not bandwidth-, bound. */
        const uint64_t vend = k0 + ((k1 - k0) & ~(uint64_t)7u);
        for (uint64_t i = k0 + (uint64_t)tid * 8u; i < vend; i += (uint64_t)nt * 8u) {
            const uint4 wv = *reinterpret_cast<const uint4 *>(wr + i);
            const float4 xa = *reinterpret_cast<const float4 *>(x + i);
            const float4 xb = *reinterpret_cast<const float4 *>(x + i + 4);
            const __half2 *h = reinterpret_cast<const __half2 *>(&wv);
            const float2 w0 = __half22float2(h[0]);
            const float2 w1 = __half22float2(h[1]);
            const float2 w2 = __half22float2(h[2]);
            const float2 w3 = __half22float2(h[3]);
            sum += w0.x * xa.x + w0.y * xa.y + w1.x * xa.z + w1.y * xa.w
                 + w2.x * xb.x + w2.y * xb.y + w3.x * xb.z + w3.y * xb.w;
        }
        for (uint64_t i = vend + tid; i < k1; i += nt) sum += __half2float(wr[i]) * x[i];
    } else {
        for (uint64_t i = k0 + tid; i < k1; i += nt) sum += __half2float(wr[i]) * x[i];
    }
    sum = block_reduce_sum_256(sum);
    if (threadIdx.x == 0u) partial[row * (uint64_t)ksplit + (uint64_t)kseg] = sum;
}

/* Split-K F16 matmul, pass 2: combine the ksplit per-segment partials for each
 * row in a fixed (kseg ascending) order. Fixed order keeps the result
 * deterministic and eager==captured. */
__global__ static void matmul_f16_splitk_combine_kernel(
        float *out,
        const float *partial,
        uint64_t out_dim,
        uint32_t ksplit) {
    const uint64_t row = (uint64_t)blockIdx.x * (uint64_t)blockDim.x + (uint64_t)threadIdx.x;
    if (row >= out_dim) return;
    const float *p = partial + row * (uint64_t)ksplit;
    float s = 0.0f;
    for (uint32_t k = 0u; k < ksplit; k++) s += p[k];
    out[row] = s;
}

__device__ __forceinline__ static int32_t dot_i8_block(const int8_t *a, const int8_t *b, uint64_t n, int use_dp4a);

__device__ __forceinline__ static bool top2_value_better(float av, uint32_t ai, float bv, uint32_t bi) {
    return av > bv || (av == bv && ai < bi);
}

__device__ __forceinline__ static void top2_insert_value(
        float v,
        uint32_t id,
        float &v0,
        uint32_t &id0,
        float &v1,
        uint32_t &id1) {
    if (id == id0 || id == id1) return;
    if (top2_value_better(v, id, v0, id0)) {
        v1 = v0;
        id1 = id0;
        v0 = v;
        id0 = id;
    } else if (top2_value_better(v, id, v1, id1)) {
        v1 = v;
        id1 = id;
    }
}

__global__ static void matmul_q8_0_top2_warp8_kernel(
        ds4_gpu_top2_result *candidates,
        const unsigned char *w,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t blocks,
        int use_dp4a) {
    const uint32_t warp = threadIdx.x >> 5u;
    const uint32_t lane = threadIdx.x & 31u;
    const uint64_t row = (uint64_t)blockIdx.x * 8u + warp;

    float acc = -INFINITY;
    if (row < out_dim) {
        const unsigned char *wr = w + row * blocks * 34;
        acc = 0.0f;
        for (uint64_t b = lane; b < blocks; b += 32u) {
            uint64_t i0 = b * 32;
            uint64_t bn = in_dim - i0 < 32 ? in_dim - i0 : 32;
            const __half *scale_h = (const __half *)(wr + b * 34);
            const int8_t *qs = (const int8_t *)(wr + b * 34 + 2);
            const int8_t *xqb = xq + b * 32;
            int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
            acc += __half2float(*scale_h) * xscale[b] * (float)dot;
        }
        acc = warp_sum_f32(acc);
    }

    __shared__ float vals[8];
    __shared__ uint32_t ids[8];
    if (lane == 0) {
        vals[warp] = acc;
        ids[warp] = row < out_dim ? (uint32_t)row : UINT32_MAX;
    }
    __syncthreads();

    if (threadIdx.x == 0) {
        float v0 = -INFINITY;
        float v1 = -INFINITY;
        uint32_t id0 = UINT32_MAX;
        uint32_t id1 = UINT32_MAX;
        for (uint32_t i = 0; i < 8u; i++) {
            if (ids[i] != UINT32_MAX) top2_insert_value(vals[i], ids[i], v0, id0, v1, id1);
        }
        candidates[blockIdx.x] = {id0, id1, v0, v1};
    }
}

__global__ static void matmul_q8_0_top2_logits_n2_warp8_kernel(
        ds4_gpu_top2_result *row0_candidates,
        float *row1_logits,
        const unsigned char *w,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t blocks,
        int use_dp4a) {
    const uint32_t warp = threadIdx.x >> 5u;
    const uint32_t lane = threadIdx.x & 31u;
    const uint64_t row = (uint64_t)blockIdx.x * 8u + warp;

    const int8_t *xq0 = xq;
    const int8_t *xq1 = xq + blocks * 32u;
    const float *xs0 = xscale;
    const float *xs1 = xscale + blocks;
    float acc0 = -INFINITY;
    float acc1 = -INFINITY;
    if (row < out_dim) {
        const unsigned char *wr = w + row * blocks * 34;
        acc0 = 0.0f;
        acc1 = 0.0f;
        for (uint64_t b = lane; b < blocks; b += 32u) {
            uint64_t i0 = b * 32u;
            uint64_t bn = in_dim - i0 < 32u ? in_dim - i0 : 32u;
            const __half *scale_h = (const __half *)(wr + b * 34u);
            const int8_t *qs = (const int8_t *)(wr + b * 34u + 2u);
            const float ws = __half2float(*scale_h);
            int dot0 = dot_i8_block(qs, xq0 + b * 32u, bn, use_dp4a);
            int dot1 = dot_i8_block(qs, xq1 + b * 32u, bn, use_dp4a);
            acc0 += ws * xs0[b] * (float)dot0;
            acc1 += ws * xs1[b] * (float)dot1;
        }
        acc0 = warp_sum_f32(acc0);
        acc1 = warp_sum_f32(acc1);
        if (lane == 0) row1_logits[row] = acc1;
    }

    __shared__ float vals[8];
    __shared__ uint32_t ids[8];
    if (lane == 0) {
        vals[warp] = acc0;
        ids[warp] = row < out_dim ? (uint32_t)row : UINT32_MAX;
    }
    __syncthreads();

    if (threadIdx.x == 0) {
        float v0 = -INFINITY;
        float v1 = -INFINITY;
        uint32_t id0 = UINT32_MAX;
        uint32_t id1 = UINT32_MAX;
        for (uint32_t i = 0; i < 8u; i++) {
            if (ids[i] != UINT32_MAX) top2_insert_value(vals[i], ids[i], v0, id0, v1, id1);
        }
        row0_candidates[blockIdx.x] = {id0, id1, v0, v1};
    }
}

__global__ static void matmul_q8_0_candidates_warp8_kernel(
        float *out,
        const uint32_t *candidate_ids,
        uint32_t candidate_count,
        const unsigned char *w,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t blocks,
        int use_dp4a) {
    const uint32_t warp = threadIdx.x >> 5u;
    const uint32_t lane = threadIdx.x & 31u;
    const uint32_t cand = (uint32_t)blockIdx.x * 8u + warp;

    if (cand >= candidate_count) return;
    const uint32_t row32 = candidate_ids[cand];
    const uint64_t row = (uint64_t)row32;
    float acc = -INFINITY;
    if (row < out_dim) {
        const unsigned char *wr = w + row * blocks * 34;
        acc = 0.0f;
        for (uint64_t b = lane; b < blocks; b += 32u) {
            uint64_t i0 = b * 32;
            uint64_t bn = in_dim - i0 < 32 ? in_dim - i0 : 32;
            const __half *scale_h = (const __half *)(wr + b * 34);
            const int8_t *qs = (const int8_t *)(wr + b * 34 + 2);
            const int8_t *xqb = xq + b * 32;
            int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
            acc += __half2float(*scale_h) * xscale[b] * (float)dot;
        }
        acc = warp_sum_f32(acc);
    }
    if (lane == 0) out[cand] = acc;
}

__global__ static void q8_0_row_group_norms_warp_kernel(
        float *row_group_norms,
        const unsigned char *w,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t blocks,
        uint32_t group_count) {
    const uint64_t row = (uint64_t)blockIdx.x;
    const uint32_t group = threadIdx.x >> 5u;
    const uint32_t lane = threadIdx.x & 31u;
    if (row >= out_dim || group >= group_count) return;

    const uint64_t group_start = ((uint64_t)group * in_dim) / group_count;
    const uint64_t group_end = ((uint64_t)(group + 1u) * in_dim) / group_count;
    const uint64_t block_start = group_start / 32u;
    const uint64_t block_end = (group_end + 31u) / 32u;
    const unsigned char *wr = w + row * blocks * 34;
    float sum = 0.0f;
    for (uint64_t b = block_start; b < block_end; b++) {
        const uint64_t i0 = b * 32u;
        const uint64_t lo = group_start > i0 ? group_start - i0 : 0u;
        const uint64_t hi0 = group_end < i0 + 32u ? group_end - i0 : 32u;
        const __half *scale_h = (const __half *)(wr + b * 34);
        const int8_t *qs = (const int8_t *)(wr + b * 34 + 2);
        const float scale = __half2float(*scale_h);
        for (uint64_t i = lo + lane; i < hi0; i += 32u) {
            const float v = scale * (float)qs[i];
            sum += v * v;
        }
    }
    sum = warp_sum_f32(sum);
    if (lane == 0) row_group_norms[row * group_count + group] = sqrtf(sum);
}

__global__ static void q8_0_x_group_norms_kernel(
        float *x_group_norms,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t blocks,
        uint32_t group_count) {
    const uint32_t group = (uint32_t)blockIdx.x;
    if (group >= group_count) return;
    const uint64_t group_start = ((uint64_t)group * in_dim) / group_count;
    const uint64_t group_end = ((uint64_t)(group + 1u) * in_dim) / group_count;
    const uint64_t block_start = group_start / 32u;
    const uint64_t block_end = (group_end + 31u) / 32u;
    float sum = 0.0f;
    for (uint64_t b = block_start; b < block_end; b++) {
        const uint64_t i0 = b * 32u;
        const uint64_t lo = group_start > i0 ? group_start - i0 : 0u;
        const uint64_t hi0 = group_end < i0 + 32u ? group_end - i0 : 32u;
        const float scale = xscale[b];
        const int8_t *xqb = xq + b * 32u;
        for (uint64_t i = lo + threadIdx.x; i < hi0; i += blockDim.x) {
            const float v = scale * (float)xqb[i];
            sum += v * v;
        }
    }
    __shared__ float partial[256];
    partial[threadIdx.x] = sum;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1u; stride > 0u; stride >>= 1u) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    if (threadIdx.x == 0) x_group_norms[group] = sqrtf(partial[0]);
}

__global__ static void q8_0_candidate_certify_prune_warp8_kernel(
        ds4_gpu_top2_result *candidates,
        const float *candidate_logits,
        const uint32_t *candidate_ids,
        const unsigned char *w,
        const int8_t *xq,
        const float *xscale,
        const float *row_group_norms,
        const float *x_group_norms,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t blocks,
        uint32_t group_count,
        int use_dp4a) {
    const uint32_t warp = threadIdx.x >> 5u;
    const uint32_t lane = threadIdx.x & 31u;
    const uint64_t row = (uint64_t)blockIdx.x * 8u + warp;
    const uint32_t candidate = candidate_ids[0];
    const float threshold = candidate_logits[0] - 1.0e-4f;

    float row_bound = -INFINITY;
    uint32_t row_id = UINT32_MAX;
    if (row < out_dim && (uint32_t)row != candidate) {
        const float *rn = row_group_norms + row * group_count;
        float residual = 0.0f;
        for (uint32_t g = lane; g < group_count; g += 32u) {
            residual += rn[g] * x_group_norms[g];
        }
        residual = warp_sum_f32(residual);
        residual = __shfl_sync(0xffffffffu, residual, 0);

        const unsigned char *wr = w + row * blocks * 34;
        float acc = 0.0f;
        for (uint32_t g = 0; g < group_count; g++) {
            const float group_bound = rn[g] * x_group_norms[g];
            residual -= group_bound;

            const uint64_t group_start = ((uint64_t)g * in_dim) / group_count;
            const uint64_t group_end = ((uint64_t)(g + 1u) * in_dim) / group_count;
            const uint64_t block_start = group_start / 32u;
            const uint64_t block_end = (group_end + 31u) / 32u;
            float part = 0.0f;
            for (uint64_t b = block_start + lane; b < block_end; b += 32u) {
                const uint64_t i0 = b * 32u;
                const uint64_t bn = in_dim - i0 < 32u ? in_dim - i0 : 32u;
                const __half *scale_h = (const __half *)(wr + b * 34);
                const int8_t *qs = (const int8_t *)(wr + b * 34 + 2);
                const int8_t *xqb = xq + b * 32u;
                int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
                part += __half2float(*scale_h) * xscale[b] * (float)dot;
            }
            part = warp_sum_f32(part);
            part = __shfl_sync(0xffffffffu, part, 0);
            acc += part;
            row_bound = acc + residual;
            if (row_bound < threshold) break;
        }
        row_id = (uint32_t)row;
    }

    __shared__ float vals[8];
    __shared__ uint32_t ids[8];
    if (lane == 0) {
        vals[warp] = row_bound;
        ids[warp] = row_id;
    }
    __syncthreads();

    if (threadIdx.x == 0) {
        float v0 = -INFINITY;
        uint32_t id0 = UINT32_MAX;
        for (uint32_t i = 0; i < 8u; i++) {
            if (ids[i] != UINT32_MAX &&
                (vals[i] > v0 || (vals[i] == v0 && ids[i] < id0))) {
                v0 = vals[i];
                id0 = ids[i];
            }
        }
        candidates[blockIdx.x] = {id0, UINT32_MAX, v0, -INFINITY};
    }
}

__global__ static void q8_0_candidate_certify_merge_kernel(
        ds4_gpu_candidate_cert_result *result,
        const ds4_gpu_top2_result *candidates,
        uint32_t n_candidates,
        const float *candidate_logits,
        const uint32_t *candidate_ids) {
    const uint32_t tid = threadIdx.x;
    float best = -INFINITY;
    uint32_t best_id = UINT32_MAX;
    for (uint32_t i = tid; i < n_candidates; i += blockDim.x) {
        ds4_gpu_top2_result c = candidates[i];
        if (c.id0 != UINT32_MAX &&
            (c.value0 > best || (c.value0 == best && c.id0 < best_id))) {
            best = c.value0;
            best_id = c.id0;
        }
    }

    __shared__ float sbest[1024];
    __shared__ uint32_t sid[1024];
    sbest[tid] = best;
    sid[tid] = best_id;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1u; stride > 0u; stride >>= 1u) {
        if (tid < stride) {
            const float ov = sbest[tid + stride];
            const uint32_t oi = sid[tid + stride];
            if (ov > sbest[tid] || (ov == sbest[tid] && oi < sid[tid])) {
                sbest[tid] = ov;
                sid[tid] = oi;
            }
        }
        __syncthreads();
    }
    if (tid == 0) {
        const uint32_t candidate = candidate_ids[0];
        const float candidate_logit = candidate_logits[0];
        const uint32_t certified = sbest[0] < candidate_logit - 1.0e-4f ? 1u : 0u;
        result[0] = {candidate, certified, sid[0], candidate_logit, sbest[0]};
    }
}

__global__ static void q8_0_top2_merge_kernel(
        ds4_gpu_top2_result *out,
        const ds4_gpu_top2_result *candidates,
        uint32_t n_candidates) {
    const uint32_t tid = threadIdx.x;
    float v0 = -INFINITY;
    float v1 = -INFINITY;
    uint32_t id0 = UINT32_MAX;
    uint32_t id1 = UINT32_MAX;

    for (uint32_t i = tid; i < n_candidates; i += blockDim.x) {
        ds4_gpu_top2_result c = candidates[i];
        if (c.id0 != UINT32_MAX) top2_insert_value(c.value0, c.id0, v0, id0, v1, id1);
        if (c.id1 != UINT32_MAX) top2_insert_value(c.value1, c.id1, v0, id0, v1, id1);
    }

    __shared__ float sv0[1024];
    __shared__ float sv1[1024];
    __shared__ uint32_t sid0[1024];
    __shared__ uint32_t sid1[1024];
    sv0[tid] = v0;
    sv1[tid] = v1;
    sid0[tid] = id0;
    sid1[tid] = id1;
    __syncthreads();

    for (uint32_t stride = blockDim.x >> 1u; stride > 0u; stride >>= 1u) {
        if (tid < stride) {
            top2_insert_value(sv0[tid + stride], sid0[tid + stride],
                              sv0[tid], sid0[tid], sv1[tid], sid1[tid]);
            top2_insert_value(sv1[tid + stride], sid1[tid + stride],
                              sv0[tid], sid0[tid], sv1[tid], sid1[tid]);
        }
        __syncthreads();
    }

    if (tid == 0) {
        out[0] = {sid0[0], sid1[0], sv0[0], sv1[0]};
    }
}

__device__ static float warp_max_f32(float v) {
    for (int offset = 16; offset > 0; offset >>= 1) {
        v = fmaxf(v, __shfl_down_sync(0xffffffffu, v, offset));
    }
    return v;
}

__device__ static float dot4_f32(float4 a, float4 b) {
    return a.x * b.x + a.y * b.y + a.z * b.z + a.w * b.w;
}

__device__ __forceinline__ static int32_t load_i8x4_i32_aligned(const int8_t *p) {
    return *(const int32_t *)p;
}

__device__ __forceinline__ static int32_t load_i8x4_i32_unaligned(const int8_t *p) {
    const uint8_t *u = (const uint8_t *)p;
    return (int32_t)((uint32_t)u[0] |
                     ((uint32_t)u[1] << 8) |
                     ((uint32_t)u[2] << 16) |
                     ((uint32_t)u[3] << 24));
}

__device__ __forceinline__ static int32_t dot_i8x32_dp4a(const int8_t *a, const int8_t *b) {
    int32_t dot = 0;
#pragma unroll
    for (uint32_t i = 0; i < 32u; i += 4u) {
        dot = __dp4a(load_i8x4_i32_unaligned(a + i), load_i8x4_i32_aligned(b + i), dot);
    }
    return dot;
}

__device__ __forceinline__ static int32_t dot_i8_block(const int8_t *a, const int8_t *b, uint64_t n, int use_dp4a) {
    if (use_dp4a && n == 32u) return dot_i8x32_dp4a(a, b);
    int32_t dot = 0;
    for (uint64_t i = 0; i < n; i++) dot += (int32_t)a[i] * (int32_t)b[i];
    return dot;
}

/* M1-Inc4: per-block dot against the aligned-SoA Q8_0 artifact (kind 5):
 * qs32 is 16B-aligned (two int4 loads), xqb is the 16B-aligned prequant
 * buffer.  Same integer result as dot_i8_block(n==32), so kernels that
 * swap this in keep bit-identical accumulation. */
__device__ __forceinline__ static int32_t dot_i8x32_aligned(const int8_t *qs32, const int8_t *xqb) {
    const int4 w0 = *(const int4 *)qs32;
    const int4 w1 = *(const int4 *)(qs32 + 16);
    const int *u = (const int *)xqb;
    int sumi = 0;
    sumi = __dp4a(w0.x, u[0], sumi);
    sumi = __dp4a(w0.y, u[1], sumi);
    sumi = __dp4a(w0.z, u[2], sumi);
    sumi = __dp4a(w0.w, u[3], sumi);
    sumi = __dp4a(w1.x, u[4], sumi);
    sumi = __dp4a(w1.y, u[5], sumi);
    sumi = __dp4a(w1.z, u[6], sumi);
    sumi = __dp4a(w1.w, u[7], sumi);
    return sumi;
}

__global__ static DS4_CUDA_UNUSED void matmul_q8_0_kernel(
        float *out,
        const unsigned char *w,
        const float *x,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t n_tok) {
    uint64_t row = (uint64_t)blockIdx.x;
    uint64_t tok = (uint64_t)blockIdx.y;
    if (row >= out_dim || tok >= n_tok) return;
    const uint64_t blocks = (in_dim + 31) / 32;
    const unsigned char *wr = w + row * blocks * 34;
    const float *xr = x + tok * in_dim;
    float acc = 0.0f;

    for (uint64_t b = threadIdx.x; b < blocks; b += blockDim.x) {
        uint64_t i0 = b * 32;
        uint64_t bn = in_dim - i0 < 32 ? in_dim - i0 : 32;
        float amax = 0.0f;
        for (uint64_t i = 0; i < bn; i++) amax = fmaxf(amax, fabsf(xr[i0 + i]));
        float d = amax / 127.0f;
        float id = d != 0.0f ? 1.0f / d : 0.0f;
        const __half *scale_h = (const __half *)(wr + b * 34);
        const int8_t *qs = (const int8_t *)(wr + b * 34 + 2);
        int dot = 0;
        for (uint64_t i = 0; i < bn; i++) {
            int q = (int)lrintf(xr[i0 + i] * id);
            q = q > 127 ? 127 : (q < -128 ? -128 : q);
            dot += (int)qs[i] * q;
        }
        acc += __half2float(*scale_h) * d * (float)dot;
    }

    __shared__ float partial[256];
    partial[threadIdx.x] = acc;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    if (threadIdx.x == 0) out[tok * out_dim + row] = partial[0];
}

__global__ static void quantize_q8_0_f32_kernel(
        int8_t *xq,
        float *xscale,
        const float *x,
        uint64_t in_dim,
        uint64_t blocks) {
    uint64_t b = blockIdx.x;
    uint64_t tok = blockIdx.y;
    if (b >= blocks) return;
    uint64_t i0 = b * 32;
    uint64_t bn = in_dim - i0 < 32 ? in_dim - i0 : 32;
    const float *xr = x + tok * in_dim + i0;

    float a = 0.0f;
    if (threadIdx.x < bn) a = fabsf(xr[threadIdx.x]);
    __shared__ float vals[32];
    vals[threadIdx.x] = a;
    __syncthreads();
    for (uint32_t stride = 16; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) vals[threadIdx.x] = fmaxf(vals[threadIdx.x], vals[threadIdx.x + stride]);
        __syncthreads();
    }
    const float d = vals[0] / 127.0f;
    const float id = d != 0.0f ? 1.0f / d : 0.0f;
    if (threadIdx.x == 0) xscale[tok * blocks + b] = d;
    int8_t *dst = xq + (tok * blocks + b) * 32;
    if (threadIdx.x < bn) {
        int v = (int)lrintf(xr[threadIdx.x] * id);
        v = v > 127 ? 127 : (v < -128 ? -128 : v);
        dst[threadIdx.x] = (int8_t)v;
    } else {
        dst[threadIdx.x] = 0;
    }
}

/* M2-Inc1b: encode-scoped registry of pre-quantized q8_0 activations.
 * A producer kernel that already holds an activation's values in registers
 * (the fused HC stage writing attn_norm/ffn_norm) emits the q8_0 codes as a
 * sidecar and registers them here; the next consumer entry that would
 * quantize that same tensor takes the codes and skips its prelude launch.
 * Safety contract: slots are reset at every fused-HC-stage entry call (a
 * consumer pop can never precede its producer within a layer), a lookup pops
 * the slot (single consumption), and hits require pointer AND length match.
 * Host-side state only — replayed graphs bake the folded dataflow. */
/* block_q8_1 mirror of the vendored cuda/mmq layout ({half2 (d,sum);
 * int8 qs[32]}, 36 B) so emitted blocks are byte-compatible with
 * quantize_q8_1 consumers. */
typedef struct { __half2 ds; int8_t qs[32]; } ds4_hc_block_q8_1;

typedef struct {
    const void *src;
    uint64_t    in_dim;
    int8_t     *xq;      /* q8_0 sidecar (codes + scales), or NULL */
    float      *xscale;
    const void *q81;     /* q8_1 sidecar (block_q8_1 array), or NULL */
} cuda_q8_fold_slot;
#define CUDA_Q8_FOLD_SLOTS 4
static cuda_q8_fold_slot g_q8_fold[CUDA_Q8_FOLD_SLOTS];

static void cuda_q8_fold_reset(void) {
    memset(g_q8_fold, 0, sizeof(g_q8_fold));
}
static void cuda_q8_fold_register(const void *src, uint64_t in_dim,
                                  int8_t *xq, float *xscale, const void *q81) {
    for (int i = 0; i < CUDA_Q8_FOLD_SLOTS; i++) {
        if (g_q8_fold[i].src == src || g_q8_fold[i].src == NULL) {
            g_q8_fold[i].src = src;
            g_q8_fold[i].in_dim = in_dim;
            g_q8_fold[i].xq = xq;
            g_q8_fold[i].xscale = xscale;
            g_q8_fold[i].q81 = q81;
            return;
        }
    }
}
/* Each format pops independently (ffn_norm has a q8_0 consumer — the shexp
 * pair — AND a q8_1 consumer — the routed-MoE mmvq); the slot stays matched
 * until both are taken or the next reset. */
static int cuda_q8_fold_take(const void *src, uint64_t in_dim,
                             int8_t **xq, float **xscale) {
    for (int i = 0; i < CUDA_Q8_FOLD_SLOTS; i++) {
        if (g_q8_fold[i].src == src && g_q8_fold[i].in_dim == in_dim &&
            g_q8_fold[i].xq != NULL) {
            *xq = g_q8_fold[i].xq;
            *xscale = g_q8_fold[i].xscale;
            g_q8_fold[i].xq = NULL;
            g_q8_fold[i].xscale = NULL;
            return 1;
        }
    }
    return 0;
}
/* M2-Inc2a: q8_1 flavor, callable from the vendored ds4_mmq.cu entries. */
extern "C" int ds4_cuda_q8_fold_take_q81(const void *src, uint64_t in_dim,
                                         const void **q81) {
    for (int i = 0; i < CUDA_Q8_FOLD_SLOTS; i++) {
        if (g_q8_fold[i].src == src && g_q8_fold[i].in_dim == in_dim &&
            g_q8_fold[i].q81 != NULL) {
            *q81 = g_q8_fold[i].q81;
            g_q8_fold[i].q81 = NULL;
            return 1;
        }
    }
    return 0;
}

__global__ static void matmul_q8_0_preq_kernel(
        float *out,
        const unsigned char *w,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t n_tok,
        uint64_t blocks,
        int use_dp4a) {
    uint64_t row = (uint64_t)blockIdx.x;
    uint64_t tok = (uint64_t)blockIdx.y;
    if (row >= out_dim || tok >= n_tok) return;
    const unsigned char *wr = w + row * blocks * 34;
    const int8_t *xqr = xq + tok * blocks * 32;
    const float *xsr = xscale + tok * blocks;
    float acc = 0.0f;
    for (uint64_t b = threadIdx.x; b < blocks; b += blockDim.x) {
        uint64_t i0 = b * 32;
        uint64_t bn = in_dim - i0 < 32 ? in_dim - i0 : 32;
        const __half *scale_h = (const __half *)(wr + b * 34);
        const int8_t *qs = (const int8_t *)(wr + b * 34 + 2);
        const int8_t *xqb = xqr + b * 32;
        int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
        acc += __half2float(*scale_h) * xsr[b] * (float)dot;
    }
    __shared__ float partial[256];
    partial[threadIdx.x] = acc;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    if (threadIdx.x == 0) out[tok * out_dim + row] = partial[0];
}

__global__ static void matmul_q8_0_preq_warp8_kernel(
        float *out,
        const unsigned char *w,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out_dim,
        uint64_t blocks,
        int use_dp4a) {
    uint64_t row = (uint64_t)blockIdx.x * 8u + (threadIdx.x >> 5u);
    uint32_t lane = threadIdx.x & 31u;
    if (row >= out_dim) return;
    const unsigned char *wr = w + row * blocks * 34;
    float acc = 0.0f;
    for (uint64_t b = lane; b < blocks; b += 32u) {
        uint64_t i0 = b * 32;
        uint64_t bn = in_dim - i0 < 32 ? in_dim - i0 : 32;
        const __half *scale_h = (const __half *)(wr + b * 34);
        const int8_t *qs = (const int8_t *)(wr + b * 34 + 2);
        const int8_t *xqb = xq + b * 32;
        int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
        acc += __half2float(*scale_h) * xscale[b] * (float)dot;
    }
    acc = warp_sum_f32(acc);
    if (lane == 0) out[row] = acc;
}

__global__ static void matmul_q8_0_pair_preq_warp8_kernel(
        float *out0,
        float *out1,
        const unsigned char *w0,
        const unsigned char *w1,
        const int8_t *xq,
        const float *xscale,
        uint64_t in_dim,
        uint64_t out0_dim,
        uint64_t out1_dim,
        uint64_t blocks,
        int use_dp4a) {
    uint64_t row = (uint64_t)blockIdx.x * 8u + (threadIdx.x >> 5u);
    uint32_t lane = threadIdx.x & 31u;
    if (row >= out0_dim && row >= out1_dim) return;
    float acc0 = 0.0f;
    float acc1 = 0.0f;
    const unsigned char *wr0 = row < out0_dim ? w0 + row * blocks * 34 : NULL;
    const unsigned char *wr1 = row < out1_dim ? w1 + row * blocks * 34 : NULL;
    for (uint64_t b = lane; b < blocks; b += 32u) {
        uint64_t i0 = b * 32;
        uint64_t bn = in_dim - i0 < 32 ? in_dim - i0 : 32;
        const int8_t *xqb = xq + b * 32;
        const float xs = xscale[b];
        if (wr0) {
            const __half *scale_h = (const __half *)(wr0 + b * 34);
            const int8_t *qs = (const int8_t *)(wr0 + b * 34 + 2);
            int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
            acc0 += __half2float(*scale_h) * xs * (float)dot;
        }
        if (wr1) {
            const __half *scale_h = (const __half *)(wr1 + b * 34);
            const int8_t *qs = (const int8_t *)(wr1 + b * 34 + 2);
            int dot = dot_i8_block(qs, xqb, bn, use_dp4a);
            acc1 += __half2float(*scale_h) * xs * (float)dot;
        }
    }
    acc0 = warp_sum_f32(acc0);
    acc1 = warp_sum_f32(acc1);
    if (lane == 0) {
        if (row < out0_dim) out0[row] = acc0;
        if (row < out1_dim) out1[row] = acc1;
    }
}

/* M1-Inc4: aligned-SoA variant of the pair kernel.  Weight reads go through
 * the kind-5 artifact ([half dq[nblk]][pad64][int8 qs[nblk*32]]); loop and
 * accumulation order identical to the raw kernel (bit-identical outputs;
 * proto_q8_warp8: q_a+kv 190->211, shared gate+up 206->232 GB/s).
 * Requires in_dim % 1024 == 0 (full 32-byte blocks). */
__global__ static void matmul_q8_0_pair_preq_aligned_warp8_kernel(
        float *out0,
        float *out1,
        const int8_t *qs0,
        const __half *dq0,
        const int8_t *qs1,
        const __half *dq1,
        const int8_t *xq,
        const float *xscale,
        uint64_t out0_dim,
        uint64_t out1_dim,
        uint64_t blocks) {
    uint64_t row = (uint64_t)blockIdx.x * 8u + (threadIdx.x >> 5u);
    uint32_t lane = threadIdx.x & 31u;
    if (row >= out0_dim && row >= out1_dim) return;
    const uint64_t rbase = row * blocks;
    const int in0 = row < out0_dim;
    const int in1 = row < out1_dim;
    float acc0 = 0.0f;
    float acc1 = 0.0f;
    for (uint64_t b = lane; b < blocks; b += 32u) {
        const int8_t *xqb = xq + b * 32;
        const float xs = xscale[b];
        if (in0) {
            const int dot = dot_i8x32_aligned(qs0 + (rbase + b) * 32u, xqb);
            acc0 += __half2float(dq0[rbase + b]) * xs * (float)dot;
        }
        if (in1) {
            const int dot = dot_i8x32_aligned(qs1 + (rbase + b) * 32u, xqb);
            acc1 += __half2float(dq1[rbase + b]) * xs * (float)dot;
        }
    }
    acc0 = warp_sum_f32(acc0);
    acc1 = warp_sum_f32(acc1);
    if (lane == 0) {
        if (row < out0_dim) out0[row] = acc0;
        if (row < out1_dim) out1[row] = acc1;
    }
}

