        for (uint32_t p = 0; p < np; p++) xqb[p] = sxq[p];
    }
    for (uint32_t rr = 0; rr < ROW_SPAN / 32u; rr++) {
        uint32_t row = blockIdx.x * ROW_SPAN + row_lane + rr * 32u;
        if (row >= out_dim) continue;
        const cuda_block_q2_K *wr = (const cuda_block_q2_K *)(down_base + (uint64_t)expert * down_expert_bytes + (uint64_t)row * down_row_bytes);
        float acc[16] = {0.0f};
        for (uint32_t b = lane; b < midq_blocks; b += 8u) {
            dev_dot_q2_K_q8_K_block8(wr + b, xqb[0] ? xqb[0] + b : NULL, xqb[1] ? xqb[1] + b : NULL,
                                     xqb[2] ? xqb[2] + b : NULL, xqb[3] ? xqb[3] + b : NULL,
                                     xqb[4] ? xqb[4] + b : NULL, xqb[5] ? xqb[5] + b : NULL,
                                     xqb[6] ? xqb[6] + b : NULL, xqb[7] ? xqb[7] + b : NULL, np < 8u ? np : 8u, acc);
            if (np > 8u) {
                dev_dot_q2_K_q8_K_block8(wr + b, xqb[8] ? xqb[8] + b : NULL, xqb[9] ? xqb[9] + b : NULL,
                                         xqb[10] ? xqb[10] + b : NULL, xqb[11] ? xqb[11] + b : NULL,
                                         xqb[12] ? xqb[12] + b : NULL, xqb[13] ? xqb[13] + b : NULL,
                                         xqb[14] ? xqb[14] + b : NULL, xqb[15] ? xqb[15] + b : NULL, np - 8u, acc + 8);
            }
        }
        for (uint32_t p = 0; p < np; p++) {
            acc[p] = quarter_warp_sum_f32(acc[p], lane);
            if (lane == 0) {
                if (atomic_out) {
                    uint32_t tok = pair[p] / n_expert;
                    atomicAdd(down_out + (uint64_t)tok * out_dim + row, acc[p]);
                } else {
                    down_out[(uint64_t)pair[p] * out_dim + row] = acc[p];
                }
            }
        }
    }
}

__global__ static void moe_down_sorted_p2_qwarp32_kernel(
        float *down_out,
        const char *down_base,
        const cuda_block_q8_K *midq,
        const uint32_t *sorted_pairs,
        const int32_t *selected,
        uint64_t down_expert_bytes,
        uint64_t down_row_bytes,
        uint32_t midq_blocks,
        uint32_t out_dim,
        uint32_t n_expert,
        uint32_t pair_count) {
    uint32_t lane = threadIdx.x & 7u;
    uint32_t pair_lane = (threadIdx.x >> 3u) & 1u;
    uint32_t row = blockIdx.x * 16u + (threadIdx.x >> 4u);
    uint32_t sorted_idx = blockIdx.y * 2u + pair_lane;
    if (row >= out_dim || sorted_idx >= pair_count) return;
    uint32_t pair = sorted_pairs[sorted_idx];
    uint32_t tok = pair / n_expert;
    uint32_t slot = pair - tok * n_expert;
    int32_t expert_i = selected[(uint64_t)tok * n_expert + slot];
    if (expert_i < 0) expert_i = 0;
    if (expert_i >= 256) expert_i = 255;  /* routed expert ids fixed at 256 */
    const cuda_block_q2_K *wr = (const cuda_block_q2_K *)(down_base + (uint64_t)(uint32_t)expert_i * down_expert_bytes + (uint64_t)row * down_row_bytes);
    const cuda_block_q8_K *xq = midq + (uint64_t)pair * midq_blocks;
    float acc = 0.0f;
    for (uint32_t b = lane; b < midq_blocks; b += 8u) acc += dev_dot_q2_K_q8_K_block(wr + b, xq + b);
    acc = quarter_warp_sum_f32(acc, lane);
    if (lane == 0) down_out[(uint64_t)pair * out_dim + row] = acc;
}

/* mmq pipeline helper: SwiGLU + clamp + weight, in (token, slot, feature)
 * layout matching what ds4_mmq_*_moe writes.  Mirrors the inline math in
 * moe_gate_up_mid_qwarp32_kernel (line ~9885): clamp gate to [-inf, clamp],
 * clamp up to [-clamp, clamp], compute silu(gate)*up*weight, store as mid.
 * Phase 6 uses this on the gate/up matmul outputs to produce mid; the
 * existing moe_sum_kernel below sums slots into the final per-token output. */
__global__ static void moe_mmq_swiglu_weighted_clamp_kernel(
        float *mid_out,
        float *gate_out_dbg, float *up_out_dbg,
        const float *gate_buf, const float *up_buf,
        const float *weights,
        uint32_t expert_mid_dim,
        uint32_t n_tokens,
        uint32_t n_expert_used,
        float clamp) {
    uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)n_tokens * n_expert_used * expert_mid_dim;
    if (gid >= n) return;
    uint64_t slot_pair = gid / expert_mid_dim;
    uint32_t tok = (uint32_t)(slot_pair / n_expert_used);
    uint32_t slot = (uint32_t)(slot_pair - (uint64_t)tok * n_expert_used);
    float g = gate_buf[gid];
    float u = up_buf[gid];
    /* P3: sanitize at read (nonfinite -> 0, exactly what the standalone
     * ds4_mmq_sanitize_f32 pass wrote).  Lets the SoA mmq entries skip that
     * whole-buffer pass; sanitized producers are unaffected (values already
     * finite). */
    if (!isfinite(g)) g = 0.0f;
    if (!isfinite(u)) u = 0.0f;
    if (clamp > 1.0e-6f) {
        if (g > clamp) g = clamp;
        if (u > clamp) u = clamp;
        if (u < -clamp) u = -clamp;
    }
    const float w = weights[(uint64_t)tok * n_expert_used + slot];
    const float s = g / (1.0f + expf(-g));
    if (gate_out_dbg) gate_out_dbg[gid] = g;
    if (up_out_dbg)   up_out_dbg[gid]   = u;
    mid_out[gid] = s * u * w;
}

/* P3: guard_nonfinite=1 sanitizes each slot at read (nonfinite -> dropped,
 * exactly what summing the standalone-sanitized buffer produced) so the mmq
 * pipeline can skip the whole-buffer ds4_mmq_sanitize_f32 pass.  The legacy
 * f32/qwarp32 producers pass 0 to keep their historical propagation. */
__global__ static void moe_sum_kernel(float *out, const float *down, uint32_t out_dim, uint32_t n_expert, uint32_t n_tokens, uint32_t guard_nonfinite) {
    uint64_t gid = (uint64_t)blockIdx.x * blockDim.x + threadIdx.x;
    uint64_t n = (uint64_t)n_tokens * out_dim;
    if (gid >= n) return;
    uint32_t tok = gid / out_dim;
    uint32_t row = gid - (uint64_t)tok * out_dim;
    float acc = 0.0f;
    for (uint32_t e = 0; e < n_expert; e++) {
        const float v = down[((uint64_t)tok * n_expert + e) * out_dim + row];
        if (!guard_nonfinite || isfinite(v)) acc += v;
    }
    out[gid] = acc;
}

__device__ static float dev_iq2_xxs_dot_f32(const cuda_block_iq2_xxs *row, const float *x, uint32_t nb) {
    float acc = 0.0f;
    for (uint32_t b = 0; b < nb; b++) {
        const cuda_block_iq2_xxs *xb = row + b;
        const float d = dev_f16_to_f32(xb->d);
        const uint16_t *q2 = xb->qs;
        const float *xf = x + (uint64_t)b * CUDA_QK_K;
        for (uint32_t ib32 = 0; ib32 < CUDA_QK_K / 32; ib32++) {
            const uint32_t aux_g = (uint32_t)q2[0] | ((uint32_t)q2[1] << 16);
            const uint32_t aux_s = (uint32_t)q2[2] | ((uint32_t)q2[3] << 16);
            q2 += 4;
            const float dl = d * (0.5f + (float)(aux_s >> 28)) * 0.25f;
            const uint8_t grids[4] = {
                (uint8_t)(aux_g & 0xffu),
                (uint8_t)((aux_g >> 8) & 0xffu),
                (uint8_t)((aux_g >> 16) & 0xffu),
                (uint8_t)((aux_g >> 24) & 0xffu),
            };
            for (uint32_t half = 0; half < 2; half++) {
                for (uint32_t g = 0; g < 2; g++) {
                    const uint32_t gi = half * 2 + g;
                    const uint64_t grid = cuda_iq2xxs_grid[grids[gi]];
                    const uint8_t signs = cuda_ksigns_iq2xs[(aux_s >> (14u * half + 7u * g)) & 127u];
                    for (uint32_t i = 0; i < 8; i++) {
                        float w = (float)((grid >> (8u * i)) & 0xffu);
                        if (signs & (1u << i)) w = -w;
                        acc += dl * w * xf[ib32 * 32u + half * 16u + g * 8u + i];
                    }
                }
            }
        }
    }
    return acc;
}

__device__ static float dev_q2_K_dot_f32(const cuda_block_q2_K *row, const float *x, uint32_t nb) {
    float acc = 0.0f;
    for (uint32_t b = 0; b < nb; b++) {
        const cuda_block_q2_K *xb = row + b;
        const float d = dev_f16_to_f32(xb->d);
        const float dmin = dev_f16_to_f32(xb->dmin);
        for (uint32_t il = 0; il < 16; il++) {
            const uint32_t chunk = il / 8u;
            const uint32_t pair = il & 1u;
            const uint32_t shift = ((il / 2u) & 3u) * 2u;
            const uint8_t sc = xb->scales[il];
            const float dl = d * (float)(sc & 0x0fu);
            const float ml = dmin * (float)(sc >> 4);
            const uint8_t *q = xb->qs + 32u * chunk + 16u * pair;
            const float *xf = x + (uint64_t)b * CUDA_QK_K + chunk * 128u + ((il % 8u) / 2u) * 32u + pair * 16u;
            for (uint32_t i = 0; i < 16; i++) {
                const float w = dl * (float)((q[i] >> shift) & 3u) - ml;
                acc += w * xf[i];
            }
        }
    }
    return acc;
}

__global__ static void moe_gate_up_mid_f32_kernel(
        float *gate_out,
        float *up_out,
        float *mid_out,
        const char *gate_base,
        const char *up_base,
        const float *x,
        const int32_t *selected,
        const float *weights,
        uint64_t gate_expert_bytes,
        uint64_t gate_row_bytes,
        uint32_t expert_in_dim,
        uint32_t expert_mid_dim,
        uint32_t n_expert,
        float clamp) {
    uint32_t row = blockIdx.x;
    uint32_t pair = blockIdx.y;
    if (row >= expert_mid_dim) return;
    uint32_t tok = pair / n_expert;
    uint32_t slot = pair - tok * n_expert;
    int32_t expert_i = selected[(uint64_t)tok * n_expert + slot];
    if (expert_i < 0) expert_i = 0;
    if (expert_i >= 256) expert_i = 255;  /* routed expert ids fixed at 256 */
    uint32_t expert = (uint32_t)expert_i;
    const uint32_t nb = expert_in_dim / CUDA_QK_K;
    const cuda_block_iq2_xxs *gr = (const cuda_block_iq2_xxs *)(gate_base + (uint64_t)expert * gate_expert_bytes + (uint64_t)row * gate_row_bytes);
    const cuda_block_iq2_xxs *ur = (const cuda_block_iq2_xxs *)(up_base + (uint64_t)expert * gate_expert_bytes + (uint64_t)row * gate_row_bytes);
    const float *xr = x + (uint64_t)tok * expert_in_dim;
    float gate = 0.0f;
    float up = 0.0f;
    for (uint32_t b = threadIdx.x; b < nb; b += blockDim.x) {
        gate += dev_iq2_xxs_dot_f32(gr + b, xr + (uint64_t)b * CUDA_QK_K, 1);
        up += dev_iq2_xxs_dot_f32(ur + b, xr + (uint64_t)b * CUDA_QK_K, 1);
    }
    __shared__ float partial_gate[256];
    __shared__ float partial_up[256];
    partial_gate[threadIdx.x] = gate;
    partial_up[threadIdx.x] = up;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            partial_gate[threadIdx.x] += partial_gate[threadIdx.x + stride];
            partial_up[threadIdx.x] += partial_up[threadIdx.x + stride];
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        gate = partial_gate[0];
        up = partial_up[0];
        if (clamp > 1.0e-6f) {
            if (gate > clamp) gate = clamp;
            if (up > clamp) up = clamp;
            if (up < -clamp) up = -clamp;
        }
        const uint64_t off = (uint64_t)pair * expert_mid_dim + row;
        gate_out[off] = gate;
        up_out[off] = up;
        mid_out[off] = (gate / (1.0f + expf(-gate))) * up * weights[(uint64_t)tok * n_expert + slot];
    }
}

__global__ static void moe_down_f32_kernel(
        float *down_out,
        const char *down_base,
        const float *mid,
        const int32_t *selected,
        uint64_t down_expert_bytes,
        uint64_t down_row_bytes,
        uint32_t expert_mid_dim,
        uint32_t out_dim,
        uint32_t n_expert) {
    uint32_t row = blockIdx.x;
    uint32_t pair = blockIdx.y;
    if (row >= out_dim) return;
    uint32_t tok = pair / n_expert;
    uint32_t slot = pair - tok * n_expert;
    int32_t expert_i = selected[(uint64_t)tok * n_expert + slot];
    if (expert_i < 0) expert_i = 0;
    if (expert_i >= 256) expert_i = 255;  /* routed expert ids fixed at 256 */
    const uint32_t nb = expert_mid_dim / CUDA_QK_K;
    const cuda_block_q2_K *wr = (const cuda_block_q2_K *)(down_base + (uint64_t)(uint32_t)expert_i * down_expert_bytes + (uint64_t)row * down_row_bytes);
    const float *xr = mid + (uint64_t)pair * expert_mid_dim;
    float acc = 0.0f;
    for (uint32_t b = threadIdx.x; b < nb; b += blockDim.x) acc += dev_q2_K_dot_f32(wr + b, xr + (uint64_t)b * CUDA_QK_K, 1);
    __shared__ float partial[256];
    partial[threadIdx.x] = acc;
    __syncthreads();
    for (uint32_t stride = blockDim.x >> 1; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) partial[threadIdx.x] += partial[threadIdx.x + stride];
        __syncthreads();
    }
    if (threadIdx.x == 0) down_out[(uint64_t)pair * out_dim + row] = partial[0];
}

static int routed_moe_launch(
        ds4_gpu_tensor *out,
        ds4_gpu_tensor *gate,
        ds4_gpu_tensor *up,
        ds4_gpu_tensor *mid,
        ds4_gpu_tensor *down,
        const void *model_map,
        uint64_t model_size,
        uint64_t gate_offset,
        uint64_t up_offset,
        uint64_t down_offset,
        uint32_t gate_type,
        uint32_t down_type,
        uint64_t gate_expert_bytes,
        uint64_t gate_row_bytes,
        uint64_t down_expert_bytes,
        uint64_t down_row_bytes,
        uint32_t expert_in_dim,
        uint32_t expert_mid_dim,
        uint32_t out_dim,
        const ds4_gpu_tensor *selected,
        const ds4_gpu_tensor *weights,
        uint32_t n_total_expert,
        uint32_t n_expert,
        float clamp,
        const ds4_gpu_tensor *x,
        uint32_t n_tokens,
        /* v0.5 inc-8 F5: skip the prefill-path moe_sum and leave `down`
         * per-expert unsummed (reported via *out_sum_deferred); the caller
         * folds the guarded sum into the HC expand epilogue.  Branches that
         * sum internally simply never set the flag. */
        int defer_sum,
        int *out_sum_deferred) {
    if (out_sum_deferred) *out_sum_deferred = 0;
    if (!out || !gate || !up || !mid || !down || !model_map || !selected || !weights || !x ||
        n_tokens == 0 || n_total_expert == 0 || n_expert == 0 ||
        expert_in_dim % CUDA_QK_K != 0 || expert_mid_dim % CUDA_QK_K != 0 ||
        gate_offset > model_size || up_offset > model_size || down_offset > model_size ||
        x->bytes < (uint64_t)n_tokens * expert_in_dim * sizeof(float) ||
        selected->bytes < (uint64_t)n_tokens * n_expert * sizeof(int32_t) ||
        weights->bytes < (uint64_t)n_tokens * n_expert * sizeof(float) ||
        gate->bytes < (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float) ||
        up->bytes < (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float) ||
        mid->bytes < (uint64_t)n_tokens * n_expert * expert_mid_dim * sizeof(float) ||
        down->bytes < (uint64_t)n_tokens * n_expert * out_dim * sizeof(float) ||
        out->bytes < (uint64_t)n_tokens * out_dim * sizeof(float)) {
        return 0;
    }
    const int q4k_path = (gate_type == 12u && down_type == 12u);
    /* Requant tiers (2026-07-07): gate/up and down kernel selection below
     * dispatches on the two quant types INDEPENDENTLY, so beside the two
     * original pairs (all-Q4_K MTP/drafter, IQ2_XXS+Q2_K base) the launch
     * also serves Q4_K gate/up + Q2_K down and all-Q2_K expert stacks (the
     * requantized DSpark drafters).  q4k_path keeps meaning "all-Q4_K" for
     * the scope/stats helpers that use it as a model tag.  Q2_K gate/up has
     * no fused pair kernels (yet): it rides the unfused vec tier and two
     * single mmq launches; the legacy fallback rejects the new pairs (see
     * mmq_moe_fallback entry). */
    const int gate_is_q4k = gate_type == 12u;
    const int gate_is_iq2 = gate_type == 16u;
    const int gate_is_q2k = gate_type == 10u;
    const int down_is_q2k = down_type == 10u;
    if (!((gate_is_q4k && down_type == 12u) ||
          ((gate_is_iq2 || gate_is_q4k || gate_is_q2k) && down_is_q2k))) return 0;
    /* Q4_K MoE: the LEGACY fallback (mmq_moe_fallback:) only handles the V4-Flash
     * decode shape (n_tokens=1, n_expert=6); wider Q4_K shapes are served by the
     * mmq block below (ds4_mmq_q4_K_moe_pair, n_tokens >= mmq_moe_min_tokens).
     * M4b: the batched MTP draft runs the Q4_K MTP experts at n_tokens>1, so we
     * must NOT reject q4k-wide up front -- let it reach the mmq dispatch; the
     * fallback's own guard (below) still rejects any shape mmq declines.  (Base
     * V4-Flash uses IQ2_XXS experts, not q4k, so this path is MTP-only.)
     * Note n_total_expert (runtime, was constant 256 before PRO support) sizes
     * the model weight stride. */
    const uint64_t gate_bytes = (uint64_t)n_total_expert * gate_expert_bytes;
    const uint64_t down_bytes = (uint64_t)n_total_expert * down_expert_bytes;
    if (gate_bytes > model_size - gate_offset ||
        gate_bytes > model_size - up_offset ||
        down_bytes > model_size - down_offset) {
        return 0;
    }
    /* M1-Inc1: probe for aligned-SoA IQ2_XXS gate/up artifacts (weight server
     * --repack-iq2-aligned).  When present, the raw gate/up ranges were
     * EXCLUDED from the upload, so resolving them via cuda_model_range_ptr
     * would fall into its register-or-copy miss path and pin/duplicate the
     * ~45 GiB of expert weights.  Resolve them as plain mmap pointers
     * instead: the decode vec branch below dispatches on the artifacts and
     * never reads the raw pointers; the batched/mmq paths read the raw
     * layout directly through HMM at mmap rates (prefill-amortized). */
    const char *gate_iq2_aligned = NULL;
    const char *up_iq2_aligned = NULL;
    if (gate_is_iq2) {
        const uint64_t iq2_al_bytes = ds4_mmq_iq2_xxs_aligned_bytes(
            (int)expert_mid_dim, (int)expert_in_dim, (int)n_total_expert);
        if (iq2_al_bytes != 0) {
            gate_iq2_aligned = cuda_derived_weight_ptr(
                model_map, gate_offset, gate_bytes,
                CUDA_DERIVED_IQ2_XXS_ALIGNED_MOE,
                expert_in_dim, expert_mid_dim, n_total_expert,
                iq2_al_bytes, "moe_gate_iq2_aligned");
            up_iq2_aligned = cuda_derived_weight_ptr(
                model_map, up_offset, gate_bytes,
                CUDA_DERIVED_IQ2_XXS_ALIGNED_MOE,
                expert_in_dim, expert_mid_dim, n_total_expert,
                iq2_al_bytes, "moe_up_iq2_aligned");
        }
        if (!gate_iq2_aligned || !up_iq2_aligned) {
            gate_iq2_aligned = NULL;
            up_iq2_aligned = NULL;
        }
    }
    /* M2 moe-down: probe for the aligned row-pair-SoA Q2_K down artifact
     * (weight server --repack-q2k-aligned).  Same replacement semantics as
     * the iq2 gate/up artifacts: when present, the raw down range was
     * EXCLUDED from the upload, so resolve it as a plain mmap pointer; the
     * decode vec branch dispatches on the artifact and the batched/mmq path
     * de-repacks into a device scratch. */
    const char *down_q2k_aligned = NULL;
    if (down_is_q2k) {
        const uint64_t q2k_al_bytes = ds4_mmq_q2_k_aligned_bytes(
            (int)out_dim, (int)expert_mid_dim, (int)n_total_expert);
        if (q2k_al_bytes != 0) {
            down_q2k_aligned = cuda_derived_weight_ptr(
                model_map, down_offset, down_bytes,
                CUDA_DERIVED_Q2_K_ALIGNED_MOE,
                expert_mid_dim, out_dim, n_total_expert,
                q2k_al_bytes, "moe_down_q2k_aligned");
        }
    }
    const char *gate_w = gate_iq2_aligned
        ? cuda_model_ptr(model_map, gate_offset)
        : cuda_model_range_ptr(model_map, gate_offset, gate_bytes, "moe_gate");
    const char *up_w = up_iq2_aligned
        ? cuda_model_ptr(model_map, up_offset)
        : cuda_model_range_ptr(model_map, up_offset, gate_bytes, "moe_up");
    const char *down_w = down_q2k_aligned
        ? cuda_model_ptr(model_map, down_offset)
        : cuda_model_range_ptr(model_map, down_offset, down_bytes, "moe_down");
    if (!gate_w || !up_w || !down_w) return 0;

    /* mmq routed-MoE fast path.  Gated on DS4_CUDA_USE_MMQ + n_tokens
     * threshold.  Handles both the V4-Flash quant config (IQ2_XXS gate/up +
     * Q2_K down) and Q4_K-only MoE GGUFs (gate/up/down all Q4_K, added in
     * Step 2 of the optimization plan).
     *
     * Pipeline (per-row Q-type dispatched inside):
     *   1. mmq_<gate_type>_moe(gate_w, x, selected) -> gate->ptr,
     *      shape [n_tokens * n_expert_used, expert_mid_dim] col-major =
     *      row-major same shape.
     *   2. mmq_<gate_type>_moe(up_w, x, selected)   -> up->ptr, same shape.
     *   3. moe_mmq_swiglu_weighted_clamp_kernel: clamp + silu(gate) * up
     *      * router_weight[token, slot] -> mid->ptr, same shape.  Mirrors
     *      the inline math in moe_gate_up_mid_qwarp32_kernel.
     *   4. mmq_<down_type>_moe(down_w, mid->ptr, selected) -> down->ptr,
     *      treating each (token, slot) pair as one row of an
     *      [n_tokens * n_expert_used, 1] activation tensor; the same
     *      `selected` int32 buffer flat-indexes as the expert id for each
     *      row.  Output [n_tokens * n_expert_used, out_dim] matches the
     *      legacy down layout (down[(tok * n_expert_used + slot), row]).
     *   5. moe_sum_kernel (unchanged): sum across the n_expert_used slot
     *      dim -> out, since router weights are already baked into mid. */
    /* Decode (n_tokens=1, top_k=6 -> 6 assignment rows) is handled faster
     * by the legacy fused moe_gate_up_mid_decode_lut_qwarp32_kernel than by
     * mmq's matrix-matrix code path, which has higher per-launch fixed cost
     * at small batch sizes.  Default the mmq path on for n_tokens >= 2 only.
     * DS4_CUDA_MMQ_MOE_MIN_TOKENS overrides the threshold (e.g. set to 1 to
     * force mmq even for decode, or to a very large value to disable mmq
     * for MoE entirely while keeping it for the dense path). */
    static int mmq_moe_min_tokens_init = 0;
    static uint32_t mmq_moe_min_tokens = 2;
    if (!mmq_moe_min_tokens_init) {
        mmq_moe_min_tokens_init = 1;
        const char *s = getenv("DS4_CUDA_MMQ_MOE_MIN_TOKENS");
        if (s && *s) {
            long v = strtol(s, NULL, 10);
            if (v >= 1 && v <= 0x10000) mmq_moe_min_tokens = (uint32_t)v;
        }
    }

    /* mmvq decode branch (Step 6).  Routes the n_tokens=1 (and optionally
     * a few short-prefill tokens) case through llama.cpp's vector matmul
     * kernels, which are structurally optimised for small batch.
     *
     * Constraints:
     *   - ds4_mmq_moe_vec_impl splits its column dim into per-compiled-arch
     *     capped chunks internally, so the default <=8 tier and the scoped
     *     small16 extension share the same Q8_1 vector machinery.  Every
     *     (token, slot) row is an independent single-expert matvec, so
     *     chunking is just pointer offsets.
     *   - Outside the scoped small16 extension, the vec tier as a whole is
     *     bounded by cuda_moe_vec_max_assign(); beyond it, fall through to
     *     the mmq tile path below, which amortizes expert-weight reads
     *     across assignment columns.
     *
     * The DeepSeek V4 clamp (clamp=10 in this build) is applied by the
     * existing moe_mmq_swiglu_weighted_clamp_kernel after the two matmuls.
     * mmvq's built-in pair-fused SwiGLU (ds4_mmq_<>_moe_pair_vec) is NOT
     * used here because that path applies silu without clamp; it stays
     * available for future clamp-aware fusion work.
     *
     * Opt-out: DS4_CUDA_NO_MMVQ_DECODE=1.
     * Threshold override: DS4_CUDA_MMVQ_DECODE_MAX_TOKENS=N (0 disables,
     *   1 = decode-only [default], 8 = use vec for all short batches).
     */
    /* FD Inc1: threshold logic unified with the dense Q8_0 site. */
    const uint32_t mmvq_decode_max_tokens = cuda_mmvq_decode_max_tokens();
    const uint32_t small16_max_tokens = cuda_moe_small16_max_tokens();
    const uint32_t small16_scope_active = cuda_moe_small16_scope_active(q4k_path, model_size);
    const uint32_t small16_vec_active =
        small16_scope_active &&
        small16_max_tokens != 0u &&
        n_tokens > 8u && n_tokens <= small16_max_tokens &&
        n_expert == 6u;
    const uint32_t mmvq_token_ceiling = small16_vec_active ? small16_max_tokens : mmvq_decode_max_tokens;
    if (ds4_cuda_use_mmq() && n_tokens > 0u && n_tokens <= mmvq_token_ceiling) {
        const uint32_t n_expert_used   = n_expert;
        const uint32_t n_experts_total = 256u;
        const uint64_t n_assignments   = (uint64_t)n_tokens * n_expert_used;
        /* gate ncols_dst = n_tokens (<= 8 by the outer gate); down's wider
         * column dim is chunk-split inside the vec impl.  FD Inc2a: the
         * tier envelope is the assignment knob, no longer a hard 8. */
        uint64_t vec_max_assign = (uint64_t)cuda_moe_vec_max_assign();
        if (small16_vec_active && vec_max_assign < n_assignments) vec_max_assign = n_assignments;
        if (n_assignments > vec_max_assign) {
            /* Beyond the vec tier's assignment envelope; fall through. */
        } else {
            /* Step 8: graph cache fast path.  If enabled, check the cache
             * for a captured graph matching the current shape + pointers.
             * On hit: replay (cudaGraphLaunch).  On miss: capture the
             * kernel sequence below and store the exec for next time. */
            struct moe_graph_entry *graph_slot = NULL;
            int graph_capturing = 0;
            /* Step 7 stream-ordering fix (post-analyst review): under outer
             * layer-graph capture, route mmq through the active capture
             * stream so it's recorded as a graph node with proper
             * dependencies on surrounding probes/swiglu/sum kernels.  The
             * previous initialisation left moe_stream = 0 when
             * DS4_CUDA_MOE_GRAPHS was not set, which left mmq running on
             * the legacy default stream while the rest of the layer ran on
             * the capture stream -- a race that the captured-replay
             * scheduler resolved differently than eager, producing the
             * routed_gate divergence at slot 213.  See plan-doc Step 7
             * deep-narrowing entry for the diagnosis. */
            cudaStream_t moe_stream;
            if (ds4_capture_active()) {
                moe_stream = ds4_current_stream();
            } else {
                moe_stream = ds4_cuda_moe_graphs_enabled() ? ds4_cuda_moe_stream() : (cudaStream_t)0;
            }
            /* R3 inner-bypass (Step 5, hardened in Step 6).  When an outer
             * per-layer capture is active, skip the inner MoE-graph cache
             * entirely (both HIT path and MISS path are unsafe under outer
             * capture -- see the matching guard at the dense Q8_0 site). */
            if (ds4_cuda_moe_graphs_enabled() && moe_stream && !ds4_capture_active()) {
                ds4_cuda_capture_warm_tmp_scratch();
                struct moe_graph_key key;
                memset(&key, 0, sizeof(key));
                key.gate_offset     = gate_offset;
                key.up_offset       = up_offset;
                key.down_offset     = down_offset;
                key.n_tokens        = n_tokens;
                /* Requant tiers: the field predates the split dispatch; encode
                 * BOTH quant types so distinct kernel selections never share a
                 * captured graph (offsets already disambiguate models, this
                 * makes it explicit). */
                key.q4k_path        = (gate_type << 8) | down_type;
                key.expert_in_dim   = expert_in_dim;
                key.expert_mid_dim  = expert_mid_dim;
                key.out_dim         = out_dim;
                key.gate_ptr        = gate->ptr;
                key.up_ptr          = up->ptr;
                key.mid_ptr         = mid->ptr;
                key.down_ptr        = down->ptr;
                key.out_ptr         = out->ptr;
                key.x_ptr           = x->ptr;
                key.sel_ptr         = selected->ptr;
                key.w_ptr           = weights->ptr;
                graph_slot = moe_graph_slot(&key);
                if (graph_slot->valid &&
                    memcmp(&graph_slot->key, &key, sizeof(key)) == 0) {
                    /* HIT: replay the cached graph and return. */
                    ds4_cuda_moe_stream_sync_pre(moe_stream);
                    const uint32_t lite_slot_hit = moe_lite_begin(n_tokens, q4k_path, moe_stream);
                    cudaError_t ge = cudaGraphLaunch(graph_slot->exec, moe_stream);
                    if (ge != cudaSuccess) {
                        fprintf(stderr, "ds4: cudaGraphLaunch failed: %s; recapturing\n",
                                cudaGetErrorString(ge));
                        cuda_graph_exec_destroy_noted(graph_slot->exec,
                                                      &graph_slot->exec_bytes);
                        graph_slot->valid = 0;
                        /* fall through to capture path below */
                    } else {
                        moe_lite_end(lite_slot_hit, moe_stream);
                        ds4_cuda_moe_stream_sync_post(moe_stream);
                        graph_slot->hits++;
                        return 1;
                    }
                }
                /* MISS: begin capture, run the sequence, then end capture
                 * and instantiate.  Save the exec at graph_slot. */
                memcpy(&graph_slot->key, &key, sizeof(key));
                if (graph_slot->valid) {
                    /* Hash collision with a different key - tear down the
                     * old exec before recapturing for the new one. */
                    cuda_graph_exec_destroy_noted(graph_slot->exec,
                                                  &graph_slot->exec_bytes);
                    graph_slot->valid = 0;
                    graph_slot->hits = 0;
                }
                cudaError_t ge = cudaStreamBeginCapture(moe_stream, cudaStreamCaptureModeThreadLocal);
                if (ge == cudaSuccess) {
                    graph_capturing = 1;
                    /* Route the in-capture <<<>>> kernel launches at
                     * moe_mmq_swiglu_weighted_clamp_kernel and moe_sum_kernel
                     * to moe_stream so they record into the capture.  The
                     * ds4_mmq_*_moe_vec calls below carry moe_stream as an
                     * explicit parameter and are unaffected by this. */
                    ds4_capture_set_stream(moe_stream);
                } else {
                    fprintf(stderr, "ds4: cudaStreamBeginCapture failed: %s; graphs disabled this call\n",
                            cudaGetErrorString(ge));
                    graph_slot = NULL;
                }
            }

            int rc = -1;
            int gate_up_fused = 0;
            int down_sum_fused = 0;
            const uint32_t use_q81_fused_moe =
                getenv("DS4_CUDA_MOE_Q81_FUSED") != NULL;
            const uint32_t use_q8k_gate_in_vec =
                n_expert_used == 6u && getenv("DS4_CUDA_MOE_Q8K_GATE_IN_VEC") != NULL;
            const uint32_t use_q8k_down_in_vec =
                n_expert_used == 6u && getenv("DS4_CUDA_MOE_Q8K_DOWN_IN_VEC") != NULL;
            const uint32_t use_pair_raw_vec =
                n_expert_used == 6u && getenv("DS4_CUDA_MOE_PAIR_RAW_VEC") != NULL;
            const uint32_t profile_mmvq_moe =
                getenv("DS4_CUDA_MOE_PROFILE") != NULL && !ds4_capture_active();
            /* MOE_PROF_LITE: eager/graphs-off path bracket (the graph-replay
             * HIT path is bracketed at its cudaGraphLaunch above; see the
             * moe_lite_* helpers next to moe_graph_slot). */
            const uint32_t lite_slot = graph_capturing
                ? UINT32_MAX
                : moe_lite_begin(n_tokens, q4k_path, moe_stream ? moe_stream : ds4_current_stream());
            cudaEvent_t mmvq_prof_ev[5] = {NULL, NULL, NULL, NULL, NULL};
            if (profile_mmvq_moe) {
                for (uint32_t i = 0; i < 5u; i++) {
                    if (cudaEventCreate(&mmvq_prof_ev[i]) != cudaSuccess) {
                        for (uint32_t j = 0; j < i; j++) (void)cudaEventDestroy(mmvq_prof_ev[j]);
                        memset(mmvq_prof_ev, 0, sizeof(mmvq_prof_ev));
                        break;
                    }
                }
                if (mmvq_prof_ev[0]) (void)cudaEventRecord(mmvq_prof_ev[0], ds4_current_stream());
            }

            /* M1-Inc2: aligned-SoA fused gate+up+SwiGLU.  One activation
             * quantize + one warp-per-row launch over both aligned artifacts
             * with the clamp/SwiGLU/router-weight epilogue folded in
             * (nonfinite zeroed in-kernel; no sanitize pass).  Entry-level
             * A/B: 0.130 ms (2x aligned Inc1) -> 0.118, both DRAM-honest at
             * ~218 GB/s, plus the swiglu launch removed.  Diagnostic env
             * paths below still take priority when explicitly requested. */
            /* n_tokens <= 16: the aligned kernels cover the whole vec-tier
             * envelope (widths 2..8 default, 9..16 under small16).  This is
             * load-bearing under --repack-iq2-aligned: the raw iq2 ranges are
             * replaced by the artifacts, so the legacy vec path below reads
             * host mmap at ~100x cost (the 2026-07-03 batch_eval "hang"). */
            if (n_tokens <= 16u && gate_iq2_aligned && up_iq2_aligned &&
                cuda_moe_iq2_aligned_enabled() &&
                !use_q8k_gate_in_vec && !use_q81_fused_moe && !use_pair_raw_vec) {
                rc = ds4_mmq_iq2_xxs_aligned_moe_gate_up_mid_vec(
                    gate_iq2_aligned, up_iq2_aligned,
                    (const float *)x->ptr,
                    (const int32_t *)selected->ptr,
                    (const float *)weights->ptr,
                    (float *)mid->ptr,
                    (int)expert_mid_dim, (int)expert_in_dim,
                    (int)n_tokens, (int)n_total_expert,
                    (int)n_expert_used, clamp, moe_stream);
                if (rc == 0) {
                    gate_up_fused = 1;
                    static int logged = 0;
                    if (!logged) {
                        logged = 1;
                        fprintf(stderr, "ds4: MoE decode using aligned fused gate+up+swiglu (M1-Inc2)\n");
                    }
                } else {
                    fprintf(stderr, "ds4: ds4_mmq_iq2_xxs_aligned_moe_gate_up_mid_vec returned %d; falling back\n", rc);
                }
            }
            /* 1. Gate + up + SwiGLU.  For V4 top_k=6, fuse the two
             *    canonical-Q8_1 matvecs and the clamp/SwiGLU/router-weight
             *    epilogue into mid directly.  This removes one activation
             *    quantize, one vector matmul sequence, and the separate
             *    swiglu launch while preserving the Q8_1 dot path. */
            if (!gate_up_fused && use_q8k_gate_in_vec && !gate_is_q2k) {
                const uint32_t xq_blocks = expert_in_dim / CUDA_QK_K;
                const uint64_t xq_bytes = (uint64_t)n_tokens * xq_blocks * sizeof(cuda_block_q8_K);
                if (expert_in_dim % CUDA_QK_K == 0u && down->bytes >= xq_bytes) {
                    cuda_block_q8_K *xq = (cuda_block_q8_K *)down->ptr;
                    dim3 xq_grid(xq_blocks, n_tokens, 1);
                    q8_K_quantize_kernel<<<xq_grid, 256, 0, ds4_current_stream()>>>(
                        xq, (const float *)x->ptr, expert_in_dim, n_tokens);
                    if (!cuda_ok(cudaGetLastError(), "mmvq q8k gate x quantize launch")) goto mmvq_decode_bail;

                    dim3 qgrid((expert_mid_dim + 127u) / 128u, n_assignments, 1);
                    if (gate_is_q4k) {
                        moe_gate_up_mid_decode_q4K_qwarp32_kernel<<<qgrid, 256, 0, ds4_current_stream()>>>(
                            (float *)gate->ptr,
                            (float *)up->ptr,
                            (float *)mid->ptr,
                            gate_w,
                            up_w,
                            xq,
                            (const int32_t *)selected->ptr,
                            (const float *)weights->ptr,
                            gate_expert_bytes,
                            gate_row_bytes,
                            xq_blocks,
                            expert_mid_dim,
                            n_expert_used,
                            /*write_aux=*/0u,
                            clamp);
                    } else {
                        moe_gate_up_mid_decode_lut_qwarp32_kernel<<<qgrid, 256, 0, ds4_current_stream()>>>(
                            (float *)gate->ptr,
                            (float *)up->ptr,
                            (float *)mid->ptr,
                            gate_w,
                            up_w,
                            xq,
                            (const int32_t *)selected->ptr,
                            (const float *)weights->ptr,
                            gate_expert_bytes,
                            gate_row_bytes,
                            xq_blocks,
                            expert_mid_dim,
                            n_expert_used,
                            /*write_aux=*/0u,
                            clamp);
                    }
                    if (!cuda_ok(cudaGetLastError(), "mmvq q8k gate/up launch")) goto mmvq_decode_bail;
                    gate_up_fused = 1;
                } else {
                    fprintf(stderr, "ds4: DS4_CUDA_MOE_Q8K_GATE_IN_VEC requested but scratch/shape invalid; falling back to Q8_1 gate/up\n");
                }
            } else if (use_q81_fused_moe && n_expert_used == 6u && !gate_is_q2k) {
                if (gate_is_q4k) {
                    rc = ds4_mmq_q4_K_moe_gate_up_mid_vec(gate_w, up_w,
                                                          (const float *)x->ptr,
                                                          (const int32_t *)selected->ptr,
                                                          (const float *)weights->ptr,
                                                          (float *)mid->ptr,
                                                          (int)expert_mid_dim, (int)expert_in_dim,
                                                          (int)n_tokens, (int)n_experts_total,
                                                          (int)n_expert_used, clamp, moe_stream);
                } else {
                    rc = ds4_mmq_iq2_xxs_moe_gate_up_mid_vec(gate_w, up_w,
                                                             (const float *)x->ptr,
                                                             (const int32_t *)selected->ptr,
                                                             (const float *)weights->ptr,
                                                             (float *)mid->ptr,
                                                             (int)expert_mid_dim, (int)expert_in_dim,
                                                             (int)n_tokens, (int)n_experts_total,
                                                             (int)n_expert_used, clamp, moe_stream);
                }
                if (rc == 0) {
                    gate_up_fused = 1;
                } else {
                    fprintf(stderr, "ds4: ds4_mmq_<>_moe_gate_up_mid_vec returned %d; falling back to unfused gate/up\n", rc);
                }
            }
            if (gate_up_fused) {
                if (mmvq_prof_ev[1]) (void)cudaEventRecord(mmvq_prof_ev[1], ds4_current_stream());
                if (mmvq_prof_ev[2]) (void)cudaEventRecord(mmvq_prof_ev[2], ds4_current_stream());
            }
            if (!gate_up_fused) {
                int gate_up_pair_raw = 0;
                if (use_pair_raw_vec && !gate_is_q2k) {
                    if (gate_is_q4k) {
                        rc = ds4_mmq_q4_K_moe_pair_raw_vec(gate_w, up_w,
                                                           (const float *)x->ptr,
                                                           (const int32_t *)selected->ptr,
                                                           (float *)gate->ptr, (float *)up->ptr,
                                                           (int)expert_mid_dim, (int)expert_in_dim,
                                                           (int)n_tokens, (int)n_experts_total,
                                                           (int)n_expert_used, moe_stream);
                    } else {
                        rc = ds4_mmq_iq2_xxs_moe_pair_raw_vec(gate_w, up_w,
                                                              (const float *)x->ptr,
                                                              (const int32_t *)selected->ptr,
                                                              (float *)gate->ptr, (float *)up->ptr,
                                                              (int)expert_mid_dim, (int)expert_in_dim,
                                                              (int)n_tokens, (int)n_experts_total,
                                                              (int)n_expert_used, moe_stream);
                    }
                    if (rc == 0) {
                        gate_up_pair_raw = 1;
                    } else {
                        fprintf(stderr, "ds4: ds4_mmq_<>_moe_pair_raw_vec returned %d; falling back to separate gate/up\n", rc);
                    }
                }
                /* Two separate gate/up matmuls through mmvq. */
                if (!gate_up_pair_raw && gate_is_q4k) {
                    rc = ds4_mmq_q4_K_moe_vec(gate_w, (const float *)x->ptr,
                                              (const int32_t *)selected->ptr,
                                              (float *)gate->ptr,
                                              (int)expert_mid_dim, (int)expert_in_dim,
                                              (int)n_tokens, (int)n_experts_total,
                                              (int)n_expert_used, moe_stream);
                    if (rc != 0) {
                        fprintf(stderr, "ds4: ds4_mmq_q4_K_moe_vec (gate) returned %d; falling back\n", rc);
                        goto mmvq_decode_bail;
                    }
                    rc = ds4_mmq_q4_K_moe_vec(up_w, (const float *)x->ptr,
                                              (const int32_t *)selected->ptr,
                                              (float *)up->ptr,
                                              (int)expert_mid_dim, (int)expert_in_dim,
                                              (int)n_tokens, (int)n_experts_total,
                                              (int)n_expert_used, moe_stream);
                } else if (!gate_up_pair_raw && gate_is_q2k) {
                    /* Requant tier: Q2_K gate/up rides the same raw vec entry
                     * the base model's Q2_K down uses (no aligned artifacts:
                     * the WS repack is name-gated to .ffn_down_exps and
                     * base-scope only, so drafter gate/up ranges stay raw). */
                    rc = ds4_mmq_q2_K_moe_vec(gate_w, (const float *)x->ptr,
                                              (const int32_t *)selected->ptr,
                                              (float *)gate->ptr,
                                              (int)expert_mid_dim, (int)expert_in_dim,
                                              (int)n_tokens, (int)n_experts_total,
                                              (int)n_expert_used, moe_stream);
                    if (rc != 0) {
                        fprintf(stderr, "ds4: ds4_mmq_q2_K_moe_vec (gate) returned %d; falling back\n", rc);
                        goto mmvq_decode_bail;
                    }
                    rc = ds4_mmq_q2_K_moe_vec(up_w, (const float *)x->ptr,
                                              (const int32_t *)selected->ptr,
                                              (float *)up->ptr,
                                              (int)expert_mid_dim, (int)expert_in_dim,
                                              (int)n_tokens, (int)n_experts_total,
                                              (int)n_expert_used, moe_stream);
                } else if (!gate_up_pair_raw) {
                    /* M1-Inc1: aligned-SoA IQ2_XXS decode path.  When the
                     * weight server repacked the gate/up expert stacks
                     * (--repack-iq2-aligned; probed at the top of this
                     * function), dispatch the 64B-aligned warp-per-row
                     * kernel instead of the raw-layout vec entry (+12% at
                     * the decode shape; the 66-byte block stride makes raw
                     * code-word loads 2x16-bit).  Any failure falls through
                     * to the raw path, whose gate_w/up_w resolve to the
                     * plain mmap pointers when the raw ranges were excluded
                     * from the upload. */
                    const char *gate_al = NULL;
                    const char *up_al = NULL;
                    if (n_tokens <= 16u && cuda_moe_iq2_aligned_enabled()) {
                        gate_al = gate_iq2_aligned;
                        up_al = up_iq2_aligned;
                    }
                    if (gate_al && up_al) {
                        rc = ds4_mmq_iq2_xxs_aligned_moe_vec(gate_al, (const float *)x->ptr,
                                                             (const int32_t *)selected->ptr,
                                                             (float *)gate->ptr,
                                                             (int)expert_mid_dim, (int)expert_in_dim,
                                                             (int)n_tokens, (int)n_total_expert,
                                                             (int)n_expert_used, moe_stream);
                        if (rc == 0) {
                            rc = ds4_mmq_iq2_xxs_aligned_moe_vec(up_al, (const float *)x->ptr,
                                                                 (const int32_t *)selected->ptr,
                                                                 (float *)up->ptr,
                                                                 (int)expert_mid_dim, (int)expert_in_dim,
                                                                 (int)n_tokens, (int)n_total_expert,
                                                                 (int)n_expert_used, moe_stream);
                        }
                        if (rc != 0) {
                            fprintf(stderr, "ds4: ds4_mmq_iq2_xxs_aligned_moe_vec returned %d; using raw vec path\n", rc);
                            gate_al = NULL;
                        }
                    }
                    if (!gate_al || !up_al) {
                        rc = ds4_mmq_iq2_xxs_moe_vec(gate_w, (const float *)x->ptr,
                                                     (const int32_t *)selected->ptr,
                                                     (float *)gate->ptr,
                                                     (int)expert_mid_dim, (int)expert_in_dim,
                                                     (int)n_tokens, (int)n_experts_total,
                                                     (int)n_expert_used, moe_stream);
                        if (rc != 0) {
                            fprintf(stderr, "ds4: ds4_mmq_iq2_xxs_moe_vec (gate) returned %d; falling back\n", rc);
                            goto mmvq_decode_bail;
                        }
                        rc = ds4_mmq_iq2_xxs_moe_vec(up_w, (const float *)x->ptr,
                                                     (const int32_t *)selected->ptr,
                                                     (float *)up->ptr,
                                                     (int)expert_mid_dim, (int)expert_in_dim,
                                                     (int)n_tokens, (int)n_experts_total,
                                                     (int)n_expert_used, moe_stream);
                    }
                }
                if (rc != 0) {
                    fprintf(stderr, "ds4: ds4_mmq_<>_moe_vec (up) returned %d; falling back\n", rc);
                    goto mmvq_decode_bail;
                }
                if (mmvq_prof_ev[1]) (void)cudaEventRecord(mmvq_prof_ev[1], ds4_current_stream());

                /* 2. SwiGLU + clamp + router_weight.  Same kernel as the mmq
                 *    path uses - applies the V4 clamp to gate/up BEFORE silu. */
                {
                    const uint64_t mid_floats = n_assignments * expert_mid_dim;
                    moe_mmq_swiglu_weighted_clamp_kernel<<<(uint32_t)((mid_floats + 255) / 256), 256, 0, ds4_current_stream()>>>(
                        (float *)mid->ptr, /*gate_out_dbg=*/nullptr, /*up_out_dbg=*/nullptr,
                        (const float *)gate->ptr, (const float *)up->ptr,
                        (const float *)weights->ptr,
                        expert_mid_dim, n_tokens, n_expert_used, clamp);
                    if (!cuda_ok(cudaGetLastError(), "mmvq routed_moe swiglu launch")) goto mmvq_decode_bail;
                }
                if (mmvq_prof_ev[2]) (void)cudaEventRecord(mmvq_prof_ev[2], ds4_current_stream());
            }

            /* 3. Down matmul + slot sum.  For V4's top_k=6 shape use the
             *    fused canonical-Q8_1 helper: one quantize of mid and one
             *    launch that accumulates all six selected experts directly
             *    into out[token,row].  This preserves the vec tier's Q8_1
             *    numerics while avoiding ceil(n_assignments/cap) down
             *    launches, the [token,slot,out_dim] down buffer write, and
             *    the separate moe_sum_kernel. */
            if (use_q8k_down_in_vec) {
                const uint32_t midq_blocks = expert_mid_dim / CUDA_QK_K;
                const uint64_t midq_bytes = n_assignments * (uint64_t)midq_blocks * sizeof(cuda_block_q8_K);
                if (expert_mid_dim % CUDA_QK_K == 0u && gate->bytes >= midq_bytes) {
                    cuda_block_q8_K *midq = (cuda_block_q8_K *)gate->ptr;
                    dim3 midq_grid(midq_blocks, n_assignments, 1);
                    q8_K_quantize_kernel<<<midq_grid, 256, 0, ds4_current_stream()>>>(
                        midq, (const float *)mid->ptr, expert_mid_dim, (uint32_t)n_assignments);
                    if (!cuda_ok(cudaGetLastError(), "mmvq q8k down mid quantize launch")) goto mmvq_decode_bail;

                    dim3 sgrid((out_dim + 31u) / 32u, n_tokens, 1);
                    if (!down_is_q2k) {
                        moe_down_q4K_sum6_nt_qwarp32_kernel<<<sgrid, 256, 0, ds4_current_stream()>>>(
                            (float *)out->ptr,
                            down_w,
                            midq,
                            (const int32_t *)selected->ptr,
                            down_expert_bytes,
                            down_row_bytes,
                            midq_blocks,
                            out_dim,
                            n_tokens);
                    } else {
                        moe_down_sum6_nt_qwarp32_kernel<<<sgrid, 256, 0, ds4_current_stream()>>>(
                            (float *)out->ptr,
                            down_w,
                            midq,
                            (const int32_t *)selected->ptr,
                            down_expert_bytes,
                            down_row_bytes,
                            midq_blocks,
                            out_dim,
                            n_tokens);
                    }
                    if (!cuda_ok(cudaGetLastError(), "mmvq q8k down/sum launch")) goto mmvq_decode_bail;
                    down_sum_fused = 1;
                } else {
                    fprintf(stderr, "ds4: DS4_CUDA_MOE_Q8K_DOWN_IN_VEC requested but scratch/shape invalid; falling back to Q8_1 down\n");
                }
            } else if (use_q81_fused_moe && n_expert_used == 6u) {
                if (!down_is_q2k) {
                    rc = ds4_mmq_q4_K_moe_down_sum6_vec(down_w, (const float *)mid->ptr,
                                                        (const int32_t *)selected->ptr,
                                                        (float *)out->ptr,
                                                        (int)out_dim, (int)expert_mid_dim,
                                                        (int)n_tokens, (int)n_experts_total,
                                                        (int)n_expert_used, moe_stream);
                } else {
                    rc = ds4_mmq_q2_K_moe_down_sum6_vec(down_w, (const float *)mid->ptr,
                                                        (const int32_t *)selected->ptr,
                                                        (float *)out->ptr,
                                                        (int)out_dim, (int)expert_mid_dim,
                                                        (int)n_tokens, (int)n_experts_total,
                                                        (int)n_expert_used, moe_stream);
                }
                if (rc == 0) {
                    down_sum_fused = 1;
                } else {
                    fprintf(stderr, "ds4: ds4_mmq_<>_moe_down_sum6_vec returned %d; falling back to unfused down\n", rc);
                }
            }
            if (down_sum_fused) {
                if (mmvq_prof_ev[3]) (void)cudaEventRecord(mmvq_prof_ev[3], ds4_current_stream());
                if (mmvq_prof_ev[4]) (void)cudaEventRecord(mmvq_prof_ev[4], ds4_current_stream());
            }
            if (!down_sum_fused) {
                /* Same reinterpretation trick the mmq path uses: treat each
                 * (token, slot) pair as a separate "token" with one expert.
                 * FD Inc2a: n_assignments may exceed one launch's column cap;
                 * ds4_mmq_moe_vec_impl splits the column dim internally. */
                if (!down_is_q2k) {
                    rc = ds4_mmq_q4_K_moe_vec(down_w, (const float *)mid->ptr,
                                              (const int32_t *)selected->ptr,
                                              (float *)down->ptr,
                                              (int)out_dim, (int)expert_mid_dim,
                                              (int)n_assignments, (int)n_experts_total,
                                              /*n_expert_used=*/1, moe_stream);
                } else {
                    /* M2 moe-down: aligned row-pair-SoA twin of the raw vec
                     * path, bit-identical outputs (proto_m2_q2k.cu 240/240 +
                     * capture/replay; 214 GB/s vs 154 raw on the proto rig).
                     * Any failure falls through to the raw vec entry, whose
                     * down_w resolves to the plain mmap pointer when the raw
                     * range was excluded from the upload. */
                    rc = -1;
                    if (down_q2k_aligned && cuda_moe_q2k_aligned_enabled()) {
                        rc = ds4_mmq_q2_K_aligned_moe_vec(down_q2k_aligned,
                                                          (const float *)mid->ptr,
                                                          (const int32_t *)selected->ptr,
                                                          (float *)down->ptr,
                                                          (int)out_dim, (int)expert_mid_dim,
                                                          (int)n_assignments, (int)n_total_expert,
                                                          /*n_expert_used=*/1, moe_stream);
                        if (rc == 0) {
                            static int logged = 0;
                            if (!logged) {
                                logged = 1;
                                fprintf(stderr, "ds4: M2 Q2K aligned moe-down active\n");
                            }
                        } else {
                            fprintf(stderr, "ds4: ds4_mmq_q2_K_aligned_moe_vec returned %d; using raw vec path\n", rc);
                        }
                    }
                    if (rc != 0) {
                        rc = ds4_mmq_q2_K_moe_vec(down_w, (const float *)mid->ptr,
                                                  (const int32_t *)selected->ptr,
                                                  (float *)down->ptr,
                                                  (int)out_dim, (int)expert_mid_dim,
                                                  (int)n_assignments, (int)n_experts_total,
                                                  /*n_expert_used=*/1, moe_stream);
                    }
                }
                if (rc != 0) {
                    fprintf(stderr, "ds4: ds4_mmq_<>_moe_vec (down) returned %d; falling back\n", rc);
                    goto mmvq_decode_bail;
                }
                if (mmvq_prof_ev[3]) (void)cudaEventRecord(mmvq_prof_ev[3], ds4_current_stream());

                /* 4. Sum across n_expert_used dim - same kernel as the mmq
                 *    path.  Only needed when fused down+sum is unavailable. */
                {
                    uint64_t n = (uint64_t)n_tokens * out_dim;
                    moe_sum_kernel<<<(uint32_t)((n + 255) / 256), 256, 0, ds4_current_stream()>>>(
                        (float *)out->ptr, (const float *)down->ptr,
                        out_dim, n_expert_used, n_tokens, /*guard_nonfinite=*/1);
                    if (!cuda_ok(cudaGetLastError(), "mmvq routed_moe sum launch")) goto mmvq_decode_bail;
                }
                if (mmvq_prof_ev[4]) (void)cudaEventRecord(mmvq_prof_ev[4], ds4_current_stream());
            }
            moe_lite_end(lite_slot, moe_stream ? moe_stream : ds4_current_stream());
            if (mmvq_prof_ev[4]) {
                if (cudaEventSynchronize(mmvq_prof_ev[4]) == cudaSuccess) {
                    float ms_gateup = 0.0f, ms_swiglu = 0.0f, ms_down = 0.0f, ms_sum = 0.0f, ms_total = 0.0f;
                    (void)cudaEventElapsedTime(&ms_gateup, mmvq_prof_ev[0], mmvq_prof_ev[1]);
                    (void)cudaEventElapsedTime(&ms_swiglu, mmvq_prof_ev[1], mmvq_prof_ev[2]);
                    (void)cudaEventElapsedTime(&ms_down, mmvq_prof_ev[2], mmvq_prof_ev[3]);
                    (void)cudaEventElapsedTime(&ms_sum, mmvq_prof_ev[3], mmvq_prof_ev[4]);
                    (void)cudaEventElapsedTime(&ms_total, mmvq_prof_ev[0], mmvq_prof_ev[4]);
                    fprintf(stderr,
                            "ds4: CUDA MoE mmvq profile tokens=%u assignments=%llu q4k=%u q81_fused=%u pair_raw=%u q8k_gate=%u q8k_down=%u gateup=%.3f swiglu=%.3f down=%.3f sum=%.3f total=%.3f ms\n",
                            n_tokens, (unsigned long long)n_assignments, q4k_path,
                            use_q81_fused_moe, use_pair_raw_vec, use_q8k_gate_in_vec, use_q8k_down_in_vec,
                            ms_gateup, ms_swiglu, ms_down, ms_sum, ms_total);
                }
                for (uint32_t i = 0; i < 5u; i++) {
                    (void)cudaEventDestroy(mmvq_prof_ev[i]);
                    mmvq_prof_ev[i] = NULL;
                }
            }
            /* Step 8: if we were capturing, finalize the graph and replay
             * it.  cudaStreamEndCapture builds the graph object; the
             * captured kernels have NOT executed yet (stream capture
             * records but doesn't run).  cudaGraphInstantiate builds the
             * exec; cudaGraphLaunch fires it.  Subsequent calls with the
             * same key replay via cudaGraphLaunch at the top of this
             * branch, avoiding the ~8 per-kernel CPU<->driver round
             * trips. */
            if (graph_capturing && graph_slot) {
                cudaGraph_t graph;
                cudaError_t ge = cudaStreamEndCapture(moe_stream, &graph);
                graph_capturing = 0;
                ds4_capture_set_stream((cudaStream_t)0);  /* restore: capture done */
                if (ge == cudaSuccess) {
                    cudaGraphExec_t exec;
                    ge = cuda_graph_instantiate_noted(&exec, graph,
                                                      &graph_slot->exec_bytes);
                    if (ge == cudaSuccess) {
                        graph_slot->exec = exec;
                        graph_slot->valid = 1;
                        graph_slot->hits = 0;
                        /* Execute the just-captured graph for THIS call.
                         * Capture itself does not run the kernels; we must
                         * launch the exec to actually do the work. */
                        ds4_cuda_moe_stream_sync_pre(moe_stream);
                        ge = cudaGraphLaunch(exec, moe_stream);
                        if (ge != cudaSuccess) {
                            fprintf(stderr, "ds4: cudaGraphLaunch (first) failed: %s\n",
                                    cudaGetErrorString(ge));
                        }
                    } else {
                        fprintf(stderr, "ds4: cudaGraphInstantiate failed: %s; graphs disabled this layer\n",
                                cudaGetErrorString(ge));
                    }
                    cudaGraphDestroy(graph);
                } else {
                    fprintf(stderr, "ds4: cudaStreamEndCapture failed: %s\n",
                            cudaGetErrorString(ge));
                }
            }
            /* R3 inner-bypass (Step 6 hardening): skip cross-stream sync
             * when outer per-layer capture is active (outer end_or_commit
             * handles it).  See matching guard at the dense Q8_0 site. */
            if (!ds4_capture_active()) {
                ds4_cuda_moe_stream_sync_post(moe_stream);
            }
            return 1;
        mmvq_decode_bail:
            if (mmvq_prof_ev[0]) {
                for (uint32_t i = 0; i < 5u; i++) {
                    if (mmvq_prof_ev[i]) (void)cudaEventDestroy(mmvq_prof_ev[i]);
                    mmvq_prof_ev[i] = NULL;
                }
            }
            /* Failure inside the mmvq decode branch: end any in-flight
             * capture cleanly (discard the partial graph) before falling
             * through to the mmq path. */
            if (graph_capturing) {
                cudaGraph_t partial;
                cudaError_t ge = cudaStreamEndCapture(0, &partial);
                graph_capturing = 0;
                ds4_capture_set_stream((cudaStream_t)0);  /* restore on bail */
                if (ge == cudaSuccess) {
                    cudaGraphDestroy(partial);
                } else {
                    /* Stream may be left in a bad capture state; log so we
                     * notice but proceed - the mmq fallback will reset. */
                    fprintf(stderr, "ds4: cudaStreamEndCapture (bail) failed: %s\n",
                            cudaGetErrorString(ge));
                }
                graph_capturing = 0;
                if (graph_slot) graph_slot->valid = 0;
            }
            if (small16_vec_active) goto mmq_moe_path;
            goto mmq_moe_fallback;
        }
    }

mmq_moe_path:
    if (ds4_cuda_use_mmq() && n_tokens >= mmq_moe_min_tokens) {
        const uint32_t n_expert_used = n_expert;   /* parameter name is a misnomer; this is top_k */
        const uint32_t n_experts_total = 256u;     /* matches the hardcoded constant at line 11437 */
        const uint64_t n_assignments = (uint64_t)n_tokens * n_expert_used;

        /* Reuse the caller-allocated buffers - all of gate/up/mid/down are
         * already sized to [n_tokens, n_expert_used, *].  See validation
         * block above (lines 11427-11430).  Quant-pair dispatch: IQ2_XXS
         * gate/up + Q2_K down for the V4 Flash configuration, or Q4_K for
         * all three when a Q4_K MoE GGUF is loaded. */
        /* Gate and up are two matmuls over the same activation X and the
         * same routing map.  ds4_mmq_<type>_moe_pair fuses them so the
         * Q8_1 quantize of X and the mm_ids_helper bookkeeping only run
         * once per MoE block (saves 1 quantize + 1 helper launch per
         * layer).  Step 3 of the optimization plan. */
        int rc = -1;
        int fused_done = 0;   /* v0.5 inc-9 F7: fused pipeline handled swiglu+down */
        if (gate_is_q4k) {
            rc = ds4_mmq_q4_K_moe_pair(gate_w, up_w, (const float *)x->ptr,
                                       (const int32_t *)selected->ptr,
                                       (float *)gate->ptr, (float *)up->ptr,
                                       (int)expert_mid_dim, (int)expert_in_dim,
                                       (int)n_tokens, (int)n_experts_total,
                                       (int)n_expert_used,
                                       /*stream=*/ds4_mmq_stream_for_call());
            if (rc != 0) {
                fprintf(stderr, "ds4: ds4_mmq_q4_K_moe_pair (gate+up) returned %d; falling back\n", rc);
                goto mmq_moe_fallback;
            }
        } else if (gate_is_q2k) {
            /* Requant tier: no Q2_K pair kernel yet -- two single launches
             * (one extra X quantize per MoE block vs the fused pair; the
             * drafter block step is ~14% of a spec step, measured before
             * fusing further). */
            rc = ds4_mmq_q2_K_moe(gate_w, (const float *)x->ptr,
                                  (const int32_t *)selected->ptr,
                                  (float *)gate->ptr,
                                  (int)expert_mid_dim, (int)expert_in_dim,
                                  (int)n_tokens, (int)n_experts_total,
                                  (int)n_expert_used,
                                  /*stream=*/ds4_mmq_stream_for_call());
            if (rc == 0) {
                rc = ds4_mmq_q2_K_moe(up_w, (const float *)x->ptr,
                                      (const int32_t *)selected->ptr,
                                      (float *)up->ptr,
                                      (int)expert_mid_dim, (int)expert_in_dim,
                                      (int)n_tokens, (int)n_experts_total,
                                      (int)n_expert_used,
                                      /*stream=*/ds4_mmq_stream_for_call());
            }
            if (rc != 0) {
                fprintf(stderr, "ds4: ds4_mmq_q2_K_moe (gate/up) returned %d; falling back\n", rc);
                goto mmq_moe_fallback;
            }
        } else {
            /* v0.5 inc-9 (F7, derived from Marco Palaferri's GB10 fork,
             * MIT `910501e`): complete fused MoE prefill over the aligned
             * artifacts.  ONE expert-major schedule serves gate/up AND
             * down; the direct tier keeps the gate/up accumulators in
             * registers and quantizes clamp+SwiGLU+route-weight straight
             * into the down Q8_1 D2S6 blocks - the gate/up/mid buffers
             * this path no longer materializes become its caller-owned
             * scratch (LOGICAL segment sizes only: an owning arena's
             * capacity would let the overlap guard falsely cover the
             * adjacent views).  Bit-exact vs the classic chain below:
             * per-column MMA fold order is tile-width-invariant, the
             * epilogue quantize replicates quantize_mmq_q8_1's D2S6
             * reduction op-for-op, and the down column permutation only
             * reorders independent dot products.  Falls back tier-by-tier
             * (direct -> shared-schedule materialized -> classic).
             * DS4_CUDA_NO_MOE_FUSED_PREFILL=1 escapes; dump runs
             * (DS4_METAL_GRAPH_DUMP_PREFIX) materialize intermediates. */
            static int fused_prefill_want = -1;
            if (fused_prefill_want < 0) {
                fused_prefill_want =
                    getenv("DS4_CUDA_NO_MOE_FUSED_PREFILL") == NULL &&
                    getenv("DS4_METAL_GRAPH_DUMP_PREFIX") == NULL;
            }
            if (fused_prefill_want && down_is_q2k &&
                gate_iq2_aligned && up_iq2_aligned && down_q2k_aligned &&
                cuda_moe_iq2_aligned_enabled() &&
                cuda_mmq_aligned_tiles_enabled() &&
                cuda_moe_q2k_aligned_enabled()) {
                const uint64_t seg_bytes =
                    n_assignments * (uint64_t)expert_mid_dim * sizeof(float);
                rc = -1;
                if (up->bytes >= seg_bytes && gate->bytes >= seg_bytes &&
                    mid->bytes >= seg_bytes) {
                    /* p5c: the producer-quantized ffn_norm q8, when
                     * registered for this exact (buffer, rows, K), skips
                     * the fused path's own compact input quantize. */
                    size_t moe_q8_bytes = 0;
                    const void *moe_q8 = cuda_norm_q8_lookup(
                            x->ptr, n_tokens, expert_in_dim, &moe_q8_bytes);
                    rc = ds4_mmq_iq2_xxs_q2_K_moe_fused_direct_soa(
                        gate_iq2_aligned, up_iq2_aligned, down_q2k_aligned,
                        (const float *)x->ptr, (const int32_t *)selected->ptr,
                        (const float *)weights->ptr,
                        up->ptr, (size_t)seg_bytes,
                        gate->ptr, (size_t)seg_bytes,
                        mid->ptr, (size_t)seg_bytes,
                        moe_q8, moe_q8_bytes,
                        (float *)down->ptr,
                        (int)expert_mid_dim, (int)expert_in_dim, (int)out_dim,
                        (int)n_tokens, (int)n_experts_total, (int)n_expert_used,
                        clamp, ds4_mmq_stream_for_call());
                }
                if (rc == 0) {
                    fused_done = 1;
                    static int fused_direct_notice = 0;
                    if (!fused_direct_notice) {
                        fused_direct_notice = 1;
                        fprintf(stderr, "ds4: fused MoE gateup+swiglu+q8 D2R prefill engaged (inc-9 F7 direct)\n");
                    }
                } else {
                    const int direct_rc = rc;
                    rc = ds4_mmq_iq2_xxs_q2_K_moe_fused_soa(
                        gate_iq2_aligned, up_iq2_aligned, down_q2k_aligned,
                        (const float *)x->ptr, (const int32_t *)selected->ptr,
                        (const float *)weights->ptr,
                        (float *)gate->ptr, (float *)up->ptr,
                        (float *)mid->ptr, (float *)down->ptr,
                        (int)expert_mid_dim, (int)expert_in_dim, (int)out_dim,
                        (int)n_tokens, (int)n_experts_total, (int)n_expert_used,
                        clamp, ds4_mmq_stream_for_call());
                    if (rc == 0) {
                        fused_done = 1;
                        static int fused_tier1_notice = 0;
                        if (!fused_tier1_notice) {
                            fused_tier1_notice = 1;
                            fprintf(stderr, "ds4: fused MoE prefill on the materialized tier (inc-9 F7 shared-schedule; direct rc=%d)\n", direct_rc);
                        }
                    } else {
                        static int fused_fallback_notice = 0;
                        if (!fused_fallback_notice) {
                            fused_fallback_notice = 1;
                            fprintf(stderr, "ds4: fused MoE prefill unavailable (direct rc=%d tier1 rc=%d tokens=%u); using the classic chain\n",
                                    direct_rc, rc, n_tokens);
                        }
                    }
                }
            }
            /* P4 Inc3: with the aligned gate/up artifacts present, the mmq
             * tile loader reads the SoA sections directly (bit-identical
             * tiles, no per-layer derepack, no scratch VRAM).  On failure or
             * DS4_MMQ_ALIGNED_TILES=0, the M1-Inc2b derepack-scratch path
             * below remains the fallback. */
            int pair_done = 0;
            if (!fused_done && gate_iq2_aligned && up_iq2_aligned && cuda_moe_iq2_aligned_enabled() &&
                cuda_mmq_aligned_tiles_enabled()) {
                rc = ds4_mmq_iq2_xxs_moe_pair_soa(gate_iq2_aligned, up_iq2_aligned,
                                                  (const float *)x->ptr,
                                                  (const int32_t *)selected->ptr,
                                                  (float *)gate->ptr, (float *)up->ptr,
                                                  (int)expert_mid_dim, (int)expert_in_dim,
                                                  (int)n_tokens, (int)n_experts_total,
                                                  (int)n_expert_used,
                                                  /*stream=*/ds4_mmq_stream_for_call());
                pair_done = (rc == 0);
                if (!pair_done) {
                    fprintf(stderr, "ds4: ds4_mmq_iq2_xxs_moe_pair_soa (gate+up) returned %d; trying derepack path\n", rc);
                }
            }
            if (!fused_done && !pair_done) {
            /* M1-Inc2b: when the raw gate/up spans were excluded from the
             * upload (--repack-iq2-aligned), gate_w/up_w point at the client
             * mmap; de-repack the aligned artifacts into the persistent
             * device scratch instead (same stream as the consuming pair
             * launch, so ordering is free).  NULL keeps the mmap fallback. */
            const char *gate_mmq = gate_w;
            const char *up_mmq = up_w;
            if (gate_iq2_aligned && up_iq2_aligned && cuda_moe_iq2_aligned_enabled()) {
                const char *g = cuda_moe_iq2_derepack_scratch(
                    0, gate_iq2_aligned, gate_offset, gate_bytes,
                    expert_mid_dim, expert_in_dim, n_total_expert,
                    ds4_mmq_stream_for_call());
                const char *u = g ? cuda_moe_iq2_derepack_scratch(
                    1, up_iq2_aligned, up_offset, gate_bytes,
                    expert_mid_dim, expert_in_dim, n_total_expert,
                    ds4_mmq_stream_for_call()) : NULL;
                if (g && u) { gate_mmq = g; up_mmq = u; }
            }
            rc = ds4_mmq_iq2_xxs_moe_pair(gate_mmq, up_mmq, (const float *)x->ptr,
                                          (const int32_t *)selected->ptr,
                                          (float *)gate->ptr, (float *)up->ptr,
                                          (int)expert_mid_dim, (int)expert_in_dim,
                                          (int)n_tokens, (int)n_experts_total,
                                          (int)n_expert_used,
                                          /*stream=*/ds4_mmq_stream_for_call());
            if (rc != 0) {
                fprintf(stderr, "ds4: ds4_mmq_iq2_xxs_moe_pair (gate+up) returned %d; falling back\n", rc);
                goto mmq_moe_fallback;
            }
            }
        }
        if (!fused_done) {
            const uint64_t mid_floats = n_assignments * expert_mid_dim;
            moe_mmq_swiglu_weighted_clamp_kernel<<<(uint32_t)((mid_floats + 255) / 256), 256, 0, ds4_current_stream()>>>(
                (float *)mid->ptr, /*gate_out_dbg=*/nullptr, /*up_out_dbg=*/nullptr,
                (const float *)gate->ptr, (const float *)up->ptr,
                (const float *)weights->ptr,
                expert_mid_dim, n_tokens, n_expert_used, clamp);
            if (!cuda_ok(cudaGetLastError(), "mmq routed_moe swiglu launch")) goto mmq_moe_fallback;
        }
        /* Down matmul: treat each (token, slot) pair as a single-expert
         * "token" of length expert_mid_dim.  selected is contiguous int32
         * of length n_tokens * n_expert_used; reinterpreting it as
         * [n_assignments, 1] gives one expert id per row, which is exactly
         * what ds4_mmq_*_moe with n_expert_used=1 consumes. */
        if (!fused_done && !down_is_q2k) {
            rc = ds4_mmq_q4_K_moe(down_w, (const float *)mid->ptr, (const int32_t *)selected->ptr,
                                  (float *)down->ptr,
                                  (int)out_dim, (int)expert_mid_dim,
                                  (int)n_assignments, (int)n_experts_total, /*n_expert_used=*/1,
                                  /*stream=*/ds4_mmq_stream_for_call());
            if (rc != 0) {
                fprintf(stderr, "ds4: ds4_mmq_q4_K_moe (down) returned %d; falling back\n", rc);
                goto mmq_moe_fallback;
            }
        } else if (!fused_done) {
            /* P4 Inc3: SoA-direct tile loads from the aligned down artifact
             * (see the gate/up branch above); the M2 derepack scratch stays
             * as the fallback. */
            int down_done = 0;
            if (down_q2k_aligned && cuda_moe_q2k_aligned_enabled() &&
                cuda_mmq_aligned_tiles_enabled()) {
                rc = ds4_mmq_q2_K_moe_soa(down_q2k_aligned, (const float *)mid->ptr,
                                          (const int32_t *)selected->ptr,
                                          (float *)down->ptr,
                                          (int)out_dim, (int)expert_mid_dim,
                                          (int)n_assignments, (int)n_experts_total, /*n_expert_used=*/1,
                                          /*stream=*/ds4_mmq_stream_for_call());
                down_done = (rc == 0);
                if (!down_done) {
                    fprintf(stderr, "ds4: ds4_mmq_q2_K_moe_soa (down) returned %d; trying derepack path\n", rc);
                }
            }
            if (!down_done) {
            /* M2 moe-down: when the raw down span was excluded from the
             * upload (--repack-q2k-aligned), down_w points at the client
             * mmap; de-repack the aligned artifact into the persistent
             * device scratch instead (same pattern as the iq2 gate/up
             * scratch above).  NULL keeps the mmap fallback. */
            const char *down_mmq = down_w;
            if (down_q2k_aligned && cuda_moe_q2k_aligned_enabled()) {
                const char *d = cuda_moe_q2k_derepack_scratch(
                    down_q2k_aligned, down_offset, down_bytes,
                    out_dim, expert_mid_dim, n_total_expert,
                    ds4_mmq_stream_for_call());
                if (d) down_mmq = d;
            }
            rc = ds4_mmq_q2_K_moe(down_mmq, (const float *)mid->ptr, (const int32_t *)selected->ptr,
                                  (float *)down->ptr,
                                  (int)out_dim, (int)expert_mid_dim,
                                  (int)n_assignments, (int)n_experts_total, /*n_expert_used=*/1,
                                  /*stream=*/ds4_mmq_stream_for_call());
            if (rc != 0) {
                fprintf(stderr, "ds4: ds4_mmq_q2_K_moe (down) returned %d; falling back\n", rc);
                goto mmq_moe_fallback;
            }
            }
        }
        if (defer_sum) {
            /* v0.5 inc-8 (F5 defer-sum): leave down per-expert unsummed; the
             * caller folds the guarded 6-sum into the HC expand epilogue
             * (bit-exact: same ascending-e isfinite-guarded order). */
            if (out_sum_deferred) *out_sum_deferred = 1;
        } else {
            uint64_t n = (uint64_t)n_tokens * out_dim;
            moe_sum_kernel<<<(uint32_t)((n + 255) / 256), 256, 0, ds4_current_stream()>>>(
                (float *)out->ptr, (const float *)down->ptr,
                out_dim, n_expert_used, n_tokens, /*guard_nonfinite=*/1);
            if (!cuda_ok(cudaGetLastError(), "mmq routed_moe sum launch")) goto mmq_moe_fallback;
        }
        return 1;
    }
mmq_moe_fallback:
    /* Requant tiers: the legacy fallback's kernels are IQ2-LUT / all-Q4_K
     * specific.  The new pairs (Q2_K gate/up; Q4_K gate + Q2_K down) are
     * served by the vec/mmq paths above -- if those declined (MMQ disabled,
     * or a shape they reject), reject the launch rather than run a
     * wrong-layout kernel.  The (16,10) base and (12,12) pairs keep the
     * fallback byte-identical. */
    if (gate_is_q2k || (gate_is_q4k && down_is_q2k)) return 0;
    int ok = 1;
    const uint32_t xq_blocks = expert_in_dim / CUDA_QK_K;
    const uint32_t midq_blocks = expert_mid_dim / CUDA_QK_K;
    const uint64_t xq_count = (uint64_t)n_tokens * xq_blocks;
    const uint64_t midq_count = (uint64_t)n_tokens * n_expert * midq_blocks;
    const uint64_t xq_bytes = xq_count * sizeof(cuda_block_q8_K);
    const uint64_t midq_bytes = midq_count * sizeof(cuda_block_q8_K);
    if (down->bytes >= xq_bytes && gate->bytes >= midq_bytes) {
        cuda_block_q8_K *xq = (cuda_block_q8_K *)down->ptr;
        cuda_block_q8_K *midq = (cuda_block_q8_K *)gate->ptr;
        /* Step 7 task #34: never create the profiling events under an
         * active layer-graph capture.  The cudaEventRecord(..., 0) calls
         * downstream record onto the legacy default stream; under capture
         * that either escapes the capture or aborts it.  prof_ev stays
         * all-NULL so every `if (prof_ev[i])` event-record is a no-op. */
        const uint32_t profile_moe = (getenv("DS4_CUDA_MOE_PROFILE") != NULL)
                                     && !ds4_capture_active();
        cudaEvent_t prof_ev[7] = {NULL, NULL, NULL, NULL, NULL, NULL, NULL};
        if (profile_moe) {
            for (uint32_t i = 0; i < 7u; i++) {
                if (cudaEventCreate(&prof_ev[i]) != cudaSuccess) {
                    for (uint32_t j = 0; j < i; j++) (void)cudaEventDestroy(prof_ev[j]);
                    memset(prof_ev, 0, sizeof(prof_ev));
                    break;
                }
            }
            if (prof_ev[0]) (void)cudaEventRecord(prof_ev[0], 0);
        }
        const uint32_t pair_count = n_tokens * n_expert;
        const uint32_t small16_direct_enabled =
            getenv("DS4_CUDA_MOE_SMALL16_DIRECT") != NULL;
        const uint32_t use_direct_gate_up_small16 =
            small16_direct_enabled &&
            small16_scope_active &&
            small16_max_tokens != 0u &&
            n_tokens > 8u && n_tokens <= small16_max_tokens &&
            n_expert == 6u &&
            getenv("DS4_CUDA_MOE_NO_GATE_UP_SMALL16") == NULL;
        const uint32_t use_direct_gate_up_n2 =
            n_tokens == 2u && n_expert == 6u &&
            xq_blocks <= 16u &&
            getenv("DS4_CUDA_MOE_NO_GATE_UP_N2_LUT") == NULL;
        const uint32_t use_direct_gate_up = use_direct_gate_up_n2 || use_direct_gate_up_small16;
        const uint32_t use_sorted_pairs = n_tokens > 1u && !use_direct_gate_up;
        const uint32_t use_expert_tiles = use_sorted_pairs && getenv("DS4_CUDA_MOE_NO_EXPERT_TILES") == NULL;
        const uint32_t expert_tile_m = getenv("DS4_CUDA_MOE_TILE4") ? 4u : 8u;
        const uint32_t write_gate_up = getenv("DS4_CUDA_MOE_WRITE_GATE_UP") != NULL;
        const uint32_t use_p2_sorted = use_sorted_pairs && getenv("DS4_CUDA_MOE_NO_P2") == NULL;
        /* atomicAdd(down_out) accumulates experts in nondeterministic order (finite,
         * 1-ULP, never NaN, gated n_tokens>=128).  Determinism mode forces the
         * fixed-order non-atomic per-pair path instead. */
        const uint32_t use_atomic_down = use_expert_tiles && !ds4_cuda_deterministic() &&
            (getenv("DS4_CUDA_MOE_ATOMIC_DOWN") != NULL ||
             (n_tokens >= 128u && getenv("DS4_CUDA_MOE_NO_ATOMIC_DOWN") == NULL));
        const uint32_t use_gate_row2048 = use_expert_tiles && expert_tile_m == 8u &&
            (getenv("DS4_CUDA_MOE_GATE_ROW2048") != NULL ||
             getenv("DS4_CUDA_MOE_GATE_ROW256") != NULL ||
             getenv("DS4_CUDA_MOE_GATE_ROW128") != NULL ||
             (n_tokens >= 128u &&
              getenv("DS4_CUDA_MOE_NO_GATE_ROW2048") == NULL &&
              getenv("DS4_CUDA_MOE_NO_GATE_ROW256") == NULL &&
              getenv("DS4_CUDA_MOE_NO_GATE_ROW128") == NULL));
        const uint32_t use_down_tile16 = use_atomic_down && expert_tile_m == 8u &&
            n_tokens >= 128u && getenv("DS4_CUDA_MOE_NO_DOWN_TILE16") == NULL;
        const uint32_t use_decode_lut_gate =
            n_tokens == 1u && xq_blocks <= 16u &&
            getenv("DS4_CUDA_MOE_NO_DECODE_LUT_GATE") == NULL;
        const uint32_t use_gate_up_lut =
            !q4k_path &&
            (use_decode_lut_gate ||
             (use_direct_gate_up && xq_blocks <= 16u &&
              getenv("DS4_CUDA_MOE_NO_GATE_UP_SMALL16_LUT") == NULL));
        const uint32_t gate_row_span =
            getenv("DS4_CUDA_MOE_GATE_ROW512") != NULL ? 512u :
            getenv("DS4_CUDA_MOE_GATE_ROW2048") != NULL ? 2048u : 1024u;
        const uint32_t down_row_span =
            getenv("DS4_CUDA_MOE_DOWN_ROW512") != NULL ? 512u :
            getenv("DS4_CUDA_MOE_DOWN_ROW1024") != NULL ? 1024u : 2048u;
        const uint32_t use_down_row2048 = use_atomic_down && expert_tile_m == 8u &&
            (getenv("DS4_CUDA_MOE_DOWN_ROW2048") != NULL ||
             getenv("DS4_CUDA_MOE_DOWN_ROW256") != NULL ||
             getenv("DS4_CUDA_MOE_DOWN_ROW128") != NULL ||
             getenv("DS4_CUDA_MOE_DOWN_ROW64") != NULL ||
             (use_down_tile16 &&
              getenv("DS4_CUDA_MOE_NO_DOWN_ROW2048") == NULL &&
              getenv("DS4_CUDA_MOE_NO_DOWN_ROW256") == NULL &&
              getenv("DS4_CUDA_MOE_NO_DOWN_ROW128") == NULL &&
              getenv("DS4_CUDA_MOE_NO_DOWN_ROW64") == NULL));
        const uint32_t use_direct_down_sum6_n2 =
            n_tokens == 2u && n_expert == 6u &&
            getenv("DS4_CUDA_MOE_NO_DIRECT_DOWN_SUM6_N2") == NULL &&
            getenv("DS4_CUDA_MOE_NO_DIRECT_DOWN_SUM6") == NULL;
        const uint32_t use_direct_down_sum6_small16 =
            small16_direct_enabled &&
            small16_scope_active &&
            small16_max_tokens != 0u &&
            n_tokens > 8u && n_tokens <= small16_max_tokens &&
            n_expert == 6u &&
            getenv("DS4_CUDA_MOE_NO_DIRECT_DOWN_SUM6_SMALL16") == NULL &&
            getenv("DS4_CUDA_MOE_NO_DIRECT_DOWN_SUM6") == NULL;
        const uint32_t use_direct_down_sum6 =
            ((n_tokens == 1u && n_expert == 6u) ||
             use_direct_down_sum6_n2 ||
             use_direct_down_sum6_small16) &&
            getenv("DS4_CUDA_MOE_NO_DIRECT_DOWN_SUM6") == NULL;
        /* Q4_K fallback kernels are only implemented for the direct top-k=6
         * shape.  Larger Q4_K MoE still belongs to the MMQ path. */
        if (q4k_path && (!(use_decode_lut_gate || use_direct_gate_up) || !use_direct_down_sum6)) {
            return 0;
        }
        uint32_t *sorted_pairs = NULL;
        uint32_t *sorted_offsets = NULL;
        uint32_t *sorted_counts = NULL;
        uint32_t *tile_total = NULL;
        uint32_t *tile_experts = NULL;
        uint32_t *tile_starts = NULL;
        uint32_t *tile16_total = NULL;
        uint32_t *tile16_experts = NULL;
        uint32_t *tile16_starts = NULL;
        uint32_t tile_capacity = 0;
        uint32_t tile16_capacity = 0;
        dim3 xq_grid(xq_blocks, n_tokens, 1);
        q8_K_quantize_kernel<<<xq_grid, 256, 0, ds4_current_stream()>>>(xq, (const float *)x->ptr, expert_in_dim, n_tokens);
        ok = cuda_ok(cudaGetLastError(), "routed_moe x quantize launch");
        if (prof_ev[1]) (void)cudaEventRecord(prof_ev[1], 0);
        if (ok && use_sorted_pairs) {
            const uint64_t counts_bytes = 256ull * sizeof(uint32_t);
            const uint64_t offsets_bytes = 257ull * sizeof(uint32_t);
            const uint64_t cursors_bytes = 256ull * sizeof(uint32_t);
            const uint64_t sorted_bytes = (uint64_t)pair_count * sizeof(uint32_t);
            tile_capacity = (pair_count + expert_tile_m - 1u) / expert_tile_m + 256u;
            tile16_capacity = use_down_tile16 ? ((pair_count + 15u) / 16u + 256u) : 0u;
            const uint64_t tile_offsets_bytes = 257ull * sizeof(uint32_t);
            const uint64_t tile_total_bytes = sizeof(uint32_t);
            const uint64_t tile_experts_bytes = (uint64_t)tile_capacity * sizeof(uint32_t);
            const uint64_t tile_starts_bytes = (uint64_t)tile_capacity * sizeof(uint32_t);
            const uint64_t tile16_offsets_bytes = use_down_tile16 ? 257ull * sizeof(uint32_t) : 0u;
            const uint64_t tile16_total_bytes = use_down_tile16 ? sizeof(uint32_t) : 0u;
            const uint64_t tile16_experts_bytes = (uint64_t)tile16_capacity * sizeof(uint32_t);
            const uint64_t tile16_starts_bytes = (uint64_t)tile16_capacity * sizeof(uint32_t);
            const uint64_t tile_offsets_off = counts_bytes + offsets_bytes + cursors_bytes + sorted_bytes;
            const uint64_t tile_total_off = tile_offsets_off + tile_offsets_bytes;
            const uint64_t tile_experts_off = tile_total_off + tile_total_bytes;
            const uint64_t tile_starts_off = tile_experts_off + tile_experts_bytes;
            const uint64_t tile16_offsets_off = tile_starts_off + tile_starts_bytes;
            const uint64_t tile16_total_off = tile16_offsets_off + tile16_offsets_bytes;
            const uint64_t tile16_experts_off = tile16_total_off + tile16_total_bytes;
            const uint64_t tile16_starts_off = tile16_experts_off + tile16_experts_bytes;
            const uint64_t scratch_bytes = tile16_starts_off + tile16_starts_bytes;
            uint8_t *scratch = (uint8_t *)cuda_tmp_alloc(scratch_bytes,
                                                         "routed_moe sorted pairs");
            if (!scratch) {
                ok = 0;
            } else {
                uint32_t *counts = (uint32_t *)scratch;
                uint32_t *offsets = (uint32_t *)(scratch + counts_bytes);
                uint32_t *cursors = (uint32_t *)(scratch + counts_bytes + offsets_bytes);
                sorted_pairs = (uint32_t *)(scratch + counts_bytes + offsets_bytes + cursors_bytes);
                sorted_offsets = offsets;
                sorted_counts = counts;
                uint32_t *tile_offsets = (uint32_t *)(scratch + tile_offsets_off);
                tile_total = (uint32_t *)(scratch + tile_total_off);
                tile_experts = (uint32_t *)(scratch + tile_experts_off);
                tile_starts = (uint32_t *)(scratch + tile_starts_off);
                uint32_t *tile16_offsets = use_down_tile16 ? (uint32_t *)(scratch + tile16_offsets_off) : NULL;
                tile16_total = use_down_tile16 ? (uint32_t *)(scratch + tile16_total_off) : NULL;
                tile16_experts = use_down_tile16 ? (uint32_t *)(scratch + tile16_experts_off) : NULL;
                tile16_starts = use_down_tile16 ? (uint32_t *)(scratch + tile16_starts_off) : NULL;
                ok = cuda_ok(cudaMemset(counts, 0, counts_bytes), "routed_moe sorted counts clear");
                if (ok) {
                    moe_count_sorted_pairs_kernel<<<(pair_count + 255u) / 256u, 256, 0, ds4_current_stream()>>>(
                        counts,
                        (const int32_t *)selected->ptr,
                        pair_count);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe sorted count launch");
                }
                if (ok) {
                    moe_prefix_sorted_pairs_kernel<<<1, 1, 0, ds4_current_stream()>>>(offsets, cursors, counts);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe sorted prefix launch");
                }
                if (ok) {
                    if (ds4_cuda_deterministic())
                        moe_scatter_sorted_pairs_det_kernel<<<1, 1, 0, ds4_current_stream()>>>(
                            sorted_pairs, cursors, (const int32_t *)selected->ptr, pair_count);
                    else
                        moe_scatter_sorted_pairs_kernel<<<(pair_count + 255u) / 256u, 256, 0, ds4_current_stream()>>>(
                            sorted_pairs, cursors, (const int32_t *)selected->ptr, pair_count);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe sorted scatter launch");
                }
                if (ok && use_expert_tiles) {
                    moe_build_expert_tile_offsets_kernel<<<1, 1, 0, ds4_current_stream()>>>(tile_offsets, tile_total, counts, expert_tile_m);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe expert tile offsets launch");
                }
                if (ok && use_expert_tiles) {
                    moe_build_expert_tiles_kernel<<<1, 256, 0, ds4_current_stream()>>>(tile_experts, tile_starts, tile_offsets, counts, expert_tile_m);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe expert tiles launch");
                }
                if (ok && use_expert_tiles && use_down_tile16) {
                    moe_build_expert_tile_offsets_kernel<<<1, 1, 0, ds4_current_stream()>>>(tile16_offsets, tile16_total, counts, 16u);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe expert tile16 offsets launch");
                }
                if (ok && use_expert_tiles && use_down_tile16) {
                    moe_build_expert_tiles_kernel<<<1, 256, 0, ds4_current_stream()>>>(tile16_experts, tile16_starts, tile16_offsets, counts, 16u);
                    ok = cuda_ok(cudaGetLastError(), "routed_moe expert tile16 launch");
                }
            }
        }
        if (prof_ev[2]) (void)cudaEventRecord(prof_ev[2], 0);
        if (ok) {
            dim3 mgrid((expert_mid_dim + 31u) / 32u, n_tokens * n_expert, 1);
            if (ok && sorted_pairs && use_expert_tiles && sorted_offsets && sorted_counts && tile_total && tile_experts && tile_starts) {
                if (use_gate_row2048) {
                    if (gate_row_span == 512u) {
                        dim3 tgrid((expert_mid_dim + 511u) / 512u, tile_capacity, 1);
                        moe_gate_up_mid_expert_tile8_rowspan_kernel<512><<<tgrid, 256, 0, ds4_current_stream()>>>(
                            (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                            gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                            tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                            gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                            write_gate_up, clamp);
                    } else if (gate_row_span == 1024u) {
                        dim3 tgrid((expert_mid_dim + 1023u) / 1024u, tile_capacity, 1);
                        moe_gate_up_mid_expert_tile8_rowspan_kernel<1024><<<tgrid, 256, 0, ds4_current_stream()>>>(
                            (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                            gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                            tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                            gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                            write_gate_up, clamp);
                    } else {
                        dim3 tgrid((expert_mid_dim + 2047u) / 2048u, tile_capacity, 1);
                        moe_gate_up_mid_expert_tile8_row2048_kernel<<<tgrid, 256, 0, ds4_current_stream()>>>(
                            (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                            gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                            tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                            gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                            write_gate_up, clamp);
                    }
                } else if (expert_tile_m == 8u) {
                    dim3 tgrid((expert_mid_dim + 31u) / 32u, tile_capacity, 1);
                    moe_gate_up_mid_expert_tile8_row32_kernel<<<tgrid, 256, 0, ds4_current_stream()>>>(
                        (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                        gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                        tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                        gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                        write_gate_up, clamp);
                } else {
                    dim3 tgrid((expert_mid_dim + 31u) / 32u, tile_capacity, 1);
                    moe_gate_up_mid_expert_tile4_row32_kernel<<<tgrid, 256, 0, ds4_current_stream()>>>(
                        (float *)gate->ptr, (float *)up->ptr, (float *)mid->ptr,
                        gate_w, up_w, xq, sorted_pairs, sorted_offsets, sorted_counts,
                        tile_total, tile_experts, tile_starts, (const float *)weights->ptr,
                        gate_expert_bytes, gate_row_bytes, xq_blocks, expert_mid_dim, n_expert,
                        write_gate_up, clamp);
                }
            } else if (ok && sorted_pairs && use_p2_sorted) {
                dim3 p2_mgrid((expert_mid_dim + 15u) / 16u, (pair_count + 1u) / 2u, 1);
                moe_gate_up_mid_sorted_p2_qwarp32_kernel<<<p2_mgrid, 256, 0, ds4_current_stream()>>>(
                    (float *)gate->ptr,
                    (float *)up->ptr,
                    (float *)mid->ptr,
                    gate_w,
                    up_w,
                    xq,
                    sorted_pairs,
                    (const int32_t *)selected->ptr,
                    (const float *)weights->ptr,
                    gate_expert_bytes,
                    gate_row_bytes,
                    xq_blocks,
                    expert_mid_dim,
                    n_expert,
                    pair_count,
                    clamp);
            } else if (ok && sorted_pairs) {
                moe_gate_up_mid_sorted_qwarp32_kernel<<<mgrid, 256, 0, ds4_current_stream()>>>(
                    (float *)gate->ptr,
                    (float *)up->ptr,
                    (float *)mid->ptr,
                    gate_w,
                    up_w,
                    xq,
                    sorted_pairs,
                    (const int32_t *)selected->ptr,
                    (const float *)weights->ptr,
                    gate_expert_bytes,
                    gate_row_bytes,
                    xq_blocks,
                    expert_mid_dim,
                    n_expert,
                    clamp);
            } else if (ok) {
                dim3 qgrid((expert_mid_dim + 127u) / 128u, n_tokens * n_expert, 1);
                if (q4k_path && (use_decode_lut_gate || use_direct_gate_up)) {
                    moe_gate_up_mid_decode_q4K_qwarp32_kernel<<<qgrid, 256, 0, ds4_current_stream()>>>(
                        (float *)gate->ptr,
                        (float *)up->ptr,
                        (float *)mid->ptr,
                        gate_w,
                        up_w,
                        xq,
                        (const int32_t *)selected->ptr,
                        (const float *)weights->ptr,
                        gate_expert_bytes,
                        gate_row_bytes,
                        xq_blocks,
                        expert_mid_dim,
                        n_expert,
                        write_gate_up,
                        clamp);
                } else if (use_gate_up_lut) {
                    moe_gate_up_mid_decode_lut_qwarp32_kernel<<<qgrid, 256, 0, ds4_current_stream()>>>(
                        (float *)gate->ptr,
                        (float *)up->ptr,
                        (float *)mid->ptr,
                        gate_w,
                        up_w,
                        xq,
                        (const int32_t *)selected->ptr,
                        (const float *)weights->ptr,
                        gate_expert_bytes,
                        gate_row_bytes,
                        xq_blocks,
                        expert_mid_dim,
                        n_expert,
                        write_gate_up,
                        clamp);
                } else {
                    moe_gate_up_mid_qwarp32_kernel<<<qgrid, 256, 0, ds4_current_stream()>>>(
                        (float *)gate->ptr,
                        (float *)up->ptr,
                        (float *)mid->ptr,
                        gate_w,
                        up_w,
                        xq,
                        (const int32_t *)selected->ptr,
                        (const float *)weights->ptr,
                        gate_expert_bytes,
                        gate_row_bytes,
                        xq_blocks,
                        expert_mid_dim,
                        n_expert,
                        clamp);
                }
            }
            ok = cuda_ok(cudaGetLastError(), "routed_moe gate/up launch");
        }
        if (prof_ev[3]) (void)cudaEventRecord(prof_ev[3], 0);
        if (ok) {
            dim3 midq_grid(midq_blocks, n_tokens * n_expert, 1);
            q8_K_quantize_kernel<<<midq_grid, 256, 0, ds4_current_stream()>>>(midq, (const float *)mid->ptr, expert_mid_dim, n_tokens * n_expert);
            ok = cuda_ok(cudaGetLastError(), "routed_moe mid quantize launch");
        }
        if (prof_ev[4]) (void)cudaEventRecord(prof_ev[4], 0);
        if (ok) {
            dim3 dgrid((out_dim + 31u) / 32u, n_tokens * n_expert, 1);
            uint32_t *down_tile_total = tile_total;
            uint32_t *down_tile_experts = tile_experts;
            uint32_t *down_tile_starts = tile_starts;
            uint32_t down_tile_capacity = tile_capacity;
            if (use_down_tile16 && tile16_total && tile16_experts && tile16_starts) {
                down_tile_total = tile16_total;
                down_tile_experts = tile16_experts;
                down_tile_starts = tile16_starts;
                down_tile_capacity = tile16_capacity;
            }
            if (use_direct_down_sum6) {
                if (q4k_path) {
                    dim3 sgrid((out_dim + 31u) / 32u, n_tokens, 1);
                    moe_down_q4K_sum6_nt_qwarp32_kernel<<<sgrid, 256, 0, ds4_current_stream()>>>(
                        (float *)out->ptr,
                        down_w,
                        midq,
                        (const int32_t *)selected->ptr,
                        down_expert_bytes,
                        down_row_bytes,
                        midq_blocks,
                        out_dim,
                        n_tokens);
                } else if (use_direct_down_sum6_small16) {
                    dim3 sgrid((out_dim + 31u) / 32u, n_tokens, 1);
                    moe_down_sum6_nt_qwarp32_kernel<<<sgrid, 256, 0, ds4_current_stream()>>>(
                        (float *)out->ptr,
                        down_w,
                        midq,
                        (const int32_t *)selected->ptr,
                        down_expert_bytes,
                        down_row_bytes,
                        midq_blocks,
                        out_dim,
                        n_tokens);
                } else if (use_direct_down_sum6_n2) {
                    dim3 sgrid((out_dim + 31u) / 32u, 2, 1);
                    moe_down_sum6_n2_qwarp32_kernel<<<sgrid, 256, 0, ds4_current_stream()>>>(
                        (float *)out->ptr,
                        down_w,
                        midq,
                        (const int32_t *)selected->ptr,
                        down_expert_bytes,
                        down_row_bytes,
                        midq_blocks,
                        out_dim);
                } else {
                    dim3 sgrid((out_dim + 31u) / 32u, 1, 1);
                    moe_down_sum6_qwarp32_kernel<<<sgrid, 256, 0, ds4_current_stream()>>>(
                        (float *)out->ptr,
                        down_w,
                        midq,
                        (const int32_t *)selected->ptr,
                        down_expert_bytes,
                        down_row_bytes,
                        midq_blocks,
                        out_dim);
                }
            } else if (use_atomic_down) {
                uint64_t n = (uint64_t)n_tokens * out_dim;
                zero_kernel<<<(n + 255u) / 256u, 256, 0, ds4_current_stream()>>>((float *)out->ptr, n);
                ok = cuda_ok(cudaGetLastError(), "routed_moe atomic zero launch");
            }
            if (use_direct_down_sum6) {
                /* The direct decode kernel writes the final token row. */
            } else if (sorted_pairs && use_expert_tiles && sorted_offsets && sorted_counts &&
                down_tile_total && down_tile_experts && down_tile_starts) {
                if (use_down_row2048) {
                    if (down_row_span == 512u) {
                        dim3 tgrid((out_dim + 511u) / 512u, down_tile_capacity, 1);
                        moe_down_expert_tile16_rowspan_kernel<512><<<tgrid, 256, 0, ds4_current_stream()>>>(
                            use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                            down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                            down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                            midq_blocks, out_dim, n_expert, use_atomic_down);
                    } else if (down_row_span == 1024u) {
                        dim3 tgrid((out_dim + 1023u) / 1024u, down_tile_capacity, 1);
                        moe_down_expert_tile16_rowspan_kernel<1024><<<tgrid, 256, 0, ds4_current_stream()>>>(
                            use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                            down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                            down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                            midq_blocks, out_dim, n_expert, use_atomic_down);
                    } else {
                        dim3 tgrid((out_dim + 2047u) / 2048u, down_tile_capacity, 1);
                        moe_down_expert_tile16_row2048_kernel<<<tgrid, 256, 0, ds4_current_stream()>>>(
                            use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                            down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                            down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                            midq_blocks, out_dim, n_expert, use_atomic_down);
                    }
                } else if (use_down_tile16) {
                    dim3 tgrid((out_dim + 31u) / 32u, down_tile_capacity, 1);
                    moe_down_expert_tile16_row32_kernel<<<tgrid, 256, 0, ds4_current_stream()>>>(
                        use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                        down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                        down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                        midq_blocks, out_dim, n_expert, use_atomic_down);
                } else if (expert_tile_m == 8u) {
                    dim3 tgrid((out_dim + 31u) / 32u, down_tile_capacity, 1);
                    moe_down_expert_tile8_row32_kernel<<<tgrid, 256, 0, ds4_current_stream()>>>(
                        use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                        down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                        down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                        midq_blocks, out_dim, n_expert, use_atomic_down);
                } else {
                    dim3 tgrid((out_dim + 31u) / 32u, down_tile_capacity, 1);
                    moe_down_expert_tile4_row32_kernel<<<tgrid, 256, 0, ds4_current_stream()>>>(
                        use_atomic_down ? (float *)out->ptr : (float *)down->ptr,
                        down_w, midq, sorted_pairs, sorted_offsets, sorted_counts,
                        down_tile_total, down_tile_experts, down_tile_starts, down_expert_bytes, down_row_bytes,
                        midq_blocks, out_dim, n_expert, use_atomic_down);
                }
            } else if (sorted_pairs && use_p2_sorted) {
                dim3 p2_dgrid((out_dim + 15u) / 16u, (pair_count + 1u) / 2u, 1);
                moe_down_sorted_p2_qwarp32_kernel<<<p2_dgrid, 256, 0, ds4_current_stream()>>>(
                    (float *)down->ptr,
                    down_w,
                    midq,
                    sorted_pairs,
                    (const int32_t *)selected->ptr,
                    down_expert_bytes,
                    down_row_bytes,
                    midq_blocks,
                    out_dim,
                    n_expert,
                    pair_count);
            } else if (sorted_pairs) {
                moe_down_sorted_qwarp32_kernel<<<dgrid, 256, 0, ds4_current_stream()>>>(
                    (float *)down->ptr,
                    down_w,
                    midq,
                    sorted_pairs,
                    (const int32_t *)selected->ptr,
                    down_expert_bytes,
                    down_row_bytes,
                    midq_blocks,
                    out_dim,
                    n_expert);
            } else {
                moe_down_qwarp32_kernel<<<dgrid, 256, 0, ds4_current_stream()>>>(
                    (float *)down->ptr,
                    down_w,
                    midq,
                    (const int32_t *)selected->ptr,
                    down_expert_bytes,
                    down_row_bytes,
                    midq_blocks,
                    out_dim,
                    n_expert);
            }
            ok = cuda_ok(cudaGetLastError(), "routed_moe down launch");
        }
        if (prof_ev[5]) (void)cudaEventRecord(prof_ev[5], 0);
        if (ok && !use_atomic_down && !use_direct_down_sum6) {
            uint64_t n = (uint64_t)n_tokens * out_dim;
            moe_sum_kernel<<<(n + 255) / 256, 256, 0, ds4_current_stream()>>>((float *)out->ptr, (const float *)down->ptr, out_dim, n_expert, n_tokens, /*guard_nonfinite=*/0);
            ok = cuda_ok(cudaGetLastError(), "routed_moe sum launch");
        }
        if (prof_ev[6]) {
            (void)cudaEventRecord(prof_ev[6], 0);
            if (cudaEventSynchronize(prof_ev[6]) == cudaSuccess) {
                float ms_xq = 0.0f, ms_sort = 0.0f, ms_gate = 0.0f, ms_midq = 0.0f, ms_down = 0.0f, ms_sum = 0.0f, ms_total = 0.0f;
                (void)cudaEventElapsedTime(&ms_xq, prof_ev[0], prof_ev[1]);
                (void)cudaEventElapsedTime(&ms_sort, prof_ev[1], prof_ev[2]);
                (void)cudaEventElapsedTime(&ms_gate, prof_ev[2], prof_ev[3]);
                (void)cudaEventElapsedTime(&ms_midq, prof_ev[3], prof_ev[4]);
                (void)cudaEventElapsedTime(&ms_down, prof_ev[4], prof_ev[5]);
                (void)cudaEventElapsedTime(&ms_sum, prof_ev[5], prof_ev[6]);
                (void)cudaEventElapsedTime(&ms_total, prof_ev[0], prof_ev[6]);
                fprintf(stderr,
                        "ds4: CUDA MoE profile tokens=%u pairs=%u xq=%.3f sort=%.3f gateup=%.3f midq=%.3f down=%.3f sum=%.3f total=%.3f ms\n",
                        n_tokens, pair_count, ms_xq, ms_sort, ms_gate, ms_midq, ms_down, ms_sum, ms_total);
            }
            for (uint32_t i = 0; i < 7u; i++) (void)cudaEventDestroy(prof_ev[i]);
        }
        return ok;
    }

    if (ok) {
        dim3 mgrid(expert_mid_dim, n_tokens * n_expert, 1);
        moe_gate_up_mid_f32_kernel<<<mgrid, 256, 0, ds4_current_stream()>>>(
            (float *)gate->ptr,
            (float *)up->ptr,
            (float *)mid->ptr,
            gate_w,
            up_w,
            (const float *)x->ptr,
            (const int32_t *)selected->ptr,
            (const float *)weights->ptr,
            gate_expert_bytes,
            gate_row_bytes,
            expert_in_dim,
            expert_mid_dim,
            n_expert,
            clamp);
        ok = cuda_ok(cudaGetLastError(), "routed_moe gate/up launch");
    }
    if (ok) {
        dim3 dgrid(out_dim, n_tokens * n_expert, 1);
        moe_down_f32_kernel<<<dgrid, 256, 0, ds4_current_stream()>>>(
            (float *)down->ptr,
            down_w,
            (const float *)mid->ptr,
            (const int32_t *)selected->ptr,
            down_expert_bytes,
            down_row_bytes,
            expert_mid_dim,
            out_dim,
            n_expert);
        ok = cuda_ok(cudaGetLastError(), "routed_moe down launch");
    }
    if (ok) {
        uint64_t n = (uint64_t)n_tokens * out_dim;
        moe_sum_kernel<<<(n + 255) / 256, 256, 0, ds4_current_stream()>>>((float *)out->ptr, (const float *)down->ptr, out_dim, n_expert, n_tokens, /*guard_nonfinite=*/0);
        ok = cuda_ok(cudaGetLastError(), "routed_moe sum launch");
    }
    return ok;
}

extern "C" int ds4_gpu_routed_moe_one_tensor(ds4_gpu_tensor *out, ds4_gpu_tensor *gate, ds4_gpu_tensor *up, ds4_gpu_tensor *mid, ds4_gpu_tensor *down, const void *model_map, uint64_t model_size, uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset, uint32_t gate_type, uint32_t down_type, uint64_t gate_expert_bytes, uint64_t gate_row_bytes, uint64_t down_expert_bytes, uint64_t down_row_bytes, uint32_t expert_in_dim, uint32_t expert_mid_dim, uint32_t out_dim, const ds4_gpu_tensor *selected, const ds4_gpu_tensor *weights, uint32_t n_total_expert, uint32_t n_expert, float clamp, const ds4_gpu_tensor *x) {
    return routed_moe_launch(out, gate, up, mid, down, model_map, model_size,
                             gate_offset, up_offset, down_offset,
                             gate_type, down_type,
                             gate_expert_bytes, gate_row_bytes,
                             down_expert_bytes, down_row_bytes,
                             expert_in_dim, expert_mid_dim, out_dim,
                             selected, weights, n_total_expert, n_expert, clamp, x, 1,
                             /*defer_sum=*/0, NULL);
}
extern "C" int ds4_gpu_routed_moe_batch_tensor(ds4_gpu_tensor *out, ds4_gpu_tensor *gate, ds4_gpu_tensor *up, ds4_gpu_tensor *mid, ds4_gpu_tensor *down, const void *model_map, uint64_t model_size, uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset, uint32_t gate_type, uint32_t down_type, uint64_t gate_expert_bytes, uint64_t gate_row_bytes, uint64_t down_expert_bytes, uint64_t down_row_bytes, uint32_t expert_in_dim, uint32_t expert_mid_dim, uint32_t out_dim, const ds4_gpu_tensor *selected, const ds4_gpu_tensor *weights, uint32_t n_total_expert, uint32_t n_expert, float clamp, const ds4_gpu_tensor *x, uint32_t layer_index, uint32_t n_tokens, bool *mid_is_f16) {
    (void)layer_index;
    if (mid_is_f16) *mid_is_f16 = false;
    return routed_moe_launch(out, gate, up, mid, down, model_map, model_size,
                             gate_offset, up_offset, down_offset,
                             gate_type, down_type,
                             gate_expert_bytes, gate_row_bytes,
                             down_expert_bytes, down_row_bytes,
                             expert_in_dim, expert_mid_dim, out_dim,
                             selected, weights, n_total_expert, n_expert, clamp, x, n_tokens,
                             /*defer_sum=*/0, NULL);
}
/* v0.5 inc-8 F5: defer-sum sibling — identical to the batch entry but asks
 * the prefill mmq path to leave `down` per-expert unsummed.  On any branch
 * that sums internally, *out_sum_deferred stays 0 and `out` is valid as
 * before; when it returns 1 with *out_sum_deferred=1 the caller MUST
 * consume `down` (guarded-sum semantics) instead of `out`. */
extern "C" int ds4_gpu_routed_moe_batch_defer_sum_tensor(ds4_gpu_tensor *out, ds4_gpu_tensor *gate, ds4_gpu_tensor *up, ds4_gpu_tensor *mid, ds4_gpu_tensor *down, const void *model_map, uint64_t model_size, uint64_t gate_offset, uint64_t up_offset, uint64_t down_offset, uint32_t gate_type, uint32_t down_type, uint64_t gate_expert_bytes, uint64_t gate_row_bytes, uint64_t down_expert_bytes, uint64_t down_row_bytes, uint32_t expert_in_dim, uint32_t expert_mid_dim, uint32_t out_dim, const ds4_gpu_tensor *selected, const ds4_gpu_tensor *weights, uint32_t n_total_expert, uint32_t n_expert, float clamp, const ds4_gpu_tensor *x, uint32_t layer_index, uint32_t n_tokens, bool *mid_is_f16, int *out_sum_deferred) {
    (void)layer_index;
    if (mid_is_f16) *mid_is_f16 = false;
    return routed_moe_launch(out, gate, up, mid, down, model_map, model_size,
                             gate_offset, up_offset, down_offset,
                             gate_type, down_type,
                             gate_expert_bytes, gate_row_bytes,
                             down_expert_bytes, down_row_bytes,
                             expert_in_dim, expert_mid_dim, out_dim,
                             selected, weights, n_total_expert, n_expert, clamp, x, n_tokens,
                             /*defer_sum=*/1, out_sum_deferred);
}
/* v0.5 inc-8 F5 fallback: standalone guarded expert sum (bit-identical to
 * the prefill path's internal moe_sum) for when a deferred sum cannot be
 * folded into the HC epilogue after all. */
extern "C" int ds4_gpu_moe_sum_tensor(ds4_gpu_tensor *out, const ds4_gpu_tensor *down, uint32_t out_dim, uint32_t n_expert, uint32_t n_tokens) {
    if (!out || !down || out_dim == 0 || n_expert == 0 || n_tokens == 0 ||
        out->bytes < (uint64_t)n_tokens * out_dim * sizeof(float) ||
        down->bytes < (uint64_t)n_tokens * n_expert * out_dim * sizeof(float)) return 0;
    const uint64_t n = (uint64_t)n_tokens * out_dim;
    moe_sum_kernel<<<(uint32_t)((n + 255) / 256), 256, 0, ds4_current_stream()>>>(
        (float *)out->ptr, (const float *)down->ptr,
        out_dim, n_expert, n_tokens, /*guard_nonfinite=*/1);
    return cuda_ok(cudaGetLastError(), "moe_sum fallback launch");
}
extern "C" int ds4_gpu_hc_split_sinkhorn_tensor(ds4_gpu_tensor *out, const ds4_gpu_tensor *mix, const void *model_map, uint64_t model_size, uint64_t scale_offset, uint64_t base_offset, uint32_t n_hc, uint32_t sinkhorn_iters, float eps) {
    if (!out || !mix || !model_map || n_hc != 4) return 0;
    const uint64_t mix_bytes = 24ull * sizeof(float);
    if (scale_offset > model_size || model_size - scale_offset < 3ull * sizeof(float) ||
        base_offset > model_size || model_size - base_offset < mix_bytes ||
        mix->bytes < mix_bytes || out->bytes < mix_bytes) return 0;
    const float *scale = (const float *)cuda_model_range_ptr(model_map, scale_offset, 3ull * sizeof(float), "hc_scale");
    const float *base = (const float *)cuda_model_range_ptr(model_map, base_offset, mix_bytes, "hc_base");
    if (!scale || !base) return 0;
    uint32_t n_rows = (uint32_t)(mix->bytes / mix_bytes);
    if (out->bytes / mix_bytes < n_rows) n_rows = (uint32_t)(out->bytes / mix_bytes);
    hc_split_sinkhorn_kernel<<<(n_rows + 255) / 256, 256, 0, ds4_current_stream()>>>(
        (float *)out->ptr, (const float *)mix->ptr,
        scale,
        base,
        n_rows, sinkhorn_iters, eps);
    return cuda_ok(cudaGetLastError(), "hc_split_sinkhorn launch");
}
extern "C" int ds4_gpu_hc_weighted_sum_tensor(ds4_gpu_tensor *out, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *weights, uint32_t n_embd, uint32_t n_hc) {
    if (!out || !residual_hc || !weights || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out->bytes / ((uint64_t)n_embd * sizeof(float)));
    hc_weighted_sum_kernel<<<((uint64_t)n_embd * n_tokens + 255) / 256, 256, 0, ds4_current_stream()>>>(
        (float *)out->ptr, (const float *)residual_hc->ptr, (const float *)weights->ptr,
        n_embd, n_hc, n_tokens, n_hc);
    return cuda_ok(cudaGetLastError(), "hc_weighted_sum launch");
}
extern "C" int ds4_gpu_dspark_capture_mean_tensor(ds4_gpu_tensor *concat, const ds4_gpu_tensor *hc,
        uint32_t n_embd, uint32_t n_hc, uint32_t n_tokens, uint32_t slot, uint32_t n_slots) {
    if (!concat || !hc || n_embd == 0 || n_hc == 0 || n_tokens == 0 || slot >= n_slots) return 0;
    uint64_t n = (uint64_t)n_embd * n_tokens;
    dspark_capture_mean_kernel<<<(n + 255) / 256, 256, 0, ds4_current_stream()>>>(
        (float *)concat->ptr, (const float *)hc->ptr, n_embd, n_hc, n_tokens, slot, n_slots);
    return cuda_ok(cudaGetLastError(), "dspark_capture_mean launch");
}
extern "C" int ds4_gpu_hc_weighted_sum_split_tensor(ds4_gpu_tensor *out, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *split, uint32_t n_embd, uint32_t n_hc) {
    if (!out || !residual_hc || !split || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out->bytes / ((uint64_t)n_embd * sizeof(float)));
    uint32_t stride = (uint32_t)(2u * n_hc + n_hc * n_hc);
    hc_weighted_sum_kernel<<<((uint64_t)n_embd * n_tokens + 255) / 256, 256, 0, ds4_current_stream()>>>(
        (float *)out->ptr, (const float *)residual_hc->ptr, (const float *)split->ptr,
        n_embd, n_hc, n_tokens, stride);
    return cuda_ok(cudaGetLastError(), "hc_weighted_sum_split launch");
}
extern "C" int ds4_gpu_hc_split_weighted_sum_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *split,
        const ds4_gpu_tensor *mix,
        const ds4_gpu_tensor *residual_hc,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint32_t                n_embd,
        uint32_t                n_hc,
        uint32_t                sinkhorn_iters,
        float                   eps) {
    if (!out || !split || !mix || !residual_hc || !model_map ||
        n_embd == 0 || n_hc != 4) {
        return 0;
    }
    const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
    const uint64_t mix_bytes = mix_hc * sizeof(float);
    const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
    const uint64_t residual_row_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
    if (out->bytes < out_row_bytes || out->bytes % out_row_bytes != 0 ||
        scale_offset > model_size || 3ull * sizeof(float) > model_size - scale_offset ||
        base_offset > model_size || mix_bytes > model_size - base_offset) {
        return 0;
    }
    uint64_t n_rows = out->bytes / out_row_bytes;
    if (mix->bytes < n_rows * mix_bytes ||
        split->bytes < n_rows * mix_bytes ||
        residual_hc->bytes < n_rows * residual_row_bytes) {
        return 0;
    }
    const float *scale = (const float *)cuda_model_range_ptr(model_map, scale_offset, 3ull * sizeof(float), "hc_scale");
    const float *base = (const float *)cuda_model_range_ptr(model_map, base_offset, mix_bytes, "hc_base");
    if (!scale || !base) return 0;
    hc_split_weighted_sum_fused_kernel<<<(uint32_t)n_rows, 256, 0, ds4_current_stream()>>>(
            (float *)out->ptr,
            (float *)split->ptr,
            (const float *)mix->ptr,
            (const float *)residual_hc->ptr,
            scale,
            base,
            n_embd, n_hc, (uint32_t)n_rows, sinkhorn_iters, eps);
    return cuda_ok(cudaGetLastError(), "hc split weighted sum launch");
}
extern "C" int ds4_gpu_hc_split_weighted_sum_norm_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *norm_out,
        ds4_gpu_tensor       *split,
        const ds4_gpu_tensor *mix,
        const ds4_gpu_tensor *residual_hc,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint64_t                norm_weight_offset,
        uint32_t                n_embd,
        uint32_t                n_hc,
        uint32_t                sinkhorn_iters,
        float                   eps,
        float                   norm_eps) {
    if (getenv("DS4_CUDA_DISABLE_HC_SPLIT_NORM_FUSED") == NULL) {
        if (!out || !norm_out || !split || !mix || !residual_hc || !model_map ||
            n_embd == 0 || n_hc != 4) {
            return 0;
        }
        const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
        const uint64_t mix_bytes = mix_hc * sizeof(float);
        const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
        const uint64_t residual_row_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
        if (out->bytes < out_row_bytes || out->bytes % out_row_bytes != 0 ||
            norm_out->bytes < out->bytes ||
            scale_offset > model_size || 3ull * sizeof(float) > model_size - scale_offset ||
            base_offset > model_size || mix_bytes > model_size - base_offset ||
            norm_weight_offset > model_size ||
            (uint64_t)n_embd * sizeof(float) > model_size - norm_weight_offset) {
            return 0;
        }
        uint64_t n_rows = out->bytes / out_row_bytes;
        if (n_rows == 1) {
            if (mix->bytes < n_rows * mix_bytes ||
                split->bytes < n_rows * mix_bytes ||
                residual_hc->bytes < n_rows * residual_row_bytes) {
                return 0;
            }
            const float *scale = (const float *)cuda_model_range_ptr(model_map, scale_offset,
                    3ull * sizeof(float), "hc_scale");
            const float *base = (const float *)cuda_model_range_ptr(model_map, base_offset,
                    mix_bytes, "hc_base");
            const float *norm_w = (const float *)cuda_model_range_ptr(model_map, norm_weight_offset,
                    (uint64_t)n_embd * sizeof(float), "hc_norm_weight");
            if (!scale || !base || !norm_w) return 0;
            hc_split_weighted_sum_norm_fused_kernel<<<(uint32_t)n_rows, 256, 0, ds4_current_stream()>>>(
                    (float *)out->ptr,
                    (float *)norm_out->ptr,
                    (float *)split->ptr,
                    (const float *)mix->ptr,
                    (const float *)residual_hc->ptr,
                    scale,
                    base,
                    norm_w,
                    n_embd, n_hc, (uint32_t)n_rows, sinkhorn_iters, eps, norm_eps);
            return cuda_ok(cudaGetLastError(), "hc split weighted sum norm launch");
        }
    }
    return ds4_gpu_hc_split_weighted_sum_tensor(out, split, mix, residual_hc,
                                                  model_map, model_size,
                                                  scale_offset, base_offset,
                                                  n_embd, n_hc,
                                                  sinkhorn_iters, eps) &&
           ds4_gpu_rms_norm_weight_tensor(norm_out, out, model_map, model_size,
                                            norm_weight_offset, n_embd, norm_eps);
}

/* M2-Inc1: fused decode HC stage entry.  Covers the chain
 *   rms_norm_plain(flat, residual) -> f16 matmul (in_dim x 24, splitk) ->
 *   hc_split_weighted_sum_norm(out, norm_out, split, mix, residual)
 * with one cooperative kernel (see hc_stage_fused_coop_kernel).  Any
 * precondition miss falls back to the exact unfused chain below, so callers
 * treat this as a drop-in for the three-call sequence.  Kill switch:
 * DS4_CUDA_NO_HC_STAGE_FUSED=1.
 * M2-Inc1b: emit_q8 bit 0 additionally emits q8_0 codes of norm_out from the
 * fused kernel and registers them for the next consumer (fold kill switch:
 * DS4_CUDA_NO_HC_Q8_FOLD=1); pass 0 when no q8_0 consumer of norm_out
 * follows.  The unfused fallback ignores it (consumers quantize as before). */
extern "C" int ds4_gpu_hc_stage_fused_tensor(
        ds4_gpu_tensor       *out,
        ds4_gpu_tensor       *norm_out,
        ds4_gpu_tensor       *split,
        ds4_gpu_tensor       *mix,
        ds4_gpu_tensor       *flat_scratch,
        const ds4_gpu_tensor *residual_hc,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                fn_weight_offset,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint64_t                norm_weight_offset,
        uint32_t                n_embd,
        uint32_t                n_hc,
        uint32_t                sinkhorn_iters,
        float                   eps,
        float                   norm_eps,
        uint32_t                emit_q8) {
    const uint64_t in_dim = (uint64_t)n_hc * n_embd;
    const uint64_t mix_hc = 2ull * n_hc + (uint64_t)n_hc * n_hc;
    static int no_fused = -1;
    if (no_fused < 0) no_fused = getenv("DS4_CUDA_NO_HC_STAGE_FUSED") != NULL;
    static int no_q8_fold = -1;
    if (no_q8_fold < 0) no_q8_fold = getenv("DS4_CUDA_NO_HC_Q8_FOLD") != NULL;
    /* Stale-slot hygiene: no consumer pop can precede an HC stage within a
     * layer, so resetting here (fused or not) keeps the registry sound. */
    cuda_q8_fold_reset();
    do {
        if (no_fused || n_hc != 4u || n_embd == 0u ||
            (in_dim % 256u) != 0u || g_hc_stage_scratch == NULL) break;
        if (!out || !norm_out || !split || !mix || !residual_hc || !model_map) break;
        const uint64_t mix_bytes = mix_hc * sizeof(float);
        const uint64_t out_row_bytes = (uint64_t)n_embd * sizeof(float);
        const uint64_t weight_bytes = mix_hc * in_dim * sizeof(uint16_t);
        if (out->bytes < out_row_bytes || norm_out->bytes < out_row_bytes ||
            mix->bytes < mix_bytes || split->bytes < mix_bytes ||
            residual_hc->bytes < in_dim * sizeof(float)) break;
        if (out->bytes / out_row_bytes != 1u) break;  /* decode row only */
        if (fn_weight_offset > model_size || weight_bytes > model_size - fn_weight_offset ||
            scale_offset > model_size || 3ull * sizeof(float) > model_size - scale_offset ||
            base_offset > model_size || mix_bytes > model_size - base_offset ||
            norm_weight_offset > model_size ||
            (uint64_t)n_embd * sizeof(float) > model_size - norm_weight_offset) break;
        const char *wp = cuda_model_range_ptr(model_map, fn_weight_offset, weight_bytes, "hc_fn_f16");
        const float *scale = (const float *)cuda_model_range_ptr(model_map, scale_offset,
                3ull * sizeof(float), "hc_scale");
        const float *base = (const float *)cuda_model_range_ptr(model_map, base_offset,
                mix_bytes, "hc_base");
        const float *norm_w = (const float *)cuda_model_range_ptr(model_map, norm_weight_offset,
                (uint64_t)n_embd * sizeof(float), "hc_norm_weight");
        if (!wp || !scale || !base || !norm_w) break;
        if (((uintptr_t)wp & 15u) != 0u || ((uintptr_t)residual_hc->ptr & 15u) != 0u) break;
        /* Coop-launch capability probe.  Cached BEFORE the first layer-graph
         * capture (the warmup pass runs eager), so a cooperative launch can
         * never fail for residency reasons mid-capture. */
        static int coop_ok = -1;
        if (coop_ok < 0) {
            int dev = 0, supported = 0, blocks_per_sm = 0, n_sm = 0;
            (void)cudaGetDevice(&dev);
            (void)cudaDeviceGetAttribute(&supported, cudaDevAttrCooperativeLaunch, dev);
            (void)cudaOccupancyMaxActiveBlocksPerMultiprocessor(
                    &blocks_per_sm, hc_stage_fused_coop_kernel, 256, 0);
            (void)cudaDeviceGetAttribute(&n_sm, cudaDevAttrMultiProcessorCount, dev);
            coop_ok = supported != 0 &&
                      (uint64_t)blocks_per_sm * (uint64_t)n_sm >= DS4_HC_STAGE_BLOCKS;
            if (coop_ok) {
                fprintf(stderr, "ds4: M2-Inc1 fused HC stage active (coop %u-blk, in_dim %u)\n",
                        DS4_HC_STAGE_BLOCKS, (uint32_t)in_dim);
            } else {
                fprintf(stderr, "ds4: M2-Inc1 fused HC stage unavailable (coop=%d, co-resident blocks=%d), unfused chain\n",
                        supported, blocks_per_sm * n_sm);
            }
        }
        if (!coop_ok) break;
        float *out_p = (float *)out->ptr;
        float *norm_out_p = (float *)norm_out->ptr;
        float *split_p = (float *)split->ptr;
        float *mix_p = (float *)mix->ptr;
        const __half *w_p = (const __half *)wp;
        const float *x_p = (const float *)residual_hc->ptr;
        uint32_t in_dim32 = (uint32_t)in_dim;
        /* M2-Inc1b: q8_0 sidecar for norm_out (same [xq | xscale] layout the
         * consumer preludes allocate).  Alloc failure just skips the fold. */
        /* Sidecars come from the DEDICATED rings — never cuda_tmp_alloc
         * (single shared sticky scratch: two allocations alias and the
         * emissions overwrite each other). */
        int8_t *q80_xq = NULL;
        float *q80_scale = NULL;
        ds4_hc_block_q8_1 *q81 = NULL;
        if ((emit_q8 & 1u) && !no_q8_fold && (n_embd % 32u) == 0u && n_embd <= 8192u) {
            g_q8_fold_q80_idx ^= 1;
            int8_t *buf = g_q8_fold_q80_buf[g_q8_fold_q80_idx];
            if (buf) {
                const uint64_t sc_off = ((uint64_t)n_embd + 15u) & ~15ull;
                q80_xq = buf;
                q80_scale = (float *)((char *)buf + sc_off);
            }
        }
        /* M2-Inc2a: q8_1 sidecar (block_q8_1 array) for the routed-MoE mmvq
         * consumer of ffn_norm.
         * C3-Inc4 SAFETY INVARIANT (see the qkv-rms q8_1 emit for the full
         * story): emit only when the take bakes into the same outer captured
         * graph (capture active) or runs host-side every step (inner MoE
         * graph cache disabled).  Eager + inner cache would bake ONE ring
         * parity into the consumer's private graph while this emit keeps
         * flipping it -> stale sidecar on replays. */
        if ((emit_q8 & 2u) && !no_q8_fold && (n_embd % 32u) == 0u && n_embd <= 8192u &&
            (ds4_capture_active() || !ds4_cuda_moe_graphs_enabled())) {
            g_q8_fold_q81_idx ^= 1;
            q81 = (ds4_hc_block_q8_1 *)g_q8_fold_q81_buf[g_q8_fold_q81_idx];
        }
        void *args[] = {
            (void *)&out_p, (void *)&norm_out_p, (void *)&split_p, (void *)&mix_p,
            (void *)&g_hc_stage_scratch,
            (void *)&w_p, (void *)&x_p,
            (void *)&scale, (void *)&base, (void *)&norm_w,
            (void *)&q80_xq, (void *)&q80_scale, (void *)&q81,
            (void *)&n_embd, (void *)&in_dim32,
            (void *)&sinkhorn_iters, (void *)&eps, (void *)&norm_eps, (void *)&norm_eps };
        cudaError_t err = cudaLaunchCooperativeKernel(
                (void *)hc_stage_fused_coop_kernel,
                dim3(DS4_HC_STAGE_BLOCKS, 1, 1), dim3(256, 1, 1),
                args, 0, ds4_current_stream());
        if (err != cudaSuccess) {
            static int warned = 0;
            if (!warned) {
                warned = 1;
                fprintf(stderr, "ds4: fused HC stage launch failed (%s), unfused chain\n",
                        cudaGetErrorString(err));
            }
            (void)cudaGetLastError();
            break;
        }
        if (q80_xq || q81) cuda_q8_fold_register(norm_out->ptr, n_embd, q80_xq, q80_scale, q81);
        return 1;
    } while (0);
    /* Unfused fallback: the exact original three-call chain. */
    if (!flat_scratch) return 0;
    if (!ds4_gpu_rms_norm_plain_tensor(flat_scratch, residual_hc, (uint32_t)in_dim, norm_eps)) return 0;
    if (!ds4_gpu_matmul_f16_tensor(mix, model_map, model_size, fn_weight_offset,
                                     in_dim, mix_hc, flat_scratch, 1)) return 0;
    return ds4_gpu_hc_split_weighted_sum_norm_tensor(out, norm_out, split, mix,
                                                       residual_hc, model_map, model_size,
                                                       scale_offset, base_offset,
                                                       norm_weight_offset, n_embd, n_hc,
                                                       sinkhorn_iters, eps, norm_eps);
}

extern "C" int ds4_gpu_output_hc_weights_tensor(
        ds4_gpu_tensor       *out,
        const ds4_gpu_tensor *pre,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                scale_offset,
        uint64_t                base_offset,
        uint32_t                n_hc,
        float                   eps) {
    if (!out || !pre || !model_map || n_hc == 0) return 0;
    const uint64_t row_bytes = (uint64_t)n_hc * sizeof(float);
    if (row_bytes == 0 || out->bytes < row_bytes || out->bytes % row_bytes != 0 ||
        pre->bytes < out->bytes ||
        scale_offset > model_size || sizeof(float) > model_size - scale_offset ||
        base_offset > model_size || row_bytes > model_size - base_offset) {
        return 0;
    }
    const uint64_t n_tokens = out->bytes / row_bytes;
    const float *scale = (const float *)cuda_model_range_ptr(model_map, scale_offset, sizeof(float), "output_hc_scale");
    const float *base = (const float *)cuda_model_range_ptr(model_map, base_offset, row_bytes, "output_hc_base");
    if (!scale || !base) return 0;
    uint64_t n = n_tokens * n_hc;
    output_hc_weights_kernel<<<(n + 255) / 256, 256, 0, ds4_current_stream()>>>(
            (float *)out->ptr,
            (const float *)pre->ptr,
            scale,
            base,
            n_hc,
            (uint32_t)n_tokens,
            eps);
    return cuda_ok(cudaGetLastError(), "output hc weights launch");
}
extern "C" int ds4_gpu_hc_expand_tensor(ds4_gpu_tensor *out_hc, const ds4_gpu_tensor *block_out, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *post, const ds4_gpu_tensor *comb, uint32_t n_embd, uint32_t n_hc) {
    if (!out_hc || !block_out || !residual_hc || !post || !comb || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out_hc->bytes / ((uint64_t)n_hc * n_embd * sizeof(float)));
    uint64_t n_elem = (uint64_t)n_tokens * n_hc * n_embd;
    hc_expand_kernel<<<(n_elem + 255) / 256, 256, 0, ds4_current_stream()>>>((float *)out_hc->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)residual_hc->ptr,
                                                    (const float *)post->ptr,
                                                    (const float *)comb->ptr,
                                                    n_embd, n_hc, n_tokens,
                                                    n_hc, n_hc * n_hc, 0);
    return cuda_ok(cudaGetLastError(), "hc_expand launch");
}
extern "C" int ds4_gpu_hc_expand_split_tensor(ds4_gpu_tensor *out_hc, const ds4_gpu_tensor *block_out, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *split, uint32_t n_embd, uint32_t n_hc) {
    if (!out_hc || !block_out || !residual_hc || !split || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out_hc->bytes / ((uint64_t)n_hc * n_embd * sizeof(float)));
    uint32_t mix_hc = 2u * n_hc + n_hc * n_hc;
    uint64_t n_elem = (uint64_t)n_tokens * n_hc * n_embd;
    const float *base = (const float *)split->ptr;
    hc_expand_kernel<<<(n_elem + 255) / 256, 256, 0, ds4_current_stream()>>>((float *)out_hc->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)residual_hc->ptr,
                                                    base + n_hc,
                                                    base + 2u * n_hc,
                                                    n_embd, n_hc, n_tokens,
                                                    mix_hc, mix_hc, 0);
    return cuda_ok(cudaGetLastError(), "hc_expand_split launch");
}
extern "C" int ds4_gpu_hc_expand_add_split_tensor(ds4_gpu_tensor *out_hc, const ds4_gpu_tensor *block_out, const ds4_gpu_tensor *block_add, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *split, uint32_t n_embd, uint32_t n_hc) {
    if (!out_hc || !block_out || !block_add || !residual_hc || !split || n_embd == 0 || n_hc == 0) return 0;
    uint32_t n_tokens = (uint32_t)(out_hc->bytes / ((uint64_t)n_hc * n_embd * sizeof(float)));
    uint32_t mix_hc = 2u * n_hc + n_hc * n_hc;
    uint64_t n_elem = (uint64_t)n_tokens * n_hc * n_embd;
    const float *base = (const float *)split->ptr;
    hc_expand_kernel<<<(n_elem + 255) / 256, 256, 0, ds4_current_stream()>>>((float *)out_hc->ptr,
                                                    (const float *)block_out->ptr,
                                                    (const float *)block_add->ptr,
                                                    (const float *)residual_hc->ptr,
                                                    base + n_hc,
                                                    base + 2u * n_hc,
                                                    n_embd, n_hc, n_tokens,
                                                    mix_hc, mix_hc, 1);
    return cuda_ok(cudaGetLastError(), "hc_expand_add_split launch");
}
/* P3-Inc2: fused batched hc_expand + next-stage rms_norm f16 emission (see
 * hc_expand_split_rmsf16_kernel).  block_add == NULL -> plain expand (attn
 * side); non-NULL -> add variant (ffn side).  xh_out receives the f16 GEMM
 * activations for the NEXT HC mix (1-ulp contraction class vs the unfused
 * pair -- see the kernel comment).  Returns 0 with all outputs untouched on
 * any precondition miss; the caller must then run the unfused expand (and
 * the next mix falls back on its own).
 * Kill switch: DS4_CUDA_NO_HC_EXPAND_RMS_FOLD=1. */
extern "C" int ds4_gpu_hc_expand_rmsf16_split_tensor(ds4_gpu_tensor *out_hc, ds4_gpu_tensor *xh_out, const ds4_gpu_tensor *block_out, const ds4_gpu_tensor *block_add, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *split, uint32_t n_embd, uint32_t n_hc, float norm_eps) {
    static int no_fold = -1;
    if (no_fold < 0) no_fold = getenv("DS4_CUDA_NO_HC_EXPAND_RMS_FOLD") != NULL;
    if (no_fold) return 0;
    if (!out_hc || !xh_out || !block_out || !residual_hc || !split) return 0;
    if (n_embd != 4096u || n_hc != 4u) return 0;
    const uint64_t n = (uint64_t)n_hc * n_embd;
    const uint32_t n_tokens = (uint32_t)(out_hc->bytes / (n * sizeof(float)));
    /* The f16 emission only pays off when the next mix takes the cublas
     * batch path; at native-f16 widths the consumer reads f32 directly. */
    if (n_tokens <= cuda_native_f16_max_tokens()) return 0;
    if (xh_out->bytes < (uint64_t)n_tokens * n * sizeof(__half)) return 0;
    const uint32_t mix_hc = 2u * n_hc + n_hc * n_hc;
    const float *base = (const float *)split->ptr;
    const int has_add = block_add != NULL;
    const float *badd = has_add ? (const float *)block_add->ptr : (const float *)block_out->ptr;
    static int announced = 0;
    if (!announced) {
        announced = 1;
        fprintf(stderr, "ds4: hc expand emitting rms-fold f16 activations (P3-Inc2)\n");
    }
    hc_expand_split_rmsf16_kernel<4096u, 4u><<<n_tokens, 256, 0, ds4_current_stream()>>>(
            (float *)out_hc->ptr, (__half *)xh_out->ptr,
            (const float *)block_out->ptr, badd,
            (const float *)residual_hc->ptr,
            base + n_hc, base + 2u * n_hc,
            n_tokens, mix_hc, mix_hc, has_add, norm_eps,
            /*moe_unsummed=*/NULL, 0u);
    if (!cuda_ok(cudaGetLastError(), "hc_expand_rmsf16 launch")) return 0;
    /* One-shot bounded-error parity selftest at production shape
     * (DS4_HC_EXPAND_RMS_FOLD_SELFTEST=1): run the unfused hc_expand_kernel +
     * rms_norm_plain_f16_rows_kernel pair into private scratch and compare
     * BOTH outputs.  The contraction variance is ~1 intermediate ulp, which
     * cancellation can blow up to enormous ULP distances on near-zero
     * elements while the ABSOLUTE error stays ~2^-24 of row scale -- so the
     * f32 bound is per-row absolute-at-row-scale: max |fused-ref| <=
     * rms(row) * 2^-19 (32x the measured class; a real indexing bug is
     * O(row scale), ~500000x over).  f16 bound: max 4 ulp on <= 0.1% of
     * elements.  Any non-finite disagreement is an automatic FAIL.
     * Synchronous and off by default. */
    static int selftest = -1;
    if (selftest < 0) selftest = getenv("DS4_HC_EXPAND_RMS_FOLD_SELFTEST") != NULL;
    if (selftest == 1) {
        selftest = 2;
        const uint64_t fbytes = (uint64_t)n_tokens * n * sizeof(float);
        const uint64_t hbytes = (uint64_t)n_tokens * n * sizeof(__half);
        float *out_ref = NULL;
        __half *xh_ref = NULL;
        void *ha = malloc(fbytes), *hb = malloc(fbytes);
        void *hc = malloc(hbytes), *hd = malloc(hbytes);
        if (cudaMalloc(&out_ref, fbytes) == cudaSuccess &&
            cudaMalloc(&xh_ref, hbytes) == cudaSuccess && ha && hb && hc && hd) {
            const uint64_t n_elem = (uint64_t)n_tokens * n;
            hc_expand_kernel<<<(unsigned)((n_elem + 255) / 256), 256, 0, ds4_current_stream()>>>(
                    out_ref, (const float *)block_out->ptr, badd,
                    (const float *)residual_hc->ptr, base + n_hc, base + 2u * n_hc,
                    n_embd, n_hc, n_tokens, mix_hc, mix_hc, has_add);
            rms_norm_plain_f16_rows_kernel<<<n_tokens, 256, 0, ds4_current_stream()>>>(
                    xh_ref, out_ref, (uint32_t)n, n_tokens, norm_eps);
            cudaMemcpyAsync(ha, out_hc->ptr, fbytes, cudaMemcpyDeviceToHost, ds4_current_stream());
            cudaMemcpyAsync(hb, out_ref, fbytes, cudaMemcpyDeviceToHost, ds4_current_stream());
            cudaMemcpyAsync(hc, xh_out->ptr, hbytes, cudaMemcpyDeviceToHost, ds4_current_stream());
            cudaMemcpyAsync(hd, xh_ref, hbytes, cudaMemcpyDeviceToHost, ds4_current_stream());
            if (cudaStreamSynchronize(ds4_current_stream()) == cudaSuccess) {
                const uint64_t total = (uint64_t)n_tokens * n;
                const float *fa = (const float *)ha;
                const float *fb = (const float *)hb;
                const uint16_t *ga = (const uint16_t *)hc;
                const uint16_t *gb = (const uint16_t *)hd;
                double worst_ratio = 0.0;   /* max over rows of maxdiff / (rms * 2^-19) */
                uint64_t f32_diff = 0;
                uint64_t f16_ulp_max = 0, f16_diff = 0;
                int nonfinite = 0;
                for (uint32_t t = 0; t < n_tokens && !nonfinite; t++) {
                    const float *ra = fa + (uint64_t)t * n;
                    const float *rb = fb + (uint64_t)t * n;
                    double ss = 0.0, maxd = 0.0;
                    for (uint64_t i = 0; i < n; i++) {
                        if (!isfinite(ra[i]) || !isfinite(rb[i])) {
                            if (ra[i] != rb[i]) { nonfinite = 1; break; }
                            continue;
                        }
                        ss += (double)rb[i] * (double)rb[i];
                        const double d = fabs((double)ra[i] - (double)rb[i]);
                        if (d > 0.0) f32_diff++;
                        if (d > maxd) maxd = d;
                    }
                    const double scale = sqrt(ss / (double)n);
                    const double bound = scale * 1.9073486328125e-06; /* 2^-19 */
                    const double ratio = bound > 0.0 ? maxd / bound : (maxd > 0.0 ? 1e30 : 0.0);
                    if (ratio > worst_ratio) worst_ratio = ratio;
                }
                for (uint64_t i = 0; i < total && !nonfinite; i++) {
                    const int32_t ja = ga[i] & 0x8000 ? (int32_t)INT16_MIN - (int32_t)(int16_t)ga[i] : (int32_t)ga[i];
                    const int32_t jb = gb[i] & 0x8000 ? (int32_t)INT16_MIN - (int32_t)(int16_t)gb[i] : (int32_t)gb[i];
                    if (ja != jb) {
                        const uint64_t d = (uint64_t)(ja > jb ? ja - jb : jb - ja);
                        if (d > f16_ulp_max) f16_ulp_max = d;
                        f16_diff++;
                    }
                }
                const int pass = !nonfinite && worst_ratio <= 1.0 && f16_ulp_max <= 4 &&
                                 f16_diff * 1000 <= total;
                fprintf(stderr, "ds4: HC-EXPAND-RMS-FOLD SELFTEST %s (rows=%u f32 worst=%.3f of row-scale bound diffs=%llu, f16 max_ulp=%llu diffs=%llu/%llu%s)\n",
                        pass ? "PASS" : "FAIL", (unsigned)n_tokens,
                        worst_ratio, (unsigned long long)f32_diff,
                        (unsigned long long)f16_ulp_max, (unsigned long long)f16_diff,
                        (unsigned long long)total, nonfinite ? ", NONFINITE" : "");
            } else {
                fprintf(stderr, "ds4: HC-EXPAND-RMS-FOLD SELFTEST FAIL (sync error)\n");
            }
        } else {
            fprintf(stderr, "ds4: HC-EXPAND-RMS-FOLD SELFTEST FAIL (alloc)\n");
        }
        if (out_ref) cudaFree(out_ref);
        if (xh_ref) cudaFree(xh_ref);
        free(ha); free(hb); free(hc); free(hd);
    }
    return 1;
}
/* v0.5 inc-8 F5: moe-variant of the fused expand — reads the per-expert
 * UNSUMMED routed down output and folds the guarded 6-sum (bit-identical
 * to moe_sum_kernel) + shared-expert add + HC expand + RMS + f16 emit into
 * the one kernel.  Same gates and return-0-fallback contract as the plain
 * entry; the caller must run ds4_gpu_moe_sum_tensor + the unfused expand
 * when this declines. */
extern "C" int ds4_gpu_hc_expand_rmsf16_split_moe_tensor(ds4_gpu_tensor *out_hc, ds4_gpu_tensor *xh_out, const ds4_gpu_tensor *moe_down_unsummed, const ds4_gpu_tensor *block_add, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *split, uint32_t n_embd, uint32_t n_hc, uint32_t n_expert_used, float norm_eps) {
    static int no_fold = -1;
    if (no_fold < 0) no_fold = getenv("DS4_CUDA_NO_HC_EXPAND_RMS_FOLD") != NULL;
    if (no_fold) return 0;
    if (!out_hc || !xh_out || !moe_down_unsummed || !block_add || !residual_hc || !split) return 0;
    if (n_embd != 4096u || n_hc != 4u || n_expert_used == 0u) return 0;
    const uint64_t n = (uint64_t)n_hc * n_embd;
    const uint32_t n_tokens = (uint32_t)(out_hc->bytes / (n * sizeof(float)));
    if (n_tokens <= cuda_native_f16_max_tokens()) return 0;
    if (xh_out->bytes < (uint64_t)n_tokens * n * sizeof(__half)) return 0;
    if (moe_down_unsummed->bytes < (uint64_t)n_tokens * n_expert_used * n_embd * sizeof(float)) return 0;
    if (block_add->bytes < (uint64_t)n_tokens * n_embd * sizeof(float)) return 0;
    const uint32_t mix_hc = 2u * n_hc + n_hc * n_hc;
    const float *base = (const float *)split->ptr;
    static int announced_moe = 0;
    if (!announced_moe) {
        announced_moe = 1;
        fprintf(stderr, "ds4: hc expand folding deferred MoE sum (inc-8 F5)\n");
    }
    hc_expand_split_rmsf16_kernel<4096u, 4u><<<n_tokens, 256, 0, ds4_current_stream()>>>(
            (float *)out_hc->ptr, (__half *)xh_out->ptr,
            /*block_out (unused in moe path)=*/(const float *)block_add->ptr,
            (const float *)block_add->ptr,
            (const float *)residual_hc->ptr,
            base + n_hc, base + 2u * n_hc,
            n_tokens, mix_hc, mix_hc, /*has_add=*/1, norm_eps,
            (const float *)moe_down_unsummed->ptr, n_expert_used);
    return cuda_ok(cudaGetLastError(), "hc_expand_rmsf16_moe launch");
}

extern "C" int ds4_gpu_hc_expand_add_split_n2_rows_tensor(ds4_gpu_tensor *out0_hc, ds4_gpu_tensor *out1_hc, const ds4_gpu_tensor *block_out, const ds4_gpu_tensor *block_add, const ds4_gpu_tensor *residual_hc, const ds4_gpu_tensor *split, uint32_t n_embd, uint32_t n_hc) {
    if (!out0_hc || !out1_hc || !block_out || !block_add || !residual_hc || !split ||
        n_embd == 0 || n_hc == 0) return 0;
    const uint64_t hc_bytes = (uint64_t)n_hc * n_embd * sizeof(float);
    const uint64_t row_bytes = (uint64_t)n_embd * sizeof(float);
    const uint32_t mix_hc = 2u * n_hc + n_hc * n_hc;
    if (out0_hc->bytes < hc_bytes || out1_hc->bytes < hc_bytes ||
        block_out->bytes < 2ull * row_bytes ||
        block_add->bytes < 2ull * row_bytes ||
        residual_hc->bytes < 2ull * hc_bytes ||
        split->bytes < 2ull * mix_hc * sizeof(float)) {
        return 0;
    }
    uint64_t n_elem = 2ull * n_hc * n_embd;
    const float *base = (const float *)split->ptr;
    hc_expand_add_split_n2_rows_kernel<<<(n_elem + 255) / 256, 256, 0, ds4_current_stream()>>>(
            (float *)out0_hc->ptr,
            (float *)out1_hc->ptr,
            (const float *)block_out->ptr,
            (const float *)block_add->ptr,
            (const float *)residual_hc->ptr,
            base + n_hc,
            base + 2u * n_hc,
            n_embd,
            n_hc,
            mix_hc);
    return cuda_ok(cudaGetLastError(), "hc_expand_add_split_n2_rows launch");
}
extern "C" int ds4_gpu_shared_down_hc_expand_q8_0_tensor(
        ds4_gpu_tensor       *out_hc,
        ds4_gpu_tensor       *shared_out,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint64_t                in_dim,
        uint64_t                out_dim,
        const ds4_gpu_tensor *shared_mid,
        const ds4_gpu_tensor *routed_out,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *split,
        uint32_t                n_embd,
        uint32_t                n_hc) {
    if (getenv("DS4_CUDA_DISABLE_Q8_HC_EXPAND_FUSED") == NULL) {
        return cuda_matmul_q8_0_hc_expand_tensor_labeled(out_hc, shared_out,
                                                        model_map, model_size,
                                                        weight_offset,
                                                        in_dim, out_dim,
                                                        shared_mid,
                                                        routed_out,
                                                        residual_hc,
                                                        split,
                                                        n_embd, n_hc,
                                                        "shared_down_hc_expand");
    }
    return ds4_gpu_matmul_q8_0_tensor(shared_out, model_map, model_size,
                                        weight_offset, in_dim, out_dim,
                                        shared_mid, 1) &&
           ds4_gpu_hc_expand_add_split_tensor(out_hc, shared_out, routed_out,
                                                residual_hc, split, n_embd, n_hc);
}

extern "C" int ds4_gpu_matmul_q8_0_hc_expand_tensor(
        ds4_gpu_tensor       *out_hc,
        ds4_gpu_tensor       *block_out,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint64_t                in_dim,
        uint64_t                out_dim,
        const ds4_gpu_tensor *x,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *split,
        uint32_t                n_embd,
        uint32_t                n_hc) {
    if (getenv("DS4_CUDA_DISABLE_Q8_HC_EXPAND_FUSED") == NULL) {
        return cuda_matmul_q8_0_hc_expand_tensor_labeled(out_hc, block_out,
                                                        model_map, model_size,
                                                        weight_offset,
                                                        in_dim, out_dim,
                                                        x,
                                                        NULL,
                                                        residual_hc,
                                                        split,
                                                        n_embd, n_hc,
                                                        "q8_hc_expand");
    }
    return ds4_gpu_matmul_q8_0_tensor(block_out, model_map, model_size,
                                        weight_offset, in_dim, out_dim, x, 1) &&
           ds4_gpu_hc_expand_split_tensor(out_hc, block_out, residual_hc,
                                            split, n_embd, n_hc);
}

extern "C" int ds4_gpu_matmul_q8_0_hc_expand_n2_tensor(
        ds4_gpu_tensor       *out_hc,
        ds4_gpu_tensor       *block_out,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint64_t                in_dim,
        uint64_t                out_dim,
        const ds4_gpu_tensor *x,
        const ds4_gpu_tensor *residual_hc,
        const ds4_gpu_tensor *split,
        uint32_t                n_embd,
        uint32_t                n_hc) {
    if (getenv("DS4_CUDA_DISABLE_Q8_HC_EXPAND_FUSED") == NULL) {
        return cuda_matmul_q8_0_hc_expand_n2_tensor_labeled(out_hc,
                                                            block_out,
                                                            model_map,
                                                            model_size,
                                                            weight_offset,
                                                            in_dim,
                                                            out_dim,
                                                            x,
                                                            residual_hc,
                                                            split,
                                                            n_embd,
                                                            n_hc,
                                                            "q8_hc_expand_n2");
    }
    return ds4_gpu_matmul_q8_0_tensor(block_out, model_map, model_size,
                                        weight_offset, in_dim, out_dim, x, 2) &&
           ds4_gpu_hc_expand_split_tensor(out_hc, block_out, residual_hc,
                                            split, n_embd, n_hc);
}

extern "C" int ds4_gpu_matmul_q8_0_hc_expand_n2_split_residual_tensor(
        ds4_gpu_tensor       *out_hc,
        ds4_gpu_tensor       *block_out,
        const void             *model_map,
        uint64_t                model_size,
        uint64_t                weight_offset,
        uint64_t                in_dim,
        uint64_t                out_dim,
        const ds4_gpu_tensor *x,
        const ds4_gpu_tensor *residual0_hc,
        const ds4_gpu_tensor *residual1_hc,
        const ds4_gpu_tensor *split,
        uint32_t                n_embd,
        uint32_t                n_hc) {
    if (getenv("DS4_CUDA_DISABLE_Q8_HC_EXPAND_FUSED") == NULL) {
        return cuda_matmul_q8_0_hc_expand_n2_split_residual_tensor_labeled(out_hc,
                                                                           block_out,
                                                                           model_map,
                                                                           model_size,
                                                                           weight_offset,
                                                                           in_dim,
                                                                           out_dim,
                                                                           x,
                                                                           residual0_hc,
                                                                           residual1_hc,
                                                                           split,
                                                                           n_embd,
                                                                           n_hc,
                                                                           "q8_hc_expand_n2_split_residual");
    }
    if (!out_hc || !block_out || !x || !residual0_hc || !residual1_hc || !split) return 0;
    const uint64_t hc_dim = (uint64_t)n_hc * n_embd;
    const uint64_t split_dim = 2ull * n_hc + (uint64_t)n_hc * n_hc;
    int ok = 1;
    for (uint32_t t = 0; ok && t < 2u; t++) {
        ds4_gpu_tensor *out_row = ds4_gpu_tensor_view(out_hc,
                                                      (uint64_t)t * hc_dim * sizeof(float),
                                                      hc_dim * sizeof(float));
        ds4_gpu_tensor *block_row = ds4_gpu_tensor_view(block_out,
                                                        (uint64_t)t * out_dim * sizeof(float),
                                                        out_dim * sizeof(float));
        ds4_gpu_tensor *x_row = ds4_gpu_tensor_view(x,
                                                    (uint64_t)t * in_dim * sizeof(float),
                                                    in_dim * sizeof(float));
        ds4_gpu_tensor *split_row = ds4_gpu_tensor_view(split,
                                                        (uint64_t)t * split_dim * sizeof(float),
                                                        split_dim * sizeof(float));
        const ds4_gpu_tensor *residual = t == 0 ? residual0_hc : residual1_hc;
        ok = out_row && block_row && x_row && split_row &&
             ds4_gpu_matmul_q8_0_hc_expand_tensor(out_row,
                                                  block_row,
                                                  model_map,
                                                  model_size,
                                                  weight_offset,
                                                  in_dim,
                                                  out_dim,
                                                  x_row,
                                                  residual,
                                                  split_row,
                                                  n_embd,
                                                  n_hc) != 0;
        ds4_gpu_tensor_free(split_row);
        ds4_gpu_tensor_free(x_row);
        ds4_gpu_tensor_free(block_row);
        ds4_gpu_tensor_free(out_row);
    }
    return ok;
}

